\subsection{Overview of Error Exponents}
\label{RandomCodingErrorExponents}

An error exponent $E(R)$ is said to be achievable at rate $R$ whenever
\begin{equation}
    \label{eqn:probability_of_error_bound}
    E_{\text{r}}(R) \le \operatorname*{lim}_{n \to \infty} - \frac{1}{n} \log \bar{p}_e(n, \lfloor e^{nR} \rfloor),
\end{equation}
where $\bar{p}_e$ is the average error probability over all randomly generated codes of a specific ensemble. If \eqref{eqn:probability_of_error_bound} holds with equality, $E_{\text{r}}(R)$ is said to be the ensemble-tight exponent \cite[Ch. 7.1]{Foundations}. For ML decoding,
\begin{align} \label{eqn:RCErrorExponent}
    E_{\text{r}}(\QX, R) &\triangleq \operatorname*{max}_{\rho \in [0, 1]} E_0(\QX, \rho) - \rho R
\end{align}
is the (ensemble-tight) random coding exponent \cite{GallagerWiley1968} achievable at rate $R$ with i.i.d and constant-composition codes, where the respective Gallager $E_0$ functions are defined from%
\begin{equation}
	\varepsilon_{a, \rho}(x, y) \triangleq \bigg( \frac{ \EX_{\QX}[W(y|X)^{\frac{1}{1+\rho}}e^{a(X)}]}{W(y|x)^{\frac{1}{1+\rho}} e^{a(x)}} \bigg)^{\rho}%
\end{equation}
as%
\begin{align} \label{eqn:MatchediidGallagerFunction}
E_0^{\text{iid}}(\QX, \rho) &\triangleq - \log \EX_{\QX \times W} [\varepsilon_{0, \rho}(X, Y) ]\\
\label{eqn:MatchedccGallagerFunction}
E_0^{\text{cc}}(\QX, \rho) &\triangleq \sup_{a(\cdot)} -\EX_{\QX} \big[\! \log \EX_{W} [\varepsilon_{a, \rho}(X, Y)|X ] \big]. %
\end{align}
It is known that the error exponent $E_{\text{r}}(\QX, R)$ is positive for rates $R < \frac{\partial E_0(\QX, \rho)}{\partial\rho}\big|_{\rho=0}=I(X;Y)$, proving the achievability part of the channel coding theorem. Moreover, $E_0^{\text{cc}}(\QX, \rho)\geq E_0^{\text{iid}}(\QX, \rho)$ with equality only for the respective optimal input distributions \cite[Eq. (52)]{6763080}.

Analogous to the matched case, the ensemble-tight mismatched random coding error exponents \cite[Th. 7.1]{Foundations} of i.i.d.\ and constant-composition codes are defined using%
\begin{equation}\label{eqn:e_s_a_def}
	\varepsilon_{s, a, \rho}(x, y) \triangleq  \bigg( \frac{\EX_{\QX}[q(X,y)^s e^{a(X)}]}{q(x,y)^s e^{a(x)}} \bigg) ^\rho
\end{equation}
to obtain the following dual expressions \cite[Ch. 7.2]{Foundations}:%
\begin{align}
    E_\text{r}^{\text{iid}}(\QX, R) &\triangleq \operatorname*{max}_{\rho \in [0,1]} E_0^{\text{iid}}(\QX, \rho) - \rho R \label{eqn:ErIID}\\
    E_\text{r}^{\text{cc}}(\QX, R) &\triangleq \operatorname*{max}_{\rho \in [0,1]} E_0^{\text{cc}}(\QX, \rho) - \rho R,\label{eqn:ErCC}
\end{align}
where the respective mismatched Gallager functions are%
\begin{align} 
E_0^{\text{iid}}(\QX, \rho) &\triangleq\ \sup_{s \ge 0}\ -\log \EX_{\QX{\times}W} [\varepsilon_{s, 0, \rho}(X, Y)] \label{eqn:E0IID}\\
E_0^{\text{cc}}(\QX, \rho) &\triangleq\! {\sup_{s \ge 0, a(\cdot)}} \hspace{-0.25em}{-}\EX_{\QX} \big[\! \log \EX_{W} [\varepsilon_{s, a, \rho}(X, Y)|X] \big]{.} \label{eqn:E0CC}
\end{align}
For simplicity, we have used the same notation for the mismatched error exponents as for the matched case.

An alternative expression for $E_0^{\text{cc}}$ can be formulated by observing that constant-composition and cost-constrained coding achieve the same exponent when two cost functions $c_1(\cdot)$ and $c_2(\cdot)$ are optimized \cite[Th. 4]{6763080}. This is%
\begin{align}\label{eqn:E0Cost}
	E_0^{\text{cc}}(\QX, \rho) &=\! \sup_{c_1\!(\cdot), c_2\!(\cdot)} E_0^{\text{cost}}(\QX, \rho, \{c_1, c_2\})
\end{align}
where%
\begin{align}
	E_0^{\text{cost}}(\QX, \rho, \cv) &\triangleq\! \sup_{s\ge0, \boldsymbol{\lambda}, \bar{\boldsymbol{\lambda}}} \hspace{-0.5em} -\log \EX_{\QX\times W} \big[ \varepsilon_{s,\lv, \bar{\lv}, \rho}^\text{cost}(X, Y) \big]\\
	\varepsilon_{s, \lv, \bar{\lv},\rho}^{\text{cost}}(x, y) &\triangleq \bigg( \frac{\EX_{\QX}[q(X, y)^s e^{\bar\lv^{\!T\!} (\cv(X)-\pv)}] }{q(x, y)^s e^{{\lv}^{\!T\!} (\cv(x)-\pv)}} \bigg)^\rho%
\end{align}
and $\cv(x)\triangleq[c_1(x), c_2(x)]^T$, $\lv\triangleq[\lambda_1, \lambda_2]^T$, $\bar{\lv}\triangleq[\bar{\lambda}_1, \bar{\lambda}_2]^T$ and $\boldsymbol{\phi}\triangleq[\EX[c_1(X)], \EX[c_2(X)]]^T$ defined in vector form for ease of notation.
We are more interested in the expression \eqref{eqn:E0Cost} for the mismatched $E_0$ function of constant-composition codes, as it adopts a similar form to that of i.i.d. codes, leading to tighter derivations. In addition, cost-constrained coding remains valid for continuous alphabets.
When a matched ML decoder $q(x, y) = W(y|x)$ is used, the matched Gallager $E_0$ functions \eqref{eqn:MatchediidGallagerFunction}--\eqref{eqn:MatchedccGallagerFunction}, are recovered from \eqref{eqn:E0IID}--\eqref{eqn:E0Cost} by setting $s=(1 + \rho)^{-1}$, hence recovering the matched error exponents.
Using Jensen's inequality \cite[Ch. 2]{ElementsOfInformationTheory}, it can be shown that for any pair $(W, q)$%
\begin{equation} \label{eqn:EriidLessThanErcc}
	E_\text{r}^{\text{iid}}(\QX, R)\le E_\text{r}^{\text{cc}}(\QX, R) .%
\end{equation}

