\section{Achievable Rates} \label{AchievableRatesUnderSmallMismatch}
In this section, we derive the worst-case LM and GMI rates.
For ease of explanation, we focus on the worst-case LM rate as the corresponding GMI can be obtained straightforwardly by setting $a(x)=0$ for all $x\in\Xc$.
We rewrite the mismatched information density $i_{s, a}$ in \eqref{eqn:i_sa_def_generic} with $q(x, y)=\widehat{W}(y|x)$ as%
\begin{equation}\label{eqn:i_sa_def}
i_{s, a}(x, y) = \log \frac{\widehat{W}(y|x)^s  e^{a(x)}}{\EX_{\QX} [\widehat{W}(y|X)^s e^{a(X)}]}.%
\end{equation}
The worst-case rate problem we wish to solve is%
\begin{align}\label{eqn:WorstCaseRateFormulation}
\underline{I}_{\text{\normalfont LM}}(\QX, \widehat{W}\!, r) &= \operatorname*{min}_{W \in \mathcal{B}} \operatorname*{sup}_{s \ge 0, a(\cdot)} \EX_{\QX{\times}W} [ i_{s,a}(X, Y)]
\end{align}
where the minimization is over all valid conditional probability distributions in the relative entropy ball $\mathcal{B}$ defined in \eqref{eqn:WorstCaseRatesConstraint}. Since the true channel is unknown, problem \eqref{eqn:WorstCaseRateFormulation} finds the channel in $\mathcal{B}$ that gives the worst possible LM rate. This gives an indication of the rate loss incurred by accurate but not perfect channel estimation.

Channels $W \in \mathcal{B}$ need to be valid conditional probability distributions, i.e., 
\begin{align} \label{eqn:Positivity1}
	W(y|x) \geq 0 &\quad \text{for} \quad (x,y) \in \mathcal{X}\times \mathcal{Y}\\ \label{eqn:Positivity2}
	\sum_{y} W(y|x) = 1 &\quad \text{for} \quad x \in \mathcal{X}.
\end{align}
The constraint $W(y|x) \leq 1$ for $(x,y) \in \mathcal{X}\times \mathcal{Y}$ is guaranteed by construction when \eqref{eqn:Positivity1}--\eqref{eqn:Positivity2} are satisfied.
Next, observe that imposing \eqref{eqn:Positivity1} in problem \eqref{eqn:WorstCaseRateFormulation} is unnecessary since the relative entropy in $\eqref{eqn:WorstCaseRatesConstraint}$ implies that positivity already for a strictly positive $\widehat{W}$.

\begin{theorem}\label{theorem:WorstCaseLMRate}
    Consider a class of DMCs $W(y|x)$, a mismatched decoder based on the channel estimate $\widehat{W}(y|x)$ and a fixed input distribution $\QX(x)$ satisfying \eqref{eqn:WorstCaseRatesConstraint}. Then, for a sufficiently small $r \ge 0$, the worst-case LM and GMI rates can be expressed as
    \begin{align}\label{eqn:FinalExpressionLMSmallMismatch}
    \underline{I}&_{\text{\normalfont LM}}(\QX, \widehat{W}\!, r) = \nonumber \\
    &{\operatorname*{sup}_{s\ge0, a(\cdot)}} \bigg\{ I_{s,a}^{\text{\normalfont ML}}(\QX, \widehat{W}) - \sqrt{2r V_{s,a}(\QX, \widehat{W}) } + o(\sqrt{r}) \bigg\} \\
    \underline{I}&_{\text{\normalfont GMI}}(\QX, \widehat{W}\!, r) = \nonumber\\
    &\ \operatorname*{sup}_{s\ge0} \bigg\{ I_{s,0}^{\text{\normalfont ML}}(\QX, \widehat{W}) - \sqrt{2r V_{s,0}(\QX, \widehat{W}) } + o(\sqrt{r}) \bigg\}
    \end{align}
    where%
    \begin{align}
        \label{eqn:AchievableRateMLDecodingLMRate}
        I^\text{\normalfont ML}_{s,a}(\QX, \widehat{W}) &\triangleq \EX_{\QX{\times}\widehat{W}} \big[i_{s,a}(X, Y)\big]\\
        V_{s,a}(\QX, \widehat{W}) &\triangleq \EX_{\QX} \big[ \VAR_{\widehat{W}}[i_{s,a}(X, Y) | X] \big].%
    \end{align}
\end{theorem}
\begin{proof}
	The full proof is provided in Appendix \ref{ProofLMRate}, where we minimize the dual expression for the LM rate \eqref{eqn:WorstCaseRateFormulation} including the $o(\cdot)$ term in \eqref{eqn:DKLapproximation} as a penalty in the objective function. This gives an accurate approximation to relative entropy \cite{EuclideanInformationTheory} and an accurate approximation on $\underline{I}_{\text{LM}}$ as $r\to 0$. The worst-case GMI rate is found by setting $a(x)=0$ for $x\in\Xc$.
\end{proof}

The following comments are in order from inspection of problem \eqref{eqn:WorstCaseRateFormulation}, Theorem \ref{theorem:WorstCaseLMRate} and its proof in Appendix \ref{ProofLMRate}:%
\begin{enumerate}[1)\IEEElabelindent=0em \labelsep=1pt]
	\item \textit{The solution for a chi-squared distance ball.}
	Let the small mismatch between the true and estimated channels $W$ and $\widehat{W}$ be characterized by a small radius chi-squared distance ball as%
	\begin{equation} \label{eqn:WorstCaseRatesConstraint2}
		W\! \in \tilde{\mathcal{B}}(\widehat{W}\!, r) \triangleq \big\{  P_{Y|X} \colon \!\tfrac{1}{2}\mathcal{X}^2( \QX P_{Y|X}\!, \QX \widehat{W}) {\le} r \big\}%
	\end{equation}
	where $\tfrac{1}{2}\mathcal{X}^2 ( \QX P_{Y|X}\!, \QX \widehat{W})$ as defined in \cite[Pag. 425]{BoundsMeasures} corresponds to the first term in \eqref{eqn:DKLapproximation}.	
	Then, the worst-case LM and GMI rates for sufficiently small $r\geq 0$ are exactly%
	\begin{align}
		\underline{\tilde{I}}_{\text{\normalfont LM}}&(\QX, \widehat{W}\!, r) = \nonumber\\
		&\operatorname*{sup}_{s\ge0, a(\cdot)} \bigg\{ I_{s,a}^{\text{\normalfont ML}}(\QX, \widehat{W}) - \sqrt{2r V_{s,a}(\QX, \widehat{W}) } \bigg\} \label{eqn:approxLMRate} \\	\underline{\tilde{I}}_{\text{\normalfont GMI}}&(\QX, \widehat{W}\!, r) = \nonumber \\
		&\operatorname*{sup}_{s\ge0} \bigg\{ I_{s,0}^{\text{\normalfont ML}}(\QX, \widehat{W}) - \sqrt{2r V_{s,0}(\QX, \widehat{W})} \bigg\} \label{eqn:approxGMI}
	\end{align}
	achieved for every fixed $s, a(x)$ by the channel distribution%
	\begin{align} 
		\tilde{W}_{\!s,a}^\ast(y|x) &= \widehat{W}(y|x) \Big( 1 - \sqrt{2r} \cdot \varphi_{s, a}(x, y) \Big) \label{eqn:optTrueWLM}
	\end{align}
	with%
	\begin{equation}\label{eqn:phi_def}
		\varphi_{s, a}(x, y) \triangleq \frac{i_{s,a}(x, y) - \EX_{\widehat{W}} [ i_{s,a}(x, Y) ] }{\sqrt{V_{s, a}(\QX, \widehat{W})}}.%
	\end{equation}	
	The worst-case channels $\tilde{W}_{\text{\normalfont LM}}^\ast, \tilde{W}_{\text{\normalfont GMI}}^\ast$ are found after maximizing \eqref{eqn:approxLMRate}--\eqref{eqn:approxGMI} over $s, a(x)$.	
	The key observation here is that the difference in the worst-case achievable rate for the mismatched compound channel with relative entropy or chi-squared distance balls is merely a little-$o$ term.

	\item \textit{Feasibility of worst-case channels}.
	In our proof, by shifting the $o(\cdot)$ term from the constraint to the objective function as a penalty term, we derive a more convenient and tractable mathematical analysis that yields valuable insights. However, one consequence of this shift is that the worst-case channels may have negative values, though this effect is absent for sufficiently small $r$.
	An additional condition on the ball radius $r$ must be satisfied to guarantee non-negativeness. From $1 - \sqrt{2r} \cdot \varphi_{s, a}(x, y) > 0$ for all $(x,y) \in \Xc {\times} \Yc$, we have:%
	\begin{equation}\label{eqn:r_pos}
		r < \min_{(x,y) \colon \varphi_{s,a}(x, y)>0}\ \frac{1}{2 \varphi_{s,a}(x, y)^2}.%
	\end{equation}
	$\tilde{W}_{\!s,a}^\ast(y|x) \leq 1$ for $(x,y) \in \Xc{\times}\Yc$ is satisfied by construction as \eqref{eqn:r_pos} guarantees non-negativity and $\sum_y\! \tilde{W}_{\!s,a}^\ast(y|x) = 1$.
	It is easy to show that the right-hand side of \eqref{eqn:r_pos} produces a positive value. We simply need to show that $\varphi_{s,a}(x, y)$ is finite everywhere $\widehat{W}(y|x)>0$, which can be easily shown by referring to equation \eqref{eqn:phi_def}. The only situation in which this condition would not be fulfilled is if $V_{s,a}=0$, which occurs only when $\widehat{W}(y|x)=|\Yc|^{-1}$, and for which $\underline{\tilde{I}}_{\text{\normalfont LM}}=0$. Therefore, it exists a sufficiently small $r$ that fulfills \eqref{eqn:r_pos}.
	Indeed, in all practical settings we have considered, the bound \eqref{eqn:r_pos} exceeds the ball radius of interest for the optimal $s,a(x)$ corresponding to the worst-case channels.

	\item \textit{The solution.} The worst-case channels are always found at the border of the respective ball, i.e., when \eqref{eqn:WorstCaseRatesConstraint} or \eqref{eqn:WorstCaseRatesConstraint2} holds with equality.

	\item \textit{Expansion term.} The expansions yield the same penalty term proportional to $\sqrt{r}$, the square root of the ball radius. These penalties indicate that even a small mismatch causes a severe penalty on the achievable rate.

	\item \label{Th1:5} \textit{Achievable rate at $r=0$.} For a fixed $\widehat{W}$, $\underline{I}_{\text{\normalfont LM}}$ \eqref{eqn:FinalExpressionLMSmallMismatch} is upper bounded by the mutual information of the estimated channel $\widehat{W}$ with input $\QX$, $I_{\text{\normalfont MI}}(\QX, \widehat{W})$. This is because  $\widehat{W} \in \mathcal{B}$ regardless of any $r\geq0$, so the minimum in \eqref{eqn:WorstCaseRateFormulation} can be upper bounded by evaluating at $W=\widehat{W}$. Hence%
	\begin{align} \label{eqn:FinalExpressionLMSmallMismatch0_1}
		\underline{I}_{\text{\normalfont LM}}(\QX, \widehat{W}\!, r)  &\leq \sup_{s \ge 0, a(\cdot)} I_{s,a}^{\text{\normalfont ML}}(\QX, \widehat{W})\\ \label{eqn:FinalExpressionLMSmallMismatch0_2}
		&= I_{\text{\normalfont MI}}(\QX, \widehat{W}),
	\end{align}
	and thus, information rates surpassing $I_{\text{\normalfont MI}}(\QX, \widehat{W})$ cannot be achieved. \eqref{eqn:FinalExpressionLMSmallMismatch0_1} is tight at $r=0$, where $\mathcal{B}=\{\widehat{W}\}$ and the supremum is achieved for $s=1$ and $a(x) = 0$ for $x\in \Xc$ \cite[Sec. IV-C]{6763080}. The same conclusions can be extracted for $\underline{\tilde{I}}_{\text{\normalfont LM}}$ defined in \eqref{eqn:approxLMRate}.

	\item \textit{Input-maximizing distribution.} Analysis of  \eqref{eqn:FinalExpressionLMSmallMismatch} reveals that although the first term is concave in $\QX$, the second term is not, though it is comparatively much smaller than the first, especially when $r\rightarrow0$. In this regime, $s=1$ and $a(x)=0$ are the optimal values, and therefore%
	\begin{align}
		\max_{\QX} \underline{I}_{\text{\normalfont LM}} \approx I_{1,0}(\QX^\ast, \widehat{W}) - \sqrt{2rV_{1,0}(\QX^\ast, \widehat{W})}
	\end{align} 
	where $I_{1,0}(\QX, \widehat{W}) = I_{\text{\normalfont  MI}} (\QX, \widehat{W})$ and%
	\begin{align}\label{eqn:QXoptdist}
		\QX^{\ast} \triangleq \argmax_{\QX} I_{\text{\normalfont  MI}} (\QX, \widehat{W})%
	\end{align}
	is the capacity-achieving distribution for channel $\widehat{W}$, which can be computed in a complexity efficient way via the Blahut-Arimoto algorithm \cite{1054753}. The approximation becomes tighter as $r\rightarrow0$, and holds with equality only at $r=0$, in which case%
	\begin{align}
		\max_{\QX} \underline{I}_{\text{\normalfont LM}}(\QX, \widehat{W}\!, 0) = \max_{\QX} I_{\text{\normalfont  MI}} (\QX, \widehat{W}).
	\end{align}
	The same conclusions can be extracted for $\underline{\tilde{I}}_{\text{\normalfont LM}}$ in \eqref{eqn:approxLMRate}.

	\item \label{Th1:7}\textit{Lower bound on $\underline{\tilde{I}}_{\text{\normalfont LM}}$ and $\underline{\tilde{I}}_{\text{\normalfont GMI}}$.} The worst-case rates \eqref{eqn:approxLMRate}--\eqref{eqn:approxGMI} can be lower-bounded by setting $s=1$ and $a(x)=0$ for every input as%
	\begin{align} \label{eqn:LowerBoundWorstCaseRates1}
		\underline{\tilde{I}}_{\text{\normalfont LM}}(\QX, \widehat{W}\!, r) 
		&\ge \underline{\tilde{I}}_{\text{\normalfont GMI}}(\QX, \widehat{W}\!, r) \\
		&\ge I_{\text{\normalfont MI}}(\QX, \widehat{W}) - \sqrt{2r V_{1, 0}(\QX, \widehat{W}) }. \label{eqn:LowerBoundWorstCaseRates2}
	\end{align}
	 As $r \to 0$ the penalty term shrinks until $I_{\text{\normalfont MI}}(\QX, \widehat{W})$ is achieved. The bound is tight at $r=0$. It allows the evaluation of the gain of introducing $s\ge0$ before applying Markov's inequality in the achievability proof \cite{Foundations}.
\end{enumerate}

\subsection{Example: Symmetric $\widehat{W}$ and Equiprobable $\QX$} \label{RateEgSymChannel}
We derive the worst-case GMI for a symmetric $\widehat{W}$ and a equiprobable input distribution $\QX(x) = |\Xc|^{-1}$ for $x\in\Xc$. This combination could be used when $W$ is close to being symmetric.
Symmetry is defined as Gallager \cite[Pag. 94]{GallagerWiley1968}, i.e. when each row or column of $\widehat{W}$ is a permutation of each other row or column, respectively.
We show the final results here; the complete derivations are found in Appendix \ref{ProofDiscreteSymmetricChannel}.

The worst-case GMI in \eqref{eqn:approxGMI} can be simplified due to the symmetry of $\widehat{W}$. Specifically, the magnitudes in \eqref{eqn:approxGMI} can be expressed using the first row of $\widehat{W}$, $\widehat{W}_{\text{sym}}(y)\triangleq W(y|x_1)$, as%
\begin{align}\label{eqn:worst_gmi_additive_channel}
I_{s,0}^{\text{\normalfont ML}}(\QX, \widehat{W}) &= \log \frac{|\Xc|}{{\sum_y} \widehat{W}_{\text{sym}}(y)^s} - sH(\widehat{W}_{\text{sym}})\\ \label{eqn:worst_gmi_additive_channel_V}
V_{s,0}(\QX, \widehat{W}) &= s^2 \Big( \EX_{\widehat{W}_{\text{sym}}}[ \log^2 \widehat{W}_{\text{sym}}] - H^2(\widehat{W}_{\text{sym}}) \Big)%
\end{align}
where $H(\widehat{W}_{\text{sym}})$ is the entropy of the random variable characterized by the probability mass function $\widehat{W}_{\text{sym}}$.

Next, we present two additional insightful results.
One of the most curious findings of this case study is that the worst-case channel in the chi-squared distance ball $\tilde{\mathcal{B}}$ defined in \eqref{eqn:WorstCaseRatesConstraint2} has the same structure as $\widehat{W}$, i.e. $\tilde{W}^*_{\text{\normalfont GMI}}$ is also a symmetric DMC and is independent of $s$. This suggests two key points. Firstly, adding $a(x)$ does not offer any advantage, and thus i.i.d. and constant-composition achieve the same rate, as for output-symmetric channels and metrics \cite[Ch. 2.4.2]{Foundations}. Secondly, for a scenario where the channel is known to be symmetric but unknown, the worst-case channel in $\tilde{\mathcal{B}}$, when considering only channels with the same structure as $\widehat{W}$, leads to the same solution we obtained.

The next result arises from applying the bounds in point \ref{Th1:7}) after Theorem \ref{theorem:WorstCaseLMRate}. Specifically, the worst-case GMI rate can be lower bounded by setting $s=1$ to yield%
\begin{align}
	 \underline{\tilde{I}}_{\text{\normalfont GMI}}(\QX, \widehat{W}\!, r) \geq C({\widehat{W}}) - \sqrt{2 r \VAR_{\widehat{W}_{\text{sym}}}[\log \widehat{W}_{\text{sym}}]},%
\end{align}
where $C({\widehat{W}}) \triangleq \log |\Xc| {-} H(\widehat{W}_{\text{sym}})$ is the capacity of DMC $\widehat{W}$. The bound becomes tighter as $r\rightarrow0$.

\subsection{Example: Modulo-additive $\widehat{W}$ and Equiprobable $\QX$}
Further results can be obtained even in a more closed form for the specific case of a modulo-additive $\widehat{W}$ by particularizing  \eqref{eqn:worst_gmi_additive_channel}--\eqref{eqn:worst_gmi_additive_channel_V} for the  channel estimate%
\begin{equation} \label{eqn:additive_What}
	\widehat{W} = {\begin{bmatrix}
        \bar{p} & p & \cdots & p \\
        p & \bar{p} & \cdots & p \\
        \vdots & \vdots & \ddots & \vdots \\
        p & p & \cdots & \bar{p}
    \end{bmatrix}}
\end{equation}
with $p\in [ 0, |\Xc|^{-1} ]$ and $\bar{p} \triangleq 1- (|\Xc|{-}1)p \ge p$ defined for compactness of notation.

In this case, we have%
\begin{align}
	I_{s,0}^{\text{\normalfont ML}}(\QX, \widehat{W}) &= \log \frac{|\Xc|}{{\bar{p}}^s + (1-\bar{p})p^{s-1}} \nonumber \\
	& \hspace{3em} + s ( \bar{p}\log \bar{p} + (1-\bar{p}) \log p )\\
	V_{s,0}(\QX, \widehat{W}) &= s^2 \cdot \bar{p}(1-\bar{p}) \log^2 ( \bar{p}/p )%
\end{align}
and the worst-case channel in $\tilde{\mathcal{B}}$ is a modulo-additive DMC with crossover probabilities%
\begin{align}
	q=p \left(1+\sqrt{2r} \cdot \sqrt{ \frac{\bar{p}}{1-\bar{p}}} \right).%
\end{align}
The feasibility condition \eqref{eqn:r_pos} leads to $r < \tfrac{1}{2}\tfrac{\bar{p}}{1 - \bar{p}}$. The worst-case bound $r < \tfrac{1}{2}\tfrac{1}{|\Xc| {-} 1}$ is achieved when $p = \tfrac{1}{|\Xc|}$.

