\section{Error Exponents} \label{ErrorExponentsUnderSmallMismatch}
In this section, we study the worst-case mismatched random coding error exponents%
\begin{align}
    \underline{E}_\text{r}^{\text{iid}}(\QX, \widehat{W}\!, R, r) &= \operatorname*{min}_{W \in \mathcal{B}}\operatorname*{max}_{\rho \in [0,1]} E_0^{\text{iid}}(\QX,W\!, \rho) - \rho R\\
    \underline{E}_\text{r}^{\text{cc}}(\QX, \widehat{W}\!, R, r) &= \operatorname*{min}_{W \in \mathcal{B}}\operatorname*{max}_{\rho \in [0,1]} E_0^{\text{cc}}(\QX, W\!, \rho) - \rho R
\end{align}
where%
\begin{align}\label{eq:e0iid}
E_0^{\text{iid}}(\QX, W\!, \rho)&\triangleq\ \operatorname*{sup}_{s \ge 0} 	E_{s, \zerov, \zerov,\rho}(\QX,W)\\
E_0^{\text{cc}}(\QX, W\!, \rho)&\triangleq \operatorname*{sup}_{c_1(\cdot), c_2(\cdot)}\operatorname*{sup}_{s \ge 0, \lv, \bar{\lv}}\! E_{s, \lv, \bar{\lv},\rho}(\QX,W) \label{eq:e0cc}%
\end{align}
and%
\begin{align}
	E_{s, \lv, \bar{\lv},\rho}(\QX,W) &\triangleq - \log \EX_{\QX{\times}W} [\varepsilon_{s, \lv, \bar{\lv},\rho}(X,Y)],
\end{align}
where we have redefined the \emph{mismatched exponent density} as a function of the channel estimate as%
\begin{align}\label{eq:exponent_density}
	\varepsilon_{s, \lv, \bar{\lv},\rho}(x, y) &\triangleq \bigg( \frac{\EX_{\QX} [\widehat{W}(y|X)^s e^{\bar\lv^{\!T\!} (\cv(X)-\pv)}]}{\widehat{W}(y|x)^s e^{{\lv}^{\!T\!} (\cv(x)-\pv)}} \bigg)^\rho\!.%
\end{align}
We aim to find the worst-case mismatched random coding error exponents $\underline{E}{}_{\text{r}}^{\text{iid}}$ and $\underline{E}{}_{\text{r}}^{\text{cc}}$ subject to Definition \ref{def:small_mismatch}. The following lemma serves as a preliminary to our main theorems.

\begin{lemma}
\label{lemma:ExponentEquivalentToGallagerFunction}
Finding the worst-case mismatched random coding error exponent is equivalent to first finding its corresponding worst-case Gallager function, i.e.,
\begin{align}
\underline{E}_{\mathrm{r}}(\QX, \widehat{W}\!, R, r) = \operatorname*{max}_{\rho \in [0,1]} \operatorname*{min}_{W \in \mathcal{B}} E_0(\QX, W\!, \rho) - \rho R.
\end{align}
\end{lemma}
\begin{proof}
The worst-case error exponent $\underline{E}_{\text{r}}(\QX, \widehat{W}\!, R, r)$ is%
\begin{align}
    \underline{E}_{\text{r}} (\QX, \widehat{W}\!, R, r)
\label{eqn:ExponentMinMax}
    &= \operatorname*{min}_{W \in \mathcal{B}}  \operatorname*{max}_{\rho \in [0,1]} E_0(\QX, W\!, \rho) - \rho R \\
    &= \operatorname*{max}_{\rho \in [0,1]} \operatorname*{min}_{W \in \mathcal{B}} E_0(\QX, W\!, \rho) - \rho R,
\label{eqn:ExponentMax}
\end{align}
where, as the problem is concave in $\rho\in[0,1]$ and convex in $W\in\mathcal{B}$, the minimax theorem \cite[Th. 1]{Minimax} has been used to swap the order of the optimizations from \eqref{eqn:ExponentMinMax} to \eqref{eqn:ExponentMax}. Fixing $(\QX, R)$ and noticing that $\rho R$ is independent of $W$, the problem is then equivalent to minimizing $E_0$ prior to maximizing over $\rho\in[0,1]$. 
\end{proof}

Consequently, we focus on deriving the worst-case mismatched Gallager $E_0$ functions for i.i.d. and constant-composition codes%
\begin{align} \label{eqn:WorstCaseE0iid}
	\underline{E}{}_0^{\text{iid}}(\QX, \widehat{W}\!, \rho, r) = \operatorname*{min}_{W \in \mathcal{B}} &\ \operatorname*{sup}_{s \ge 0}\ E_{s,\zerov,\zerov,\rho}(\QX,W)\\
	\label{eqn:WorstCaseE0cc}
	\underline{E}{}_0^{\text{cc}}(\QX, \widehat{W}\!, \rho, r) = \operatorname*{min}_{W \in \mathcal{B}}&\ \operatorname*{sup}_{c_1\!(\cdot), c_2\!(\cdot)} \nonumber\\ 
	&\ \operatorname*{sup}_{s \ge 0, \lv, \bar{\lv}} E_{s, \lv, \bar{\lv},\rho}(\QX,W).%
\end{align}
We describe the results together in the following theorem. The corresponding worst-case error exponents need to be computed by maximizing over $\rho\in[0,1]$ afterwards, but they are not included herein for ease of readability.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}\label{theorem:WorstCaseE0}
     Consider a class of DMCs $W(y|x)$, a mismatched decoder based on the channel estimate $\widehat{W}(y|x)$ and a fixed input distribution $\QX(x)$ satisfying \eqref{eqn:WorstCaseRatesConstraint}. Then, for sufficiently small $r \ge 0$, the worst-case mismatched Gallager function for i.i.d. and constant-composition random coding can be expressed as%
    \begin{align}
    	\underline{E}_0^{\text{\normalfont iid}}(\QX&, \widehat{W}\!, \rho, r) = \operatorname*{sup}_{s\ge0} \bigg\{ E_{s, \zerov, \zerov, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\
    	&-\log \bigg( 1 + \sqrt{2 r V_{s, \zerov, \zerov, \rho}(\QX, \widehat{W})} \bigg) + o(\sqrt{r}) \bigg\}     \label{eqn:FinalExpressioniidExponentSmallMismatch}\\
        \underline{E}_0^{\text{\normalfont cc}}(\QX&, \widehat{W}\!, \rho, r) = \operatorname*{sup}_{c_1\!(\cdot), c_2\!(\cdot)}\operatorname*{sup}_{s \ge 0, \lv, \bar{\lv}} \bigg\{ E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\
        &- \log \bigg(1+\sqrt{2r V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W}) } \bigg)+ o(\sqrt{r}) \bigg\} \label{eqn:FinalExpressionCcExponentSmallMismatch}
    \end{align}
    where%
    \begin{align}
    	\label{eqn:MLDecodingiidExponent}
    	E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) &\triangleq - \log \EX_{\QX{\times}\widehat{W}} [ \varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y) ]\\
    	\label{eqn:V_functionEps}
	    V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W}) &\triangleq \frac{\EX_{\QX} \big[ \text{\normalfont Var}_{\widehat{W}}[\varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y) | X] \big]}{\EX_{\QX{\times}\widehat{W}}^2[\varepsilon_{s, \lv, \bar{\lv},\rho}(X,Y)]}.%
    \end{align}
\end{theorem}
\begin{proof}
The proof is found in Appendix \ref{ProofiidGallagerFunction} and follows similar steps as the worst-case LM rate in Appendix \ref{ProofLMRate}.
\end{proof}

\begin{corollary}
    For sufficiently small $r$, the worst-case mismatched Gallager functions can be expanded as%
    \begin{align} 
        \underline{E}_0^{\text{\normalfont iid}}(\QX, \widehat{W}\!, \rho, r) &= \operatorname*{sup}_{s\ge0} \bigg\{ E_{s, \zerov, \zerov, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\ &- \sqrt{2 r V_{s, \zerov, \zerov, \rho}(\QX, \widehat{W})} + o(\sqrt{r}) \bigg\}     \\ \label{eqn:trueE0cc}
        \underline{E}_0^{\text{\normalfont cc}}(\QX, \widehat{W}\!, \rho, r) &= \operatorname*{sup}_{c_1\!(\cdot), c_2\!(\cdot)}\operatorname*{sup}_{s \ge 0, \lv, \bar{\lv}} \bigg\{ E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber \\ &- \sqrt{2r V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W})} + o(\sqrt{r}) \bigg\}
    \end{align}
\end{corollary}
\begin{proof}
	The expressions come from a first-order Puiseux series expansion of \eqref{eqn:FinalExpressioniidExponentSmallMismatch}--\eqref{eqn:FinalExpressionCcExponentSmallMismatch} around $r=0$. The expansions incur an error of order $O(r)$ that is absorbed in $o(\sqrt{r})$ as the latter dominates the summation for small $r\geq 0$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The following observations are in order:%
\begin{enumerate}[1)\IEEElabelindent=0em \labelsep=1pt]
	\item \textit{The solution for a chi-squared distance ball.}	The worst-case mismatched $E_0$ functions for a small mismatch given by a chi-squared distance ball as defined in \eqref{eqn:WorstCaseRatesConstraint2} are exactly%
	\begin{align}\label{eqn:approxE0iid}
		\underline{\tilde{E}}{}_0^{\text{\normalfont iid}}(\QX, \widehat{W}\!&, \rho, r) = \operatorname*{sup}_{s\ge0} \bigg\{ E_{s, \zerov, \zerov, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\
		&-\log \bigg( 1 + \sqrt{2 r V_{s, \zerov, \zerov, \rho}(\QX, \widehat{W})} \bigg) \bigg\}  \\ \label{eqn:approxE0cc}
		\underline{\tilde{E}}{}_0^{\text{\normalfont cc}}(\QX, \widehat{W}\!&, \rho, r) = \operatorname*{sup}_{c_1\!(\cdot), c_2\!(\cdot)}\operatorname*{sup}_{s \ge 0, \lv, \bar{\lv}} \bigg\{ E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\ 
		&- \log \left(1+\sqrt{2r V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W}) } \right) \!\bigg\}
	\end{align}
	achieved for fixed $s, \lv, \bar{\lv}, c_1(\cdot), c_2(\cdot)$ by the channel distribution%
	\begin{align}
		\label{eqn:optTrueWE0cc}
		\tilde{W}_{\!s,\lv,\bar{\lv}}^\ast(y|x) =\ &\widehat{W}(y|x) \nonumber \\
		&\cdot \left(1 + \frac{\sqrt{2r} \cdot\varphi_{s, \lv, \bar{\lv}, \rho}(x, y)}{\EX_{\QX{\times}\widehat{W}}[\varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y)]} \right)%
	\end{align}
	with%
	\begin{equation}
		\varphi_{s, \lv, \bar{\lv}, \rho}(x, y) \triangleq \frac{\varepsilon_{s, \lv, \bar{\lv}, \rho}(x,y) - \EX_{\widehat{W}}[\varepsilon_{s, \lv, \bar{\lv}, \rho}(x,Y)]}{\sqrt{V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W})} }.
	\end{equation}
	The worst-case channels $\tilde{W}_{\text{\normalfont iid}}^\ast, \tilde{W}_{\text{\normalfont cc}}^\ast$ are found after maximizing \eqref{eqn:approxE0iid}--\eqref{eqn:approxE0cc} over $s, \lv, \bar{\lv}, c_1(\cdot), c_2(\cdot)$. 

	\item \textit{Feasibility of worst-case channels.} Similarly to what we did for the worst-case achievable rates, the following condition over the ball radius needs to be satisfied to guarantee non-negativity of the obtained distributions:%
	\begin{equation}
		r < \min_{(x,y)\colon \varphi_{s,\lv,\bar{\lv},\rho}(x, y)>0}\ \frac{1}{2 \varphi_{s,\lv,\bar{\lv},\rho}(x, y)^2}.%
	\end{equation}

	\item \textit{The solution.} The worst-case channels are always found at the border of the respective ball, i.e., when \eqref{eqn:WorstCaseRatesConstraint} or \eqref{eqn:WorstCaseRatesConstraint2} holds with equality.

	\item \textit{Expansion term.} The expansion yields a penalty term proportional to $\sqrt{r}$ at most. This indicates that even a small mismatch causes a severe penalty on the $E_0$ function and thus on the error exponent.

	\item \textit{Achievable $E_0$ function at $r=0$.} For a fixed $\widehat{W}$,%
	\begin{equation} 
		\underline{E}{}_0^{\text{cc}}(\QX, \widehat{W}\!, \rho, r) \leq\!\! \operatorname*{sup}_{c_1\!(\cdot), c_2\!(\cdot)}\operatorname*{sup}_{s \ge 0, \lv, \bar{\lv}}\!\! E_{s, \lv, \bar{\lv},\rho}^{\text{ML}}(\QX,\widehat{W})
	\end{equation}
	coinciding with the matched Gallager function for channel $\widehat{W}$. The proof follows because $\widehat{W} \in \mathcal{B}$ for any $r\ge0$, so the minimum in \eqref{eqn:WorstCaseE0cc} can be upper bounded by evaluating at $W=\widehat{W}$. The bound is tight at $r=0$ as $\mathcal{B}=\{\widehat{W}\}$.	

	\item \textit{$E_0$ function at $\rho=0$.} The worst-case LM and GMI rates cannot be obtained by differentiating the worst-case $E_0$ functions and evaluating at $\rho=0$. This is in contrast to what occurs for $r=0$, making our separate analysis of achievable rates and error exponents highly relevant.
\end{enumerate}

