\section{Continuous Alphabets}
\label{ContinuousChannels}
In this section, we extend the study of  worst-case achievable rates and Gallager $E_0$ functions to continuous-alphabet channels by allowing the alphabets $\Xc$ and $\Yc$ to take infinite values. Specifically, our focus is on $\Xc = \Yc = \mathbb{R}$. We use $\QX(x)$ and $W(y|x)$ to denote the continuous probability input and channel distributions, respectively, and redefine small mismatch for continuous-alphabet channels as follows. 
\begin{definition} \label{def:small_mismatch_cont}
	For small mismatch (ball radius) between the continuous-alphabet channels $W$ and $\widehat{W}$, we require that%
	\begin{align}\label{eqn:Def2}
		W \in \mathcal{B} = \{ P_{Y|X} \in \mathcal{S} \colon \DKL(\widehat{W}\|P_{Y|X}|\QX) \leq r \}
	\end{align}
	holds for small $r$, where $\mathcal{S}$ is a function space admitting  probability density functions $P_{Y|X}(y|x)$ over $(x,y) \in \mathbb{R}^2$, and $\DKL(\widehat{W}\|P_{Y|X}|\QX)$ defines the conditional relative entropy in integral form as%
	\begin{equation}
		\DKL(\widehat{W} \| P_{Y|X} | \QX) \triangleq\! {\iint} \QX(x) \widehat{W}(y|x)\! \log\! \frac{\widehat{W}(y|x)}{P_{Y|X}(y|x)} \DD x \DD y.%
	\end{equation}
\end{definition}
We analyze both i.i.d. and cost-constrained codes since constant-composition random coding is undefined for continuous alphabets.
As we shall see, most of the previous expressions of information rates and $E_0$ functions remain invariant, by substituting probability distributions with the corresponding probability densities and summations with integrals. The novelty is that the formulation of the continuous case allows for unprecedented closed-form results for the nearest neighbor decoder that further extend \cite{lapidoth1998reliable,Foundations,532892}.

%%%%%%%%%%%%%%%%%%%%%%
\subsection{i.i.d. Random Coding}
For i.i.d. random coding, the mismatched information density and mismatched exponent density are defined as
\begin{align}
	i_s(x,y) &\triangleq \log \frac{\widehat{W}(y|x)^s}{{\int} \QX(\bar{x}) \widehat{W}(y|\bar{x})^s\DD \bar{x}}\\
	\varepsilon_{s, \rho}(x, y) &\triangleq  \bigg( \frac{{\int} \QX(\bar{x}) \widehat{W}(y|\bar{x})^s \DD \bar{x}}{\widehat{W}(y|x)^s} \bigg)^\rho,%
\end{align}
where we have expressed expectations in integral form for reasons of emphasis.

We want to solve the following problems to determine the worst-case GMI and $E_0$ function:
\begin{align}\label{eqn:Cont:WorstCaseRateFormulation}
\underline{I}_{\text{\normalfont GMI}}&(\QX, \widehat{W}\!, r) = \operatorname*{min}_{W \in \mathcal{B}}\ \operatorname*{sup}_{s \ge 0}\ \EX_{\QX{\times}W} [ i_{s}(X, Y)]\\
\underline{E}{}_0^{\text{iid}}&(\QX, \widehat{W}\!, r) = \operatorname*{min}_{W \in \mathcal{B}}\ \operatorname*{sup}_{s \ge 0} -\log \EX_{\QX{\times}W} [\varepsilon_{s,\rho}(X, Y)]%
\label{eqn:Cont:WorstCaseRateFormulationExp}
\end{align}
Their solutions are particular cases of cost-constrained random coding, and are thus described below.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Cost-Constrained Random Coding}
We study codebooks in which, unlike i.i.d. random coding, codewords are constrained to satisfy multiple per-codeword cost functions \cite{6763080}.
Specifically, we consider codebooks in which each codeword $\xv^{(m)}$ satisfies%
\begin{align}\label{eqn:Cont:c0}
	\frac{1}{n} \sum_{i=1}^n c_0(x_i^{(m)}) &\leq P\\\label{eqn:Cont:cl}
	\bigg\vert \frac{1}{n} \sum_{i=1}^n c_\ell(x_i^{(m)}) - \phi_\ell \bigg\vert & \leq \frac{\delta}{n} \quad, \quad \ell={1, \dots, L}%
\end{align}
where $\phi_\ell \triangleq \EX[c_\ell(X)]$ for $\ell=1,\dotsc, L$ and $\delta>0$.
Observe that these input cost functions might be related to the channel having an input cost constraint $c_0(\cdot)$, or might be design cost constraints that allow us to shape codewords in a certain way as  for the cost functions $c_{\ell}(\cdot)$ for $\ell=1,\dotsc, L$.

The corresponding mismatched information and exponent densities now read%
\begin{align}\label{eqn:Cont:FormulationCC_is}
	i_{s,\lv}(x,y) &\triangleq \log \frac{\widehat{W}(y|x)^s e^{\lv^{\!T\!} \cv(x)}}{{\int} \QX(\bar{x}) \widehat{W}(y|\bar{x})^s e^{\lv^{\!T\!}\cv(\bar{x})} \DD \bar{x}}
	\\ \label{eqn:Cont:FormulationCC_E0}
	\varepsilon_{s, \lv, \bar{\lv}, \rho}(x, y) &\triangleq  \bigg(\! \frac{{\int} \QX(\bar{x}) \widehat{W}(y|\bar{x})^s e^{\bar\lv^{\!T\!} (\cv(\bar{x})-\pv)} \DD \bar{x}}{\widehat{W}(y|x)^s e^{{\lv}^{\!T\!} (\cv(x)-\pv)}} \bigg)^{\!\rho}%
\end{align}
where we have defined the following vectors to denote  compactly the cost functions and corresponding weights:
\begin{align}
	\cv(x) &\triangleq \begin{bmatrix}
		c_0(x), c_1(x), \dotsc, c_L(x)
	\end{bmatrix}^T\\
	\pv &\triangleq \begin{bmatrix}
		P, \phi_1, \dotsc, \phi_L
	\end{bmatrix}^T\\
	\lv &\triangleq
	\begin{bmatrix}
		\lambda_0, \lambda_1, \dotsc, \lambda_L
	\end{bmatrix}^T %\quad \text{with} \quad \lambda_0\ge0, \lambda_\ell\in\RR,~ \ell=1,\dotsc,L
	\\
	\bar{\lv} &\triangleq
	\begin{bmatrix}
		\bar{\lambda}_0, \bar{\lambda}_1, \dotsc, \bar{\lambda}_L
	\end{bmatrix}^T% \quad \text{with} \quad \bar{\lambda}_0\ge0, \bar\lambda_\ell\in\RR,~ \ell=1,\dotsc,L.
\end{align}
with $\lambda_0,\bar\lambda_0\geq0$ and $\lambda_\ell,\bar\lambda_\ell\in\RR$ for $\ell=1,\dotsc,L$.
The problems we want to solve are%
\begin{align}\label{eqn:Cont:FormulationCost_is}
	\underline{I}_{\text{\normalfont cost}}(\QX&, \widehat{W}\!, r) = \operatorname*{min}_{W \in \mathcal{B}}\  \operatorname*{sup}_{s \ge 0, \lv} \EX_{\QX{\times}W} [ i_{s, \lv}(X, Y)]
	\\\label{eqn:Cont:FormulationCost_E0}
	\underline{E}{}_0^{\text{cost}}(\QX&, \widehat{W}\!, r) = \nonumber\\
	&\operatorname*{min}_{W \in \mathcal{B}} \operatorname*{sup}_{s \ge 0, \lv, \bar{\lv}} -\log \EX_{\QX{\times}W} [\varepsilon_{s,\lv,\bar{\lv},\rho}(X, Y)].%
\end{align}
The main difference with respect to the i.i.d. case is the need to further optimize over vectors $\lv,\bar{\lv}$. Note that \eqref{eqn:Cont:WorstCaseRateFormulation}--\eqref{eqn:Cont:WorstCaseRateFormulationExp} can be obtained from \eqref{eqn:Cont:FormulationCost_is}--\eqref{eqn:Cont:FormulationCost_E0} by setting $\lv=\bar{\lv}=\zerov$. The following theorem provides the solutions to all problems.

\begin{theorem}\label{theorem:CCcontinuous}
	Consider a family of continuous-alphabet channels $W(y|x)$, a mismatched decoder based on the channel estimate $\widehat{W}(y|x)$ and a fixed input distribution $\QX(x)$ satisfying \eqref{eqn:Def2}. Then, for every $r \ge 0$ sufficiently small:

	(i) the worst-case achievable rates for cost-constrained and i.i.d. random coding can be expressed as%
	\begin{align}
	\underline{I}_{\text{\normalfont cost}}(\QX, \widehat{W}\!, r) =\ & \operatorname*{sup}_{s\ge0, \lv} \bigg\{ I_{s, \lv}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\
	&- \sqrt{2r V_{s, \lv}(\QX, \widehat{W}) } + o(\sqrt{r}) \bigg\}\\
	\underline{I}_{\text{\normalfont GMI}}(\QX, \widehat{W}\!, r) =\ & \operatorname*{sup}_{s\ge0} \bigg\{ I_{s,\zerov}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\
	&- \sqrt{2r V_{s, \zerov}(\QX, \widehat{W})} + o(\sqrt{r}) \bigg\}
	\end{align}
	where%
	\begin{align}
		I^\text{\normalfont ML}_{s, \lv}(\QX, \widehat{W}) &\triangleq \EX_{\QX{\times}\widehat{W}} \big[i_{s,\lv}(X, Y)\big]\\
		V_{s, \lv}(\QX, \widehat{W}) &\triangleq \EX_{\QX} \big[ \text{\normalfont Var}_{\widehat{W}}[i_{s,\lv}(X, Y) | X] \big].
	\end{align}

	(ii) the worst-case mismatched $E_0$ functions for cost-constrained and i.i.d. random coding can be expressed as%
	\begin{align}	 \label{eqn:cont:FinalExpressionCostExponent}
	\underline{E}_0^{\text{\normalfont cost}}&(\QX, \widehat{W}\!, \rho, r) = \operatorname*{sup}_{s\ge0,\lv, \bar{\lv}} \bigg\{ E_{s,\lv,\bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\
	&- \log \bigg( 1+ \sqrt{2 r V_{s,\lv,\bar{\lv},\rho}(\QX, \widehat{W})}\bigg) +o(\sqrt{r}) \bigg\}\\
	\underline{E}_0^{\text{\normalfont iid}}&(\QX, \widehat{W}\!, \rho, r) = \operatorname*{sup}_{s\ge0} \bigg\{ E_{s,\zerov,\zerov, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W})\nonumber\\ 
	&- \log \bigg( 1+ \sqrt{2 r V_{s,\zerov,\zerov,\rho}(\QX, \widehat{W})} \bigg) +o(\sqrt{r}) \bigg\} 
	\label{eqn:cont:FinalExpressioniidExponent}
	\end{align}
	where%
	\begin{align}
		\label{eqn:Cont:MLDecodingiidExponent}
		E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) &\triangleq -\log \EX_{\QX{\times}\widehat{W}} \big[\varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y)\big]\\
		V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W}) &\triangleq \frac{\EX_{\QX} \big[ \text{\normalfont Var}_{\widehat{W}}[\varepsilon_{s, \lv, \bar{\lv},\rho}(X, Y) | X] \big]}{\EX_{\QX{\times}\widehat{W}}^2[\varepsilon_{s, \lv, \bar{\lv}, \rho}(X,Y)]}.
	\end{align}
%The bounds are tight as $r\rightarrow0$.
\end{theorem}
\begin{proof}
	The solution to worst-case achievable rates is found by resorting to the calculus of variations \cite{gelfand2000calculus}; see Appendix \ref{App:ProofCont} for the proof. The worst-case mismatched Gallager $E_0$ function is a reformulation of the worst-case achievable rates, as shown in Appendix \ref{ProofiidGallagerFunction}, followed by the steps in Appendix \ref{App:ProofCont}.
\end{proof}
%In the following, we discuss two examples of application of the above results to nearest neighbor decoding.%

%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Example: Gaussian Codebooks and Nearest Neighbor Decoding for Arbitrary Continuous-Alphabet Channels}
We next study the nearest neighbor decoder when combined with Gaussian inputs by particularizing the above results to the estimated channel $\widehat{W}(y|x)=\mathcal{N}(y{-x};\hat{\sigma}^2)$ and input distribution $\QX(x)=\mathcal{N}(x;P)$.
We make no additional assumption on the nature of the memoryless channel, other than being in a relative entropy ball of radius $r$ centered at the nearest neighbor decoder.
Appendix \ref{app:aux} details the specific computations; here we only show the final results.

\subsubsection{Gaussian i.i.d. codebooks}
the worst-case GMI rate can be expressed as%
\begin{align} \label{eqn:Cont:Igmi_opt}
	\underline{{I}}_{\text{\normalfont GMI}}(\QX,\widehat{W}\!, r) =\ & \sup_{s \ge 0} \Bigg\{ \frac{1}{2} \log\left(1+s\Gamma\right) + \frac{\Gamma(1-s)}{2(s^{-1}+\Gamma)} 
	\nonumber \\
	&- \sqrt{r \cdot \frac{\Gamma(2+s^2\Gamma)}{(s^{-1} + \Gamma)^2}} + o(\sqrt{r}) \Bigg\}%
\end{align}
where $\Gamma \triangleq P/\hat{\sigma}^2$ denotes the estimated signal-to-noise ratio assuming an additive noise structure even if the channels in $\mathcal{B}$ are not necessarily additive.

Moreover, as $r\rightarrow 0$ \eqref{eqn:Cont:Igmi_opt} is dominated by the first two terms, for which $s=1$ is the optimal value and thus \eqref{eqn:Cont:Igmi_opt} can be accurately approximated as%
\begin{align} \label{eqn:Cont:Igmi_opt_approx}
\underline{{I}}_{\text{\normalfont GMI}}(\QX,\widehat{W}\!,r) &\approx \frac{1}{2} \log\left(1+\Gamma\right) - \sqrt{r \cdot \frac{ \Gamma(2+\Gamma)}{(1+\Gamma)^2}}.%
\end{align}
Intuitively, information rates close to second order coding rates can be achieved when the true channel is close to a Gaussian channel in terms of relative entropy. 
This approximation, aided by \eqref{eqn:Cont:Igmi_opt}, helps quantify the gain of the parameter $s\ge0$. Fig. \ref{fig:cont} presents a numerical example of this gain.

A similar analysis  can be performed for the worst-case Gallager $E_0$ function (see Appendix \ref{app:exp_gauss} for details). The corresponding terms in the approximation are given by
\begin{align}
	E_{s, \zerov, \zerov, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) &= \frac{\rho}{2}  \log(1+\Gamma s) \nonumber\\
	&+ \frac{1}{2} \log\! \left(\! 1+ \frac{\rho \Gamma (1-s-\rho s)}{\Gamma+s^{-1}}\! \right)
\end{align}
and%
\begin{align}
	V_{s,\zerov,\zerov,\rho}(\QX, \widehat{W}) &= \frac{1}{\sqrt{\Gamma{+}s^{-1}}} \frac{\Gamma{+} s^{-1} + \rho \Gamma(1{-}s{-}\rho s)}{\!\sqrt{\Gamma{+}s^{-1} + 2\rho \Gamma (1{-} s {-} 2\rho s)}} \nonumber\\
	&- \frac{\sqrt{2}}{\rho s} \frac{\Gamma{+}s^{-1} + \rho \Gamma(1{-}s{-}\rho s)}{\Gamma{+} s^{-1} + \rho \Gamma (2{-}s{-}2\rho s)}.
\end{align}

\subsubsection{Gaussian spherical codebooks}
when codewords satisfy the per-codeword power constraint \eqref{eqn:Cont:c0} with $c_0(x) = x^2$, we have the following achievable rate%
\begin{align} \label{eqn:Cont:Icost_opt}
	\underline{{I}}_{\text{\normalfont cost}}(\QX&,\widehat{W}\!, r) = \sup_{s \ge 0, \lambda \geq 0} \Bigg\{ \frac{1}{2} \log\left(g(\Gamma)+s\Gamma\right) \nonumber\\
	&+ \frac{\Gamma(1{-}s)+s^{-1}g(\Gamma)(1{-}g(\Gamma))}{2(\Gamma+s^{-1}g(\Gamma))}\nonumber \\ 
	&- \sqrt{r \cdot \frac{\Gamma(2g^2(\Gamma)+s^2\Gamma)}{(s^{-1}g(\Gamma) + \Gamma)^2}} + o(\sqrt{r}) \Bigg\}
\end{align}
where $g(\Gamma) \triangleq 1-2\lambda\Gamma$. Setting $\lambda=0$ gives that $g(\Gamma)=1$ and thus $\underline{{I}}_{\text{\normalfont cost}}=\underline{I}_{\text{GMI}}$. In general, we have that $\underline{{I}}_{\text{\normalfont cost}} \geq \underline{{I}}_{\text{\normalfont GMI}}$.
Numerical evidence of such a gain is shown in Fig. \ref{fig:cont}.

