\section{Proof of Theorem \ref{theorem:WorstCaseLMRate}}
\label{ProofLMRate}

Here, we provide the full derivation for the worst-case LM rate in Theorem \ref{theorem:WorstCaseLMRate}. Let us define%
\begin{align} \label{Appth1:Isa_def}
    I_{s,a}(\QX, W) &\triangleq \sum_{x,y} \QX(x) W(y|x) i_{s, a}(x, y)\\ %
    I^\text{ML}_{s,a}(\QX, \widehat{W}) &\triangleq \sum_{x,y} \QX(x) \widehat{W}(y|x) i_{s, a}(x, y), \label{Appth1:IsaML}
\end{align}
and let small mismatch be characterized by Definition \ref{def:small_mismatch}. Then, we formulate the worst-case LM rate $\underline{I}_{\text{LM}}$ as%
\begin{align} \label{Appth1:MinLMrate}
\underline{I}_{\text{LM}}(\QX, \widehat{W}\!, r) &= \operatorname*{min}_{W \in \mathcal{B}} \operatorname*{sup}_{s \ge 0, a(\cdot)} I_{s,a}(\QX, W).
\end{align}
Since $I_{s,a}$ is linear in $W$ and concave in $s\geq 0$ and $a(x)$ \cite[Ch. 2.3.4]{Foundations}, we can switch the order of the optimizations in application of the minimax theorem \cite[Th. 1]{Minimax}.
Then, by minimizing $I_{s,a}$ over all channels $W \in \mathcal{B}$ we obtain%
\begin{align}\label{Appth1:MinIsa1}
	\underline{I}_{s,a}(\QX, \widehat{W}\!, r) &\triangleq \operatorname*{min}_{W \in \mathcal{B}}\ I_{s,a}(\QX, W) \\
	\label{Appth1:MinIsa2}
	&= I^\text{ML}_{s,a}(\QX, \widehat{W}) + \operatorname*{min}_{W \in \mathcal{B}} \thetav^{T} {\nabla\! I_{s,a}}
\end{align}
where:
\begin{equation} \label{Appth1:Theta_def}
\thetav \triangleq \Big[
\theta(y_1 | x_1), \dots, \theta(y_{|\Yc|} | x_1), \theta(y_{1} | x_2), \dots, \theta(y_{|\Yc|} | x_{|\Xc|}) \Big]^T
\end{equation}
with $\theta(y_i|x_j) = W(y_i|x_j) {-} \widehat{W}(y_i|x_j)$ as defined in \eqref{eqn:theta_def}, and%
\begin{align} \label{Appth1:IsaGrad}
\nabla\! I_{s,a} \triangleq \big[ &\QX(x_1)i_{s,a}(x_1, y_1),\ \dots,\ \QX(x_1)i_{s,a}(x_1, y_{|\Yc|}), \notag \\
&\QX(x_2)i_{s,a}(x_2, y_1),\ \dots,\ \QX(x_2)i_{s,a}(x_2, y_{|\Yc|}), \notag \\
& \dots,\ \QX(x_{|\Xc|})i_{s,a}(x_{|\Xc|}, y_{|\Yc|}) \big]^T
\end{align}
is the gradient of $I_{s, a}$ \eqref{Appth1:Isa_def} with respect to each $W(y_i|x_j)$.

The constraint $W \in \mathcal{B}$ over all valid conditional probability distributions is also written in vector form as the following set of $1{+}|\Xc|$ constraints%
\begin{align}%
	\left\{ \begin{array}{rll} \label{Appth1:Constraints}
		\DKL (\widehat{W} \| W | \QX) &=& d(\thetav) {+} o(d(\thetav)) \leq r\\ %\label{Appth1:Wconstraint}
	\thetav^{T\!} \underline{\boldsymbol{1}}_j &=& 0 \quad \text{for} \quad 1 \leq j \leq |\Xc|
	\end{array} \right.	
\end{align}
under the following definitions:
\begin{align} \label{Appth1:d_def}
	d(\thetav) &\triangleq \tfrac{1}{2} \thetav^{T\!} \mathbf{K} \thetav
	\\ \label{Appth1:KMatrix_def}
	\mathbf{K} &\triangleq \text{diag}\Bigg( \frac{\QX(x_1)}{\widehat{W}(y_1|x_1)},\ \dots,\ \frac{\QX(x_{|\Xc|})}{\widehat{W}(y_{|\Yc|} | x_{|\Xc|})}\Bigg)\\	
	\underline{\boldsymbol{1}}_j &\triangleq \begin{bmatrix}
		0\ \dots\ 0\ 1_{(1,j)}\ \dots\ 1_{(|\Yc|, j)}\ 0\ \dots\ 0
	\end{bmatrix}^T
	\label{Appth1:slicedOneVectorLM}
\end{align}
where the upper side of \eqref{Appth1:Constraints} guarantees that sought channels are within the ball of radius $r$, and the constraints in the lower side guarantee that ${\sum_y} W(y|x_j)=1$ for every $x_j \in \Xc$.

Therefore, problem in \eqref{Appth1:MinIsa2} can be written equivalently as%
\begin{align}\label{Appth1:MinIsa3}
	\operatorname*{min}_{W \in \mathcal{B}} \thetav^{T} \nabla\! I_{s,a}\ = 	\operatorname*{min}_{
		\substack{ d(\thetav) + o(d(\thetav)) \le r \\ \thetav^{T\!} \underline{\boldsymbol{1}}_j = 0,\ 1\le j \le |\Xc| }} \thetav^T \nabla\! I_{s,a}\ ,%
\end{align}
a convex problem that can be solved using the Lagrangian method \cite{ConvexOptimization}. This leads to a system of implicit equations that must be solved numerically using a trial-and-error algorithm for the unknown variables.

One of the key points to note is that there is no solution to \eqref{Appth1:MinIsa3} that satisfies $\DKL(\widehat{W}\| W| \QX) < r$, with strict inequality. As the objective function and the equality constraints are linear in $\thetav$, the following minimum%
\begin{align}
 	\operatorname*{min}_{
		\thetav^{T\!} \underline{\boldsymbol{1}}_j = 0,\ 1\le j \le |\Xc| }\ \thetav^T \nabla\! I_{s,a}%
\end{align}
is unbounded unless we impose boundary constraints on $W$. In this case, the minimum is achieved by the worst-case channel%
\begin{align}
	W^\ast(y|x) = \mathds{1}\{ i_{s,a}(x,y) = \min_{\bar{y}} i_{s,a}(x,\bar{y}) \}
\end{align}
for which the constraint $\DKL(\widehat{W}\| W^\ast| \QX) = \infty \leq r$ is never satisfied. Therefore, the inequality in \eqref{Appth1:Constraints} needs to be set with equality, and we will henceforth consider it with equality.
The geometric interpretation is that, because the objective function is linear, the optimal solution is found at the boundaries of the ellipsoid defined by the constraint. Specifically, the objective function intersects the ellipsoid at two points, one of which corresponds to the minimum we are seeking.

As we have said before, the solution to \eqref{Appth1:MinIsa3} is not explicit.
To achieve results that allow for conceptual understanding, we derive an approximation that is highly accurate as $r\rightarrow0$:%
\begin{enumerate}
	\item We rely on the fact that $o(d(\boldsymbol{\theta}))$ has a negligible impact for sufficiently small $r$. This is supported by \cite{EuclideanInformationTheory}, where it is stated that $d(\boldsymbol{\theta})$ well approximates $\DKL(\widehat{W}\|W|\QX)$ when $\widehat{W}$ is in a neighborhood of $W$. Therefore, we treat $o(d(\thetav))=\gamma$ as a small constant term independent of $\thetav$, absorbed in the constraint value via $\bar{r}\triangleq r-\gamma$. We then solve the following convex problem \cite{ConvexOptimization}%
	\begin{align}\label{Appth1:Lprobl1}
		J(\bar{r})\ &= 	\operatorname*{min}_{
			\substack{ d(\thetav) = \bar{r} \\ \thetav^{T\!} \underline{\boldsymbol{1}}_j = 0,\ 1\le j \le |\Xc| }} \!\thetav^T \nabla\! I_{s,a}\\%
		&= \operatorname*{max}_{\rho, \nu_{1}, \dots, \nu_{|\Xc|}} \operatorname*{min}_{
			\substack{ \boldsymbol{\theta}}}\ \mathcal{L}(\bar{r}) \label{Appth1:Lprobl2}
	\end{align}
	where $\mathcal{L}(\bar{r})$ is the following Lagrangian%
	\begin{align}
		\mathcal{L}(\bar{r}) &\triangleq \thetav^{T} \nabla\! I_{s,a} + \rho \big(d(\boldsymbol{\theta}) - \bar{r}\big) + {\sum_j} \nu_j \thetav^{T\!} \underline{\boldsymbol{1}}_j.
	\end{align}

	\item We expand $J(\bar{r})=J(r-\gamma)$ for small $\gamma$ as%
	\begin{align}
		J(\bar{r}) &= J(r) - J^{\prime}(r) \gamma
	\end{align}
	where the first term coincides with the minimum in \eqref{Appth1:Lprobl2} when $\bar{r}=r$ given by%
	\begin{align} \label{Appth1:Lprobl3}
		J(r) &= \operatorname*{max}_{\rho, \nu_{1}, \dots, \nu_{|\Xc|}} \operatorname*{min}_{
			\substack{ \boldsymbol{\theta}}}\ \mathcal{L}(r),
	\end{align}
	and the derivative in the second term is precisely the optimal Lagrange multiplier associated with the constraint $d(\thetav)= r$ in problem \eqref{Appth1:Lprobl3}: $\rho^\ast=-J^{\prime}(r)$.
\end{enumerate}
Our approach yields $J(\bar{r})=J(r)+\rho^\ast o(d(\thetav))$, which, when evaluated at the optimal $\thetav^\ast$, produces $J(\bar{r})=J(r)+\rho^\ast o(r)$.	

Therefore, our approach establishes the following equivalence between the optimization problems when adopting the relative entropy ball $\mathcal{B}$ in \eqref{eqn:WorstCaseRatesConstraint} or the chi-squared distance ball $\tilde{\mathcal{B}}$ in \eqref{eqn:WorstCaseRatesConstraint2} for sufficiently small $r\ge0$%
\begin{align}\label{Appth1:Lprobl4}
	\operatorname*{min}_{W \in \mathcal{B}} \thetav^{T} \nabla\! I_{s,a} &= \operatorname*{min}_{W \in \tilde{\mathcal{B}}} \thetav^{T} \nabla\! I_{s,a} + \rho^{\!\ast} o(r)
\end{align}
where
\begin{align}\label{Appth1:Lprobl5}
	\operatorname*{min}_{W \in \tilde{\mathcal{B}}} \thetav^{T} \nabla\! I_{s,a}\ &\triangleq \operatorname*{max}_{\rho, \nu_{1}, \dots, \nu_{|\Xc|}} \operatorname*{min}_{
		\substack{ \boldsymbol{\theta}}}\ \mathcal{L}(r).
\end{align}

\subsection{The Solution} \label{ProofLMRate_sol}
Problem \eqref{Appth1:Lprobl5} is linear with quadratic constraints, for which the KKT conditions are necessary and sufficient for optimality \cite{ConvexOptimization}. The stationary point equations are obtained by differentiating with respect to $\thetav^{T\!}$, $\rho$, and each $\nu_j$, and equating to zero. This gives the following system of equations:%
\begin{align} \label{Appth1:ThetaOpt}
	\thetav^\ast &= - \frac{\mathbf{K}^{-1}}{\rho^{\!\ast}} \bigg(\nabla\! I_{s,a} + {\sum_j} \nu_j^\ast \underline{\boldsymbol{1}}_j\bigg)\\
	\tfrac{1}{2} {\thetav^\ast}^{T\!} \mathbf{K}\thetav^\ast &= r\\
	{\thetav^\ast}^{T\!} \underline{\boldsymbol{1}}_j &=0 \quad \text{for} \quad j=1,\dots,|\Xc|.
\end{align}
We obtain%
\begin{align} \label{Appth1:nu_j_lm}
    \nu_j^\ast   &= - \QX(x_j)\EX_{\widehat{W}} [i_{s,a}(x_j, Y)]\\
    \rho^{\!\ast} &= \sqrt{V_{s,a}(\QX, \widehat{W})/(2r)} \\
    V_{s,a}(\QX, \widehat{W}) &\triangleq \EX_{\QX}[\text{Var}_{\widehat{W}}[i_{s,a}(X, Y)|X]]%
\end{align}
and%
\begin{equation} \label{eqn:FinalThetaWithNuExpandedLM}
    \thetav^\ast = \frac{\mathbf{K}^{-1}\!}{\rho^{\ast}} \bigg( {\sum_j} \QX(x_j) \EX_{\widehat{W}} [i_{s,a}(x_j, Y)] \underline{\boldsymbol{1}}_j - \nabla\! I_{s,a} \!\bigg)%
\end{equation}
where the element $\theta^\ast(y|x)$ is extracted from $\thetav^\ast$ \eqref{eqn:FinalThetaWithNuExpandedLM} as%
\begin{align}\label{eqn:Optimal_Theta_ij}
	\theta^\ast(y|x) &= - \sqrt{2r} \cdot \widehat{W}(y | x) \varphi_{s,a}(x, y), \\ \label{App:eqn:phi_def}
	\varphi_{s,a}(x, y) &\triangleq \frac{i_{s,a}(x, y) - \EX_{\widehat{W}} [ i_{s,a}(x, Y) ] }{\sqrt{V_{s,a}(\QX, \widehat{W})}}.
\end{align}
The worst-case channel distribution obtained by isolating $\tilde{W}^{\ast}_{\!s,a}$ from $\theta^\ast(y|x) = \tilde{W}^{\ast}_{\!s,a}(y|x)-\widehat{W}(y|x)$ is%
\begin{align} 
	\tilde{W}_{\!s,a}^\ast(y|x) &= \widehat{W}(y|x) \Big( 1 - \sqrt{2r} \cdot \varphi_{s,a}(x, y) \Big).
\end{align}
We first substitute \eqref{eqn:Optimal_Theta_ij} into \eqref{Appth1:Lprobl4}, and account for the term $\rho^{\!\ast} o(r) = o(\sqrt{r})$. We then substitute the result into \eqref{Appth1:MinIsa2}, yielding the following expression:%
\begin{align}
    \underline{I}_{s,a}(\QX, \widehat{W}\!, r) =\ & I_{s,a}^{\text{ML}}(\QX, \widehat{W}) \nonumber\\
    &- \sqrt{2r V_{s,a}(\QX, \widehat{W}) } + o(\sqrt{r}).%
\end{align}
It is straightforward to check that the solution corresponds to a minimum as the cost function is linear with quadratic constraints and $\rho^{\!\ast}>0$.

\subsection{Discussion} \label{ProofLMRate_disc}
The only remaining issue to be proven is whether the worst-case channels are non-negative. This arises because the constraint $d(\thetav) = r$ in \eqref{Appth1:Lprobl5} does not necessarily guarantee non-negativity, unlike the case with $\DKL(\widehat{W} \| W | \QX) = d(\thetav) + o(d(\thetav)) = r$ for $\widehat{W} > 0$ in the original problem \eqref{Appth1:MinIsa3}.
Further analysis reveals that this issue is fully resolved when $r$ is small, without the need to impose additional constraints.


To evidence the above, we have solved the full optimization problem including constraints to ensure that all valid conditional channel distributions are non-negative, as $W(y|x) \ge 0$ for $(x,y)\in\Xc\times\Yc$, through the slack variables $\mu(x, y)\ge0$ satisfying $\mu(x,y) W(y|x)=0$. 
The solution can be expressed in terms of the following variables%
\begin{align}
	i_{s,a}^\mu(x,y) &\triangleq i_{s,a}(x,y) - \mu(x, y)\\
	\varphi_{s,a}^\mu(y|x) &\triangleq \frac{i_{s,a}^{\mu}(x, y) - \EX_{\widehat{W}}[i_{s,a}^{\mu}(x, Y)]}{ \sqrt{V_{s,a}^{\mu}(\QX, \widehat{W})} } \\
	V_{s,a}^\mu(\QX, \widehat{W}) &\triangleq \EX_{\QX}[\VAR_{\widehat{W}}[i_{s,a}^\mu(X, Y)|X]],
\end{align}
achieving the following minimum
\begin{align}
	\underline{I}_{s,a}(\QX, \widehat{W}\!, r) =\ & \max_{\mu(\cdot)\ge0} \bigg\{  \EX_{\QX{\times}\widehat{W}}[i_{s,a}^{\mu}(X, Y)]  \nonumber\\
	&- \sqrt{2r V_{s,a}^\mu(\QX, \widehat{W})} + o(\sqrt{r}) \bigg\}%
\end{align}
for the worst-case channel distribution%
\begin{align}
	\tilde{W}_{\!s,a}^\ast(y|x) &= \widehat{W}(y|x) \Big( 1 - \sqrt{2r} \cdot \varphi_{s,a}^\mu(x, y) \Big).
\end{align}
From the above expression, it is evident that when $r$ is sufficiently small, the second term has a minimal impact on the structure of $\widehat{W}(y|x)>0$.
This confirms the validity of our approach in the absence of positivity constraints for the regime of $r$ values that make $\tilde{W}_{\!s,a}^\ast(y|x) \geq 0$ when $\mu(x,y) = 0$.

\section{Proof of Theorem \ref{theorem:WorstCaseE0}}
\label{ProofiidGallagerFunction}
We determine the worst-case Gallager $E_0$ functions
\begin{align} \label{Appth2:WorstCaseE0iid}
	\underline{E}{}_0^{\text{iid}}(\QX, \widehat{W}\!, \rho, r) &= \operatorname*{min}_{W \in \mathcal{B}}\ \operatorname*{sup}_{s \ge 0}\ E_{s,\zerov,\zerov,\rho}(\QX,W)\\
	\label{Appth2:WorstCaseE0cc}
	\underline{E}{}_0^{\text{cc}}(\QX, \widehat{W}\!, \rho, r) &= \operatorname*{min}_{W \in \mathcal{B}} \operatorname*{sup}_{c_1\!(\cdot), c_2\!(\cdot)}\operatorname*{sup}_{s \ge 0, \lv, \bar{\lv}} \! E_{s, \lv, \bar{\lv},\rho}(\QX,W)%
\end{align}
using analogous arguments to those for the proof of the worst-case LM rate in Appendix \ref{ProofLMRate}. In particular, as $\underline{E}{}_0^{\text{iid}}$ can be obtained from $\underline{E}{}_0^{\text{cc}}$ by setting $\lv=\bar{\lv}=\zerov$ and by deleting the optimization over $c_1(\cdot), c_2(\cdot)$, we will only solve \eqref{Appth2:WorstCaseE0cc}. 

Firstly, as the problem is concave in $s\ge0, c_1(\cdot), c_2(\cdot)$ and convex in $W\in\mathcal{B}$, we make use of Fan's minimax Theorem \cite{Minimax} to move the minimization as the inner problem. Hence, our approach reduces to solving%
\begin{align} 
	\underline{E}_{s, \lv, \bar{\lv}, \rho}(\QX&, \widehat{W}\!, r) \triangleq \nonumber\\
	&\operatorname*{min}_{W \in \mathcal{B}} -\log \EX_{\QX{\times}W} [ \varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y)].%
	\label{eqn:logmax_E_s_rho}
\end{align}
Now, by adding and subtracting the term $E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \triangleq - \log \EX_{\QX{\times}\widehat{W}} [ \varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y) ]$ and using $\theta(y|x)=W(y|x)-\widehat{W}(y|x)$, problem  \eqref{eqn:logmax_E_s_rho} can be rewritten as%
\begin{align}
	\underline{E}&_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W}\!,r) = E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W})\nonumber\\ &- \log \left( 1+\operatorname*{max}_{W \in \mathcal{B}} \sum_{x, y}\frac{ \QX(x) \theta(y|x) \varepsilon_{s, \lv, \bar{\lv}, \rho}(x, y)}{\EX_{\QX{\times}\widehat{W}} [ \varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y) ]} \right)\!.%
\end{align}
Note that the inner maximization problem,%
\begin{align}
	\operatorname*{max}_{W \in \mathcal{B}}\ \sum_{x, y}\frac{ \QX(x) \theta(y|x) \varepsilon_{s, \lv, \bar{\lv}, \rho}(x, y)}{\EX_{\QX{\times}\widehat{W}} [ \varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y) ]},%
\end{align}
has the same form as problem \eqref{Appth1:MinIsa3} in Appendix \ref{ProofLMRate}, but with a substitution of $\varepsilon_{s, \lv, \bar{\lv}, \rho}(x, y)/\EX_{\QX{\times}\widehat{W}} [ \varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y)]$ by $i_{s, a}(x, y)$ and a change from minimization to maximization.

The solution is obtained straightforwardly by mimicking the derivation in Appendix \ref{ProofLMRate}. This gives%
\begin{align}
	\theta^\ast(y|x) &= \sqrt{2r} \cdot \frac{\widehat{W}(y|x) \varphi_{s, \lv, \bar{\lv}, \rho}(x, y)}{\EX_{\QX{\times}\widehat{W}}[\varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y)]}%
\end{align}
with%
\begin{align}
	\varphi_{s, \lv, \bar{\lv}, \rho}(x, y) &\triangleq \frac{\varepsilon_{s, \lv, \bar{\lv}, \rho}(x, y) {-} \EX_{\widehat{W}} [ \varepsilon_{s, \lv, \bar{\lv}, \rho}(x, Y) ] }{\sqrt{V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W})}}\\
	\!\! V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W}) &\triangleq \frac{\EX_{\QX} \big[ \text{\normalfont Var}_{\widehat{W}}[\varepsilon_{s, \lv, \bar{\lv}, \rho}(X, Y) | X] \big]}{\EX_{\QX{\times}\widehat{W}}^2[\varepsilon_{s, \lv, \bar{\lv}, \rho}(X,Y)]}%
\end{align}
achieving the following objective%
\begin{align}
		\underline{E}_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W}\!, r) &=  E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\
		-\log \bigg( 1 + &\sqrt{2 r V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W})} + o(\sqrt{r}) \bigg) \\
	&= E_{s, \lv, \bar{\lv}, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) \nonumber\\
	-\log \bigg( 1 + &\sqrt{2 r V_{s, \lv, \bar{\lv}, \rho}(\QX, \widehat{W})}  \bigg) + o(\sqrt{r})
\end{align}
where for the second inequality we have used that $\log(x+o(\sqrt{r})) = \log(x) + o(\sqrt{r})$.

\section{The Case of a Symmetric $\widehat{W}$}
\label{ProofDiscreteSymmetricChannel}
For a symmetric (as Gallager \cite[Pag. 94]{GallagerWiley1968}) estimated channel $\widehat{W}$ and an equiprobable input distribution $\QX(x) = |\Xc|^{-1}$, expressions can be obtained in terms of%
\begin{align}
	\kappa_{t} &\triangleq \sum_x \widehat{W}(y|x)^t = \sum_y \widehat{W}_\text{sym}(y)^t \label{App:eqn:kappa}
\end{align}
where $\widehat{W}_{\text{sym}}(y)\equiv \widehat{W}_{\text{sym}}(y|x_1)$ denotes the first row of $\widehat{W}$. The second equality in \eqref{App:eqn:kappa} holds due to the symmetry of $\widehat{W}$.

\subsection{Computations relative to the achievable rate}
The mismatched information density reads%
\begin{align}
	i_{s, 0}(x, y) &= \log \frac{\widehat{W}(y|x)^s}{ \frac{1}{|\Xc|} {\sum_{\bar{x}}} \widehat{W}(y|\bar{x})^s } \nonumber \\
	&= \log \frac{|\Xc|}{\kappa_{\!s}} + \log \widehat{W}(y|x)^s.%
\end{align}
Therefore,%
\begin{align}
	I^{\text{ML}}_{s,0}(\QX, \widehat{W}) &= \EX_{\QX \times \widehat{W}}[i_{s, 0}(X, Y)] \nonumber \\
	&= \log \frac{|\Xc|}{\kappa_{\!s}} + s \cdot \EX_{\widehat{W}_{\text{sym}}}[\log \widehat{W}_{\text{sym}}]
\end{align}
and the expansion terms proportional to $\sqrt{r}$ are%
\begin{align}\hspace{-0.5em}
	V_{s,0}(\QX, \widehat{W}) &= \EX_{\QX} [\VAR_{\widehat{W}} [i_{s,0}(X,Y)|X]] \nonumber \\
	 &= \EX_{\QX} [\VAR_{\widehat{W}} [s\cdot \log \widehat{W}(Y|X)|X]] \nonumber \\
	&=s^2 \! \left( 
	\EX_{\widehat{W}_{\text{sym}}}^{} \hspace{-0.6em}[\log^2 \widehat{W}_{\text{sym}}] {-} \EX_{\widehat{W}_{\text{sym}}}^2 \hspace{-0.6em}[ \log \widehat{W}_{\text{sym}} ] \right)\! . \label{App:eqn:generic_additive_channel_v_function_proof}
\end{align}

\subsection{Computations relative to the Gallager $E_0$ function}
The mismatched exponent density reads%
\begin{align}
	\varepsilon_{s, \zerov, \zerov, \rho}(x, y) &= \left( \frac{\frac{1}{|\Xc|} {\sum_{\bar{x}}}  \widehat{W}(y|\bar{x})^s}{\widehat{W}(y|x)^s} \right)^\rho \notag \\
	&= \frac{\kappa_{\!s}^\rho}{|\Xc|^\rho} \widehat{W}(y|x)^{-s\rho}.%
\end{align}
Therefore%
\begin{align}
	E_{s, \zerov, \zerov, \rho}^{\text{\normalfont ML}}(\QX, \widehat{W}) &= -\log \EX_{\QX{\times}\widehat{W}}[\varepsilon_{s, \zerov, \zerov, \rho}(X,Y)] \nonumber\\
	&= \log  \frac{|\Xc|^\rho}{\kappa_{\!s}^\rho \kappa_{1{-}s\rho}}
\end{align}
and the expansion terms proportional to $\sqrt{r}$ are%
\begin{align}
	V_{s,\zerov, \zerov, \rho}(\QX, \widehat{W}) 
	&= \frac{\EX_{\QX} [ \VAR_{\widehat{W}}[ \varepsilon_{s, \zerov, \zerov, \rho}(X, Y)|X]]}{\EX_{\QX{\times}\widehat{W}}^2[\varepsilon_{s, \zerov, \zerov, \rho}(X,Y)]} \nonumber \\
	&= \frac{\EX_{\QX} [ \VAR_{\widehat{W}}[ \widehat{W}(Y|X)^{- s \rho}|X]]}{\EX_{\QX{\times}\widehat{W}}^2[\widehat{W}(Y|X)^{- s \rho}]} \nonumber \\
	&= \frac{\kappa_{1-2s\rho} - \kappa_{1-s\rho}^2}{\kappa_{1{-}s\rho}^2} .
\end{align}

\section{Proof of Theorem \ref{theorem:CCcontinuous}} \label{App:ProofCont}
The continuous-alphabet case is similar to the discrete-alphabet case, but now we work with probability density functions instead of probability mass functions, and integrals instead of summations. Therefore, we resort to the calculus of variations to address the minimization in the function space.

We want to solve the following variational problem%
\begin{align}
	\min_{W \in \mathcal{B}} {\iint_{\mathbb{R}^2}} \QX(x) W(y|x) i_{s,\lv}(x, y) \DD x \DD y%
\end{align}
where the constraint $W \in \mathcal{B}$ considers conditional probability density functions $W(y|x) \geq 0$ that satisfy%
\begin{align}
	\!\left\{\!\!\! \begin{array}{rl}
		d(\widehat{W}\|W|\QX) + o(d(\widehat{W}\|W|\QX)\!) &\leq\ r\\
	{\int_{\mathbb{R}}} W(y|x) \DD y &=\ 1\ \text{for}\ x \in \mathbb{R}
	\end{array}\right.
\end{align}
with%
\begin{align}
	d(\widehat{W}\|W|\QX) \triangleq\! {\iint_{\mathbb{R}^2}} \QX(x) \frac{(W(y|x) {-} \widehat{W}(y|x)\!)^2}{2\widehat{W}(y|x)} \DD x \DD y.%
\end{align}
For sufficiently small $r$, the same trick as in \eqref{Appth1:Lprobl2} can be applied to move the $o(\cdot)$ term in the constraint as a penalty term in the objective function. We will omit the technical derivations, as it follows the same rules outlined in Appendix \ref{ProofLMRate}, and focus on solving the following variational problem%
\begin{align}
	\min_{\substack{d(\widehat{W}\|W|\QX) = r\\ {\int_{\mathbb{R}}} W(y|x)\DD y = 1}} {\iint_{\mathbb{R}^2}} \!\QX(x) W(y|x) i_{s,\lv}(x, y) \DD x \DD y + \rho^{\!\ast} \!o(r)%
\end{align}
where the differentiability of the objective functional and constraints is assumed under an appropriately chosen norm for channels with continuous derivatives, as functionals are either linear or quadratic in $W$.

Now, we proceed by minimizing the Lagrangian%
\begin{align}
	\mathcal{L}[W] = \iint_{\mathbb{R}^2} \!F(x, y, W(y|x)) \DD x \DD y%
\end{align}
with%
\begin{align} \label{App:eqn:F}
	F(x, y, W) \triangleq\ & \QX(x) Wi_{s,\lv}(x, y) + \nu(x) W \nonumber\\
	&+ \rho \QX(x)\frac{(W {-} \widehat{W}(y|x)\!)^2}{2\widehat{W}(y|x)}%
\end{align}
and where we have obviated $W$-independent constant terms. 
We follow the rules in \cite[Sec. V]{gelfand2000calculus}, where the stationary point $W^{\ast}(y|x)$ is found by solving the Euler-Lagrange equation%
\begin{align}
	\frac{\partial F}{\partial W} - \frac{\partial}{\partial x} \frac{\partial F}{\partial W_{\!x}} - \frac{\partial}{\partial y} \frac{\partial F}{\partial W_{\!y}} =0 \quad \text{in} \quad (x,y)\in\mathbb{R}^2.%
\end{align}
In our case, since $F$ in \eqref{App:eqn:F} does not depend on the partial derivatives of $W$, denoted $W_{x}$ and $W_{y}$, the above reduces to solving $\tfrac{\partial F}{\partial W} = 0$ in $(x,y)\in\mathbb{R}^2$ for $\{W^{\ast}(y|x), \nu^{\!\ast}(x), \rho^{\!\ast}\}$ jointly with the problem constraints.
Specifically, we have%
\begin{align}
	W^{\ast}(y|x) &= \widehat{W}(y|x) \!\left( 1- \frac{\QX(x)i_{s,\lv}(x,y){+}\nu^{\!\ast}(x)}{\rho^{\!\ast} \QX(x)} \right)
\end{align}
with%
\begin{align}
	\nu^{\!\ast}(x) &\triangleq -\QX(x)\EX_{\widehat{W}}[i_{s,\lv}(x, Y)]\\
	\rho^{\!\ast} &\triangleq \sqrt{V_{s, \lv}(\QX, \widehat{W})/(2r)}\\
	V_{s,\lv} (\QX, \widehat{W}) &\triangleq \EX_{\QX} [\VAR_{\widehat{W}}[i_{s,\lv}(X,Y)|X]].%
\end{align}
The stationary point $W^{\ast}(y|x)$ corresponds to the global minimum as the problem is linear in $W$ subject to quadratic constraints in $W$ and $\rho^{\ast}>0$.

\section{Gaussian Codebooks and Nearest Neighbor Decoding} \label{app:aux}
For Gaussian i.i.d. codebooks $\QX(x) = \mathcal{N}(x; P)$ and the nearest neighbor decoder $\widehat{W}(y|x) = \mathcal{N}(y{-}x;\hat{\sigma}^2)$, we have
\begin{align} \label{eqn:AppGaussian:Whats}
	\widehat{W} (y|x)^s &= \alpha_s \cdot \mathcal{N}(y{-}x; \hat{\sigma}^2 s^{-1})
	\\\label{eqn:AppGaussian:EWhats}
	\EX_{\QX}[\widehat{W}(y|X)^s] &= \alpha_s \cdot \mathcal{N}(y;\hat{\sigma}^2 s^{-1}{+}P)
\end{align}
with $\alpha_s \triangleq \sqrt{s^{-1} (2\pi\hat{\sigma}^2)^{1-s}}$.%

\subsection{Achievable rate with Gaussian i.i.d. codebooks}
The mismatched information density is (\textit{cf}. \cite[(28)-(29)]{7605463})%
\begin{align}
	i_{s,\zerov}(x, y) &= C_1 - \frac{s}{2}\frac{(y-x)^2}{\hat{\sigma}^2} + \frac{1}{2} \frac{y^2}{\hat{\sigma}^2 s^{-1}{+}P}
\end{align}
with
\begin{align}
	C_1 &\triangleq \frac{1}{2} \log \left(1+\frac{sP}{\hat{\sigma}^2}\right),%
\end{align}
and the respective expectations are%
\begin{align}
	\EX_{\widehat{W}} [i_{s,\zerov}(x, Y)] &= C_1 + \frac{1}{2} \frac{x^2{-}sP}{\hat{\sigma}^2 s^{-1}{+}P} \\
	\EX_{\QX {\times} \widehat{W}} [i_{s,\zerov}(X, Y)] &= C_1 + \frac{P}{2} \frac{1-s}{\hat{\sigma}^2 s^{-1}{+}P}.%
\end{align}
Note that $I^\text{\normalfont ML}_{s, \zerov}(\QX, \widehat{W}) =\EX_{\QX{\times}\widehat{W}} [i_{s,\zerov}(X, Y)]$.

Now we turn our attention to the term $V_{s,\zerov}(\QX,\widehat{W}) = \EX_{\QX {\times} \widehat{W}} [i_{s,\zerov}^2(X, Y)] - \EX_{\QX}[\EX_{\widehat{W}}^2[i_{s,\zerov}(X, Y)|X]]$. After tedious but otherwise straightforward calculations, we find its two terms as follows 
\begin{align}
	\EX_{\QX {\times} \widehat{W}} [i_{s,\zerov}^2(X, Y)] =\ & K_1 + \frac{3 s^2}{4} + \frac{3(\hat{\sigma}^2{+}P)^2}{4(\hat{\sigma}^2 s^{-1}{+}P)^2} \nonumber\\
	&- \frac{1}{2} \frac{s(3\hat{\sigma}^2{+}P)}{(\hat{\sigma}^2 s^{-1}{+}P)^2}\\
	\EX_{\QX}[\EX_{\widehat{W}\!}^2[i_{s,\zerov}(X, Y)|X]] =\ & K_1 + \frac{P^2(3-2s+s^2)}{4(\hat{\sigma}^2 s^{-1}{+}P)^2}
\end{align}
where $K_{1} \triangleq C_1^2 + C_1P(1{-}s)(\hat{\sigma}^2 s^{-1}{+}P)^{-2}$, leading to%
\begin{align}
	V_{s,\zerov}(\QX,\widehat{W}) &=\frac{P}{2} \frac{2\hat{\sigma}^2{+}s^2P}{(\hat{\sigma}^2 s^{-1}{+}P)^2}.
\end{align}

\subsection{$E_0$ function with Gaussian i.i.d. codebooks}
\label{app:exp_gauss}
The expressions for the worst-case mismatched Gallager $E_0$ functions can be obtained from%
\begin{align}
	\EX_{\QX}^t[\widehat{W}(y|X)^{s}] &\triangleq \alpha_s^{t} \frac{\sqrt{2\pi P_{\!s} t^{-1}}}{\sqrt{(2\pi P_{\!s})^t}} \cdot \mathcal{N}(y; P_{\!s} t^{-1})%
\end{align}
with $P_{\!s} \triangleq \hat{\sigma}^2 s^{-1}{+}P$, and%
\begin{align}
	A(s, t) &\triangleq \! \int_{\mathbb{R}} \EX_{\QX}^t [\widehat{W}(y|X)^{s}] \EX_{\QX}[\widehat{W}(y|X)^{1-st}] \DD y \nonumber\\
	&= \!\int_{\mathbb{R}}\! \frac{\alpha^t_s \alpha_{1-st}}{\sqrt{(2\pi P_{\!s})^{t}}} \sqrt{\!\frac{P_{\!s}}{P_{\!s} {+} t P_{\!1-st}}} \mathcal{N}\! \left(\! y; \frac{P_s P_{1-st}}{P_{s} {+} t P_{1-st}} \right) \! \DD y \nonumber\\
	&= \frac{\alpha^t_s \alpha_{1-st}}{\sqrt{(2\pi P_{\!s})^t}} \sqrt{\!\frac{P_{\!s}}{P_{\!s} + t P_{\!1-st}}} \nonumber\\
	%&= \sqrt{\frac{1}{(P_{\!s}s)^t (1-st)} {\cdot} \frac{P_{\!s}}{P_{\!s} + t P_{\!1-st}}} \nonumber\\
	%&= \sqrt{\frac{1}{(1+Ps)^t} {\cdot} \frac{1}{1+ \frac{tP(1-s-ts)}{P+s^{-1}}}}\ .
	&= \sqrt{\left(1+\frac{Ps}{\hat{\sigma}^2}\right)^{\!\!-t} \! \left( 1+ \frac{tP(1-s-ts)}{P+\hat{\sigma}^2 s^{-1}} \right)^{\!\!-1}}.
\end{align}
Therefore%
\begin{align}
	E^{\text{ML}}_{s,\zerov, \zerov, \rho}(\QX, \widehat{W}) =\ & -\log A(s, \rho) \nonumber \\
	=\ & \frac{\rho}{2} \log\!\left(1+\frac{Ps}{\hat{\sigma}^2}\right) \nonumber\\
	&+ \frac{1}{2} \log \left( 1+ \frac{\rho P (1{-}s{-}\rho s)}{P+\hat{\sigma}^2 s^{-1}} \right).
\end{align}

The dispersion term $V_{s, \zerov, \zerov, \rho}(\QX, \widehat{W})$ is computed as the following sum:
\begin{align}
	V_{s, \zerov, \zerov, \rho}(\QX, \widehat{W}) = V_1(\QX, \widehat{W})-V_2(\QX, \widehat{W}).
\end{align}
The first term is%
\begin{align}
	V_{1}(\QX, \widehat{W}) &\triangleq \frac{\EX_{\QX {\times} \widehat{W}} [ \varepsilon^2_{s, \zerov, \zerov,\rho}(X, Y)]}{\EX_{\QX{\times}\widehat{W}}^2[\varepsilon_{s, \zerov, \zerov, \rho}(X,Y)]} \nonumber\\
	&= \frac{A(s, 2\rho)}{A(s, \rho)^2} \nonumber \\%
	&= \frac{1}{\sqrt{P_s}} \frac{P{+}\hat{\sigma}^2 s^{-1} + \rho P(1{-}s{-}\rho s)}{\!\sqrt{P{+}\hat{\sigma}^2s^{-1} + 2\rho P (1{-} s {-} 2\rho s)}}.
\end{align}
The second term is%
\begin{align}
	V_2(\QX, \widehat{W}) &= \frac{\EX_{\QX}[\EX_{\widehat{W}}^2 [ \varepsilon_{s, \zerov, \zerov,\rho}(X, Y)|X]]}{\EX_{\QX{\times}\widehat{W}}^2[\varepsilon_{s, \zerov, \zerov, \rho}(X,Y)]}.
\end{align}
We compute the numerator through the steps%
\begin{align}
	&\EX_{\widehat{W}}^2 [\varepsilon_{s, \zerov, \zerov, \rho}(x,Y)] =  \frac{\alpha_{1-\rho s}^2 \alpha^{2\rho}_s}{\rho(2\pi P_{\!s})^{\rho-1}}  \mathcal{N}^2\!\left(\! x; \frac{P_s {-} \rho s P}{\rho(1{-}s\rho)} \right)\\
	&\EX_{\QX}\EX_{\widehat{W}}^2 [\varepsilon_{s, \zerov, \zerov, \rho}(X,Y)|X] = \frac{1}{s \rho} \frac{\sqrt{2}(\hat{\sigma}^{2} s^{-1})^{\rho} P_s^{1-\rho}}{P_s {+} \rho P (2{-}s{-}2s\rho)}
\end{align}
and thus%
\begin{align}
	V_2(\QX, \widehat{W}) &= \frac{\sqrt{2}}{\rho s} \frac{P{+}\hat{\sigma}^2s^{-1} + \rho P(1{-}s{-}\rho s)}{P{+}\hat{\sigma}^2 s^{-1} + \rho P (2{-}s{-}2\rho s)}.
\end{align}

\subsection{Gaussian spherical codebooks}
For spherical codebooks, we have%
\begin{align}
	\EX_{\QX}[\widehat{W}^s(y|X)e^{\lambda\! X^2}] = \frac{\alpha}{\sqrt{g(P)}} \cdot \mathcal{N}(y;\hat{\sigma}^2 s^{-1} {+} P')%
\end{align}
and the auxiliary variables%
\begin{align}
	C_2 &\triangleq \frac{1}{2} \log \left(g(P)+\frac{sP}{\hat{\sigma}^2}\right)\\%
	P' &\triangleq P/g(P)\\
	g(P) &\triangleq 1-2\lambda P.
\end{align}

The mismatched information density is%
\begin{align}
	i_{s,\lambda}(x, y) &= \lambda x^2+ C_2 - \frac{s}{2}\frac{(y{-}x)^2}{\hat{\sigma}^2} + \frac{1}{2} \frac{y^2}{\hat{\sigma}^2 s^{-1}{+}P'}%
\end{align}
and%
\begin{align}
	\EX_{\widehat{W}} [i_{s,\lambda}(x, Y)] &= \lambda x^2 + C_2 + \frac{1}{2} \frac{x^2{-}sP'}{\hat{\sigma}^2 s^{-1}{+}P'} \\
	\EX_{\QX {\times} \widehat{W}} [i_{s,\lambda}(X, Y)] &= \lambda P + C_2 + \frac{1}{2} \frac{P-sP'}{\hat{\sigma}^2 s^{-1}{+}P'}.%
\end{align}
After straightforward calculations, we can write%
\begin{align}
	I^\text{\normalfont ML}_{s, \lambda}(\QX, \widehat{W}) &= \frac{1}{2} \log\!\bigg(g(P)+\frac{sP}{\hat{\sigma}^2}\bigg) \nonumber \\
	&+ \frac{P(1{-}s){+}\hat{\sigma}^2 s^{-1}g(P)(1{-}g(P))}{2(P+\hat{\sigma}^2 s^{-1}g(P))}\\
	V_{s,\lambda} (\QX, \widehat{W}) &= \frac{P}{2} \frac{2\hat{\sigma}^2 g^2(P){+}s^2P}{(\hat{\sigma}^2 s^{-1}g(P) + P)^2}.
\end{align}

