\begin{definition}[Monotonicity across layers]\label{def:monotonicity-layers}
    Let $h \in [0..n-1]$ and $f \colon \{0, 1\}^n \to \R$. % such that $f$ has a unique global maximum at $x^* \in \{0, 1\}^n$. 
    We say that $f$ is increasing (resp.\ decreasing) between layers $\layer_{h + 1}$ and $\layer_h$ %(defined w.r.t. $x^*$) 
    if for any $x \in \layer_h$ and $y \in \layer_{h + 1}$ we have
        \[ f(x) > f(y) \text{ (resp. $f(x) < f(y)$)}.\]
    We denote this by $\layer_h \overset{f}{\succ} \layer_{h + 1}$ (resp. $\layer_h \overset{f}{\prec} \layer_{h + 1}$).
\end{definition}

