\begin{definition}[The \seqopt benchmark]\label{def:seqopt}
    Let $n \geq 2$, $k \in [ 0 .. n - 2 ]$ and $d_0 = n  > d_1 > d_2 > \dots > d_k > d_{k+1} = 0$ be integers. We define {\normalfont $\seqopt_k(d_1, \ldots, d_k)$} to be the set of all functions $f \colon \{0, 1\}^n \to \R$ such that
    \begin{enumerate}
        \item $x^* = (1, \dots, 1)$ is the unique global maximum of $f$,
        \item for any $\ell \in [0 .. k]$, if $k - \ell$ is even then
            \[ \layer_{d_{\ell}} \overset{f}{\prec} \cdots \overset{f}{\prec} \layer_{d_{\ell + 1}}, \]
        and if $k - \ell$ is odd, $f$ satisfies
            \[ \layer_{d_{\ell}} \overset{f}{\succ} \cdots \overset{f}{\succ} \layer_{d_{\ell + 1}}. \]

        The union of these classes of functions, for fixed $k$, will be denoted by
            \[ \seqopt_k = \bigcup_{n > d_1 > \cdots > d_k > 0} \seqopt_k(d_1, \ldots, d_k).\]
%            \[ \seqopt_k = \bigcup_{\substack{(d_1, \ldots, d_k) \in [0 .. n]^k \\ n > d_1 > \cdots > d_k > 0}} \seqopt_k(d_1, \ldots, d_k).\]
    \end{enumerate}
\end{definition}

