\begin{algorithm}
\DontPrintSemicolon
\caption{{The Markov move-acceptance hyper-heuristic with the acceptance operators \OI and \OW.}}\label{alg:mmahh}
\SetKwProg{Init}{Initialization}{:}{}
\Init{}{
    $t \gets 0$\;
    $x_0 \sim \mathcal{U}(\{0, 1\}^n)$, a uniformly sampled bit-string\;
    %$s_0 \sim \mu_0$, the initial state\;
    $s_0 \gets \OI$\;
}

\vspace{.5\baselineskip}
%\textbf{Input:} Choose $x_0 \in \{0,1 \}^n$ uniformly at random\\
\While{true}{
    $x' \gets \textsc{RamdomOneBitFlip}(x_t)$\;
    \uIf{$s_t = \OW$ \textbf{and} $f(x') < f(x_t)$}{
        $x_{t + 1} \gets x'$\;
    }\ElseIf{$s_t = \OI$ \textbf{and} $f(x_t) < f(x')$}{
        $x_{t + 1} \gets x'$\;
    }
    $s_{t + 1} \gets \textsc{Markov}(s_t)$\; \label{alg:mmahh-markov}
    $t \gets t + 1$\;
}
\end{algorithm}

