%As in \cite{DoerrL24}, we define
Let 
    \[ X^* = \{ x \in \{0, 1\}^n \mid \| x\|_1 \in \{n - m, n\} \}, \]
the set of (local and global) maxima of $\jump_m$ and we consider the potential
    \[ d \colon x \mapsto \begin{cases}
        \lvert n - m - \| x \|_1\rvert, & \text{if $x \neq x^*$;} \\ 
        0, & \text{otherwise.}
    \end{cases} \]

In the next two lemmas, we work out lower bounds on the drift of the bit-string sequence, distinguishing two cases based on the landscape of the $\jump_m$ function. In \Cref{lem:drift-gap-region}, we lower bound the drift in the gap region, i.e., at positions $x \in \{0,1\}^n$ such that $n - m < \| x \|_1 < n$, directly on the sequence $(x_t)_{t \geq 0}$ using the potential $d$ defined earlier. This result will provide an upper bound on the average time needed to climb towards $x^*$ from a point $x_0$ in the gap region. On the other hand, \Cref{lem:drift-left-slope} deals with the drift in the region with the \onemax-like slope, i.e., bit-strings $x \in \{0,1\}^n$ for which $0 \leq \| x \|_1 < n - m$. This time, we work at the scale of a pair of phases \AM\!+\OI since locally, depending on the current operator \OI or \AM, the drift might have opposite signs, notably in the region $[\frac{n}{2}.. (n - m)]$. To this aim, we will use \Cref{lem:driftAM-OI} along with the additive drift theorem with overshooting \cite{KotzingK19} to upper bound the expected time to climb this left slope from an initial point $x_0$.

%In what follows until the end of this part, we let $1 < m < \frac{n}{2}$ be a positive integer, $0 < p, q < 1$ be real number and $\mu_0$ an probability distribution over $\{\OI, \AM\}$. In these two results we consider the {\normalfont \MMAHH} on {\normalfont $\jump_m$} starting initially in $x_0 \sim \mathcal{U}(\{0,1\}^n)$ and $s_0 \sim \mu_0$ with states \OI and \AM and transition probability $p$ and $q$ to go from $\OI \to \AM$ and $\AM \to \OI$ respectively.

\begin{lemma}[Drift in the gap region]\label{lem:drift-gap-region}
    Let $x \in \{0,1\}^n$ with $n - m < \| x \|_1 < n$. Then
        \[ \esp[d(x_t) - d(x_{t + 1}) \mid x_t = x] \geq \frac{2 d(x)}{n}. \]
\end{lemma}


\begin{lemma}[Average time spent in the slope towards a local maximum]\label{lem:drift-left-slope}
    Let $x_0 \in \{0, 1\}^n$ such that $\| x_0 \|_1 < n - m$ and $T_0 = \inf\{ t \geq 0 \mid \| x_t \|_1 = n - m \}$ be the time taken by the {\normalfont \MMAHH} to reach a local maximum of {\normalfont $\jump_m$}, starting in $(x_0, s)$ with $s \in \{\OI, \AM\}$. Then
        \[ \esp[T_0] = O \left( (n - \| x_0 \|_1 ) (1 + p n) \left( \frac{1}{p} + \frac{1}{q} \right) \right), \]
    provided that $\frac{m}{2 (n - 2 m)}\left( q + \frac{4}{n} \right) \geq p$ and $n \geq 3$.

    In particular, if $\| x_0 \|_1 = n - m - 1$, then
        \[\esp\left[ T_0 \right] = \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right) .\]
\end{lemma}

\begin{lemma}[Average time to climb towards a maximum]\label{lem:avg-time-to-climb-jump}
    Let $T_1 = \inf\{ t \geq 0 \mid x_t \in X^* \}$ be the time taken by the {\normalfont \MMAHH} starting with $(x_0, \OI)$ to reach $x^*$ or a local maximum of {\normalfont $\jump_m$} then
        \[ \esp[T_1] = \O\left( n (1 + p n) \left( \frac{1}{p} + \frac{1}{q} \right) \right), \]
    provided that $\frac{m}{2 (n - 2 m)}\left( q + \frac{4}{n} \right) \geq p$ and $n \geq 3$.
\end{lemma}

%\begin{corollary}[Average time to return to a local maximum from a neighbor in the slope]\label{lem:avg-time-to-return-slope}
%    Let $x_0 \in \{0,1\}^n$ with $\| x_0 \|_1 = n - m - 1$. and let $T_\ell$ be the time taken by the {\normalfont \MMAHH} starting with $(x_0, s_0)$ to reach a local maximum of $\jump_m$. Then
%        \[\esp\left[ T_\ell \right] = \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right) ,\]
%    provided that $\frac{m}{2 (n - 2 m)}\left( q + \frac{4}{n} \right) \geq p$ and $n \geq 3$.
%\end{corollary}

We can now prove the main theorem of this section.
\begin{proof}[Proof of \Cref{thm:mmahh-time-jump-oi-am}]
    The overall runtime of the \MMAHH can be split in two times $T_1$ and $T_2$ such that $T = T_1 + T_2$,
        \[ T_1 = \inf\{ t \geq 0 \mid x_t \in X^* \}, \]
    and $T_2$ is the time, starting in a local maximum of $\jump_m$ (if it happens), to reach $x^*$.
    First, by \Cref{lem:avg-time-to-climb-jump} we have
        \[  \esp[T_1] = \O\left( n (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right), \]
    and it remains to upper bound $\esp[T_2]$. Of course, $T_2 = 0$ if we already reached $x^*$ during the first phase. Now, assume we do not, and hence, we are in some local maximum of $\jump_m$, i.e., some $x \in \{0, 1\}^n$ such that $\| x \|_1 = n - m$. We then define excursions that start upon leaving layer $\layer_m$ (the set of local maxima of $\jump_m$) and end either when we come back to this set of local maxima in $\layer_m$ (in case of a failure) or when we reach $x^*$. As every excursion starts in state \AM, the number $N$ of such excursions can be upper bounded by the number $N^*$ of phases of \AM needed to reach $x^*$ from layer $\layer_m$. By \Cref{lem:avg-phases-AM}, this can be bounded by
        \[ \esp[N] \leq \esp[N^*] \leq \frac{n^m}{m! (1 - q)^{m - 2}}. \]

    Then, if we denote by $e_i$ the $i$-th excursion and by $\lambda(e_i)$ its length, , i.e., the time of
the excursion $e_i,$ we can write
        \[ T_2 = T^w_0 + \sum_{i = 1}^N \left( \lambda(e_i) + T^w_i \right), \]
    where $T^w_i$ for $0 \leq i \leq N$ is waiting time between each excursion ($T^w_N = 0$ and $T^w_0$ is the time before the first excursion starts). These waiting times can all be bounded from above in expectation by $\frac{1}{p}$ since only the \OI operator can be stuck in this set of local maxima of $\jump_m$. Now, we can split the excursions into two families: the left-excursions (starting with the move from $n - m$ to $n - m - 1$) and the right-excursions (beginning with the move from $n - m$ to $n - m + 1$). Given an excursion $e_i$, where $1 \leq i \leq N$, then as all the left-excursions (resp. right-excursions) follow the same distribution, we know that if $e_i$ is a left-excursion, by \Cref{lem:drift-left-slope} we have
        \begin{align*}
             \esp[\lambda(e_i)] & \leq 1 + \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right) \\ 
             & = \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right),
        \end{align*}
        %\[ \esp[\lambda(e_i)] \leq 1 + \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right) = \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right), \]
    and if $e_i$ is a right-excursion, from the proof of \Cref{lem:avg-time-to-climb-jump} and \Cref{lem:drift-gap-region} we obtain
        \[ \esp[\lambda(e_i)] \leq 1 + \frac{n}{2} = O(n). \]

    Thus, as $O(n) = O(m n) = O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right)$ we conclude that
        \[ \esp[\lambda(e_i)] = \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right). \]
    Hence, by Wald's theorem %(\Cref{thm:wald}) 
    we obtain
        \begin{align*}
            \esp[T_2] & = \esp[T_0^w] + \esp\left[ \sum_{i = 1}^N [ \lambda(e_i) + T^w_i] \right] \\ 
            & \leq \frac{1}{p} + \esp[N] \left( \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right) + \frac{1}{p} \right) \\ 
            & = \O\left( \esp[N] m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right) \\ 
            & = \O\left(\frac{n^m}{(m - 1)! (1 - q)^{m - 1}} (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right).
        \end{align*}
    Finally, building on what we computed, we have
    %summing both $\esp[T_1]$ and $\esp[T_2]$ leads to
    \begin{align*}
        \esp[T] & = \esp[T_1] + \esp[T_2] \\
        & = \O\left( (1 + pn) \left( \frac{1}{p} + \frac{1}{q} \right) N_{n, m, q} \right),
    \end{align*}
        %\[ \esp[T] = \esp[T_1] + \esp[T_2] = \O\left( (1 + pn) \left( \frac{1}{p} + \frac{1}{q} \right) \left[ n + \frac{n^m}{(m - 1)! (1 - q)^{m - 1}} \right] \right), \]
    where $N_{n, m, q} = n + \frac{n^m}{(m - 1)! (1 - q)^{m - 1}}$.
\end{proof}

\section{Runtime Analysis of the \MMAHH with OnlyWorsening Acceptance on \seqopt}\label{sec:runtime-analysis}

We now state and prove the runtime of our \MMAHH, which uses a Markov chain to select either the \OI or \OW acceptance operator, on the $\seqopt$ benchmark. 

\begin{theorem}[Runtime analysis of the \MMAHH]\label{thm:RuntimeMMAHH}
    Assume $p = \Theta(\frac{1}{n \log(n)} )$, $q = \Theta(\frac{1}{n \log(n)})$. Let $k \in [ 0 .. (n - 2) ]$ and $f \in \seqopt_k(d_1, \ldots, d_k)$ where $n > d_1 > \dots > d_k > 0 $. If $k = \O(1)$ then, the \MMAHH with \OI and \OW reaches the global maximum at $x^* = (1,\dots, 1)$ of $f$ in runtime $T$ with the expectation
        \[ \esp[T] = O \left( \frac{n^{k + 1}}{d_1 \cdots d_k} \log(n) \right). \]
\end{theorem}
\begin{proof}
    % First of all, without loss of generality (up to an additional $O(n \log(n))$ term which does not impact the overall runtime), we can assume \Cref{alg:mmahh} starts in state \OW. Moreover, we can even assume that initially $x_0 = \{0\}^n$ (worse-case scenario). This makes sense, when the initial bit-string $x_0 \sim \mathcal{U}(\{0, 1\}^n)$ is uniformly sampled then the worse possible case is the one where $x_0$ is the farthest from the global maximum at $x^*$. To make it more precise, suppose a player $A$ follows \Cref{alg:mmahh} with $x_0 \sim \mathcal{U}(\{0, 1\}^n)$ and $s_0 \sim \mu_0$, a probability distribution over $\{\OI, \OW\}$ then, as argued before in sub-sections \ref{subsubsec:minimality-pn0} and \ref{subsubsec:overview-proof}, the minimality of $p_n^0$ in conjunction with $p, q = \Theta\left(\frac{1}{n \log(n)} \right)$ ensures that the \MMAHH reaches a local optima, say at $d_{\ell}$, $\ell \in [0 .. k + 1]$ in an average $O(n \log(n))$ time. As only one of the two operators between \OI and \OW can escape from this local optima, player $A$ can wait an additional $O(n \log(n))$ time on average such that $A$ is still at $d_{\ell}$ but in state $s = \OI$ (resp. $s = \OW$) if $\layer_{d_{\ell}}$ is a set of local minima (resp. maxima). At this point, stop the algorithm and run another session with player $B$ following the same algorithm with initial conditions $x_0 = \{0\}^n$ and $s_0 = \OW$ until $B$ reaches $\layer_{d_{\ell}}$ in the same state as $A$. After this point, the two players will follows trajectories which have the same distribution as by \Cref{lem:markov-chain} $((y_t, s_t))_{t \geq 0}$ is a Markov chain. Hence, up to an additional $O(n \log(n))$ term with does not impact the claimed overall runtime, we can simply focus on upper bounding the average time taken by player $B$ starting in $(x_0, s_0) = (\{0\}^n, \OW)$ to reach $x^*$.
    We will prove the desired result by induction on the local optima $d_\ell$ for $\ell\in[1..k]$. To do so we denote the first hitting time of a local optimum at $d_{\ell},$ by $T_{\ell}.$ The inductive hypothesis is then stated as follows,
    \begin{equation} \label{eqn:MMAHHInduction}
     \esp[T_{\ell}] = O \left(  \frac{n^{\ell}}{d_1 \cdots d_{\ell - 1}} \log(n) \right).  
    \end{equation}
    We first demonstrate \eqnref{eqn:MMAHHInduction} for the base case with $\ell=1.$ We denote by $k^*_1$ the number of phases needed to first reach a local optimum at $d_1$, i.e., $k^*_1 = \inf \left\{ k \in \N \mid y_{T^{(k)}_s} = d_1 \right\}$ and $T_1$ the time taken to reach said local optimum. Here we upper bound $\esp[T_1]$ by assuming $(y_0, s_0) = (n, \OW).$ Since for times $t\in[0..T_1]$ $x_t$ is confined to the slope, for which $y_t \in [d_1, n],$ with monotonic fitness value, our \emph{one-phase approximation} in \Cref{lem:one-phase-approx} applies and gives
        \[ \esp[k_1^*] \leq \frac{1}{p_n^0} = O(1), \]
    because $p, q = \Theta(\sfrac{1}{n \log(n)})$. Now, since 
        \[ T_1 \leq \sum\limits_{k=0}^{k^*_1 - 1} Z_k, \]
    and, by Lemma 22, %\Cref{lem:geometric-law},
    $\esp\left[ Z_k \right] \leq \max\left\{ \frac{1}{p}, \frac{1}{q} \right\} = O(n \log(n))$, we can use Wald's Theorem (see Theorem 17
    %\ref{thm:wald}
    ) to obtain
        \[ \esp[T_1] \leq \frac{1}{p_n^0} \max\left\{ \frac{1}{p}, \frac{1}{q} \right\} = O(n \log(n)), \]
    as desired. This establishes \eqnref{eqn:MMAHHInduction} in the case $\ell = 1$.

     Now, for the induction step suppose that \eqnref{eqn:MMAHHInduction} is true for some $\ell \in[1..k]$. Without loss of generality, we assume that at $d_{\ell}$, the layer $\layer_{d_{\ell}}$ is a set of local maxima of $f$ (our argument equally holds for local minima by exchanging \OI and \OW). From these maxima, we define an excursion as a walk that starts by leaving $\layer_{d_{\ell}}$ and, either comes back to $\layer_{d_{\ell}}$ without having hit $\layer_{d_{\ell + 1}}$ (in case of a failure) or reach the new (unvisited) set of minima at layer $\layer_{d_{\ell + 1}}$ (in case of a success). We illustrate this situation in \Cref{fig:excursions-illustration}, where failing excursions are depicted in red and a successful excursion is shown in green.

