%\end{theorem}

\begin{theorem}[Additive drift theorem with overshooting -- \cite{KotzingK19}]\label{thm:add-drift-overshooting}
    Let $\alpha \leq 0$ be a non-positive real number, $(X_t)_{t \geq 0}$ a sequence of random variables over $\R$ and $T = \inf\{ t \geq 0 \mid X_t \leq 0\}$. Suppose that for any $0 \leq t \leq T$, $X_t \geq \alpha$ and there exists $\delta > 0$ such that for all $0 \leq t < T$, 
        \[ X_t - \esp[X_{t + 1} \mid X_0, \ldots, X_t] \geq \delta, \]
    then
        \[ \esp[T \mid X_0] \leq \frac{X_0 - \esp[X_T \mid X_0]}{\delta} \leq \frac{X_0 - \alpha}{\delta}. \]
\end{theorem}

\begin{theorem}[Multiplicative drift theorem -- \cite{DoerrJW12algo}]\label{thm:mult-drift}
    Let $S \subseteq \R_+^*$ be a finite state space of positive real numbers with minimum $s_{\min}$ and $(X_t)_{t\geq0}$ a sequence of random variables over $S \cup \{0\}$. Let $T$ be the first time $t \in \N$ for which $X_t = 0$ and suppose further that there exists a constant $\delta > 0$ such that 
    \[
    \esp\left[X_{t} - X_{t+1} \mid  X_t = s \right] \geq \delta s,
    \]
    holds for all $s \in S$ with $\Pr\left[X_t = s\right] > 0$. Then, for all $s_0 \in S$ with $\Pr\left[X_0 = s_0 \right] > 0$,
    \[
    \esp\left[T \mid  X_0 = s_0 \right] \leq \frac{1 + \log(s_0/s_{\min})}{\delta}.
    \]
\end{theorem}




\section{Tools for the Analysis of the \MMAHH}\label{app:tools-analysis-mmahh}

% Here are included results about the bit-strings $(x_t)_{t \in \N}$, the states $(s_t)_{t \in \N}$ and the length $(Z_k)_{k \in \N}$ of the phases.
\begin{proof}[Proof of \Cref{lem:minimality-p^0_n}]
    We prove that for a fixed $0 \leq h \leq n$ then the probabilities $(\Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI])_{0 \leq k  \leq n}$ are non-increasing, i.e.,
        \begin{align*} 
            \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = n, s_0 = \OI] & \leq \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = n - 1, s_0 = \OI] \\ 
            & \leq \ldots \leq \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = 0, s_0 = \OI] = 1, 
        \end{align*}
    and for a fixed $0 \leq k \leq h$, the probabilities $(\Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI])_{0 \leq h  \leq n}$ are non-decreasing, i.e.,
        \begin{align*} 
            \Pr[y_{T_s^{(1)}} \leq 0 \mid y_0 = k, s_0 = \OI] & \leq \Pr[y_{T_s^{(1)}} \leq 1 \mid y_0 = k, s_0 = \OI] \\ 
            & \leq \ldots \leq \Pr[y_{T_s^{(1)}} \leq n \mid y_0 = k, s_0 = \OI] = 1. 
        \end{align*}
    Note that these two results imply the minimality of $p_n^0$ that we claim in our lemma.

    For the first part, fix $h$ and let $0 \leq k \leq n$ then, when $k < h$ one has:
    \[ \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k + 1, s_0 = \OI] = 1 \leq 1 = \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI] \]
    and when $h \leq k < n$, we have:
        \begin{align*}
            \Pr[y_{T_s^{(1)}} \leq h \mid y_0 & = k + 1, s_0 = \OI] \\ 
            & = \frac{1}{1 - p} \frac{\Gamma(k + 2) \Gamma\left( \frac{n p}{1 - p} + h + 1 \right)}{\Gamma(h + 1) \Gamma\left( \frac{n p}{1 - p} + k + 2 \right)} \\ 
            & = \left( \frac{k + 1}{\frac{n p}{1 - p} + k + 1} \right) \frac{1}{1 - p} \frac{\Gamma(k + 1) \Gamma\left( \frac{n p}{1 - p} + h + 1 \right)}{\Gamma(h + 1) \Gamma\left( \frac{n p}{1 - p} + k + 1 \right)} \\ 
            & = \left( \frac{k + 1}{\frac{n p}{1 - p} + k + 1} \right) \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI] \\ 
            & < \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI],
        \end{align*}
    because $\frac{n p}{1 - p} > 0$ since $p > 0$.

    Now, for the other part, fix $k$ and let $0 \leq h \leq n$ then, when $k < h$ one has:
    \[ \Pr[y_{T_s^{(1)}} \leq h - 1 \mid y_0 = k, s_0 = \OI] = 1 \leq 1 = \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI] \]
    and when $0 < h \leq k$, we have:
        \begin{align*}
            \Pr[y_{T_s^{(1)}} \leq h - 1 \mid y_0 & = k, s_0 = \OI] \\ 
            & = \frac{1}{1 - p} \frac{\Gamma(k + 1) \Gamma\left( \frac{n p}{1 - p} + h \right)}{\Gamma(h) \Gamma\left( \frac{n p}{1 - p} + k + 1 \right)} \\ 
            & = \left( \frac{h}{\frac{n p}{1 - p} + h} \right) \frac{1}{1 - p} \frac{\Gamma(k + 1) \Gamma\left( \frac{n p}{1 - p} + h + 1 \right)}{\Gamma(h + 1) \Gamma\left( \frac{n p}{1 - p} + k + 1 \right)} \\ 
            & = \left( \frac{h}{\frac{n p}{1 - p} + h} \right) \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI] \\ 
            & < \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI],
        \end{align*}
    because $\frac{n p}{1 - p} > 0$ since $p > 0$. This is what we wanted to prove.
\end{proof}


We note the following elementary results following directly from the definition of the \MMAHH.

\begin{lemma}\label{lem:markov-chain}
   The sequence $\left( (x_t, s_t) \right)_{t \in \N}$ is a homogeneous Markov chain. Moreover, when $f \in \seqopt_k$ with $k \in \N$ then $\left( (y_t, s_t) \right)_{t \in \N}$ is also a homogeneous Markov chain.
\end{lemma}

\begin{proof}[Proof of \Cref{lem:markov-chain}]
    We have 
    \begin{equation}
        (x_{t+1}, s_{t+1}) = g((x_t, s_t), (z_t, v_t)),
    \end{equation}
    where $z_t \overset{\rm i.i.d.}{\sim} \mathcal U([0, 1])$ is a random variable sampled uniformly in $[0, 1]$ independently from $(x_t, s_t)$, $v_t \overset{\rm i.i.d.}{\sim} \mathcal U([1..n])$ is a random variable sampled uniformly in $[1 ..n]$ independently from $(x_t, s_t)$ and $z_t$, and the function $g$ is defined as follows
    \begin{equation}
        g((x, s), (z, v)) = \begin{cases}
            (x_v', h(s, z)), & \text{ if } s = \OI \text{ and } f(x_v') > f(x);  \\ 
            (x, h(s, z)), & \text{ if } s = \OI \text{ and } f(x_v') \leq f(x); \\
             (x_v', h(s, z)), & \text{ if } s = \OW \text{ and } f(x_v') < f(x); \\
            (x, h(s, z)), & \text{ if } s = \OW \text{ and } f(x_v') \geq f(x);
        \end{cases}
    \end{equation}
    where $x_v'$ is obtained from $x$ by flipping its $v$-th bit,  and we denote by $h$ the function defined by
    \begin{equation}
        h(s, z) = \begin{cases}
            \OI, & \text{ if } s = \OI \text{ and } z \leq 1 - p; \\
            \OW, & \text{ if } s = \OI \text{ and } z > 1 - p; \\
            \OW, & \text{ if } s = \OW \text{ and } z \leq 1 - q; \\
            \OI, & \text{ if } s = \OW \text{ and } z > 1 - p.
        \end{cases} \label{eq:def-function-h}
    \end{equation}
    This proves that $\left( (x_t, s_t) \right)_{t \in \N}$ is a homogeneous Markov chain.

    Furthermore, by definition $y_t = \Hamming(x_t, x^*)$, hence when $f \in \seqopt_k$ we have $y_t = n - \| x_t \|_1$. The following holds
    \begin{equation}
        (y_{t+1}, s_{t+1}) = \ell((y_t, s_t), (z_t', v_t')),
    \end{equation}
     where $z_t' \overset{\rm i.i.d.}{\sim} \mathcal U([0, 1])$ is a random variable sampled uniformly in $[0, 1]$ independently from $(y_t, s_t)$, $v_t' \overset{\rm i.i.d.}{\sim} \mathcal U([0, 1])$ is a random variable sampled uniformly in $[0, 1]$ independently from $(y_t, s_t)$ and $z_t'$, and the function $\ell$ is defined as follows
     \begin{equation}
         \ell((y, s), (z, v)) = \begin{cases}
             (y, h(s, z)), & \text{ if } s = \OI, v < \frac{y}{n},   \layer_{y - 1} \overset{f}{\prec} \layer_{y};\\
             (y, h(s, z)), & \text{ if } s = \OI, v \geq \frac{y}{n},  \layer_{y+1} \overset{f}{\prec} \layer_{y}; \\
             (y, h(s, z)), & \text{ if } s = \OW, v < \frac{y}{n},  \layer_{y} \overset{f}{\prec} \layer_{y-1}; \\
             (y, h(s, z)), & \text{ if } s = \OW, v \geq \frac{y}{n},  \layer_{y} \overset{f}{\prec} \layer_{y+1}; \\
             (y - 1, h(s, z)), & \text{ if } s = \OI, v < \frac{y}{n},  \layer_{y} \overset{f}{\prec} \layer_{y-1};\\
             (y - 1, h(s, z)), & \text{ if } s = \OW, v < \frac{y}{n},  \layer_{y-1} \overset{f}{\prec} \layer_{y};\\
             (y + 1, h(s, z)), & \text{ if } s = \OI, v \geq \frac{y}{n},  \layer_{y} \overset{f}{\prec} \layer_{y+1}; \\
             (y + 1, h(s, z)), & \text{ if } s = \OW, v \geq \frac{y}{n},  \layer_{y+1} \overset{f}{\prec} \layer_{y};
         \end{cases}
     \end{equation}
     where the function $h$ is defined in the same manner as in \eqref{eq:def-function-h}, and the random variable $v_t$ is used to express wether the flip at time $t$ is a $0$-flip or a $1$-flip. This concludes the proof.
\end{proof}

%And the next two lemmas will be useful when splitting a probability according to the length of a phase.
\begin{lemma} \label{lem:independance}
    For any $k \in \N$, the random variables $Z_k$ and $x_{T_s^{(k)}}$ are independent. Consequently, the conditional law of $Z_k$ under $s_0 = s \in \{\OI, \OW\}$ does not depend on $x_{T_s^{(k)}}$ -- and thus also not on $y_{T_s^ {(k)}}$.
\end{lemma}

\begin{proof}[Proof of \Cref{lem:independance}]
    Fix $\ell \in \N^*$, we have by definition $Z_k = T_s^{(k+1)} - T_s^{(k)}$ where $T_s^{(k+1)} = \inf\{t \geq T_s{(k)}: s_{t} \neq s_{T_s^{(k)}} \}$. Hence $Z_k$ is fully determined by the $\sigma$-algebra $\mathcal F$ generated by the random variables $\{s_t: t \geq 0 \}$. Since $\{s_t\}_{t\geq 0}$ is a Markov chain ($s_{t+1}$ depends only on $s_t$), we have 
    \begin{equation}
        \forall \mathcal A \in \mathcal F,\;  \Pr[\mathcal A \mid x_{T_s^{(k)}}] = \Pr[\mathcal A],
    \end{equation}
    thus we have $\Pr[Z_k \mid x_{T_s^{(k)}}] = \Pr[Z_k]$. This yields the independence of $Z_k$ and $x_{T_s^{(k)}}$.
\end{proof}

\begin{lemma}\label{lem:geometric-law}
    For any $k \in \N$ we have
        \[ Z_k \sim U_k, \]
    where $U_k$ is a random geometric variable of parameter $p$ when $k$ is even and $q$ otherwise.
\end{lemma}
\begin{proof}[Proof of \Cref{lem:geometric-law}]
    If $k$ is even, since $s_0 = \OI$ we have $s_{T_s^{(k)}} = \OI$ and $s_{T_s^{(k+1)}} = \OW$. Fix $\ell \in \N^*$, we have 
    \begin{align}
        \Pr[Z_k = \ell] &= \Pr[T_s^{(k+1)} - T_s^{(k)} = \ell]\\
        &= \sum_{j \geq 0} \Pr[T_s^{(k+1)} - T_s^{(k)} = \ell \mid T_s^{(k)} = j] \Pr[T_s^{(k)} = j] \\
        &= \sum_{j \geq 0} \Pr[T_s^{(k+1)} = j + \ell \mid T_s^{(k)} = j] \Pr[T_s^{(k)} = j] \\
        & = \sum_{j \geq 0} \Pr[s_{j+ \ell} = \OW, s_{j+ \ell - 1} = \OI, \dots, s_{j+1} = \OI \mid T_s^{(k)} = j] \Pr[T_s^{(k)} = j]  \\
        &= \sum_{j \geq 0} (1- p)^{\ell - 1} p \Pr[T_s^{(k)} = j]  \\
        &= (1- p)^{\ell - 1} p \sum_{j \geq 0} \Pr[T_s^{(k)} = j] \\
        &= (1 - p)^{\ell - 1} p,
    \end{align}
    hence $Z_k$ follows the geometric law of parameter $p$ as claimed in the lemma.

    Similarly, if $k$ is odd we have $s_{T_s^{(k)}} = \OW$ and $s_{T_s^{(k+1)}} = \OI$. Fix $\ell \in \N^*$, we have 
    \begin{align}
        \Pr[Z_k = \ell] &= \Pr[T_s^{(k+1)} - T_s^{(k)} = \ell]\\
        &= \sum_{j \geq 0} \Pr[T_s^{(k+1)} - T_s^{(k)} = \ell \mid T_s^{(k)} = j] \Pr[T_s^{(k)} = j] \\
        &= \sum_{j \geq 0} \Pr[T_s^{(k+1)} = j + \ell \mid T_s^{(k)} = j] \Pr[T_s^{(k)} = j] \\
        & = \sum_{j \geq 0} \Pr[s_{j+ \ell} = \OI, s_{j+ \ell - 1} = \OW, \dots, s_{j+1} = \OW \mid T_s^{(k)} = j] \Pr[T_s^{(k)} = j]  \\
        &= \sum_{j \geq 0} (1- q)^{\ell - 1} q \Pr[T_s^{(k)} = j]  \\
        &= (1- q)^{\ell - 1} q \sum_{j \geq 0} \Pr[T_s^{(k)} = j] \\
        &= (1 - q)^{\ell - 1} q,
    \end{align}
    hence $Z_k$ follows the geometric law of parameter $q$ as claimed.
\end{proof}

The heart of our analysis is the following proof of \Cref{lem:oi-prob}.

\begin{proof}[Proof of \Cref{lem:oi-prob}]
    Fix $\ell \in \N^*$, we denote by $p_{k, \ell}^h$ the following probability
        \[ p_{k, \ell}^h = \Pr[y_{\ell} \leq h \mid y_0 = k, T_s^{(1)} = \ell, s_0 = \OI], \]
    which is the probability that at some time $0 \leq t \leq \ell$ we reach a bit-string $x'$ such that $\Hamming(x', x^*) \leq h$ after performing consecutively $\ell$ times the \OI acceptance operator. %These probabilities $\left( p_{k, \ell}^h \right)_{\substack{\ell \in \N^* \\ 0 \leq k \leq n}}$ satisfy, given $0 \leq k \leq n$ and $\ell \geq 1$
    Now, given $0 \leq k \leq n$ and $\ell \geq 1$, we have the boundary conditions $p_{k, \ell}^h = 1$ if $k \leq h$ and $p_{k, \ell}^h = 0$ if $h < k$ and $\ell < k - h$. Otherwise, when $h < k$, $\ell \geq k - h$ and $\ell \geq 2$, the following recurrence
        \begin{equation}\label{oi-prob:eq1}
            p_{k, \ell}^h = \left( \frac{n - k}{n} \right) p_{k, \ell - 1}^h + \left( \frac{k}{n} \right) p_{k - 1, \ell - 1}^h, 
        \end{equation} 
    holds and is derived using a first step analysis of the Markov chain $((x_t, s_t))_{t \in \N}$ and as $\ell \geq 2$ then at least $s_0 = \OI = s_1$. Notice that relation \eqnref{oi-prob:eq1} still holds in the cases $k \leq h$ (since also $k - 1 \leq h)$ but also when both $h < k$ and $\ell < k - h$ since then $\ell - 1 < k - h$ and $\ell - 1 < (k - 1) - h$.
    %\begin{itemize}
    %    \item $p_{k, \ell}^h = 1$ if $k \leq h$,
    %    \item $p_{k, \ell}^h = 0$ if $h < k$ and $\ell < k - h$,
    %    \item if $h < k$, $\ell \geq k - h$ and $\ell \geq 2$ then
    %        \[ p_{k, \ell}^h = \left( \frac{n - k}{n} \right) p_{k, \ell - 1}^h + \left( \frac{k}{n} \right) p_{k - 1, \ell - 1}^h, \]
    %    which is derived using a first step analysis of the Markov chain $((X_t, s_t))_{t \in \N}$.
    %\end{itemize}

    That being said, we can now split the probability $p_k^h$ where $0 \leq k \leq n$ is such that\footnote{Otherwise, if $0 \leq k \leq h$ then $p_k^h = 1$ as we will see.} $h < k$ as
        \begin{align*}
            p_k^h & = \Pr[y_{T_s^{(1)}} \leq h \mid y_0 = k, s_0 = \OI] \\ 
            & = \sum_{\ell = 1}^{\infty} \Pr[y_{\ell} \leq h \mid y_0 = k, T_s^{(1)} = \ell, s_0 = \OI] \Pr[T_s^{(1)} = \ell \mid y_0 = k, s_0 = \OI] \\
            & = \sum_{\ell = 1}^{\infty} p_{k, \ell}^h \Pr[Z_0 = \ell \mid s_0 = \OI] \numberthis\label{eq:prob-1} \\ 
            & = \sum_{\ell = 1}^{\infty} p_{k, \ell}^h (1 - p)^{\ell - 1} p \\
            & = p_{k, 1}^h p + \sum_{\ell = 2}^{\infty} \left( \left( \frac{n - k}{n} \right) p_{k, \ell - 1}^h + \left( \frac{k}{n} \right) p_{k - 1, \ell - 1}^h \right) (1 - p)^{\ell - 1} p \\ 
            & = p_{k, 1}^h p + \left( \frac{n - k}{n} \right) (1 - p) \sum_{\ell = 2}^{\infty} p_{k, \ell - 1}^h (1 - p)^{\ell - 2} p \\
            &\hphantom{= p_{k, 1}^h p\ }+ \left( \frac{k}{n} \right) (1 - p) \sum_{\ell = 2}^{\infty} p_{k - 1, \ell - 1}^h (1 - p)^{\ell - 2} p \\ 
            & = p_{k, 1}^h p + \left( \frac{n - k}{n} \right) (1 - p) p_k^h + \left( \frac{k}{n} \right) (1 - p) p_{k - 1}^h \numberthis\label{eq:prob-2},
        \end{align*}
    where, in \eqnref{eq:prob-1} we use \Cref{lem:independance} since $T_s^{(1)} = Z_0$ denotes the length of the first phase of \OI (as $s_0 = \OI$).

    Then to solve this recurrence, first, one need to find an expression for $p_{k, 1}^h$, which is
        \[ p_{k, 1}^h = \begin{cases} 0, & \text{if $h + 1 < k$;} \\ \frac{h + 1}{n}, & \text{if $k = h + 1$;} \\ 1, & \text{if $k \leq h$;} \end{cases} \]
    and
        \[ p_h^h = \sum_{\ell = 1}^{\infty} p_{h, \ell}^h (1 - p)^{\ell - 1} p = \sum_{\ell = 1}^{\infty} (1 - p)^{\ell - 1} p = 1. \]

    Next, we distinguish the cases $k = h + 1$ and $k > h + 1$. First of all, if $k = h + 1$ then \eqnref{eq:prob-2} becomes
        \begin{align*} p_{h + 1}^h & = p_{h + 1, 1}^h p + \left( \frac{n - (h + 1)}{n} \right) (1 - p) p_{h + 1}^h + \left( \frac{h + 1}{n} \right) (1 - p) p_h^h \\ 
        & = \frac{h + 1}{n} +  \left( \frac{n - (h + 1)}{n} \right) (1 - p) p_{h + 1}^h,
        \end{align*}
    hence,
        \begin{align*} 
            p_{h + 1}^h & = \frac{h + 1}{n} \frac{1}{1 - \left( \frac{n - h - 1}{n} \right) (1 - p)} \\ 
            & = \frac{h + 1}{n - (n - h - 1)(1 - p)} \\
            & = \frac{1}{1 - p} \frac{h + 1}{\frac{n}{1 - p} - n + h + 1} \\
            & = \frac{1}{1 - p} \frac{h + 1}{\frac {n p}{1 - p} + h + 1}.
        \end{align*}

    On the other hand, when $k > h + 1$ then $p_{k, 1}^h = 0$ and grouping together the two terms in $p_k^h$, \eqnref{eq:prob-2} now becomes
        \begin{align*}
            p_k^h & = \frac{1}{1 - \left( \frac{n - k}{n} \right) (1 - p)} \left( \frac{k}{n} \right) (1 - p) p_{k - 1}^h \\ 
            & = \frac{k}{n - (n - k)(1 - p)} (1-p) p_{k - 1}^h \\ 
            & = \frac{k}{\frac{n}{1 - p} - n + k} p_{k - 1}^h \\ 
            & = \frac{k}{\frac{n p}{1 - p} + k} p_{k - 1}^h.
        \end{align*}

    Combining both cases, this leads to the following formula for $p_k^h$ when $h < k \leq n$
        \begin{align*} 
            p_k^h & = \frac{1}{1 - p} \prod_{j = h + 1}^k \left( \frac{j}{\frac{n p}{1 - p} + j} \right) \\
            & = \frac{1}{1 - p} \frac{k!}{h!} \frac{1}{\left( \frac{n p}{1 - p} + k \right) \cdots \left( \frac{n p}{1 - p} + h + 1 \right)} \\ 
            & = \frac{1}{1 - p} \frac{\Gamma(k + 1) \Gamma\left( \frac{n p}{1 - p} + h + 1 \right)}{\Gamma(h + 1) \Gamma\left( \frac{n p}{1 - p} + k + 1 \right)},
        \end{align*}
    where $\Gamma$ is the Gamma function. Moreover, when $k \leq h$ then $p_k^h = 1$ which is intuitive since the \OI operator cannot climb down \onemax. This proves the \Cref{lem:oi-prob} as desired.
\end{proof}


\begin{proof}[Proof of \Cref{lem:limit}]
    By \Cref{lem:oi-prob}, for any integer $n > 0$,
        \[ p_n^0 = \frac{1}{1 - p} \frac{\Gamma(n + 1) \Gamma\left( \frac{n p}{1 - p} + 1 \right)}{\Gamma\left( \frac{n p}{1 - p} + n + 1 \right)}, \]
    and, as $p = \frac{1}{c n \log(n)} = \o_{n \to +\infty}\left( \frac{1}{n} \right)$ then $\frac{1}{1 - p} = 1 + o(1)$ and $\frac{n p}{1 - p} = o(1)$. Moreover, by the continuity of the Gamma function over $\R_+^*$ 
        \[ \Gamma\left( \frac{n p}{1 - p} + 1 \right) = \Gamma(1) + o(1) = 1 + o(1). \]

    To derive the claimed asymptotic, we will use the Stirling's approximation for the gamma function which can be found in \cite[5.11.7]{NIST:DLMF}. We have
    \begin{align*}
        p_n^0 & = \frac{1}{1 - p} \frac{\Gamma(n + 1) \Gamma\left( \frac{n p}{1 - p} + 1 \right)}{\Gamma\left( \frac{n p}{1 - p} + n + 1 \right)} \\ 
        & = \frac{n!}{\Gamma\left( \frac{n}{1 - p} + 1 \right)} (1 + o(1)) \\
        & = \frac{\left( \frac{n}{e} \right)^n \sqrt{2 \pi n}}{\left( \frac{n}{e (1 - p)} \right)^{\frac{n}{1 - p}} \sqrt{\frac{2 \pi n}{1 - p}}} (1 + o(1)),
    \end{align*}
    and the factor in front of the $(1 + o(1))$ becomes
        \begin{align*}
            \frac{\left( \frac{n}{e} \right)^n \sqrt{2 \pi n}}{\left( \frac{n}{e (1 - p)} \right)^{\frac{n}{1 - p}} \sqrt{\frac{2 \pi n}{1 - p}}} & = \left( \frac{n}{e} \right)^n \left( \frac{e (1 - p)}{n} \right)^{\frac{n}{1 - p}} \sqrt{1 - p} \\ 
            & = \exp\left( n \log(n) - n + \frac{n}{1 - p} \left( \log(1 - p) + 1 - \log(n) \right) \right) \sqrt{1 - p},
        \end{align*}
    \hypertarget{exp-factor}{}
    where $\sqrt{1 - p} = 1 + o(1)$ while, for the exponential factor
    \begin{align*}
        &\exp\left( n \log(n) - n + \frac{n}{1 - p} \left( \log(1 - p) + 1 - \log(n) \right) \right) \\ 
        & = \exp\left( n \log(n) - n + \frac{n}{1 - p} - n \log(n) \left( 1 + p + O(p^2) \right) + \frac{n \log(1 - p)}{1 - p} \right) \\ 
        & = \exp\left( \frac{n p}{1 - p} - n \log(n) p + O\left( \frac{1}{n \log(n)} \right) + \frac{n}{1 - p} \left( -p + o(p) \right) \right) \\ 
        & = \exp\left( -\frac{1}{c} + o(1) \right). 
    \end{align*}

    Thus, we conclude that
        \[ \Pr[y_{T_s^{(1)}} = 0 \mid y_0 = n, s_0 = \OI] = \left( 1 + \o_{n \to +\infty}(1) \right)e^{-1 / c}, \]
    as desired.
\end{proof}

\section{Drift Lemmas}

\begin{proof}[Proof of \Cref{lem:driftAM}]
    First, as the length of a phase is also random, we write for $\ell \in \N_{>0}$
    \[ \Delta^{\AM}_{i, \ell} = \esp\left[ y_0 - y_{T_s^{(1)}} \mid \, y_0 = i, Z_0 = \ell, s_0 = \AM \right], \]
    the drift after performing exactly $\ell$ times the \AM operator in a row when starting in $y_0 = i$. Then, by conditioning on the length of the phase \AM, we obtain
        \begin{align*}
            \Delta^{\AM}_i & = \sum_{\ell = 1}^{\infty}  \Delta^{\AM}_{i, \ell} \Pr\left[ Z_{2 k} = \ell \mid y_{T_s^{(2k)}} = i, s_{T_s^{(2k)}} = \AM\right] \\
            & = \sum_{\ell = 1}^{\infty}  \Delta^{\AM}_{i, \ell} \Pr\left[ Z_{2 k} = \ell \mid s_{T_s^{(2k)}} = \AM \right] \numberthis\label{lem:driftAM-eq1} \\
            & = \sum_{\ell = 1}^{\infty}  \Delta^{\AM}_{i, \ell} (1 - q)^{\ell - 1} q, \numberthis\label{conditioningAM}
        \end{align*}
    where in \eqnref{lem:driftAM-eq1} we use \Cref{lem:independance} stating that variables $Z_{2 k}$ and $y_{T_s^{(2k)}}$ are independent. Then, for $\ell > 0$ and $j \in [0.. \ell - 1]$ let
    \[\Delta^{\AM}_{i, j, \ell} = \esp\left[ y_{T_s^{(2k)} + j} - y_{T_s^{(2k)} + j + 1} \mid \ y_{T_s^{(2 k)}} = i, Z_{2 k} = \ell, s_{T_s^{(2 k)}} = \AM \right], \]
    hence
    \[\Delta^{\AM}_{i, \ell} = \sum_{j = 0}^{\ell - 1} \Delta^{\AM}_{i, j, \ell}, \]
    and we now show by finite induction on $j \in [0.. \ell - 1]$ that
    \begin{equation}\label{lem:driftAM-HR}
        \forall i \in [0.. n],\  \Delta^{\AM}_{i, j, \ell} = \left(\frac{n-2}{n}\right)^j \frac{2i-n}{n}.    
    \end{equation}

    First, for $j = 0$, we have
    \begin{align*}
        \Delta^{\AM}_{i, 0, \ell} &= \esp\left[ y_{T_s^{(2k)}} - y_{T_s^{(2k)} + 1} \mid \ y_{T_s^{(2 k)}} = i, Z_{2 k} = \ell, s_{T_s^{(2 k)}} = \AM \right]\\ 
        &= \frac{i}{n} (1) + \frac{n-i}{n} (-1)\\
        &= \frac{2i - n}{n}.
    \end{align*}

    Then, if we suppose the result \eqnref{lem:driftAM-HR} correct for some $j \in [0..\ell - 2]$, we obtain
    \begin{align*}
        \Delta^{\AM}_{i, j+1, \ell} &= \esp\left[ y_{T_s^{(2k)} + j + 1} - y_{T_s^{(2k)} + j + 2} \mid \ y_{T_s^{(2 k)}} = i, Z_{2 k} = \ell, s_{T_s^{(2 k)}} = \AM, y_{T_s^{(2 k)} + 1} = i + 1 \right] \\
& \quad \Pr\left[ y_{T_s^{(2 k)} + 1} = i + 1 \mid \ y_{T_s^{(2 k)}} = i, Z_{2 k} = \ell, s_{T_s^{(2 k)}} = \AM \right]\\
        &\quad + \esp\left[ y_{T_s^{(2k)} + j + 1} - y_{T_s^{(2k)} + j + 2} \mid \ y_{T_s^{(2 k)}} = i, Z_{2 k} = \ell, s_{T_s^{(2 k)}} = \AM, y_{T_s^{(2 k)} + 1} = i - 1 \right] \\
& \quad \Pr\left[ y_{T_s^{(2 k)} + 1} = i - 1 \mid \ y_{T_s^{(2 k)}} = i, Z_{2 k} = \ell, s_{T_s^{(2 k)}} = \AM \right] \\
        & = \left(\frac{n-i}{n} \right) \esp\left[ y_{T_s^{(2k)} + j} - y_{T_s^{(2k)} + j + 1} \mid \ Z_{2 k} = \ell, s_{T_s^{(2 k)}} = \AM, y_{T_s^{(2 k)} + 1} = i + 1 \right] \\
        &\quad + \left(\frac{i}{n} \right) \esp\left[ y_{T_s^{(2k)} + j} - y_{T_s^{(2k)} + j + 1} \mid \ Z_{2 k} = \ell, s_{T_s^{(2 k)}} = \AM, y_{T_s^{(2 k)} + 1} = i - 1 \right]  \numberthis\label{equality 3} \\
        & =\left(\frac{n-i}{n} \right) 
        \Delta^{\AM}_{i+1, j, \ell} + \left(\frac{i}{n} \right) \Delta^{\AM}_{i-1, j, \ell} \\
        &= \left( \frac{n-i}{n} \right) \left(\frac{n-2}{n}\right)^j \frac{2(i+1)-n}{n} + \left(\frac{i}{n} \right) \left(\frac{n-2}{n}\right)^j \frac{2(i-1)-n}{n} \numberthis\label{equality 4}\\
        &= \left(\frac{n-2}{n}\right)^{j+1} \frac{2i-n}{n},
    \end{align*}
    where in \eqnref{equality 3}, we the first step analysis on a phase of \AM. In \eqnref{equality 4}, we use the hypothesis of induction from \eqnref{lem:driftAM-HR}.

    Recall that $\Delta^{\AM}_{i, \ell} = \sum\limits_{j = 0}^{\ell - 1} \Delta^{\AM}_{i, j, \ell}$ and thus we obtain using \eqnref{lem:driftAM-HR}
    \begin{align*}
        \Delta^{\AM}_{i, \ell} &= \sum_{j = 0}^{\ell - 1} \left(\frac{n-2}{n}\right)^{j} \frac{2i-n}{n}\\
        &= \frac{1 - \left(\frac{n-2}{n}\right)^{\ell}}{1 - \frac{n-2}{n}} \frac{2i - n}{n} \\
        &= \left( 1 - \left(\frac{n-2}{n}\right)^{\ell} \right) \frac{2i - n}{2}.
    \end{align*}

    Now, we will use \eqnref{conditioningAM} to compute the drift on a phase of \AM as follows
    \begin{align*}
        \Delta^{\AM}_{i} &=  \sum_{\ell = 1}^{\infty}  \Delta^{\AM}_{i, \ell} (1 - q)^{\ell - 1} q \\
        &= \sum_{\ell = 1}^{\infty} \left( 1 - \left(\frac{n-2}{n}\right)^{\ell} \right) \frac{2i - n}{2} (1 - q)^{\ell - 1} q \\
        &= \frac{2i - n}{2} q \sum_{\ell = 1}^{\infty} \left( (1 - q)^{\ell - 1} - \frac{n-2}{n} \left( \frac{n-2}{n} (1 - q) \right)^{\ell - 1} \right) \\
        &= \frac{2i - n}{2} q  \left( \frac{1}{q} - \frac{n-2}{n} \frac{1}{1 - \frac{n-2}{n} (1-q)} \right)\\
        &= \frac{2 i - n}{2 + q (n-2)},
    \end{align*}
    as expected.
\end{proof}

\begin{proof}[Proof of \Cref{lem:driftOI}]
    Let $i \in [0..n]$, notice that the drift $\Delta^{\OI}_i$ can be written as
        \[ \Delta^{\OI}_i = i - \esp\left[ y_{T_s^{(1)}} \mid \, y_0 = i, s_0 = \OI \right], \]
    hence, we only need to compute the average number of zero bits $y_{T_s^{(1)}}$ after one phase of \OI. To ease the notation, let's define
        \[ \mathcal{Y}^{\OI}_i = \esp\left[ y_{T_s^{(1)}} \mid \, y_0 = i, s_0 = \OI \right], \]
    and 
        \[ \mathcal{Y}^{\OI}_{i, \ell} = \esp\left[ y_{\ell} \mid \, y_0 = i, Z_0 = \ell, s_0 = \OI \right] \]
    where $\ell \in \N^*$ denote the length of the phase of \OI. As for the drift $\Delta^{\AM}_i$ in \Cref{lem:driftAM}, the following decomposition according to the length $Z_0$ of the phase of \OI holds
        \begin{align*}
             \mathcal{Y}^{\OI}_i & = \sum_{\ell = 1}^{\infty}  \mathcal{Y}^{\OI}_{i, \ell} \Pr\left[ Z_0 = \ell \mid y_0 = i, s_0 = \OI \right] \\
            & = \sum_{\ell = 1}^{\infty} \mathcal{Y}^{\OI}_{i, \ell} \Pr\left[ Z_0 = \ell \mid s_0 = \OI \right] \numberthis\label{lem:driftOI-eq1} \\
            & = \sum_{\ell = 1}^{\infty} \mathcal{Y}^{\OI}_{i, \ell} (1 - p)^{\ell - 1} p,
        \end{align*}
    where in \eqnref{lem:driftOI-eq1} we use \Cref{lem:independance} stating the independence of $y_0$ and $Z_0$. Now, it remains to find a closed form for all the $\left( \mathcal{Y}^{\OI}_{i, \ell} \right)_{\ell \geq 1}$.

    First, when $\ell = 1$, we have, for any $0 \leq i \leq n$
        \begin{align*}
            \mathcal{Y}^{\OI}_{i, 1} & = \esp\left[ y_1 \mid \, y_0 = i, Z_0 = 1, s_0 = \OI \right] \\ 
            & = i \left(\frac{n - i}{n} \right) + (i - 1) \frac{i}{n} \\ 
            & = \frac{i}{n} \left( (n - i) + (i - 1) \right) \\ 
            & = i \left( 1 - \frac{1}{n} \right).
        \end{align*}

    We will now show by induction on $\ell \geq 1$ that for all $i \in [0.. n]$ we have 
        \[ \mathcal{Y}^{\OI}_{i, \ell} = i \left( 1 - \frac{1}{n} \right)^{\ell}. \numberthis\label{lem:driftOI-HR} \]

    We already initialized the above property so let's assume \eqnref{lem:driftOI-HR} holds for some $\ell \geq 1$. Then, either $i = 0$ and as the \OI operator cannot climb down \onemax
        \[ \mathcal{Y}^{\OI}_{0, \ell + 1} = \esp\left[ y_{\ell} \mid \, y_0 = 0, Z_0 = \ell, s_0 = \OI \right] = 0, \]
    hence \eqnref{lem:driftOI-HR} holds. Otherwise when $i \in [1.. n]$, by conditioning on the value of $y_1$, i.e., with a first step analysis on the phase of \OI, we obtain
        \begin{align*}
            \mathcal{Y}^{\OI}_{i, \ell + 1} & = \esp\left[ y_{\ell + 1} \mid \, y_0 = i, Z_0 = \ell + 1 + 1, s_0 = \OI \right] \\ 
            & = \Pr[y_1 = i \, \mid \, y_0 = i, Z_0 = \ell + 1, s_0 = \OI] \\
            &\qquad\qquad \times \esp\left[ y_{\ell + 1} \mid \, y_0 = i, y_1 = i, Z_0 = \ell + 1, s_0 = \OI \right] \\ 
            &\quad + \Pr[y_1 = i - 1 \, \mid \, y_0 = i, Z_0 = \ell + 1, s_0 = \OI] \\ 
            &\qquad\qquad \times \esp\left[ y_{\ell + 1} \mid \, y_0 = i, y_1 = i- 1, Z_0 = \ell + 1, s_0 = \OI \right] \\ 
            & = \frac{n - i}{n} \esp\left[ y_{\ell + 1} \mid \, y_1 = i, Z_0 = \ell + 1, s_0 = \OI \right] \numberthis\label{lem:driftOI-HR-eq1} \\
            & \quad + \frac{i}{n} \esp\left[ y_{\ell + 1} \mid \, y_1 = i - 1, Z_0 = \ell + 1, s_0 = \OI \right] \\ 
            & = \mathcal{Y}^{\OI}_{i, \ell} \left(  \frac{n - i}{n} \right) + \mathcal{Y}^{\OI}_{i - 1, \ell} \left( \frac{i}{n} \right) \\ 
            & = i \left( \frac{n - 1}{n} \right) \left( 1 - \frac{1}{n} \right)^{\ell} + (i - 1) \left( \frac{i}{n} \right) \left( 1 - \frac{1}{n} \right)^{\ell} \numberthis\label{lem:driftOI-HR-eq2} \\ 
            & = \frac{i}{n} \left[ (n - i) + (i - 1) \right] \left( 1 - \frac{1}{n} \right)^{\ell} \\ 
            & = i \left( 1 - \frac{1}{n} \right)^{\ell + 1},
        \end{align*}
    as desired. Thus, the formula \eqnref{lem:driftOI-HR} holds true for all $\ell \geq 1$ and $0 \leq i \leq n$. Above, in \eqnref{lem:driftOI-HR-eq1} we use the first step analysis on a phase of \OI and based on the event $\{ y_1 = i, Z_0 = \ell + 1, s_0 = \OI \}$ the expectation in \eqnref{lem:driftOI-HR-eq1} simplifies to
        \[ \esp\left[ y_{\ell + 1} \mid \, y_1 = i, Z_0 = \ell + 1, s_0 = \OI \right] = \esp\left[ y_{\ell} \mid \, y_0 = i, Z_0 = \ell, s_0 = \OI \right], \]
   since, as $Z_0 = \ell + 1 > 1$, we have $s_1 = \OI$ and we can forget the past, i.e., the event $\{ (y_0, s_0) = (i, \OI) \}$. In \eqnref{lem:driftOI-HR-eq2}, we use the induction hypothesis from \eqnref{lem:driftOI-HR}.

   Finally, it remains to plug the formula of $\mathcal{Y}^{\OI}_{i, \ell}$ in the sum \eqnref{lem:driftOI-eq1}, hence
    \begin{align*}
        \mathcal{Y}^{\OI}_i & = \sum_{\ell = 1}^{\infty} \mathcal{Y}^{\OI}_{i, \ell} (1 - p)^{\ell - 1} p \\ 
        & = \sum_{\ell = 1}^{\infty} \mathcal{Y}^{\OI}_{i, \ell} \left( i \left( 1 - \frac{1}{n} \right)^{\ell} (1 - p)^{\ell - 1} p \right) \\ 
        & = i p \left(1 - \frac{1}{n} \right) \sum_{\ell = 1}^{\infty} \left( \left(1 - \frac{1}{n} \right)^{\ell - 1} (1 - p)^{\ell - 1} \right) \\ 
        & = i p \left(1 - \frac{1}{n} \right) \sum_{\ell = 1}^{\infty} \left( \left(1 - \frac{1}{n} \right) (1 - p) \right)^{\ell - 1} \numberthis\label{lem:driftOI-final-eq1} \\ 
        & = i p \left(1 - \frac{1}{n} \right) \frac{1}{1 - (1 - p) \frac{n - 1}{n}} \\ 
        & = \frac{i p (n - 1)}{n - (1 - p) (n - 1)} \\ 
        & = \frac{i p (n - 1)}{1 + p (n - 1)},
    \end{align*}
where in \eqnref{lem:driftOI-final-eq1} we recognize a geometric series.

    Thus, the drift $\Delta^{\OI}_i$ is
        \[ \Delta^{\OI}_i = i - \mathcal{Y}^{\OI}_i = \frac{i}{1 + p (n - 1)} \]
    as expected.
\end{proof}

\begin{proof}[Proof of \Cref{lem:driftAM-OI}]
    Let $\Delta_i^{\AM-\OI} = \esp[y_0 - y_{T_s^{(2)}} \mid y_0 = i, s_0 = \AM]$, then
        \begin{align*}
            \Delta_i^{\AM-\OI} & = \esp[y_0 - y_{T_s^{(2)}} \mid y_0 = i, s_0 = \AM] \\ 
            & = \esp[y_0 - y_{T_s^{(1)}} \mid y_0 = i, s_0 = \AM] \\ & \qquad +  \esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_0 = i, s_0 = \AM] \\ 
            & = \Delta^{\AM}_i + \esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_0 = i, s_0 = \AM],
        \end{align*}
        %    \begin{align*}
         %   \Delta_i^{\AM-\OI} & = \esp[y_0 - y_{T_s^{(2)}} \mid y_0 = i, s_0 = \AM] \\ 
         %   & = \esp[y_0 - y_{T_s^{(1)}} \mid y_0 = i, s_0 = \AM] + \esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_0 = i, s_0 = \AM] \\ 
         %   & = \Delta^{\AM}_i + \esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_0 = i, s_0 = \AM],
        %\end{align*}
    where we split the initial drift between $y_0$ and $y_{T_s^{(2)}}$ in two drifts, one over the phase of \AM and the other over the phase of \OI (but the conditioning is different from the one in $\Delta^{\OI}_i$). Now, let $\esp_i[\cdot] = \esp[\cdot \mid y_0 = i, s_0 = \AM]$ and by the tower property of the expectation
        \begin{align*}
            \esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid & \, y_0 = i, s_0 = \AM] \\
            & = \esp_i[\esp_i[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_{T_s^{(1)}}]],
        \end{align*}
    %\esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_0 = i, s_0 = \AM] & = \esp_i[\esp_i[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_{T_s^{(1)}}]],   
    where the inner expectation is 
        \begin{align*}
            \esp_i[& \, y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid  y_{T_s^{(1)}}] \\ &=\esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_{T_s^{(1)}}, y_0 = i, s_0 = \AM, s_{T_s^{(1)}} = \OI] \\
            & = \esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_{T_s^{(1)}}, s_{T_s^{(1)}} = \OI] \\
            & = \Delta^{\OI}_{y_{T_s^{(1)}}}, 
        \end{align*}
        %\begin{align*}
        %    \esp_i[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_{T_s^{(1)}}] & = \esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_{T_s^{(1)}}, y_0 = i, s_0 = \AM, s_{T_s^{(1)}} = \OI] \\
        %    & = \esp[y_{T_s^{(1)}} - y_{T_s^{(2)}} \mid y_{T_s^{(1)}}, s_{T_s^{(1)}} = \OI] \\
        %    & = \Delta^{\OI}_{y_{T_s^{(1)}}}, 
        %\end{align*}
    where we use \Cref{lem:independance} since $\onemax \in \seqopt_0$ to forget about the past event $\{y_0 = i, s_0 = \AM\}$ of the Markov chain $((y_t, s_t))_{t \in \N}$. Finally, using the fact that $\Delta^{\OI}_{i}$ is affine in $i$, the function $i \mapsto \Delta^{\OI}_i$ then commutes with the expectation thus
        \[ \esp_i[\Delta^{\OI}_{y_{T_s^{(1)}}}] = \Delta^{\OI}_{\esp_i[y_{T_s^{(1)}}]} = \Delta^{\OI}_{\left( i - \Delta^{\AM}_i \right)}, \]
    since 
        \[ \esp_i[y_{T_s^{(1)}}] = i - \esp[y_0 - y_{T_s^{(1)}} \mid y_0 = i, s_0 = \AM] = i - \Delta^{\AM}_i. \]
\end{proof}


\begin{proof}[Proof of \Cref{lem:avg-phases-AM}]
    Given the initial condition $(x_0, s_0) = (x, \AM)$ where $x \in \layer_m$ (a local maximum), we are interested in the probability $q^*$ that the trajectory $(x_0, \ldots, x_{T_s^{(1)}})$ of \AM reaches $x^*$. To lower bound $q^*$, we will only consider the trajectories that go straight right to layer $\layer_1$ and then to the global maximum in the next iteration (using \AM or \OI), i.e., trajectories for which $T_s^{(1)} \geq m - 1$ and $y_0 = m$, $y_1 = m - 1$, $\ldots$, $y_m = 0$. Hence, denoting $Y_m$ the event $\{y_1 = m - 1, \ldots, y_m = 0\}$.
        \begin{align*}
            q^* & \geq \Pr[T_s^{(1)} \geq m - 2, Y_m \mid y_0 = m, s_0 = \AM] \\ 
            & = \Pr[T_s^{(1)} \geq m - 2 \mid y_0 = m, s_0 = \AM] \numberthis\label{lem:avg-phases-AM-eq1} \\ 
            &\qquad \times \Pr[Y_m \mid y_0 = m, s_0 = \AM, T_s^{(1)} \geq m - 1] \\ 
            & = (1 - q)^{m - 2} \Pr[Y_m \mid y_0 = m, s_0 = \AM, T_s^{(1)} \geq m - 1] \\ 
            & = (1 - q)^{m - 2} \frac{m}{n} \frac{m - 1}{n} \cdots \frac{1}{n} \\ 
            & = (1 - q)^{m - 2} \frac{m!}{n^m},
        \end{align*}
        %\begin{align*}
         %   q^* & \geq \Pr[T_s^{(1)} \geq m, y_1 = m - 1, \ldots, y_m = 0 \mid y_0 = m, s_0 = \AM] \\ 
         %   & = \Pr[T_s^{(1)} \geq m \mid y_0 = m, s_0 = \AM] \tag*{(1)}\label{lem:avg-phases-AM-eq1} \\ 
         %   &\qquad \times \Pr[y_1 = m - 1, \ldots, y_m = 0 \mid y_0 = m, s_0 = \AM, T_s^{(1)} \geq m] \\ 
         %   & = (1 - q)^{m - 1} \Pr[y_1 = m - 1, \ldots, y_m = 0 \mid y_0 = m, s_0 = \AM, T_s^{(1)} \geq m] \\ 
        %    & = (1 - q)^{m - 1} \frac{m}{n} \frac{m - 1}{n} \cdots \frac{1}{n} \\ 
        %    & = (1 - q)^{m - 1} \frac{m!}{n^m},
        %\end{align*}
    where, in \eqnref{lem:avg-phases-AM-eq1} we use the independence of $Z_0 = T_s^{(1)}$ and $y_0$ as stated in \Cref{lem:independance} which leads to
        \begin{align*}
            \Pr[T_s^{(1)} \geq m - 1 \mid & \, y_0 = m, s_0 = \AM]  \\ & =  \Pr[Z_0 \geq m - 1 \mid s_0 = \AM] \\ 
            & = \sum_{\ell = m - 1}^{\infty} (1 - q)^{\ell - 1} q \\ 
            & = (1 - q)^{m - 2}.
        \end{align*} 
        %\begin{align*}
        %    \Pr[T_s^{(1)} \geq m \mid y_0 = m, s_0 = \AM] & = \Pr[Z_0 \geq m \mid s_0 = \AM] \\ 
        %    & = \sum_{\ell = m}^{\infty} (1 - q)^{\ell - 1} q \\ 
        %    & = (1 - q)^{m - 1}.
        %\end{align*} 
\end{proof}

