\begin{proof}[Proof of \Cref{lem:drift-left-slope}]
   First, as both \onemax and $\jump_m$ have a similar increasing slope (in the $1$-norm) on all bit-strings $x$ such that $\| x \|_1 \leq n - m$ then, the time $T_0 = \inf\{ t \geq 0 \mid \| x_t \|_1 = n - m\}$ (as defined on $\jump_m$) is the same as the time taken by the \MMAHH on \onemax starting initially with $(x_0, s)$ (recall that $s \in \{\OI, \AM\}$). Hence, it is enough to work on \onemax only, with the same initial conditions. Moreover, we have $T_0 \leq T_0^*$ where $T_0^*$ is the first time where the number of one-bits becomes greater or equal to $n - m$ at the end of a pair of phases \AM\!+\OI, i.e., 
        \[ T_0^* = \sum_{k = 0}^{k^* - 1}(Z_{2k} + Z_{2k+1}), \]
    where $k^* = \inf\{k \in \N \mid y_{T_s^{(2k)}} \leq m \}$. Note that, if $s = \OI$ then, up to an additional term of $\frac{1}{p}$ (we wait until the phase of \OI ends and either we already reach a local maximum -- in which case we stop -- or we continue with \AM), we can assume we start in $s = \AM$.

    Now, in order to have an upper bound on $\esp\left[k^*\right]$, we will use the additive drift theorem with overshooting (see \Cref{thm:add-drift-overshooting}), with the sequence $\left( y_{T_s^{(2 k)}} \right)_{0 \leq k \leq k^*}$ and the potential $z_t = y_t - m = (n - m) - \| x_t \|_1 \geq -m$ for which $\left( y_{T_s^{(2 k)}} \right)_{0 \leq k \leq k^*}$ is thus lower bounded. Moreover, with this potential, we have $k^* = \inf\{k \in \N, z_{T_s^{(2k)}} \leq 0 \}$ and, for any $0 \leq k < k^*$ and any $0 < i \leq n - m$, as we start with $s_0 = \AM$ then $s_{T_s^{(2 k)}} = \AM$ and using \Cref{lem:driftAM-OI} we have
    \begin{align*}
        \esp[ & z_{T_s^{(2k)}} - z_{T_s^{(2k + 2)}} \mid z_{T_s^{(2k)}} = i ] \\
        & = \Delta^{\AM-\OI}_{m + i} \\ 
        & =  \esp[ y_{T_s^{(2k)}} - y_{T_s^{(2k + 2)}} \mid y_{T_s^{(2k)}} = i + m ] \\
        & = \frac{(i+m)(2 + q(n-2) + 2 p (n-1)) - np(n-1)}{(1 + p(n-1))(2 + q(n-2))} \\
        & = \frac{i(2 + q(n-2) + 2 p (n-1))}{(1 + p(n-1))(2 + q(n-2))} \\
        &\quad + \frac{m(2 + 2 p (n-1) + q(n-2)) - np(n-1)}{(1 + p(n-1))(2 + q(n-2))}, \numberthis\label{lem:drift-left-slope-eq1}
    \end{align*}
    and $m(2 + 2 p (n-1) + q(n-2)) - np(n-1)$ from \eqnref{lem:drift-left-slope-eq1} is non-negative if, and only if, 
        \[ 2 m + m q (n - 2) \geq p (n - 1) (n - 2 m), \]
    i.e., either if $n \geq m \geq \frac{n}{2}$ or when $\frac{n}{2} > m \geq 0$ and
        \[ \frac{1}{n - 2 m}\left( \frac{m (n - 2)}{n - 1} q + \frac{2 m}{n - 1} \right) \geq p. \]
    Now, given $n \geq 3$ then $\frac{n - 2}{n - 1} \geq \frac{1}{2}$ and moreover, $\frac{2}{n - 1} \geq \frac{2}{n}$. Hence, for \eqnref{lem:drift-left-slope-eq1} to be non-negative, it suffices to have $n \geq 3$ and either $n \geq m \geq \frac{n}{2}$ or
        \[ \frac{n}{2} > m \geq 0 \, \text{ and } \, \frac{m}{2 (n - 2 m)}\left( q + \frac{4}{n} \right) \geq p. \]

    Now, we obtain
        \begin{align*}
            \Delta^{\AM-\OI}_{m + i} & \geq \frac{i(2 + q(n-2) + 2 p (n-1))}{(1 + p(n-1))(2 + q(n-2))} \\ 
            & \geq \frac{i(2 + q(n-2))}{(1 + p(n-1))(2 + q(n-2))} \\ 
            & =  \frac{i}{1 + p(n-1)} \\ 
            & \geq \frac{i}{1 + p n},
        \end{align*}
    and we can now apply \Cref{thm:add-drift-overshooting} using the fact that the overshooting is at most $\esp[ z_{T_s^{(2k^*)}} ] \geq - m$ since $y_{T_s^{(2k^*)}} \geq 0$ hence
        \[\esp[k^*] \leq (n - \| x_0 \|_1) (1 + pn), \]
    because the potential at the starting point is $z_0 = y_0 - m = n - \| x_0 \|_1 - m$ with an overshooting of $m$ hence, giving the factor $n - \| x_0 \|_1$.

    Finally, using Wald's theorem (\Cref{thm:wald}) we obtain the estimate
        \begin{align*}
            \esp\left[ T_0 \right] & \leq \frac{1}{p} + \esp[T_0^*] \\ 
            & =  \frac{1}{p} + \esp\left[ \sum_{k = 0}^{k^* - 1}(Z_{2k} + Z_{2k+1}) \right] \\ 
            & \leq  \frac{1}{p} + \esp[k^*] \left( \frac{1}{p} + \frac{1}{q} \right) \\ 
            & = \O\left( (n - \| x_0 \|_1)  (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right).
        \end{align*}

    For the particular case $\| x_0 \|_1 = n - m - 1$, we have
    \begin{align*}
        \esp\left[ T_0 \right] & \leq \frac{1}{p} + (n - \| x_0 \|_1)  (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \\ 
        & = \frac{1}{p} + (m + 1) (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \\ 
        & = \O\left( m (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right),
    \end{align*}
    as desired.
\end{proof}

\begin{proof}[Proof of \Cref{lem:avg-time-to-climb-jump}]
    As the \MMAHH relies on the \textsc{RandomOneBitFlip} mutation operator, it is enough for upper bounding $\esp[T_1]$ to distinguish between $\| x_0 \|_1 < n - m$ and $n - m < \| x_0 \|_1 < n$ then, use the drift computed in \Cref{lem:drift-gap-region} and \Cref{lem:drift-left-slope} and apply separately one of the drift theorems from section \ref{subsec:math-tools}.

    First, if $n - m < \| x_0 \|_1 < n$ then, for any time $0 \leq t < T_1$, we still have $n - m < \| x_t \|_1 < n$ and by \Cref{lem:drift-gap-region} we can apply the multiplicative drift with $\delta = \frac{2}{n}$ in the gap region (at the scale of the bit-string) hence for any $x\in \{0, 1\}^n$ such that $n - m < \| x \|_1 < n$ we have
    \begin{align*}
        \esp[T_1 \mid x_0 = x] & \leq \frac{1 + \log(d(x))}{\delta} \\ 
        & \leq \frac{1 + \log(m)}{\delta} \\
        &= O(n \log(m)).
    \end{align*}
        %\[ \esp[T_1 \mid x_0 = x] \leq \frac{1 + \log(d(x))}{\delta} \leq \frac{1 + \log(m)}{\delta} = O(n \log(m)). \]

    Now, consider the case where $0 \leq \| x_0 \|_1 < n - m$, as of before, whatever the time $0 \leq t < T_1$ we have $0 \leq \| x_t \|_1 < n - m$. Moreover, as $s_0 = \OI$, by simply waiting until the phase of \OI ends (and either we already reached a local maximum -- in which case we stop -- or we continue with now \AM), we can assume we start in \AM. Now by \Cref{lem:drift-left-slope} we obtain, for any $x\in \{0, 1\}^n$ such that $n - m < \| x \|_1 < n$,
        \begin{align*}
            \esp[T_1 \mid x_0 = x] & \leq \frac{1}{p} + (n - \| x \|_1)  (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \\ 
            & = \O\left( (n - \| x \|_1)  (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right) \\ 
            & = \O\left( n (1 + pn) \left(\frac{1}{p} + \frac{1}{q} \right) \right).
        \end{align*}

    Of course, if $x_0 \in X^*$ then $T_1 = 0$. Hence, combining all these three cases leads to 
        \[ \esp[T_1] = \O\left( n (1 + p n) \left( \frac{1}{p} + \frac{1}{q} \right) \right), \]
    since $\log(m) = O(n) = \O\left( (1 + p n) \left( \frac{1}{p} + \frac{1}{q} \right) \right)$ and we are done.
\end{proof}

