\section{Preliminaries}
\label{sec:prelim}
\paragraph{A Reading Guide}
Due to the daunting length and complexity of our proof, we take several measures to assist the reader:
\begin{itemize}
    \item The current section is denoted in the header.
    \item Proof environments are colored in {\color{violet!75!black} purple hue, to distinguish them from other text}.
    \item We mark some results and definitions with \keyicon if they are key ideas, and with \lightbulbicon if their proof has special insights. We recommend focusing on \keyicon statements, and on \lightbulbicon proofs, for a first read.
    \item Most of our definitions use english terms rather than symbols, to assist in remembering their meaning. Very few (and widely used) ones are left  as symbols.
    \item Lastly, we note that on most PDF readers, the keyboard shortcut ``Alt + Left Arrow'' or ``Cmd + Left Arrow'' goes back after following a hyperlink (e.g., a reference to a definition). 
\end{itemize}

For an alphabet $\Sigma$, we denote by $\Sigma^*$ (resp. $\Sigma^+$) the set of finite words (resp. non-empty finite words) over $\Sigma$. 
For a word $w\in \Sigma^*$, we denote its length by $|w|$ and the set of its prefixes by $\pref(w)$. We write $w[i,j]=\sigma_i\cdots \sigma_j$ for the infix of $w$ corresponding to $1<i<j\le |w|$.

We denote by  $\bbNinf$ and $\bbZinf$ the sets $\bbN\cup \{\infty\}$ and $\bbZ\cup \{\infty\}$, respectively. We extend the addition and $\min$ operations to $\infty$ in the natural way: $a+\infty=\infty$ and $\min\{a,\infty\}=a$ for all $a\in \bbZinf$. By $\arg\min\{f(x)\mid x\in A\}$ we mean the set of elements in $A$ for which $f(x)$ is minimal for some function $f$ and set $A$.

\paragraph{Weighted Automata}
A \emph{$(\min,+)$ Weighted Finite Automaton} (WFA for short) is a tuple $\cA= \tup{Q,\Sigma, q_0, \Delta}$ with the following components:
\begin{itemize}
    \item $Q$ is a finite set of \emph{states}.
    \item $q_0\in Q$ is the \emph{initial} state.\footnote{Having a set of initial states does not add expressiveness, as it can be replaced by a single initial state that simulates the first transition from the entire set.}
    \item $\Sigma$ is an \emph{alphabet}. We remark that we often use an \emph{infinite alphabet} $\Sigma$, hence we do not require it to be finite. 
    \item $\Delta\subseteq Q\times \Sigma\times \bbZinf\times Q$ is a transition relation such that for every $p,q\in Q$ and $\sigma\in \Sigma$ there exists exactly\footnote{This is without loss of generality: if there are two transitions with different weights, the higher weight can always be ignored in the $(\min,+)$ semantics. Missing transitions can be introduced with weight $\infty$.} one weight $c\in \bbZinf$ such that $(p,\sigma,c,q)\in \Delta$.
    %is relation $\Delta \subseteq Q \times \Sigma \times \bbZ \times Q$.
\end{itemize}
If for every $p\in Q$ and $\sigma\in \Sigma$ there exists at most one transition $(p,\sigma,c,q)$ with $c\neq \infty$, then $\cA$ is called \emph{deterministic}.

\begin{remark}[On initial and final weights, and accepting states]
    \label{rmk: initial and final weights}
    Weighted automata are often defined with initial and final weights, i.e., 
    $q_0$ is replaced with an initial vector $\init\in \bbZinf^Q$ (and in particular may have several initial states with finite weight), and there are designated accepting states or a final weight vector $\fin\in \bbZinf^Q$.
    Then, the weight of a run also includes the initial weight and final weight (which may be $\infty$).

    In \cref{sec:no need for init and fin and acc} we show that the determinization problem for this general model can be reduced to that of our setting. Therefore, it is sufficient to consider our model, without initial and final weights, and with a single initial state. 
    We remark that while replacing $\init$ and $\fin$ with initial and accepting states is straightforward, making \emph{all} states accepting is nontrivial.
\end{remark}

\paragraph{Runs}
A \emph{run} of $\cA$ is a sequence of transitions $\rho=t_1,t_2,\ldots,t_m$ where $t_i=(p_i,\sigma_i,c_i,q_i)$ such that $q_i=p_{i+1}$ for all $1\le i<m$ and $c_i <\infty$ for all $1\le i \le m$.
We say that $\rho$ is a run \emph{on the word $w=\sigma_1\cdots\sigma_m$ from $p_1$ to $q_m$}, and we denote $\rho:p_1\runsto{w}q_m$. 
For an infix $x=w[i,j]$ we denote the corresponding infix of $\rho$ by $\rho[i,j]=t_i,\ldots,t_j$ (and sometimes by $\rho(x)$, if this clarifies the indices).
The \emph{weight} of the run $\rho$ is $\weight(\rho)=\sum_{i=1}^m c_i$. 

For a word $w$, the weight assigned by $\cA$ to $w$, denoted $\weight_{\cA}(w)$ is the minimal weight of a run of $\cA$ on $w$. For convenience, we introduce some auxiliary notations.

For a word $w\in \Sigma^*$ and sets of states $Q_1,Q_2\subseteq Q$, denote
\[\minweight_\cA(w,Q_1\to Q_2)=\min\{\weight(\rho)\mid \exists q_1\in Q_1,q_2\in Q_2,\ \rho:q_1\runsto{w}q_2\}\]
If $Q_1$ or $Q_2$ are singletons, we denote them by a single state (e.g., $\minweight_\cA(w,P\to q)$ for some set $P\subseteq Q$ and state $q$).
%
We can now define
\[
\weight_\cA(w)=\minweight_\cA(w,q_0\to Q)
\]
If there are no runs on $w$, then $\weight_\cA(w)=\infty$.
The function $\weight_\cA:\Sigma^*\to \bbZinf$ can be seen as the weighted analogue of the \emph{language} of an automaton.
We omit the subscript $\cA$ when clear from context.

For a word $w\in \Sigma^*$ and a state $q\in Q$, of particular interest are runs from $q_0$ to $q$ on $w$ that remain minimal throughout. Indeed, other runs are essentially ``cut short'' by some lower run. Formally, let $w=\sigma_1\cdots \sigma_n$ and consider a run $\rho:q_0\runsto{w}q$ with $\rho=t_1,t_2,\ldots,t_n$ and $t_i=(q_i,\sigma_i,e_i,q_{i+1})$. We say that $\rho$ is \emph{seamless} if for every $1\le j\le n$ it holds that $\weight(t_1,\ldots,t_j)=\minweight(\sigma_1\cdots \sigma_j,q_0\to q_{j+1})$.

We define $\wmax{w}$ to be the maximal weight (in absolute value) occurring in any possible transition on the letters of $w$, i.e., 
\[\wmax{w}=\max\{|c|<\infty \mid \exists p,q\in Q, 1\le i\le n,\  (p,\sigma_i,c,q)\in \Delta\}\] 
Additionally, the \emph{maximal effect} of $w$ is an upper bound on the change in weight that can happen upon reading $w$, defined as $\maxeff{w}=\sum_{i=1}^n\wmax{\sigma_i}$.
Thus, any finite-weight run $\rho$ on $w$ satisfies $|\weight(\rho)|\le \maxeff{w}\le \wmax{w}|w|$.

We write $p\runsto{w}q$ when there exists some run $\rho$ %with $\weight(\rho)<\infty$ 
such that $\rho:p\runsto{w}q$.
We lift this notation to concatenations of runs, e.g., $\rho: p\runsto{x}q\runsto{y}r$ means that $\rho$ is a run on $xy$ from $p$ to $r$ that reaches $q$ after the prefix $x$. We also incorporate this to $\minweight$ by writing e.g., $\minweight(xy,q\runsto{x}p\runsto{y}r)$ to mean the minimal weight of a run $\rho:q\runsto{x}p\runsto{y}r$.

For a set of states $Q'\subseteq Q$ and a word $w\in \Sigma^*$, we define the {\em reachable set of states from $Q'$ upon reading $w$} as $\delta_{\bbB}(Q',w)=\{q\in Q\mid \exists p\in Q',\ p\runsto{w}q\}$ (where $\bbB$ stands for ``$\bbB$oolean'').


A WFA is \emph{trim} if every state is reachable from $q_0$ by some run. Note that states that do not satisfy this can be found in polynomial time (by simple graph search), and can be removed from the WFA without changing the weight of any accepted word. Throughout this paper, we assume that all WFAs are trim.

\paragraph{Determinizability}
We say that WFAs $\cA$ and $\cB$ are \emph{equivalent} if $\weight_\cA\equiv \weight_\cB$. We say that $\cA$ is \emph{determinizable} if it is equivalent to some deterministic WFA. Our central object of study is the following problem.
\begin{problem}[WFA Determinizability]
\label{prob:determinizability}
    Given a WFA $\cA$ over a finite alphabet $\Sigma$, decide whether $\cA$ is determinizable.
\end{problem}
The determinization problem is PSPACE-hard. This does not seem to be published anywhere, and we therefore provide a proof in \cref{apx:PSPACE hard} (we recommend reading this proof only after \cref{thm:det iff bounded gap}, as it relies on it).




\paragraph{Configurations}
A \emph{configuration} of $\cA$ is a vector $\vec{c}\in \bbZinf^Q$ which, intuitively, describes for each $q\in Q$ the weight $\vec{c}(q)$ of a minimal run to $q$ thus far (assuming some partial word has already been read). 
For a state $q$ we define the configuration $\vec{c_q}$ that assigns $0$ to $q$ and $\infty$ to $Q\setminus\{q_0\}$.
Intuitively, before reading a word, $\cA$ is in the configuration $\vec{c_\init}=\vec{c_{q_0}}$. 
%that assigns $0$ to $q_0$ and $\infty$ to $Q\setminus\{q_0\}$. 

We adapt our notations to include a given starting configuration $\vec{c}$, as follows.
Given a configuration $\vec{c}$ and a word $w$, they induce a new configuration $\vec{c'}$ by assigning each state the minimal weight with which it is reachable via $w$ from $\vec{c}$. We denote this by 
$\xconf(w,\vec{c})(q)=\minweight_{\vec{c}}(w,Q\to q)$ for every $q\in Q$.
In particular, $\xconf(w,\vec{c}_{\init})$ is the configuration that $\cA$ reaches by reading $w$ along a minimal run. 

We use the natural component-wise partial order on configurations. That is, for two configuration $\vec{c},\vec{d}$, we say that $\vec{d}$ is \emph{superior} to $\vec{c}$, denoted $\vec{c}\le \vec{d}$, if $\vec{c}(q)\le \vec{d}(q)$ for every $q\in Q$. We also denote the \emph{support} of a configuration by $\supp(\vec{c})=\{q\in Q\mid \vec{c}(q)<\infty\}$.



For a run $\rho:p\runsto{w}q$ and configuration $\vec{c}$, we define the \emph{weight of $\rho$ from $\vec{c}$} to be $\weight_{\vec{c}}(\rho)=\vec{c}(p)+\weight(\rho)$. We similarly extend the notation $\minweight$ to include configurations, by writing
\[
\minweight_{\vec{c}}(w,Q_1\to Q_2)=\min\{\weight_{\vec{c}}(\rho) \mid \exists q_1\in Q_1,q_2\in Q_2,\ \rho:q_1\runsto{w}q_2\}
\]
(we remark that we never need both the subscript $\cA$ and $\vec{c}$ together).
We say that $\rho$ is \emph{seamless from $\vec{c}$} if for every $1\le j\le n$ it holds that $\weight_{\vec{c}}(t_1,\ldots,t_j)=\minweight_{\vec{c}}(\sigma_1\cdots \sigma_j,T\to q_{j+1})$ where $T=\supp(\vec{c})$.
%%%%%We use ``Seamless from \vec{c}'' in the monotone potential/charge lemma. 



\subsection{A Characterization of Determinizability}
\label{sec:determinizability equiv characterization}
The following theorem gives an equivalent characterization of determinizability by means of runs, and of how far two potentially-minimal runs can get away from one another, which we commonly refer to as a \emph{gap}. 
Intuitively, we show that $\cA$ is determinizable if and only if there is some bound $B\in \bbN$ such that if two runs on a word $x$ obtain weights that are far from each other, but the ``upper'' run can still become minimal over some suffix, 
%and the minimal run can become accepting on some suffix, 
then the runs are at most $B$ apart. This is depicted in \cref{fig:abs:gap witness}.
%\shtodo{depict.}

We remark that this theorem is folklore, but to our knowledge has not been stated explicitly anywhere. Moreover, since we often treat infinite alphabets, we need to tweak the statement accordingly.
A similar characterization (with finite alphabet) was given for \emph{discounted-sum automata}~\cite{almagor2024determinization}.
\begin{definition}[$B$-Gap Witness]
\label{def: B gap witness}
    For $B\in \bbN$, a \emph{$B$-gap witness over alphabet $\Sigma'$} consists of a pair of words $x,y\in \Sigma'^*$ and a state $q\in Q$ such that
    \begin{itemize}
        \item $\minweight_\cA(x\cdot y,q_0\to Q)=\minweight_\cA(x\cdot y,q_0\runsto{x}q\runsto{y}Q)<\infty$, but 
        \item $\minweight_\cA(x,q_0\to q)-\minweight_\cA(x,q_0\to Q')>B$.
    \end{itemize}
\end{definition}
\noindent Then, the characterization is as follows.
\begin{theorem}
    \label{thm:det iff bounded gap}
    Consider a WFA $\cA$, then the following hold.
    \begin{enumerate}
        \item If there exists $B\in \bbN$ such that there is no $B$-gap witness over $\Sigma$, then $\cA$ is determinizable.
        \item If there is a finite alphabet $\Sigma'\subseteq \Sigma$ such that for every $B\in \bbN$ there is a $B$-gap witness over $\Sigma'$, the $\cA$ is not determinizable.
    \end{enumerate}
 \end{theorem}
We prove the theorem in \cref{sec:apx det iff bounded gap}. We remark that the proof there considers also initial and final weights, as it is later used in \cref{sec:no need for init and fin and acc} to establish \cref{rmk: initial and final weights}.

Observe that for WFAs over a finite alphabet, \cref{thm:det iff bounded gap} provides an exact characterization of determinizability.


\section{The Baseline-Augmented Subset Construction}
\label{sec:augmented construction}
We now construct a WFA $\augA$ that augments $\cA$ with additional information regarding its runs. This information is kept in both the states and in the alphabet.
Technically, the alphabet of $\augA$ consists of the \emph{transitions} of $\cA$, i.e. $\Delta$. Each state of $\augA$ contains information about the current state, the current reachable subset of states, as well as a special \emph{baseline} state. 
Intuitively, the baseline states aim to describe the minimal-weight run on the current word. 

We proceed with the precise construction.
Let $\cA= \tup{Q,\Sigma, q_0, \Delta}$. We define $\augA=\tup{\augStates,\Delta,\augInitState,\augTrans}$ with the following components:
\begin{itemize}
    \item The states are 
    $\augStates=\{(q,p,T) \in Q \times Q \times 2^Q \mid q,p \in T\}$.
    %\quad \text{ and }\quad \augInitSet=\{(q,Q_0)\in Q\times 2^Q\mid q\in Q_0\}\]
    We refer to the components of a state $(q,p,T)\in S$ as the \emph{inner state} $q$, the \emph{baseline component} $p$, and the \emph{reachable subset} $T$.
    \item The alphabet of $\augA$ is the set of transitions $\Delta$ of $\cA$. For clarity, we denote elements of $\Delta$ using either explicit tuples, or by $\tau$. In practice, we consider reading only transitions of finite weight, but this is enforced in the transition relation.
    \item The initial state is $(q_0,q_0,\{q_0\})$.
    \item The transitions $\augTrans$ are defined as follows. 
    Consider states $(p_1,q_1,T_1)$ and $(p_2,q_2,T_2)$ in $\augStates$ and a letter $(q_1,\sigma,c,q_2)\in \Delta$ with $c\neq \infty$
    (i.e., the transition in $\cA$ from $q_1$ to $q_2$ on some $\sigma\in \Sigma$). 
    If $T_2=\booltrans(T_1,\sigma)$, then consider the unique transition $(p_1,\sigma,c',p_2)\in \Delta$. We add to $\augTrans$ the transition $((p_1,q_1,T_1),(q_1,\sigma,c,q_2),c'-c,(p_2,q_2,T_2))$.

    % For the initial states, there are finite-weight transitions only to states in $S$, as follows: for an initial state $(p_1,Q_0)$ in $S_0$, a state $(p_2,q_2,T)$ in $S$ and a letter $(q_1,\sigma,c,q_2)$, if $T=\booltrans(Q_0,\sigma)$ and $q_1 \in Q_0$ then consider the unique transition $(p_1,\sigma,c',p_2)\in \Delta$ (namely $c'=\Delta(\sigma)_{p_1,p_2}$).
    % We add to $\augTrans$ the transition 
    % $((p_1,Q_0),(q_1,\sigma,c,q_2),c'-c,(p_2,q_2,T_2))$.

    Finally, we complete any undefined transitions with $\infty$.

     %\item The accepting states are determined by their first component: 
     %\[\augAccSet=\{(q,p,T)\in S\mid q\in F\}\cup \{(q,T)\in S_0 \mid q\in F\}\]  
\end{itemize}
To gain some intuition on the construction (specifically on the transition function), observe that for a state $(p_1,q_1,T_1)$ and letter $(q,\sigma,c,q')$, the transition on the second and third component is entirely deterministic (assuming it has finite weight): any state $(p_2,q_2,T_2)$ reached must satisfy $T_2=\booltrans(T_1,\sigma)$, and it must hold that $q_1=q$ and $q_2=q'$.
%\shtodo{Maybe note somewhere that $T$ tracks $\booltrans$ along the entire run. It would help with the DAG definition.}
The first component simulates $\cA$: from $p_1$ we can reach any state $p_2$ that satisfies $(p_1,\sigma,c',p_2)$ for some $c'$. 
Finally, the cost of the transition is $c'-c$: this reflects the fact that we ``normalize'' all weights so that if we had started at state $p$, the cost of the transition is $0$.

The remainder of our analysis is carried out on $\augA$. We now show that this is sound and complete.


We now elaborate further on the behavior of $\augA$. Recall that $\augA$ reads a sequence $x$ of transitions of $\cA$ (and this sequence must form a run in order to have finite weight). Each state in $\augA$ keeps track of two runs of $\cA$, and of the set of reachable states. This is done as follows.
Each transition $(q_1,\sigma,c,q_2)$ that is read (as a letter for $\augA$) induces the letter in $\sigma\in \Sigma$ that $\cA$ reads, but in addition ``suggests'' a transition on $\sigma$ from $q_1$ to $q_2$. 
Then, this suggestion is only ``accepted'' in states whose baseline component is $q_1$, i.e., $(p_1,q_1,T_1)$ for some $p_1,T_1$ with $p_1,q_1\in T_1$. 
This suggestion means that $\augA$ can now move to any state $p_2$ reachable from $p_1$ via $\sigma$, while the baseline component is now $q_2$. 
Further observe that upon reading a word $x$, all the states reachable by $\augA$ are of the form $(\cdot,p,T)$, i.e., share the same second and third components. Moreover, the possible reachable inner states (the first component) are exactly those in $T$, which are the states reachable by $\cA$ upon reading the letters in the word in $\Sigma^*$ induced by $x$. 
Thus, $\augA$ essentially simulates the run tree of $\cA$, with some additional information.

Of particular importance are states of the form $(q_1,q_1,T_1)$, which are reachable and can accept the suggestion $(q_1,\sigma,c,q_2)$. Then, $\augA$ may move to $(q_2,q_2,T_2)$ (as well as possibly to other states). Due to the weight normalization, the weight of this transition in $\augA$ is $c-c=0$. Such states are central to our analysis.
\begin{definition}[Baseline States and Baseline Runs]
    \label{def:baseline states}
    A state in $S$ is a \emph{baseline} if it is of the form $(p,p,T)$ for some $p\in T$. 
    %States in $S_0$ are also baseline.
    A run $\rho=t_1\cdots t_m$ of $\augA$ with $t_i=(s_i,\tau_i,d,s_{i+1})$ is called a \emph{baseline} if $s_i$ is a baseline for all $i$.
\end{definition}

\begin{observation}
    \label{obs:baseline runs have weight 0}
    Recall that the weight of a transition in $\augA$ on letter $(p,\sigma,c,q)$ is normalized by reducing $c$ from any transition. In particular, a transition between baseline states $(p,p,T)\runsto{\sigma}(q,q,T)$ has weight $0$. Consequently, if $\rho$ is a baseline run, then $\weight(\rho)=0$. Note that there may still be other runs of both positive and negative weights.
\end{observation}
The intuition behind the baseline run is that it forms a ``point of view'' (POV) of the various runs of $\cA$ on a given word, in the sense that the weights of the transitions in $\cA$ are shifted so that the baseline run has weight $0$, and all other runs are shifted accordingly. We formalize this intuition in \cref{sec:shift POV}.
In particular, this enables us to show that $\cA$ is determinizable if and only if $\augA$ is determinizable.


\subsection{Shifts Between $\cA$ and $\augA$}
\label{sec:shift POV}
%\shtodo{I'm not sure this is a good name -- we're not changing POV, just moving between A and augA.}
Intuitively, the runs of $\cA$ and of $\augA$ have the same relative structure, up to the choice of baseline run dictated in $\augA$. 
Indeed, for a word $w\in \Sigma^*$ and a run $\rhobase$ of $\cA$ on $w$, when $\augA$ reads $\rhobase$, each run corresponds to a run of $\cA$ on $w$, with the weights shifted according to $\rhobase$. In particular, the difference in weights between any two runs of $\augA$ on $\rhobase$ is the same as the difference in weights between the corresponding runs of $\cA$ on $w$.
Conversely, for a word $\aug{w}\in \Delta^*$, we can associate a word $w\in \Sigma^*$ such that $\aug{w}$ is a run of $\cA$ on $w$, and such that each run $\aug{\rho}$ of $\augA$ on $\aug{w}$ corresponds to a run $\rho$ of $\cA$ on $w$, and such that the difference in weight is similarly maintained as above.

We now formalize this intuition.
Consider a word\footnote{Observe that the definition does not actually depend on $w$, as $w$ is already induced by $\rhobase$.} $w\in \Sigma^*$ and a run $\rhobase=t_1,t_2,\ldots,t_n$ of $\cA$ on $w$ with $t_i=(q_i,\sigma_i,c_i,q_{i+1})$. We think of the run $\rhobase$ as a word read by $\cA$. 
Consider a run $\augrho=\aug{r_1},\aug{r_2},\ldots, \aug{r_n}$ of $\augA$ on $\rhobase$ where for all $1\le i< n$ we have
\[\aug{r_i}=((p_i,q_i,T_i),t_i,d_i,(p_{i+1},q_{i+1},T_{i+1}))\in \augTrans\]
The \emph{$\rhobase$-shifted run of $\cA$ corresponding to $\augrho$},
denoted $\shifttoorig(\augrho)$, 
is then the run $\rho=t'_1,t'_2,\ldots, t'_n$ where $t'_i=(p_i,\sigma_i,d_i+c_i,p_{i+1})$.
Note that $\rho$ follows the inner states of the run $\augrho$, but has weights shifted by $\rhobase$. 

We first observe that $\rho$ is indeed a run of $\cA$ on $w$: the initial state of $\augrho$ is $\augInitState=(q_0,q_0,\{q_0\})$, and therefore the initial state of $\rho$ is $q_0$. For the transitions, for every $1\le i< n$, since $\aug{r_i}\in \augTrans$ is a transition on the letter $t_i$, then (by the definition of $\augTrans$) we have that $(p_i,\sigma_i,c'_i,p_{i+1})$ for $c'_i$ such that $c'_i-c_i=d_i$. But then $c'_i=c_i+d_i$, so the transition $t'_i$ is indeed a valid transition in $\Delta$.

We now show that $\rhobase$-shifted runs maintain the weight differences of their origin runs. Intuitively, this holds because both runs are shifted by the same corresponding weights of $\rhobase$.
\begin{proposition}
\label{prop: pov shift from aug to A maintains distance}
    Consider a run $\rhobase$ of $\cA$ and two runs $\augrho=\aug{r_1},\aug{r_2},\ldots,\aug{r_n}$ and $\aug{\mu}=\aug{x_1},\aug{x_2},\ldots,\aug{x_n}$ of $\augA$ on $\rhobase$. 
    Let $\rho=r'_1,r'_2,\ldots,r'_n$ and $\mu=x'_1,x'_2,\ldots,x'_n$ be 
    %the respective $\rhobase$-shifted runs, 
    $\shifttoorig(\augrho)$ and $\shifttoorig(\aug{\mu})$, respectively,
    then for every $1\le i\le n$ we have
    \[\weight_{\augA}(\aug{r_1},\aug{r_2},\ldots,\aug{r_i})-\weight_{\augA}(\aug{\mu}=\aug{x_1},\aug{x_2},\ldots,\aug{x_i})=\weight_\cA(r'_1,r'_2,\ldots,r'_i)-\weight_\cA(x'_1,x'_2,\ldots,x'_i)\]
\end{proposition}
\begin{proof}\ifproofs   
    The proof follows easily by induction on $i$. The base case is trivial: for $i=0$ all runs accumulate $0$ weight, so the differences are both $0$. 
    Assume correctness for $i-1$, we prove for $i$.
    By the induction hypothesis, up to prefix $i$ the differences are maintained, and thus it suffices to prove that
    \[\weight_{\augA}(\aug{r_i})-\weight_{\augA}(\aug{x_i})=\weight_\cA(r'_i)-\weight_\cA(x'_i)\]
    Denote $\aug{r_i}=((p_i,q_i,T_i),t_i,d_i,(p_{i+1},q_{i+1},T_{i+1}))$ and $\aug{x_i}=((p'_i,q_i,T'_i),t_i,d'_i,(p'_{i+1},q_{i+1},T'_{i+1}))$ (the second and third components are the same since both runs are runs on $\rhobase$)
    with $t_i=(q_i,\sigma_i,c_i,q_{i+1})$. 
    Then by the definition above we have
    $r'_i=(p_i,\sigma_i,d_i+c_i,p_{i+1})$ and $x'_i=(p'_i,\sigma_i,d'_i+c_i,p'_{i+1})$.
    Thus, we need to prove that
    \[d_i-d'_i=d_i+c_i-(d'_i+c_i)\]
    which indeed holds.
\else \textbf{PROOFS REMOVED} \fi\end{proof}
Recall that a run is seamless if at all prefixes, it is the minimal run to its most recent state. By \cref{prop: pov shift from aug to A maintains distance} we immediately have the following.
\begin{corollary}
\label{cor:pov shift from Aug to A maintains seamless}
    Consider a run $\rhobase$ of $\cA$ and a run $\augrho=\aug{r_1},\aug{r_2},\ldots,\aug{r_n}$ of $\augA$ on $\rhobase$. Let $\rho=r'_1,r'_2,\ldots,r'_n$ be $\shifttoorig(\augrho)$, then $\augrho$ is seamless if and only if $\rho$ is seamless.
\end{corollary}

We now turn to the converse shift: from runs of $\cA$ to runs of $\augA$. 
To this end, consider a word $w\in \Sigma^*$ and a run $\rhobase$ of $\cA$ on $w$. With every run $\rho$ of $\cA$ on $w$ we associate the \emph{$\rhobase$-shifted run of $\augA$ corresponding to $\rho$} denoted $\augrho=\shifttoaug(\rho)$ as follows.

Let $\rhobase=t_1,t_2,\ldots,t_n$ with $t_i=(q_i,\sigma_i,c_i,q_{i+1})$ and $\rho=r_1,r_2,\ldots,r_n$ with $r_i=(p_i,\sigma_i,d_i,p_{i+1})$, then $\augrho$ is the run of $\cA$ on $\rhobase$ defined by $\augrho=\aug{r_1},\aug{r_2},\ldots,\aug{r_n}$ with 
\[\aug{r_i}=((p_i,q_i,T_i),t_i,d_i-c_i,(p_{i+1},q_{i+1},T_{i+1}))\]
and $T_i$ is determined deterministically by $\augA$ on $\rhobase$.

As above, we observe that $\aug{r_i}$ is a run of $\augA$ on $\rhobase$. The initial state of $\rhobase$ and of $\rho$ is $q_0$, so the initial state of $\augrho$ is $(q_0,q_0,\{q_0\})$, i.e., the initial state of $\augA$.
For the transitions, for every $1\le i< n$, the transition $r_i$ is valid in $\augA$ on the internal state by the transition of $\rho$, and on the baseline and reachable set by the transitions (i.e., letters) of $\rhobase$. It remains to check that the weight of $r_i$ matches the transitions in $\augA$, but this follows directly by the definition of $\augTrans$.

The shift from $\cA$ to $\augA$ and from $\augA$ to $\cA$ can be seen as inverse operators, in that when shifting from $\cA$ to $\augA$, apart from the change in the state space, the weight of transitions in $\rhobase$ is subtracted, and conversely, when going back from $\augA$ to $\cA$ the weight of transitions in $\rhobase$ is added (again, apart from the change in state space). We thus have the following
\begin{observation}
    \label{obs:pov shift are inverses}
Consider a word $w\in \Sigma^*$ and a run $\rhobase$ of $\cA$ on $w$.
\begin{itemize}
    \item For runs $\rho,\rhobase$ of $\cA$ on $w$, let $\augrho=\shifttoaug(\rho)$ and let $\mu=\shifttoorig(\augrho)$, then $\mu=\rho$.
    \item For a run $\augrho$ of $\cA$ on $\rhobase$, let $\rho=\shifttoorig(\augrho)$ and $\aug{\mu}=\shifttoaug(\rho)$, then $\aug{\mu}=\augrho$.
\end{itemize}
\end{observation}
%
\begin{remark}
    \label{rmk: rhobase in shifts}
    Note that while $\rhobase$ is a parameter in $\shifttoaug(\rho)$, it is actually fixed in $\shifttoorig(\augrho)$, as it is determined by $\augrho$ (it is the word upon which $\augrho$ runs).
\end{remark}
%
We can now readily prove an analogue of \cref{prop: pov shift from aug to A maintains distance}.
\begin{proposition}
\label{prop: pov shift from A to aug maintains distance}
    Consider a run $\rhobase$ of $\cA$ on $w$, and two runs $\rho=r'_1,r'_2,\ldots,r'_n$ and $\mu=x'_1,x'_2,\ldots,x'_n$ of $\cA$ on $w$. 
    Let $\augrho=\aug{r_1},\aug{r_2},\ldots,\aug{r_n}$ and $\aug{\mu}=\aug{x_1},\aug{x_2},\ldots,\aug{x_n}$ of $\augA$ on $\rhobase$ be the respective $\rhobase$-shifted runs, then for every $1\le i\le n$ we have
    \[\weight_{\augA}(\aug{r_1},\aug{r_2},\ldots,\aug{r_i})-\weight_{\augA}(\aug{\mu}=\aug{x_1},\aug{x_2},\ldots,\aug{x_i})=\weight_\cA(r'_1,r'_2,\ldots,r'_i)-\weight_\cA(x'_1,x'_2,\ldots,x'_i)\]
\end{proposition}
\begin{proof}\ifproofs   
    By \cref{prop: pov shift from aug to A maintains distance} the $\rhobase$-shifted runs of $\cA$ that correspond to $\augrho$ and $\aug{\mu}$ maintain the differences, but by \cref{obs:pov shift are inverses} these runs are exactly $\rho$ and $\mu$, respectively.
\else \textbf{PROOFS REMOVED} \fi\end{proof}

We can now conclude that $\cA$ and $\augA$ are equi-determinizable, allowing us to proceed with an analysis of $\augA$ instead of $\cA$.

\begin{lemma}
    \label{lem:A det iff augA det}
    $\cA$ is determinizable if and only if $\augA$ is determinizable.
\end{lemma}
\begin{proof}\ifproofs    
For the first direction, assume $\cA$ is not determinizable. By \cref{thm:det iff bounded gap,def: B gap witness}, for every $B\in \bbN$ there exist words $x,y\in \Sigma^*$ and a state $q\in Q$ such that $\minweight_\cA(x\cdot y,q_0\to Q)=\minweight_\cA(x\cdot y,q_0\runsto{x}q\runsto{y}Q)<\infty$, and $\minweight_\cA(x,q_0\to q)-\minweight_\cA(x,q_0\to Q)> B$. 

By \cref{prop: pov shift from A to aug maintains distance}, the same gap between runs exists between the corresponding runs after a $\rhobase$-shift for any $\rhobase$. Moreover, a minimal run in $\cA$ is shifted to a minimal run in $\augA$. Thus, again by \cref{thm:det iff bounded gap}, we conclude that $\augA$ is not determinizable.

The converse direction is similar: assume $\augA$ is not determinizable, then for every $B\in \bbN$ there exist words $\aug{x},\aug{y}\in \Sigma^*$ and a state $s\in S$ such that $\minweight_{\augA}(\aug{x}\cdot \aug{y},s_0\to S)=\minweight_{\augA}(\aug{x}\cdot \aug{y},s_0\runsto{\aug{x}}s\runsto{\aug{y}}S)<\infty$, and $\minweight_{\augA}(\aug{x},s_0\to s)-\minweight_{\augA}(\aug{x},s_0\to S)> B$. 

By \cref{prop: pov shift from aug to A maintains distance}, the gap is maintained by the corresponding shifted runs. Note that here, the shift is dictated by the word being read, namely $\aug{x}$ (comparing the shifted runs of $s_0\runsto{\aug{x}}s$ and $s_0\runsto{\aug{x}}Q$). 
Thus, again by \cref{thm:det iff bounded gap}, we conclude that $\cA$ is not determinizable.
\else \textbf{PROOFS REMOVED} \fi\end{proof}


\section{Stable Cycles and Bounded Behaviors}
\label{sec:stable cycles and bounded behaviours}
A fundamental approach used in reasoning about weighted automata is that of \emph{stabilization}. Intuitively, the idea is to symbolically represent a repeated application of a certain transition matrix, until entries either become bounded, unreachable, or tend to $\infty$. In essence, this is a form of ``pumping''.
While useful in many setting, this form of stabilization seems to be too crude for showing that determinizability is decidable (evidently, all attempts for using it thus far have failed).

In this work, we use a much more delicate notion of stabilization, whereby we restrict attention to very specific subsets of states and transition matrices (i.e., words). 
%The fundamental concept in reasoning about automata is that of \emph{pumping}, i.e., finding a behaviour that can be repeated. 
%In our work, 
The basic structure that allows some form of pumping is that of \emph{stable cycles}. Intuitively a stable cycle is a pair $(S',w)$ where $S'$ is a set of states and $w$ is a word such that reading $w$ any number of times from the states in $S'$ leads back to $S'$, and the weighted behaviors of runs are ``stable'', in the sense that we can identify which states generate minimal runs, and which tend to unbounded weights, regardless of the starting weights. 
We make this notion precise in the following. 

\subsection{Stable Cycles}
\label{sec:stable cycles}
We start with a weaker definition than stable cycles.
\begin{definition}
    \label{def:reflexive cycle and state}
    Consider a set of states $S'\subseteq S$ and $w\in \Delta^*$. We say that $(S',w)$ is a \emph{reflexive cycle} if there exists $q\in Q$ and $T\subseteq Q$ such that $S'=\{(p,q,T)\mid p\in T\}$ and $\booltrans(S',w)\subseteq S'$.

    A state $s\in S'$ is a \emph{reflexive state} if $s\runsto{w}s$. We denote the set of reflexive states of $(S',w)$ as $\RefStates(S',w)=\{s\in S'\mid s\runsto{w}s\}$.
\end{definition}
%\gatodo{change from $booltrans$ to $ghostTrans$}
%\shtodo{Changed from $=$ to $\subseteq$, since $ghostTrans$ are not defined yet.}


That is, the states in $S'$ share the last two components, and $T$ is ``saturated'' in the sense that every state $p\in T$ represented in $S'$ as $(p,q,T)$. Reflexivity requires that reading $w$ from $S'$ leads back to $S'$, or a subset thereof.
%\gatodo{leads back to a sub-set of the same states}
Note that if $(S',w)$ is a reflexive cycle, then so is $(S',w^n)$ for every $n\in \bbN$ (this is immediate by the requirement $\booltrans(S',w)\subseteq S'$).

A-priori, $(S',w)$ might not have reflexive states at all. Clearly, however, for $w^n$ with $n$ large enough, some states become reflexive. Our first two observation is that we can stabilize the reachability set and the reflexive states by taking a large-enough repetition of $w$. 
To this end, let $\bigN= |S|!$ and $\bigM=|S| \cdot \bigN$.

A basic observation from Boolean automata is that the transition relation becomes idempotent after $\bigM$ iterations. More precisely, we have the following.
\begin{proposition}
    \label{prop: transitions stabilize at M}
    For every word $w$, states $s,r\in S$ and $n\in \bbN$ we have $s\runsto{w^\bigM}r$ if and only if $s\runsto{w^{\bigM n}}r$.
\end{proposition}
\begin{proof}
    For readers versed with the algebraic view of automata, this can be shown using the order of the transition monoid of the automaton (see e.g.,~\cite{bojanczyk2020languages}). 
    We bring a state-based proof for completeness. 

    If $s\runsto{w^\bigM}r$, then since $\bigM>|S|$ there is a simple cycle in such a run, i.e., $s\runsto{w^a}r'\runsto{w^b}r'\runsto{w^{\bigM -a-b}}r$ with $b<|S|$. But then $b$ divides $\bigM$, so we can repeat this cycle for additional $(n-1) \bigM/b$, thus yielding a run $s\runsto{w^{\bigM n}}r$.

    Conversely, if $s\runsto{w^{\bigM n}}r$, since $\bigM=|S|\bigN$, we can decompose $s$ into $\frac{\bigM n}{\bigN}=|S|n$ segments of $w^{\bigN}$.
    \[
    \rho:s\runsto{w^{\bigN}}s_1\runsto{w^{\bigN}}s_2\cdots \runsto{w^{\bigN}}s_{|S|n}=r
    \]
    Since there are more than $|S|$ such segments, we can remove cycles and obtain a run 
    \[
    \mu:s\runsto{w^{\bigN}}t_1\runsto{w^{\bigN}}t_2\cdots \runsto{w^{\bigN}}t_{k}=r
    \]
    with $k\le |S|$. 
    If $k=|S|$, then $k\bigN=\bigM$, and therefore $s\runsto{w^{\bigM}}r$ and we are done.
    Otherwise, $1\le k<|S|$, and in particular since $\bigN>|S|$ the prefix $s\runsto{w^{\bigN}}t_1$ contains a cycle of the form $t'\runsto{w^m}t'$ for some $1\le m<|S|$. Since $\bigM=|S|\cdot |S|!$, in particular $m$ divides $|S|!=\bigN$, and therefore $m$ divides $\bigM-k\bigN$.
    Thus, by repeating this cycle an additional $\frac{\bigM-k\bigN}{m}$ times, we obtain a run $s\runsto{w^{\bigM}}r$, and we are done.
\end{proof}

\begin{proposition}
\label{prop:reflexive cycles stabilize at N}
Consider a reflexive cycle $(S',w)$. For every $n,m\in \bbN$ we have that
$\RefStates(S',w^{m})\subseteq \RefStates(S',w^\bigN)=\RefStates(S',w^{\bigN \cdot n})$.
Additionally, $\booltrans(S',w^{\bigN})=\booltrans(S',w^{\bigN \cdot n})$.
\end{proposition}
\begin{proof}\ifproofs 
Let $s\in \RefStates(S',w^m)$ for some $m\in \bbN$, and take this $m$ to be minimal. 
Thus, $\rho:s\runsto{w^m}s$ for some run $\rho$. We start by showing that $s\in \RefStates(S',w^\bigN)$. First, note that if $m\le |S|$, then $m| \bigN = |S|!$, so $\rho^{\bigN/m}:s\runsto{w^\bigN}s$. Thus, $s\in \RefStates(S',w^\bigN)$. 
Next, if $m>|S|$, then by the pigeonhole principle $\rho$ has a cycle between some $w^i$ and $w^j$. 
That is, there are $1\le i<j\le m$  and some state $s'\in S$ such that $\rho:s\runsto{w^i}s'\runsto{w^{j-i}}s'\runsto{w^{m-j}}s$. We can now remove this cycle and obtain the run
$\rho':s\runsto{w^{m-(j-i)}}s$, contradicting the minimality of $m$.

Next, we show that $\RefStates(S',w^\bigN)=\RefStates(S',w^{\bigN \cdot n})$. The direction $\RefStates(S',w^\bigN)\subseteq\RefStates(S',w^{\bigN \cdot n})$ trivially holds, by repeating cycles (since $\bigN$ divides $\bigN\cdot n$). The converse holds by the argument above, plugging $m=\bigN\cdot n$.

For the reachability part, by reflexivity we inductively have that $\{\booltrans(S',w^k)\}_{k=0}^\infty$ forms a decreasing chain, and in particular $\booltrans(S',w^{\bigN \cdot n})\subseteq \booltrans(S',w^{\bigN})$.
Conversely, consider $s\in \booltrans(S',w^{\bigN})$, then by a similar pigeonhole argument as above, there is $s',s''\in S'$ such that $s'\runsto{w^i}s''\runsto{w^{j}}s'' \runsto{w^{\bigN-i-j}}s$ for some $j<|S|$, and by repeating the $w^j$ cycle we can obtain a run $s'\runsto{w^{\bigN\cdot n}}s$, so $s\in \booltrans(S',w^{\bigN\cdot n})$.
\else \textbf{PROOFS REMOVED} \fi\end{proof}
\cref{prop:reflexive cycles stabilize at N} shows that all the reflexive cycles on any number of repetitions of $w$ are already present for $w^\bigN$.

In the $(\min,+)$ semantics, of particular importance are reflexive cycles whose cycles have minimal weight. We capture this as follows. 
\begin{definition}
    \label{def:minimal reflexive states}
    Consider a reflexive cycle $(S',w)$. We say that a state $s\in \RefStates(S',w)$ is \emph{minimal reflexive} if $\minweight(w,s\to s)=\min\{\minweight(w,r\to r)\mid r\in \RefStates\}$.    
    We then define 
    \[\MinRefStates(S',w)=\{s\in S'\mid s\text{ is minimal reflexive.}\}\]
\end{definition}
That is, the cycle on $w$ from $s$ to $s$ has minimal weight among all reflexive cycles on $w$.
Recall that $S'=\{(p,q,T)\mid p\in T\}$  for some $T\subseteq Q$. In particular, $(q,q,T)\in S'$ is the unique baseline state in $S'$. 
We now ask whether $(q,q,T)$ is a minimal reflexive state, and whether its minimal reflexive run is a baseline (and therefore by \cref{obs:baseline runs have weight 0} has weight $0$). Moreover, we ask whether this holds for $w^n$ for every $n\in \bbN$. In case this holds, we say that $(S',w)$ is a \emph{Stable Cycle}. We now formalize this.

\begin{definition}[\keyicon Stable Cycle]
\label{def:stable cycle}
A reflexive cycle $(S',w)$ with baseline state $s=(q,q,T)$ is a \emph{stable cycle} if for every $n\in \bbN$ it holds that $s\in \MinRefStates(S',w^n)$ and $\minweight(w^n,s\to s)=0$.
\end{definition}

Note that if $(S',w)$ is a stable cycle, then the baseline run $\rho:s\runsto{w^n} s$ is a cycle of minimal weight on any state $s'\in S'$, and its weight is $0$.
There could be other runs from $S'$ on some $w^n$ that are negative, but not cycles.

We now show an analogous result to \cref{prop:reflexive cycles stabilize at N}, showing that the minimal reflexive states also become stable quickly, under the assumption that we have a stable cycle.
\begin{proposition}
\label{prop:minimal reflexive cycles stabilize at N}
Consider a stable cycle $(S',w)$. For every $n,m\in \bbN$ we have that 
\[\MinRefStates(S',w^{m})\subseteq \MinRefStates(S',w^\bigN)=\MinRefStates(S',w^{\bigN \cdot n})\]   
\end{proposition}
\begin{proof}\ifproofs 
Let $s\in \MinRefStates(S',w^m)$ for some $m\in \bbN$ (not necessarily the baseline state), and take this $m$ to be minimal. 
Thus, $\rho:s\runsto{w^m}s$ for some minimal-weight run $\rho$. We start by showing that $s\in \MinRefStates(S',w^\bigN)$. If $m\le |S|$, then $m| \bigN=|S|!$, so $\rho^{\bigN/m}:s\runsto{w^\bigN}s$. 
By \cref{def:stable cycle} we have $\weight(\rho)=0$, so $\weight(\rho^{\bigN/m})=0$ as well. Since $(S',w)$ is stable, then in particular $\minweight(w^{\bigN},s'\to s')\ge 0$ for every $s'\in S'$, since the baseline state is minimal reflexive for $w^{\bigN}$ (indeed, for all repetitions of $w$) and has cycle weight $0$.
It follows that $s\in \MinRefStates(S',w^{\bigN})$

Next, if $m>|S|$, then by the pigeonhole principle $\rho$ has a cycle between some $w^i$ and $w^j$. 
That is, there are $1\le i<j\le m$  and some state $s'\in S$ such that $\rho^i:s\runsto{w^i}s'$ and  $\rho^j:s\runsto{w^j}s'$. Therefore, $\rho^{j-i}:s'\runsto{w^{j-i}}s'$. Moreover, $\weight(\rho^{j-i})\ge 0$. Indeed, otherwise enough repetitions of $\rho^{j-i}$ would yield a negative cycle, contradicting the fact that the baseline state is minimal reflexive with weight 0 for \emph{every} repetition of $w$. 

We can now remove this cycle and obtain the run
$\rho':s\runsto{w^{m-(j-i)}}s$ with weight at most $0$ (and by the above -- exactly $0$), contradicting the minimality of $m$.

Next, we show that $\MinRefStates(S',w^\bigN)=\MinRefStates(S',w^{\bigN \cdot n})$. 
The direction $\MinRefStates(S',w^\bigN)$ $\subseteq\MinRefStates(S',w^{\bigN \cdot n})$ holds by repeating cycles (since $\bigN$ divides $\bigN\cdot n$), and by observing that negative cycles cannot occur in a stable cycle. 
The converse holds by the argument above, plugging $m=\bigN\cdot n$.
\else \textbf{PROOFS REMOVED} \fi\end{proof}


\subsection{States with Bounded Behaviors}
\label{sec:bounded states}
Recall that our motivation in this section is to establish a ``pumpable'' structure. Let $(S',w)$ be a stable cycle, and consider the long-term behavior of runs on $w^m$ for large $m$, starting from states in $S'$.


Recall that for a state $s\in \MinRefStates(S',w)$ we have $\minweight(w,s\to s)=0$, and that this is the minimal weight of a cycle on $w$ from $S'$. Then, for every state $r\in S'$, if either $s\runsto{w}r$ or $r\runsto{w}s$, more  repetitions of $w$ intuitively do not increase (nor decrease) the weight further, since they incur weight $0$ by cycling on $s$. 
The converse is almost correct: we would want to say that runs that avoid $\MinRefStates(S',w)$
%\gatodo{and so are runs that avoid $\MinRefStates(S',w^{\bigM})$} 
must increase unboundedly. This is almost true, except that a state might not be minimal-reflexive for $w$, but becomes minimal reflexive for $w^\bigM$, so does not lead to unbounded weights.
In the following we show that this is indeed the case: runs that avoid $\MinRefStates(S',w^{\bigM})$ inevitably yield increasing weights.
Moreover, we identify after how many repetitions of $w$ these eventual behaviors stabilize.

We start with the definitions for the three types of ``bounded behavior'': states that are reachable via $w$ from a minimal-reflexive state are called \emph{tethered} (as they are ``tethered'' to a $0$-weight cycle), states from which a minimal-reflexive state is reachable are called \emph{plateau}, as they reach a $0$-weight cycle, and their combination is referred to as \emph{grounded}, as follows.
\begin{definition}[Tethered, Plateau and Grounded Pairs]
    \label{def:tethered}
    \label{def:plateau}
    \label{def:grounded pairs}
    For a stable cycle $(S',w)$ we define:
    \begin{itemize}
        \item The \emph{tethered pairs} as
        \[\TethPairs(S',w)=\{(s,r)\in S'\times S'\mid s\in \MinRefStates(S',w)\wedge s\runsto{w}r\}\]
        We refer to each such $r$ as a \emph{tethered state}.
        \item The \emph{plateau pairs} as
        \[\PlatPairs(S',w)=\{(s,r)\in S'\times S'\mid r\in \MinRefStates(S',w)\wedge s\runsto{w}r\}\]
        We refer to each such $s$ as a \emph{plateau state}.
        \item The \emph{grounded pairs} as
        \[\GroundPairs(S',w)=\{(s,r)\in S'\times S'\mid \exists g\in \MinRefStates(S',w^{\bigM})\ST s\runsto{w^{\bigM}}g\runsto{w^{\bigM}}r\}\]
        For $(s,r)\in \GroundPairs(S',w)$, the state $g\in \MinRefStates(S',w^{\bigM})$ for which $\weight(s\runsto{w^{\bigM}}g\runsto{w^{\bigM}}r)$ is minimal (among all states in $\MinRefStates(S',w^\bigM)$) is the \emph{grounding state of $(s,r)$.}
    \end{itemize}
\end{definition}
\cref{fig:pair_types} depicts the three types of pairs in \cref{def:tethered}.
\begin{figure}[ht]
    \centering
    \includegraphics[width=0.9\linewidth]{fig/pair_types.pdf}
    \caption{$(s,r)$ is a tethered pair (1), a plateau pair (2), and grounded pair with a grounding state $g$ (3)}
    %\shtodo{Update figure 3 to the grounding state with $\bigM$.}
    \label{fig:pair_types}
\end{figure}
As a sanity-check, note that since $\booltrans(S',w)\subseteq S'$, then for every tethered, plateau, or grounded pair $(s,r)$, the fact that $r\in S'$ already follows from $s\in S'$.

Similarly to \cref{prop:reflexive cycles stabilize at N,prop:minimal reflexive cycles stabilize at N}, we show that the tethered and plateau pairs stabilize. This, however, no longer holds for any repetition of $w$, but for repetitions of $w^\bigN$, and the stabilization occurs at $\bigM$ (recall $\bigM=|S| \cdot \bigN$), as follows.

\begin{proposition}
\label{prop:tethered states stabilize at N}
Consider a stable cycle $(S',w)$. For every $n,m\in \bbN$ we have that 
\[\TethPairs(S',w^{m \cdot \bigN})\subseteq \TethPairs(S',w^\bigM)=\TethPairs(S',w^{\bigM \cdot n}).\]
Moreover, for every $(s,r) \in \TethPairs(S',w^{m \cdot \bigN})$ it holds that
\[\minweight(w^{m\cdot \bigN}, s \to r)\ge \minweight(w^{\bigM}, s \to r) = \minweight(w^{n\cdot \bigM}, s \to r) 
\]
\end{proposition}
\begin{proof}\ifproofs The proof proceeds in three steps.
\paragraph{Step 1:}
Consider a tethered pair $(s,r)\in \TethPairs(S',w^{m\bigN})$ for some $m$, and let $m$ be minimal for this pair. We claim that $m\le |S|$. Indeed, similarly to the proofs of \cref{prop:reflexive cycles stabilize at N,prop:minimal reflexive cycles stabilize at N}, if $m>|S|$, by the pigeonhole principle there exists a state $s'$ that repeats in the minimal weight run $\rho:s\runsto{w^{m\bigN}}r$. We can thus write
$\rho:s\runsto{w^{m_1\bigN}}s'\runsto{w^{m_2\bigN}}s'\runsto{w^{m_3\bigN}}r$ with $m_1+m_2+m_3=m$. We then have that $s\runsto{w^{(m_1+m_3)\bigN}}r$. In order to reach a contradiction to the minimality of $m$, we need to show that $s\in \MinRefStates(S',w^{(m_1+m_3)\bigN})$, so that $(s,r)$ is a tethered pair in $(S',w^{(m_1+m_3)}\bigN)$. This, however, follows directly from \cref{prop:minimal reflexive cycles stabilize at N}, since $\MinRefStates(S',w^{m\bigN})=\MinRefStates(S',w^{(m_1+m_3)\bigN})$. We can  therefore assume $m\le |S|$.

In addition, since stable cycles do not contain negative cycles, we have that $\minweight(w^{m_2\bigN},s'\to s')\ge 0$, so $\minweight(w^{(m_1+m_3)\bigN},s\to r)\le \minweight(w^{m\bigN},s\to r)$.

\paragraph{Step 2:} Next, we prove that $\TethPairs(S',w^{m\bigN})\subseteq \TethPairs(S',w^{k\bigN})$ for all $k\ge m$. 
Indeed, consider a tethered pair $(s,r)\in \TethPairs(S',w^{m\bigN})$, then $s\runsto{w^{m\bigN}}r$ and $s\in \MinRefStates(S',w^{m\bigN})$. 
By \cref{prop:minimal reflexive cycles stabilize at N} and since $k\ge m$ we also have 
\[s\in \MinRefStates(S',w^{\bigN})=\MinRefStates(S',w^{(k-m)\bigN})=\MinRefStates(S',w^{k\bigN}).\]
In particular, $s\runsto{w^{(k-m)\bigN}}s$, and therefore $s\runsto{w^{k-m}\bigN}s\runsto{w^{m\bigN}}r$, so $s\runsto{w^{(k\bigN)}}r$ and thus $(s,r)\in \TethPairs(S',w^{k\bigN})$.

Moreover, since $s\in \MinRefStates(w^{(k-m)\bigN})$, it follows that $\minweight(w^{(k-m)\bigN},s\to s)=0$, and from the run description above we get that
$\minweight(w^{m\bigN},s\to r)\ge \minweight(w^{k\bigN},s\to r)$ (where we have an inequality instead of equality, since conceptually there could be other runs with lower weight).

\paragraph{Step 3:} We can now complete the proof. for a pair $(s,r)\in \TethPairs(S',w^{m\bigN})$, we can assume by Step 1 that $m\le |S|$, and this can only decrease the weight. By Step 2 we also have $(s,r)\in\TethPairs(S',w^{\bigM})$, since $\bigM=|S|\bigN>m\bigN$, and that this again decreases the weight, i.e., 
\[\minweight(w^{m\bigN},s\to r)\ge \minweight(w^{\bigM},s\to r)\ge \minweight(w^{n\bigM},s\to r).\]
Conversely, if $(s,r)\in\TethPairs(S',w^{\bigM})$ then since $\bigM$ is a multiple of $\bigN$, by Step 2 we have $(s,r)\in\TethPairs(S',w^{n\bigM})$ for all $n\ge 1$. 
To conclude the equality of weights, by Step 1 and Step 2 combined, we have that 
$\minweight(w^{n\bigM},s\to r)\ge \minweight(w^{\bigM},s\to r)$. Indeed, decreasing from $n\bigM$ to at most $|S|\bigN$ decreases the weight (Step 1), and it further decreases to $|S|\bigN=\bigM$ (Step 2).
\else \textbf{PROOFS REMOVED} \fi\end{proof}


A similar claim holds for plateau states, with an analogous proof.
\begin{proposition}
\label{prop:plateau states stabilize at N}
    Consider a stable cycle $(S',w)$. For every $n,m\in \bbN$ we have that 
    \[\PlatPairs(S',w^{m \cdot \bigN})\subseteq \PlatPairs(S',w^\bigM)=\PlatPairs(S',w^{\bigM \cdot n}).\]
    Moreover, for every $(s,r) \in \PlatPairs(S',w^{m \cdot \bigN})$ it holds that
    \[\minweight(w^{m\cdot \bigN}, s \to r)\ge \minweight(w^{\bigM}, s \to r) = \minweight(w^{n\cdot \bigM}, s \to r) 
    \]
\end{proposition}
\begin{proof}\ifproofs The proof proceeds in three steps.
    \paragraph{Step 1:}
        Consider a plateau pair $(s,r)\in \PlatPairs(S',w^{m\bigN})$ for some $m$, and let $m$ be minimal for this pair. We claim that $m\le |S|$. Indeed, similarly to the proofs of \cref{prop:reflexive cycles stabilize at N,prop:minimal reflexive cycles stabilize at N}, if $m>|S|$, by the pigeonhole principle there exists a state $s'$ that repeats in the minimal weight run $\rho:s\runsto{w^{m\bigN}}r$. We can thus write
        $\rho:s\runsto{w^{m_1\bigN}}s'\runsto{w^{m_2\bigN}}s'\runsto{w^{m_3\bigN}}r$ with $m_1+m_2+m_3=m$. We then have that $s\runsto{w^{(m_1+m_3)\bigN}}r$. In order to reach a contradiction to the minimality of $m$, we need to show that $r\in \MinRefStates(S',w^{(m_1+m_3)\bigN})$, so that $(s,r)$ is a plateau pair in $(S',w^{(m_1+m_3)}\bigN)$. This, however, follows directly from \cref{prop:minimal reflexive cycles stabilize at N}, since $\MinRefStates(S',w^{m\bigN})=\MinRefStates(S',w^{(m_1+m_3)\bigN})$. We can  therefore assume $m\le |S|$.

        In addition, since stable cycles do not contain negative cycles, we have that $\minweight(w^{m_2\bigN},s'\to s')\ge 0$, so $\minweight(w^{(m_1+m_3)\bigN},s\to r)\le \minweight(w^{m\bigN},s\to r)$.

    \paragraph{Step 2:} 
        Next, we prove that $\PlatPairs(S',w^{m\bigN})\subseteq \PlatPairs(S',w^{k\bigN})$ for all $k\ge m$. 
        Indeed, consider a plateau pair $(s,r)\in \PlatPairs(S',w^{m\bigN})$, then $s\runsto{w^{m\bigN}}r$ and $r\in \MinRefStates(S',w^{m\bigN})$. 
        By \cref{prop:minimal reflexive cycles stabilize at N} and since $k\ge m$ we also have 
        \[r\in \MinRefStates(S',w^{\bigN})=\MinRefStates(S',w^{(k-m)\bigN})=\MinRefStates(S',w^{k\bigN}).\]
        In particular, $r\runsto{w^{(k-m)\bigN}}r$, and therefore $s\runsto{w^{m\bigN}}r\runsto{w^{k-m}\bigN}r$, so $s\runsto{w^{(k\bigN)}}r$ and thus $(s,r)\in \PlatPairs(S',w^{k\bigN})$.

    Moreover, since $r\in \MinRefStates(w^{(k-m)\bigN})$, it follows that $\minweight(w^{(k-m)\bigN},r\to r)=0$, and from the run description above we get that
    $\minweight(w^{m\bigN},s\to r)\ge \minweight(w^{k\bigN},s\to r)$ (where we have an inequality instead of equality, since conceptually there could be other runs with lower weight).

    \paragraph{Step 3:} 
        We can now complete the proof. for a pair $(s,r)\in \PlatPairs(S',w^{m\bigN})$, we can assume by Step 1 that $m\le |S|$, and this can only decrease the weight. By Step 2 we also have $(s,r)\in\PlatPairs(S',w^{\bigM})$, since $\bigM=|S|\bigN>m\bigN$, and that this again decreases the weight, i.e., 
        \[\minweight(w^{m\bigN},s\to r)\ge \minweight(w^{\bigM},s\to r)\ge \minweight(w^{n\bigM},s\to r).\]
        Conversely, if $(s,r)\in\PlatPairs(S',w^{\bigM})$ then since $\bigM$ is a multiple of $\bigN$, by Step 2 we have $(s,r)\in\PlatPairs(S',w^{n\bigM})$ for all $n\ge 1$. 
        To conclude the equality of weights, by Step 1 and Step 2 combined, we have that 
        $\minweight(w^{n\bigM},s\to r)\ge \minweight(w^{\bigM},s\to r)$. Indeed, decreasing from $n\bigM$ to at most $|S|\bigN$ decreases the weight (Step 1), and it further decreases to $|S|\bigN=\bigM$ (Step 2).
\else \textbf{PROOFS REMOVED} \fi\end{proof}



The stabilization of $\TethPairs$ and $\PlatPairs$ implies that the grounding state in grounded pairs does not have to be reachable and co-reachable with $w^\bigM$, as follows.
\begin{proposition}
    \label{prop:grounding states reachable with any bigM k}
    Consider a stable cycle $(S',w)$. For every $s,r,g\in S'$ with $g\in \MinRefStates(S',w^{\bigM})$, if $s\runsto{w^{\bigM i}}g\runsto{w^{\bigM j}}r$ for some $i,j\ge 1$, then $(s,r)\in \GroundPairs(S',w)$.
\end{proposition}
\begin{proof}
    Since $g\in \MinRefStates(S',w^{\bigM})$, %then by \cref{prop:minimal reflexive cycles stabilize at N} we have $g\in \MinRefStates(S',w^\bigM)$. It follows that 
    then $(s,g)\in \PlatPairs(S',w^{\bigM i})=\PlatPairs(S',w^{\bigM})$ (by \cref{prop:plateau states stabilize at N}) and that $(g,r)\in \TethPairs(S',w^{\bigM j})=\TethPairs(S',w^{\bigM})$. 
    We thus have $s\runsto{w^{\bigM}}g\runsto{w^{\bigM}}r$, so by \cref{def:grounded pairs} we have $(s,r)\in \GroundPairs(S',w)$.
\end{proof}


The main result of this section aggregated the asymptotic behavior of grounded pairs, and shows that they stabilize. We give a brief overview of the argument.

%\shtodo{The text below needs changing after the change in definitions -- we need $\bigM$ in places.}
Consider a pair of states $(s,r)$ in a stable cycle $(S',w)$. If $(s,r)\notin \GroundPairs(S',w)$, then every run $\rho:s\runsto{w^m}r$ has only strictly positive cycles (focusing on the states after each $w$), and is therefore intuitively increasing. There may, however, be negative simple paths upon reading $w$, and the negative weight can depend on the length of $w$. Thus, it is guaranteed that every long-enough run has very large weight, but achieving this weight may take a while.

Conversely, if $(s,r)\in \GroundPairs(S',w)$ and $g$ is their grounding state (c.f. \cref{def:grounded pairs}), then it is possible to spend any number $m\bigM>2\bigM$ of iterations of $w$ between $r$ and $s$ by taking $0$-weight cycles on $g$. While this is optimal among runs that go through a grounding state, there may be other runs with lower weight that initially take a very negative transition. Nonetheless, after enough repetitions of $w$, the path through the grounding state becomes optimal altogether. This is captured as follows.

\begin{lemma}[\keyicon Pumping Grounded Pairs]
\label{lem:pumping grounded pairs}
Consider a stable cycle $(S',w)$. For every $n\in \bbN$ there exists $M_0\in \bbN$ (efficiently computable) such that for all $m\ge M_0$ the following hold.\footnote{Note that Item 2 does not depend on $n$.}  
\begin{enumerate}
    \item If $(s,r)\notin \GroundPairs(S',w)$ then $\minweight(w^{m\cdot 2\bigM},s\to r)>n$.
    % \item If $(s,r)\in \GroundPairs(S',w)$ then $\minweight(w^{m\cdot 2\bigM},s\to r)=\minweight(w^{M_0\cdot 2\bigM},s\to r)$.
    % \item If $(s,r)\in \GroundPairs(S',w)$ with grounding state $g$, then $\minweight(w^{2\bigM},s\runsto{w^{M}} g\runsto{w^{M}}  r)=\minweight(w^{M_0\cdot 2\bigM},s\to r)$.
    \item If $(s,r)\in \GroundPairs(S',w)$ with grounding state $g$, then 
    \[
    \minweight(w^{m\cdot 2\bigM},s\to r)=\minweight(w^{M_0\cdot 2\bigM},s\to r)=\minweight(w^{2\bigM},s\runsto{w^{M}} g\runsto{w^{M}}  r)
    \]
    Moreover, we have $\minweight(w^{m'\cdot 2\bigM},s\to r)\le \minweight(w^{2\bigM},s\runsto{w^{M}} g\runsto{w^{M}}  r)$ for every $m'\in \bbN$.
\end{enumerate}
%\shtodo{Check if we need both 2 and 3.}
\end{lemma}
\begin{proof} \ifproofs
We first prove Item 1, and then use it to prove Item 2.% and 3.
\paragraph{Proof of Item 1.}
Let $(s,r)\notin \GroundPairs(S',w)$. We construct a weighted directed graph $G=\tup{V,E}$ whose vertices are $V=S'$ and for $p,q\in S'$ we add the edge $(p,q)$ with weight $\minweight(w^\bigM,p\to q)$ (which might be $\infty$). Observe that there is a bijection between paths from $s$ to $r$ in $G$ and runs of the form  $\rho:s=p_1\runsto{w^\bigM}p_2\runsto{w^{\bigM}}\cdots \runsto{w^\bigM}p_{k}=r$ provided each section $p_i\runsto{w^\bigM}p_{i+1}$ in the run has minimal weight (indeed, otherwise it can be replaced by a lower-weight run).
In particular, for all $k$, the minimal weight of a run from $s$ to $r$ on $w^{k\bigM}$ is attained by a path in the graph.


Since $(S',w)$ is stable, this graph has no strictly negative cycles.
Since $(s,r)\notin \GroundPairs(S',w)$, then every cycle in the graph that is reachable from $s$ and can reach $r$, has strictly positive weight. Indeed, otherwise there would be a run $s\runsto{w^{k_1\bigM}}q\runsto{w^{k_2\bigM}}q\runsto{w^{k_3\bigM}}r$ with $\minweight(q\runsto{w^{k_2\bigM}}q)=0$. However, by \cref{prop:minimal reflexive cycles stabilize at N} this implies $q\in \MinRefStates(S',w^{\bigM})$, which in turn implies by \cref{prop:tethered states stabilize at N,prop:plateau states stabilize at N,prop:minimal reflexive cycles stabilize at N} that $(s,r)\in \GroundPairs(S',w)$ (as $(s,q)\in \PlatPairs(S',w^{\bigM})$ and $(q,r)\in \TethPairs(S',w^{\bigM})$), but this contradicts the assumption that $(s,r)\notin \GroundPairs(S',w)$.

We conclude that every cycle reachable between $s$ and $r$ has strictly positive weight. The claim readily follows from this, by noting that increasingly long runs have increasingly large weight (which corresponds to all the runs having large weight). We spell out the argument for completeness.

By Johnson's algorithm~\cite{johnson1977efficient} we can (efficiently) compute a new weight function on the edges $\mu:E\to \bbN$ and two numbers $v_s,v_r\in \bbZ$ such that the weight of a path $s=p_1,p_2,\ldots,p_k=r$ in the original graph $G$ is $v_s+\sum_{i=1}^{k-1}E(p_i,p_{i+1})-v_r$. Note that in the new weights, there are no negative edges at all, and the property that there are no reachable $0$-cycles between $s$ and $r$ is maintained by Johnson's construction. We can now readily see that in every segment of length $|S|$ in the path there is at least one cycle, whose weight is at least $1$. Therefore, for every $n\in \bbN$, every path of length $|S|(|v_s|+|v_r|+n)$ has weight at least $n$ in $G$. Thus, for every $n\in \bbN$ we can set $M_0=|S|(|v_s|+|v_r|+n)$, and the claim follows (note that we prove the claim already for $w^{m\cdot \bigM}$, but we take $w^{m\cdot 2\bigM}$ for uniformity with the other constants).

Note that in fact, we prove a slightly stronger result: for any pair $(s,r)$, if $\rho:s\runsto{w^{m\cdot 2\bigM}}r$ does not traverse a $0$-weight cycle while reading some $w^i$ infix, then $\weight(\rho)>n$. In particular, if $\weight(\rho)\le n$ then it must make a $0$-weight cycle on some state $q\in \MinRefStates(S',w^\bigM)$.
This observation is used in the next part of the proof.


%\paragraph{Proof of Items 2 and 3.}
\paragraph{Proof of Item 2.}
Consider $(s,r)\in \GroundPairs(S',w)$ and let $g$ be the grounding state for $(s,r)$ (see \cref{def:grounded pairs}). 
We first note that for every $m\in \bbN$ it holds that there is always a run on $w^{m\cdot 2\bigM}$ that uses the grounding state as a $0$-cycle. Indeed, $s\runsto{w^\bigM}g\runsto{w^{(m-1)2\bigM}}g\runsto{w^{M}}r$ is a run from $s$ to $r$ on $w^{m\cdot 2\bigM}$. Since $\minweight(w^{\bigM},g\to g)=0$ it follows that the weight of this run is exactly $\minweight(w^{2\bigM},s\runsto{w^{\bigM}} g\runsto{w^{\bigM}}r)$. We thus have the inequality:
\[
\minweight(w^{2\bigM},s\runsto{w^{\bigM}} g\runsto{w^{\bigM}}r)\ge \minweight(w^{m\cdot 2\bigM},s\to r).
\]
This concludes the ``Moreover'' part.
It remains to show that there is some $M_0\in \bbN$ such that for all $m\ge M_0$, the reverse inequality holds.

Fix $n=\minweight(w^{2\bigM},s\runsto{w^{\bigM}} g\runsto{w^{\bigM}}r)$ and let $M_0$ be the constant constructed in the proof of Item 1 for this $n$. The observation at the end of the proof of Item 1 gives us that for every $m\ge M_0$, every run $\rho:s\runsto{w^{m\cdot 2\bigM}}r$ that does not visit a state in $\MinRefStates(S',w^\bigM)$ must have weight larger than $n$. By the inequality above, such runs cannot be minimal, and we can therefore ignore them.

Consider then a minimal-weight run $\rho:s\runsto{w^{m\cdot 2\bigM}}r$ that visits a state $q\in \MinRefStates(S',w^\bigM)$, then we can write
$\rho:s\runsto{w^{k_1\cdot 2\bigM}}q\runsto{w^{k_2\cdot 2\bigM}}r$ for some $k_1,k_2\ge 1$. 
 Then, by \cref{prop:tethered states stabilize at N,prop:plateau states stabilize at N} we have that $(s,q)\in \PlatPairs(w^{\bigM},s\to q)$ and $(q,r)\in \TethPairs(w^{\bigM},q\to r)$, and moreover: $\minweight(w^\bigM,s\to q)=\minweight(w^{k_1\bigM},s\to q)$ and similarly $\minweight(w^\bigM,q\to r)=\minweight(w^{k_2\bigM},q\to r)$.
 Thus, we have $\weight(\rho)=\minweight(w^{2\bigM},s\runsto{w^\bigM}q\runsto{w^{\bigM}}r)$. However, recall that $g$ is the grounding state, which by definition means that $g$ minimizes this expression over all $q\in \MinRefStates(S',w^{\bigM})$, and therefore $\weight(\rho)\ge \minweight(w^{2\bigM},s\runsto{w^\bigM}g\runsto{w^{\bigM}}r)$. We thus have 
 \[
\minweight(w^{m\cdot 2\bigM},s\to r)\ge \minweight(w^{2\bigM},s\runsto{w^{\bigM}} g\runsto{w^{\bigM}}r)
\]
and we conclude the equality.
We can now either plug in $m=M_0$ or leave $m\ge M_0$ to get the two equalities of Item 2.
\else \textbf{PROOFS REMOVED} \fi \end{proof}

\section{The Cactus Extension}
\label{sec:cactus extension}
Consider a baseline-augmented subset construction $\augA=\tup{S,\Gamma,\augInitState,\augTrans}$. Note that we now denote the alphabet by $\Gamma$; we no longer assume $\Gamma$ is finite. 
More precisely, we do not assume the precise transitions defined in \cref{sec:augmented construction}, but the following:
%\shtodo{Consider flipping $q$ and $p$, so we match the previous section.}
\begin{itemize}
    \item The states are of the form $(q,p,T)$ where $q,p\in T$.
    \item The transitions are deterministic with respect to the second and third components (referred to as \emph{baseline component} and \emph{reachable set}, respectively).
\end{itemize}
%
In the following, we repeatedly extend the alphabet and transitions of $\augA$ to obtain a sequence of automata over the same state space with the properties above. We briefly sketch our approach.
Our extension consists of three phases. First, we introduce a \emph{stabilization} operator, which adds letters referred to as \emph{cactus letters}. Intuitively, a cactus letter is built by nesting stable cycles, where each stable cycle becomes a letter. 
The next phase is a \emph{rebase} operator, which further adds the \emph{rebase letters}. Intuitively, these letters represent a stable cycle, but also shift the baseline to a new state (which is not possible in cactus letters). 
We then repeatedly alternate adding cactus letters and rebase letters to an infinite limit. 
Finally, we add another set of letters, referred to as \emph{jump} letters. These allow us to change the baseline. The need for jump letters is technical, and we explain their usage in due course.

\subsection{Cactus Letters}
\label{sec:cactus letters}
Cactus letters are defined as the infinite union of an inductively defined set. The induction steps are defined by adding new letters and transitions with the following \emph{stabilization} operator.
%At the base of the induction, for every stable cycle $(S',w)$ in $\augA$ we introduce a new letter and transitions, as follows.
\begin{definition}[\keyicon Stabilization]
\label{def:stabilization}
    For each stable cycle $(S',w)$ we introduce a new letter $\alpha_{S',w}$ with the following transitions: for every $(s,r)\in \GroundPairs(S',w)$ with grounding state $g$ we have the transition $(s,\alpha_{S',w},\minweight(w^{2\bigM},s\runsto{w^\bigM}g\runsto{w^\bigM} r),r)$. We refer to this operation as \emph{stabilization}, and denote the new letters by $\stab_{\augA}(\Gamma)$ and the new transitions by $\stab_{\augA}(\augTrans)$.
\end{definition}
\begin{remark}
\label{rmk:stabilization other works}
The term \emph{stabilization} is often used in the algebraic view of automata to denote a closure operation on the transition monoid of a WFA~\cite{lombardy2006sequential,daviaud2023big} whereby runs that increase too much are ``sent to $\infty$''.
Our usage is technically different, but has a similar flavor, and hence we reuse the name. 
Indeed, by \cref{lem:pumping grounded pairs}, the effect of reading arbitrarily many repetitions of $w$ from a state in a stable cycle is either bounded (for a grounded pair) or tends to infinity. 
\end{remark}

We define the stabilization by essentially considering $w^{2\bigM}$. This, however, can be replaced by $w^{m2\bigM}$ for any $m\in \bbN$, as we now show. Intuitively, the reason is that at $2\bigM$ most of the behaviors stabilize.
\begin{proposition}
    \label{prop:cactus letters stabilizes at 2M}
    Consider a stable cycle $(S',w)$, then for every $m\in \bbN$ we have that $(S',w^{m\cdot 2\bigM})$ is also a stable cycle, and the transitions defined on $\alpha_{S',w}$ are identical to those of $\alpha_{S',w^{m\cdot 2\bigM}}$. 
    I.e, for every $s,r\in S$ we have $\minweight(\alpha_{S',w},s\to r)=\minweight(\alpha_{S',w^{m\cdot 2\bigM}},s\to r)$.
\end{proposition}
\begin{proof}
    Let $m\in \bbN$. We first claim that $(S',w^{m\cdot 2\bigM})$ is a stable cycle. 
    Since $(S',w)$ is reflexive, then $\booltrans(S',w)\subseteq S'$, so $\booltrans(S',w^{k})\subseteq S'$ for every $k\in \bbN$, and in particular for $k=m2\bigM$. 
    Similarly, by \cref{def:stable cycle} we have that for every $n\in \bbN$, the baseline state $s\in S$ satisfies $s\in \MinRefStates(S',w^{n})$ and has a $0$-cycle, and in particular this holds for multiples of $m 2\bigM$, so $(S',w^{m\cdot 2\bigM})$ is a stable cycle.

    Next, consider $(s,r)\in \GroundPairs(S',w)$, then by definition we have $s\runsto{w^\bigM}g\runsto{w^\bigM}r$  for $g\in \MinRefStates(S',w^\bigM)$, but then we also have $s\runsto{(w^{m2\bigM})^\bigM} g\runsto{(w^{m2\bigM})^\bigM} r$ via the run
    $
    s\runsto{w^\bigM}g \runsto{w^{m4\bigM^2-2}} g   \runsto{w^\bigM} r 
    $,
    so $(s,r)\in \GroundPairs(S',w^{m\cdot 2\bigM})$. Moreover, by the run above we also have
    $\minweight(w^{2\bigM},s\to r)\le \minweight((w^{m2\bigM})^{2\bigM},s\to r)$.

     Conversely, consider $(s,r)\in \GroundPairs(S',w^{m\cdot 2\bigM})$, then by \cref{prop:grounding states reachable with any bigM k} we have $(s,r)\in \GroundPairs(S',w)$, and by \cref{lem:pumping grounded pairs} we have $\minweight((w^{m2\bigM})^{2\bigM},s\to r)\le \minweight(w^{2\bigM},s\to r)$.

     Since the transitions on cactus letters are only defined for grounded pairs, this concludes the proof.
\end{proof}

We now apply stabilization inductively, and take the infinite union, as follows.
\begin{definition}[\keyicon Stabilization Closure]
\label{def:stab closure}
For every $k\in \bbNinf$ we define  
$\stab_k(\augA) = \augA_k =\tup{S,\Gamma_k,\augInitState,\augTrans_k}$ inductively as follows.
\begin{itemize}
    \item For $k=0$ we define $\Gamma_0=\Gamma$, $\augTrans_0=\augTrans$.
    \item For $k>0$ we define $\Gamma_k=\Gamma_{k-1}\cup \stab_{\augA_{k-1}}(\Gamma_{k-1})$ and $\augTrans_k=\augTrans_{k-1}\cup \stab_{\augA_{k-1}}(\augTrans_{k-1})$ 
    \item For $k=\infty$ we define $\Gamma_\infty=\bigcup_{k\in \bbN}\Gamma_k$ and $\augTrans_\infty=\bigcup_{k\in \bbN}\augTrans_k$.
\end{itemize}
\end{definition}
We refer to the letters in $\Gamma_\infty$ as \emph{cactus letters of $\Gamma$} and we denote 
$\augA_\infty = \stab_\infty(\augA) = \bigcup_{k\in \bbN}\augA_k$. Notice that while the sets of letters and transitions of $\augA_\infty$ are infinite, its set of states is $S$.  
%\shtodo{an example would be really helpful here.}
\begin{example}[Cactus Letters]
    \label{xmp:cactus letters}
    Suppose $\Gamma=\{a,b\}$, we construct some cactus letters (See \cref{fig:cactus}). 
    For the sake of the example we do not have a concrete WFA, as we just illustrate the syntax of cactus letters. 
    Let ${\color{Cerulean}w_1=aaa}$ and ${\color{Cerulean}w_4=bbb}$, we define ${\color{Cerulean}\alpha_1=\alpha_{S_1,w_1}}$ and ${\color{Cerulean}\alpha_4=\alpha_{S_4,w_4}}$. 
