\begin{remark}
\label{rmk:baseline transitions with cactus are zero}
Recall that in $\augA$, transitions between baseline states have weight 0. We remark that this is preserved in $\augA_\infty$. Indeed, a transition on $\alpha_{S',w}$ between baseline states $(p,p,T)$ and $(q,q,T')$ implies that $p=q$, and that $w$ prescribes a $0$-weight self loop on $p$, since $S'$ is a stable cycle and $p\in \MinRefStates(S',w^{\bigM})$ (see \cref{def:stable cycle}). 
\end{remark}



Consider a word $w\in \Gamma_\infty^*$, then $w$ is a concatenation of letters from various $\Gamma_k$'s. In the following we define the \emph{depth} of $w$ as the maximal $k$ used in the letters of $w$. This is illustrated in \cref{fig:cactus}.

In addition, we define a \emph{cost} of a word. Intuitively, the cost represents a measure of ``length'' of words, where cactus letters are defined to be extremely long, and dramatically increasing in length with each added depth. The notion of cost is central to our proof, and becomes clear later on.
\begin{definition}
\label{def:cost depth and sub cactus}
The functions $\cost:\Gamma_\infty\to \bbN$ and $\depth:\Gamma_\infty\to \bbN$ are defined inductively on the structure of $\Gamma_\infty^*$ in \cref{tab:cost depth and sub}.
\begin{table}[h!]
\centering
\begin{tabular}{|c|c|c|}
\hline
 & $\cost(w)=$ & $\depth(w)=$ \\
\hline
$w = a \in \Gamma_0=\Gamma$ & $ \wmax{a}+1$ & $1$  \\
\hline
$w = \alpha_{S',x} \in \Gamma_\infty$ & $ 2^{16(\bigM |S| \cdot \cost(x))^2}$ & $ 1 + \depth(x)$  \\
\hline
$w = \sigma_1 \cdots \sigma_m \in \Gamma_\infty^*,\  m\ge 2$ & $ \sum_{i=1}^m \cost(\sigma_i)$ & $ \max_{1\le i\le m}(\depth(\sigma_i))$ \\
\hline
\end{tabular}
\caption{The cost and depth functions.}
\label{tab:cost depth and sub}
\end{table}
\end{definition}

Note that \cref{def:cost depth and sub cactus} is indeed inductive, since if $\alpha_{S',w}\in \Gamma_k$ for some $k\in \bbN$, then $w\in \Gamma_{k-1}^*$. That is, considering the ``inner'' letters of a cactus letter must decrease the depth, so the definition reaches a terminating condition. 

\begin{remark}[$\cost$ is strictly increasing on prefixes]
    \label{rmk:cost is strictly increasing}
    The reason for $+1$ in the cost of a single letter is just so that the cost function is always strictly positive. Then, since the cost of a word is defined as the sum of the costs of its letters, we have that if $x$ is a prefix of $y$, then $\cost(x)<\cost(y)$.
\end{remark}



The precise reason for the cost of $\alpha_{S',x}$ being defined as it is becomes apparent in later sections. For now, we show that the cost can be used to upper-bound the maximal weight.
\begin{proposition}
\label{prop:cost higher than max weight}
    For every $w \in \Gamma_\infty^*$ it holds that $\maxeff{w}\le \cost(w)$.
    %we have that the maximal weight of $\alpha$ is at most $cost(\alpha)$.
\end{proposition}
\begin{proof}
The proof is immediate by induction according to \cref{tab:cost depth and sub}, as follows.
    \begin{itemize}
        \item If $w=a\in \Gamma_0$, then by definition $\cost(a)=\wmax{a}+1=\maxeff{a}+1>\maxeff{a}$.
        \item If $w=\alpha_{S',x}$, let $p,q$ such that $(p,\alpha_{S',x},c,q)\in \augTrans_\infty$ with maximal (finite) $c$ in absolute value, i.e., $|c|=\wmax{\alpha_{S',x}}$. 
        Since there is a finite-weight transition on $\alpha_{S',x}$ from $p$ to $q$, it follows from \cref{def:stabilization} that $c=\minweight(x^{2\bigM},p\runsto{x^\bigM} g\runsto{x^\bigM} q)$ for some state $g$. In particular, $c\le \wmax{x^{2\bigM}}2\bigM |x|$. By induction we have $\wmax{x}|x|\le \cost(x)$, so 
        \[
        \begin{split}
            c&\le \wmax{x^{2\bigM}}2\bigM |x| =\wmax{x}2\bigM |x|\\
            &\le \cost(x)2\bigM \le 2^{16\bigM |S|^2 \cost(x)}=\cost(\alpha_{S',x})=\cost(\alpha_{S',x})
        \end{split}
        \]
        where we use the fact that $\wmax{x^{2\bigM}}=\wmax{x}$, since $\wmax{}$ depends only of the set of letters occurring in the word, and the fact that $b 2\bigM \le 2^{16 \bigM |S|^2 b}$, which holds for all $b\in \bbN$.

        We conclude that $\wmax{\alpha_{S',x}}|\alpha_{S',x}|=c\le \cost(\alpha_{S',x})$, as required.

        \item If $w=\sigma_1\cdots \sigma_m$, we have by the induction hypothesis that
        \[ \cost(w)=\sum_{i=1}^n\cost(\sigma_i)\ge \sum_{i=1}^n\maxeff{\sigma_i}=\sum_{i=1}^n\wmax{\sigma_i}=\maxeff{w}\] 
        where we use the fact that for single letters, $\maxeff{\sigma_i}=\wmax{\sigma_i}$.
    \end{itemize}
\end{proof}




\subsection{Rebase Letters}
\label{sec:rebase letters}
In light of \cref{rmk:baseline transitions with cactus are zero}, we note that cactus letters maintain the baseline. However, later on in the proof (in \cref{sec:condition for type 1 witness}), we need to change the baseline while reading a stable cycle. 
To this end, we introduce an additional set of letters and transitions that allow to (intuitively) traverse a grounded pair by reading a cactus letter $\alpha_{S',w}$, while changing the baseline to a new state. The weight of these transitions is then normalized by the weight of the transition on $\alpha_{S',w}$.
\begin{definition}[Rebase]
\label{def:rebase}
    Let $\augA_\infty$ be the stabilization closure of $\augA$.
    Consider a cactus letter $\alpha_{S',w}\in \Gamma_\infty$ and write $S'=\{(q,p,T)\mid q\in T\}$. 
    For each grounded pair $(s,r)\in \GroundPairs(S',w)$ where $s=(q_1,p,T)$ and $r=(q_2,p,T)$ with the transition $(s,\alpha_{S',w},c,r)\in \augTrans_\infty$, we add a letter $\beta_{S',w,s\to r}$ with the following transitions:
 \[
\{((q',q_1,T),\beta_{S',w,s\to r},d-c,(q'',q_2,T))\mid ((q',p,T),\alpha_{S',w},d,(q'',p,T))\in \augTrans_\infty\}
 \]
We refer to the resulting WFA as $\rebase(\augA_\infty)$. 
%, and denote the new letters by $\rebase_{\augA}(\Gamma)$ and the new transitions by $\rebase_{\augA}(\augTrans)$.
\end{definition}
\begin{figure}[ht]
    \centering
    \includegraphics[width=0.75\linewidth]{fig/rebase.pdf}
    \caption{Rebase letter $\beta_{S',w,s\to r}$ with $s=(q,p,T)$ and $r=(q',p,T)$ induced by the $\alpha_{S',w}$ transition from $(q,p)$ to $(q',p)$. The weight of the resulting transitions, as well as the baseline run, shifts down by $c$, in accordance with the new base transition from $q$ to $q'$. }
    \label{fig:rebase}
\end{figure}
We illustrate the behavior of a rebase letter in \cref{fig:rebase}.


\begin{remark}[Cactus as Rebase]
\label{rmk:cactus as rebase}
Consider a cactus letter $\alpha_{S',w}$ where $S'=\{(q,p,T)\mid q\in T\}$. We observe that for the baseline state $s_p=(p,p,T)$, the transitions defined on the letter $\beta_{S',w,s_p\to s_p}$ are identical to those on $\alpha_{S',w}$.

Indeed, $(s_p,\alpha_{S',w},0,s_p)\in \augTrans_\infty$, so plugging in $0$ for $c$ in \cref{def:rebase} gives identical weights to those of $\alpha_{S',w}$.
\end{remark}

As a sanity check, note that the weight of the transition from $s$ to $r$ upon reading $\beta_{S',w,s\to r}$ is $0$ (since $(s,\alpha_{S',w},c,r)\in \augTrans_\infty$, and by plugging in $q'=q_1$ and $q''=q_2$ in \cref{def:rebase}). Therefore, the property that baseline transitions have weight $0$ is maintained.

\begin{remark}
\label{rmk:rebase is idempotent}
    Observe that rebase introduces new letters only for letters obtained by stabilization. Therefore, it is an idempotent operator. That is, if $\augA'$ is obtained from $\augA$ by applying rebase, then applying rebase on $\augA'$ does not introduce new letters.
\end{remark}

We now alternate the stabilization closure and rebase ad infinitum, as follows.
\begin{definition}[Cactus Extension]
\label{def:cactus extension}
Define $\augA^0_0=\augA$. 
For every $k,j\in \bbNinf$ we define 
$\augA^j_k=\tup{S,\Gamma^j_k,\augInitState,\augTrans^j_k}$ inductively as follows.
\begin{itemize}
    \item We define $\augA^0_k=\stab_k(\augA)$ as per \cref{def:stab closure}.
    \item For $j>0$ we define $\augA^j_0=\rebase(\augA^{j-1}_\infty)$.
    \item For $j>0$ and $k>0$ (including $k=\infty$) we define $\augA^j_k = \stab_k(\augA^j_0)$.
    \item For $j=\infty$ and every $k$ we define $\augA^\infty_k$ as the union (of alphabets and transitions) of $\augA^j_\infty$ for $j\in\bbN$. 
\end{itemize}
\end{definition}
\begin{remark}
\label{rmk:rebase not relevant in infinite level}
    Observe that $\augA^\infty_k=\augA^\infty_\infty$ for all $k$, since applying stabilization on the infinite union does not add new letters (since stabilization is applied to words of some finite depth anyway, and is therefore already in the union).
\end{remark}
\begin{remark}
    \label{rmk:cost functions on cactus extension levels}
    Recall that the $\cost$ and $\depth$ functions (\cref{def:cost depth and sub cactus}) are defined with respect to the stabilization closure. Thus, when considered on a word in the scope of $\augA^j_\infty$ for some $j>0$, the underlying alphabet $\Gamma$ is actually $\Gamma^j_0$. 
    %\shtodo{Is the following correct?}
    That is, rebase letters are considered as having depth $1$, like ``regular'' letters. 
    In the context of our results, we never use $\cost$ and $\depth$ over rebase letters. However, since we also establish a general toolbox, this is worth noticing.
\end{remark}

\subsection{Jump Letters}
\label{sec:jump letters}
Our final type of letters is a technical addition that simplifies (some) proofs.
These letters, referred to as \emph{jump letters}, allow us to change the baseline state without other effect. 
\begin{definition}
    \label{def:jump letters}
    Consider a cactus extension $\augA^j_k$. For states $s=(q,p_1,T), r=(q,p_2,T)\in S$ and $T\subseteq Q$ (recall that $Q$ is the state space of the original WFA $\cA$) we introduce a \emph{jump letter} $\jl_{s\to r}$ with the following transitions. For states $t=(q',p_1,T)$ and $g=(q',p_2,T)$ (note the same \emph{first} and third component), we add the transition $(t,\jl_{s\to r},0,g)$.
    %and for every $s'=(q',p',T)$ with $p'\neq p_1$ we have $(s',\jl_{p_1\to p_2,T},0,s')$
    %\gatodo{why cant this also be infinity ?}
    %\shtodo{It can and should. Thanks.}
    For states not of the form $(\cdot,p_1,T)$, the transitions have weight $\infty$.
%
    Note that the transitions on $\jl_{s\to r}$ are deterministic.
\end{definition}
Thus, jump letters can change the baseline without further effect. 
Note that since the baseline component is deterministic, then upon reading $\jl_{s\to r,T}$, all reachable states change their baseline. 
Also observe that jump can only change the baseline component to a state in $T$. However, as we discuss in the following (\cref{sec:reachable ghost states}), some states in $T$ may be unreachable. And indeed, $\jl$ letters may allow the baseline to be at an unreachable state, thus making the baseline run not seamless.

\begin{remark}
    \label{rmk:jump letters first component}
    Note that in \cref{def:jump letters}, the component $q$ in $s$ and $r$ is ignored (indeed, the same transitions are induced regardless of $q$). Thus, we sometimes denote the states $s,r$ of $\jl_{s\to r}$ as e.g., $s=(\cdot,p_1,T)$, where $\cdot$ stands for some arbitrary state.
\end{remark}

Finally, due to the ``violent'' nature of jump letters, we emphasize whenever they are present in a run, and in particular in a seamless run. We say that a run is \emph{jump free} if its transitions do not contain a jump letter.
We do not annotate whether an alphabet contains jump letters or not, but we state so explicitly when relevant.




\subsection{Ghost Reachable States}
\label{sec:reachable ghost states}
%\begin{remark}[Ghost Reachable States $\mathghost$]
%\label{rmk:reachable ghost states}
Consider a word $w$. Recall that $\booltrans(s_0,w)$ is the set of states reachable from $s_0$ by reading $w$. 
In $\augA$, before the introduction of cactus letters, it holds that 
$\booltrans(s_0,w)=\{(p,q,T)\mid p\in T\}$ for some set $T$. That is, the reachable first components are exactly captured by the third component $T$.
After introducing cactus letters, however, this no longer holds. Indeed, \cref{def:cactus extension,def:rebase} limit the transitions to certain states (namely those obtained from grounded pairs). In particular, we have that
$\booltrans(s_0,w)=\{(p,q,T)\mid p\in T'\}$ for some $T'\subseteq T$, but equality does not necessarily hold.
Intuitively, the states in $T\setminus T'$ are 
those for which repetitions of cactus infixes lead to unbounded increase in weight, and are therefore abstracted to $\infty$ in the stabilization.

Nonetheless, our analysis (in particular in \cref{sec:witness,sec:existence of separated increasing infixes}) requires us to reason about these states, which we term \emph{ghost states}. 

\begin{definition}[Ghost-Reachable States $\mathghost$]
    \label{def:ghost states}
    Consider a state $s=(p_1,q_1,T_1)$ and word $w$ with $\booltrans(s,w)=\{(p_2,q_2,T'_1)\mid p_2\in T_2\}$ for some $T_2\subseteq T'_1$. 
    We define the set \emph{ghost-reachable states of $w$ from $s$} as
$\ghostTrans(s,w)=\{(p_2,q_2,T'_1)\mid p_2\in T'_1\}$.
\end{definition}
%We therefore define for  
Note that $\ghostTrans(s,w)$ includes the ghost states as well as the standard reachable states. That is, $\booltrans(s,w)\subseteq \ghostTrans(s,w)$.
Moreover, observe that $\ghostTrans(s,w)$ is determined by $\booltrans(s,w)$, and therefore if $\booltrans(s,w)=\booltrans(s',w')$ then $\ghostTrans(s,w)=\ghostTrans(s',w')$.
%\end{remark}

\begin{remark}[Stable Cycles Maintain Ghost States]
\label{rmk:stable cycles maintain ghost states}
    For every stable cycle $(S',w)$ we have $\ghostTrans(S',w)=S'$. 
    Indeed, recall that for a cycle to be stable, and in particular reflexive (\cref{def:reflexive cycle and state}), it holds that $S'=\{(p,q,T)\mid p\in T\}$ for some $T$ (i.e., the set of states is ``saturated'' with respect to $T$), and that $\booltrans(S',w)\subseteq S'$. In particular, all states in $\booltrans(S',w)$ are of the form $(\cdot,q,T)$ for some $q,T\in Q$.
    Thus, we have $\ghostTrans(S',w)=\{(p,q,T)\mid p\in T\}=S'$.
\end{remark}

We also lift the definition to runs, as follows.
\begin{definition}[Ghost Run]
\label{def:ghost run}
    Consider words $w_1,w_2$ and states $p\in \ghostTrans(s_0,w_1)\setminus\booltrans(s_0,w_1)$ and $q\in \ghostTrans(s_0,w_1w_2)\setminus\booltrans(s_0,w_1w_2)$.
    We then say that a run $q \runsto{w_2} p$ on the infix $w_2$ is a \emph{ghost run from $w_1$ to $w_1w_2$}. 
\end{definition}
We note that a ghost run cannot visit the same state as a ``real'' run on any prefix of $w_2$, as that would entail $q\in \booltrans(s_0,w_1w_2)$. Thus, ghost runs are ``uninterrupted'' by real ones.


\section{A Toolbox for Cacti}
\label{sec:cactus toolbox}
Cactus, rebase and jump letters intuitively do two things: (1) abstract away parts of words as ``pumpable'' cycles, in a \emph{nested} manner, and (2) shift the baseline run between states. 
A central theme in our reasoning is to utilize these features by ``folding'' parts of words into a cactus, ``unfolding'' other parts, possibly in a nested fashion, and shifting the baseline to a certain run as a ``point-of-view change''. These operations demonstrate the versatility of the cactus framework. 
In this section, we present the toolbox that allows us to perform these operations. This is divided to three parts: a framework to bound the depth of ``interesting'' nested cacti (\cref{sec:degeneracy and cactus depth bound}), a framework for shifting the baseline run (\cref{sec: baseline shift}), and a framework for getting rid of all cacti and rebase letters by \emph{flattening} (\cref{sec: cactus unfolding}).

\subsection{Degeneracy and A Bound on Cactus Depth}
\label{sec:degeneracy and cactus depth bound}
In this section, we consider words built up by repeatedly nesting cactus letters, as the following definition captures (see \cref{fig:cactus}).
\begin{definition}[Cactus Chain]
\label{def:cactus chain}
    A \emph{cactus chain} is a finite sequence of letters $\alpha_{S'_1,w_1},\ldots,\alpha_{S'_n,w_n}$ such that for every $1\le i<n$ we have $w_i=u_i \alpha_{S'_{i+1},w_{i+1}}v_i$.
\end{definition}
%\shtodo{SARAI, can you add to Fig 2 the subwords $u_i,v_i$ so that the chain into $\alpha_4$ is a cactus chain? (this will also demonstrate that $u_1$ can contain a cactus letter).}

Cactus chains can be arbitrarily deep. Our goal in this section is to show that while this is the case, only a bounded number of ``layers'' can include interesting behaviors. In order to formalize this, we introduce the notions of \emph{degenerate} and \emph{non-degenerate} stable cycles, as follows.


\begin{definition}[(Non-)Degenerate Stable Cycle]
\label{def:degenerate stable cycle}
    A stable cycle $(S',w)$ is \emph{degenerate} if for every $s\in S'$, $t\in \RefStates(S',w^{2\bigM})$, if there is a run $s\runsto{w^{2\bigM k}}t$ for some $k\ge 1$, then $(s,t)\in \GroundPairs(S',w)$.

    Otherwise, $(S',w)$ is \emph{non-degenerate}, and a state $s\in S'$ such that there exists $t\in \RefStates(S',w^{2\bigM})$ and $k\ge 1$ for which $s\runsto{w^{2\bigM k}}t$ and $(s,t)\notin \GroundPairs(S',w)$ is called a \emph{non-degenerate state}.
    %we define degenerate stable cycle $(S',w)$ as stable cycle in which for every $s \in S', t \in \RefStates(S',w^{2 \bigM})$ if there is a run $s \runsto{w^{2\bigM i}} t$ (for some $i$) than $(s,t) \in \GroundPairs(S',w)$.
\end{definition}
Intuitively, the ``canonical'' degenerate cycle is one where all the reflexive states are also minimal-reflexive (i.e., have a $0$-cycle on $w^{2\bigM}$). Indeed, then any reflexive state can serve also as a grounding state. The definition of degeneracy generalizes this notion, by allowing some reflexive states that are not minimal, but they cannot be reached without going through a grounding state, and therefore their non-minimality does not really add any unboundedness. We formalize this in \cref{sec:boundedness of degenerate cycles}. 
%In contrast, a non-degenerate cycle has a non-degenerate state, from which a non-minimal reflexive state can be reached, and repeating $w$ actually induces higher and higher weights. 
\subsubsection{Boundedness of Degenerate Cycles}
\label{sec:boundedness of degenerate cycles}
\begin{proposition}
\label{prop:degenerate cycle has bounded weights}
    Consider a degenerate stable cycle $(S',w)$ and $s,r \in S'$. For every $k\in \bbN$, if $s\runsto{w^{2\bigM |S| k}}r$, then 
    $|\minweight(w^{2\bigM |S| k},s \to r)|\leq 2\bigM \cost(w)$.
\end{proposition}
\begin{proof}
    We split the proof to the upper and lower bound, starting with the former.
    Consider $s,r\in S'$ and $k\in \bbN$ such that $s\runsto{w^{2\bigM |S| k}}r$. We show that $\minweight(w^{2\bigM |S| k},s \to r)\le  2\bigM \cost(w)$. Consider the minimal-weight run $\rho:s\runsto{w^{2\bigM |S| k}}r$, i.e., $\weight(\rho)=\minweight(w^{2\bigM |S| k},s \to r)$.

    By the pigeonhole principle there exists $t\in S'$ such that we can write $\rho:s \runsto{w^{2\bigM k_1}} t\runsto{w^{2\bigM  k_2}} t \runsto{w^{2\bigM  k_3}}r$ with $k_1+k_2+k_3=|S|k$ and $k_2>0$. In particular, we have $t\in \RefStates(S',w^{2\bigM k_2})= \RefStates(S',w^{2\bigM})$ (by \cref{prop:reflexive cycles stabilize at N}). 

    Since $(S',w)$ is degenerate, it follows from \cref{def:degenerate stable cycle} that $(s,t)\in \GroundPairs(S',w)$. We claim that this implies $(s,r)\in \GroundPairs(S',w)$. Indeed, take the grounding state of $(s,t)$, i.e., some $t'\in \MinRefStates(S',w^{\bigM})$ such that $s\runsto{w^{\bigM}}t'\runsto{w^{\bigM}}t$, then we can write
    \[s \runsto{w^{\bigM}} t'\runsto{w^{\bigM}}t \runsto{w^{2\bigM  k_3}}r\]
    and therefore $s\runsto{w^{\bigM}}t'\runsto{w^{(2k_3+1)\bigM}}r$. By \cref{prop:grounding states reachable with any bigM k} this implies $(s,r)\in \GroundPairs(S',w)$.
    Now, by \cref{lem:pumping grounded pairs,prop:cost higher than max weight}, we have that 
    \[\minweight(w^{2\bigM |S| k},s\to r)\le \minweight(w^{2\bigM},s\runsto{w^\bigM} t'\runsto{w^\bigM}r)\le 2\bigM\cost(w)\]
    Concluding the upper bound.

    We proceed with the lower bound, which is significantly simpler. Intuitively, in order for the weight to decrease so much, there must be a negative cycle, which cannot happen in a stable cycle. We now formalize this argument.

    Recall that $\bigM\gg |S|$. We prove a stronger claim than the lower bound: for every $m\in \bbN$ we have $\minweight(w^m,s\runsto{m}r)\ge -|S|\cost(w)>-2\bigM \cost(w)$.
    To this end, assume otherwise by way of contradiction, and let $m\in \bbN$ be the minimal number such that $\minweight(w^m,s\to r)<-|S|\cost(w)$. By \cref{prop:cost higher than max weight} it must hold that $m\ge |S|$, since $|\maxeff{w^m}|\le m\cost(w)$.

    Let $\rho$ be a minimal-weight run such that $\rho:s\runsto{w}s_1\runsto{w}s_2\runsto{w}\cdots \runsto{w}s_{m-1}\runsto{w}r$. Denote $s=s_0$ and $r=s_m$. Since $m\ge |S|$, then by the pigeonhole principle there exist $0\le i<j\le m$ such that $s_i=s_j$. Denote $t=s_i=s_j$, then $t\in \RefStates(S',w)$. 
    Now, if $\minweight(w^{j-i},t\to t)\ge 0$, then we can shorten the run $\rho$ while still having value lower than $-|S|\cost(w)$, contradicting the minimality of $m$. However, if $\minweight(w^{j-i},t\to t)< 0$, this contradicts the fact that $(S',w)$ is a  stable cycle (\cref{def:stable cycle}). Thus, we are done.
\end{proof}
A simple corollary of \cref{prop:degenerate cycle has bounded weights} is that enough repetitions of $w$ cause a repeated configuration, as follows.
\begin{proposition}
\label{prop:degenerate cycle has repeating configuration}
    Consider a degenerate stable cycle $(S',w)$. There exist
    $m<n\le (2+4\bigM\cost(w))^{|S|^2}$
    such that for every $t\in S'$ and corresponding configuration $\vec{c_t}$ we have \[\xconf(\vec{c_t},w^{2\bigM |S| m})=\xconf(\vec{c_t},w^{2\bigM |S| n})\]
\end{proposition}
\begin{proof}
    Fix $t\in S'$. 
    By \cref{prop:degenerate cycle has bounded weights}, for every $k\in \bbN$ it holds that 
    \[ 
    \xconf(\vec{c_t},w^{2\bigM |S| k})\in (\{-2\bigM\cost(w),\ldots, 2\bigM\cost(w)\}\cup\{\infty\})^{S}
    \]
    Denote $D=\{-2\bigM\cost(w),\ldots, 2\bigM\cost(w)\}\cup\{\infty\}$, then $|D|=4\bigM\cost(w)+2$. 
    Taking this view on all states simultaneously, we have that for every $k\in \bbN$, the vector 
    $\mathcal{T}_k=(\xconf(\vec{c_t},w^{2\bigM |S| k}))_{t\in S}$ is in $(D^{S})^{S}$.

    Thus, by the pigeonhole principle, there exists $0\le m<n\le (4\bigM\cost(w)+2)^{|S|^2}$ such $\mathcal{T}_m=\mathcal{T}_n$, which proves the claim.
\end{proof}
Naturally, once a configuration repeats in all states, this cycle can be arbitrarily pumped without any effect on the weight, as follows.
\begin{proposition}
\label{prop:stable cycle config repeat}
    Consider a stable cycle $(S',w)$ and $m<n \in \bbN$ such that for every $t \in S'$ it holds that $\xconf(\vec{c_t},w^{2\bigM m})=\xconf(\vec{c_t},w^{2\bigM n})$. Then for every $t,r \in S'$ and every $i \in \bbN$, we have that $\minweight(w^{2\bigM (m+i (n-m))},t \to r)=\minweight(\alpha_{S',w}, t \to r)$.
\end{proposition}
\begin{proof}
    Denote $k=n-m$ and $n_i=ik+m$ for every $i\in \bbN$. In particular, $n_0=m$ and $n_1=n$. By induction it is immediate that  $\xconf(\vec{c_t},w^{2\bigM m})=\xconf(\vec{c_t},w^{2\bigM n_i})$ for every $i\in \bbN$.

    The slightly more involved part of the proof is concluding that for every $t,r\in S'$ it holds that $\minweight(w^{2\bigM (m+i (n-m))},t \to r)=\minweight(\alpha_{S',w}, t \to r)$. 
    Intuitively, this holds because in order for the configurations to repeat, either $r$ is not reachable from $t$ at all, or the weights remain bounded, meaning that $(t,r)$ is a grounded pair. We now formalize this intuition.

    First, if $\minweight(w^{2\bigM (m+i (n-m))},t \to r)=\infty$ for some $i\in \bbN$, then in particular $\minweight(w^{2\bigM},t\to r)=\infty$. Indeed, if there is a finite-weight run from $t$ to $r$ on 
    $w^{2\bigM}$, then there is a reflexive state within this run, which can be pumped to a finite-weight run on $w^{2\bigM (m+i (n-m))}$ (indeed, on any multiple of $w^{2\bigM}$).

    Next, assume $\minweight(w^{2\bigM (m+i (n-m))},t \to r)=c<\infty$, we claim that $(t,r)\in \GroundPairs(S',w)$. Indeed, assume by way of contradiction that $(t,r)\notin \GroundPairs(S',w)$, then by \cref{lem:pumping grounded pairs} there exists $M_0\in \bbN$ such that for every $m'\ge M_0$ it holds that $\minweight(w^{2\bigM m'},t \to r)>c$. Take $m'=m+M_0(n-m)$, then $m'\ge M_0$, so this inequality holds. However, by first part of the proof (the repetition of configurations), we have that 
    \[\xconf(\vec{c_t},w^{2\bigM m})=\xconf(\vec{c_t},w^{2\bigM (m+i (n-m))})=\xconf(\vec{c_t},w^{2\bigM (m+M_0(n-m))})\]
    and therefore
    \[
    c<\minweight(w^{2\bigM m'},t \to r)=\minweight(w^{2\bigM (m+i (n-m))},t \to r)=c
    \]
    which is a contradiction.

    We conclude that $(t,r)\in \GroundPairs(S',w)$, and therefore by \cref{lem:pumping grounded pairs,def:stabilization} we have $\minweight(w^{2\bigM (m+i (n-m))},t \to r)=\minweight(\alpha_{S',w},t\to r)$.
\end{proof}

We conclude this section with its main result, stating that for a degenerate cycle $(S',w)$, we can find $m$ that is not too large, such that the behavior of $w^{2\bigM |S| m}$ is identical to $\alpha_{S',w}$, but $w^{2\bigM |S| m}$ has lower cost than $\alpha_{S',w}$. Intuitively, this means that it is worthwhile  replacing $\alpha_{S',w}$ with $w^{2\bigM |S| m}$. This, in turn, implies that in order to minimize the cost of a word, degenerate cycles can be eliminated.

\begin{lemma}
    \label{lem:degenerate cycles high cost}
    Consider a degenerate stable cycle $(S',w)$. There exists $m<(2+4\bigM\cost(w))^{|S|^2}$ such that $\cost(w^{2\bigM |S| m})<\cost(\alpha_{S',w})$ and for every $t,r\in S'$ it holds that $\minweight(w^{2\bigM |S| m},t \to r)=\minweight(\alpha_{S',w},t \to r)$.
    %\shtodo{Something is slightly weird here -- why did we prove the repeating configuration lemma above, if we're only using it for $m$? (I see why we need it as part of the proof, but do we want it in the formulation of the lemma? possibly, to expand the toolbox).}
\end{lemma}
\begin{proof}
    Combining \cref{prop:degenerate cycle has repeating configuration,prop:stable cycle config repeat} (note that the constant $|S|$ needs to be introduced in \cref{prop:stable cycle config repeat}), there exist $m<(2+4\bigM\cost(w))^{|S|^2}$ such that for every $t,r\in S'$ it holds that $\minweight(w^{2\bigM |S| m},t\to r)=\minweight(\alpha_{S',w},t\to r)$.

    It remains to work out the cost constraint, using \cref{def:cost depth and sub cactus} (\cref{tab:cost depth and sub}).
    \[
    \begin{split}
        &\cost(w^{2\bigM |S| m})=2\bigM |S| m \cost(w) < 2\bigM |S| (2+4\bigM\cost(w))^{|S|^2} \cost(w)\\
        &<_{(\dagger)}2^{16(\bigM |S| \cost(w))^2}=\cost(\alpha_{S',w})
    \end{split}
    \]
    where the inequality $(\dagger)$ is a crude upper bound that can be seen as follows: denote $|S|=s$ and $\cost(w)=c$, then $\bigM s<\bigM^{s^2}$, and we have
    \[
    \begin{split}
        &2\bigM s (2+4\bigM c)^{s^2} c <  2\bigM s c(8\bigM c)^{s^2} < 2^{s^2}\bigM^{s^2} c^{s^2}(8\bigM c)^{s^2} =\\
        &(16 \bigM^2c^2)^{s^2}< 2^{(16 \bigM^2c^2)^{s^2}}=2^{16 (\bigM s c)^2}
    \end{split}
    \]    
\end{proof}


\subsubsection{Existence of Degenerate Cycles in Cactus Chains}
\label{sec:existence of degenerate cycle in chain}
Our goal in this section is to show that a deep-enough cactus chain must contain a degenerate stable cycle. Specifically, ``deep-enough'' is more than $|S|$. We need some definitions and result along the way.

We now define the \emph{Minimal-Reflexive Graph} of a stable cycle $(S',w)$. This directed graph captures the reachability relation between minimal-reflexive states, upon reading $w^{2\bigM}$.

\begin{definition}[$\MinGraph$]
    Consider a stable cycle $(S',w)$. Its \emph{minimal-reflexive graph} is the directed graph
    $\MinGraph(S',w)=\tup{V,E}$ with vertices
    $V=\MinRefStates(S',w^{\bigM})$ and 
    $E=\GroundPairs(S',w) \cap (\MinRefStates(S',w^{\bigM}) \times \MinRefStates(S',w^{\bigM}))$
    %\shtodo{Check if we can make due with $\MinRefStates(S',w^{2\bigM})$}
    %\[\MinGraph(S',w) =  \MinRefStates(S',w^{2\bigM}), \GroundPairs(S',w) \cap (\MinRefStates(S',w) \times \MinRefStates(S',w))\] 
\end{definition}
That is, we have $(s,r)\in E$ if $s,r\in \MinRefStates(S',w^{\bigM})$ and there exists $g\in \MinRefStates(S',w^{\bigM})$ such that $s\runsto{w^M}g\runsto{w^M}r$ (as per \cref{def:grounded pairs}).
%\shtodo{??? Do we want to add a proposition that all the SCCs in the graph are actually cliques? I think it's true.}
We present a simple but useful property of $\MinGraph(S',w)$, namely that it is transitively closed.
\begin{proposition}
    \label{prop:mingraph is transitively closed}
    For every stable cycle $(S',w)$, the graph $\MinGraph(S',w)$ is transitively closed. That is, if $(s,r)\in E$ and $(r,t)\in E$, then $(s,t)\in E$.
\end{proposition}
\begin{proof}
    Assume $(s,r)\in E$ and $(r,t)\in E$. Thus, there exist $g_1,g_2\in \MinRefStates(S',w^{\bigM})$ such that $s\runsto{w^\bigM}g_1\runsto{w^\bigM}r$ and $r\runsto{w^\bigM}g_2\runsto{w^\bigM}t$. In particular, $s\runsto{w^{2\bigM}}r$ and $r\runsto{w^{2\bigM}}t$. 
    Since $V=\MinRefStates(S',w^{\bigM})$, then $s,r\in \MinRefStates(S',w^{\bigM})$. Since the minimal states stabilize at $w^{\bigM}$ (\cref{prop:minimal reflexive cycles stabilize at N}) we also have $s,r\in \MinRefStates(S',w^{2\bigM})$. 
    Thus, we have $(s,r),(r,t)\in \TethPairs(S',w^{2\bigM})$ (see \cref{def:tethered}). 
    Since tethered states also stabilize at $\bigM$ (\cref{prop:tethered states stabilize at N}), we have in particular that $(s,r),(r,t)\in \TethPairs(S',w^{\bigM})$, so $s\runsto{w^{\bigM}}r\runsto{w^\bigM}t$, and since $r\in \MinRefStates(S',w^{\bigM})$, we conclude that $(s,t)\in \GroundPairs(S',w)$, so $(s,t)\in E$.
\end{proof}
We now decompose $\MinGraph$ into (maximal) \emph{Strongly-Connected Components (SCC)}. Recall that an SCC is $C\subseteq V$ such that for every $s,r\in C$ there is a path from $s$ to $r$ and from $r$ to $s$, and that $C$ is maximal with this property (with respect to containment). By \cref{prop:mingraph is transitively closed}, in the case of transitive graphs we can just define an SCC to be a maximal clique (with respect to containment). 
%Denote by $C_1,\ldots, C_m$ the SCCs of $\MinGraph(S',w)$.
%Recall that the SCCs for a directed acyclic graph, and can be topologically sorted. That is, there is a linear ordering $\prec$ on the SCCs, such that if $C_i\prec C_j$ then there are no edges from $C_j$ to $C_i$.

We now turn to the main technical result of this section, relating the number of SCCs of consecutive levels in a cactus chain, where the inner cactus is non-degenerate.
\begin{lemma}[\lightbulbicon SCCs of Nested $\MinGraph$]
\label{lem:nondegenerate mingraph more SCC}
    Consider a stable cycle $(S',w)$ with $w=u\alpha_{B,x}v$. Then the number of SCCs of $\MinGraph(B,x)$ is at least the number of SCCs of $\MinGraph(S',w)$. Moreover, if $(S',w)$ is a non-degenerate stable cycle, then this number is strictly greater. 
\end{lemma}
\begin{proof}
    Denote the SCCs of $\MinGraph(S',w)$ by $C_1,...,C_m$. 
    For each SCC $C_i$ choose a representative $s_i\in C_i$. For every $1\le i\le m$, since $s_i\in \MinRefStates(S',w^{\bigM})$, then in particular there is a minimal reflexive run $s_i\runsto{\alpha_{S',w}}s_i$. By \cref{def:stabilization}, this means that $s_i\runsto{w^{2\bigM}}s_i$. That is, $s_i\runsto{(u\alpha_{B,x}v)^{2\bigM}}s_i$. We split the run as follows:
    \[ s_i\runsto{u}t_i\runsto{\alpha_{B,x}}r_i\runsto{v(u\alpha_{B,x}v)^{2\bigM-1}}s_i
    \]
    Again by \cref{def:stabilization}, we have $(t_i,r_i)\in \GroundPairs(B,x)$, so there exists $g_i\in \MinRefStates(B,x^\bigM)$ such that $t_i\runsto{x^\bigM}g_i\runsto{x^\bigM}r_i$. We associate with each $s_i$ the corresponding state $g_i$. Note that $g_i$ is a vertex in $\MinGraph(B,x)$. 

    We claim that for every $j\neq i$, if there is an edge $(g_j,g_i)$ in $\MinGraph(B,x)$, then there is also an edge $(s_j,s_i)$ in $\MinGraph(S',w)$. Indeed, 
    By the assumption we have that $(g_j,g_i)\in \GroundPairs(B,x)$.
    We therefore have the following:
    \[\begin{split}        &s_j\runsto{u}t_j\runsto{x^\bigM}g_j\runsto{x^\bigM}r_j\runsto{v(u\alpha_{B,x}v)^{2\bigM-1}}s_j\\        &s_i\runsto{u}t_i\runsto{x^\bigM}g_i\runsto{x^\bigM}r_i\runsto{v(u\alpha_{B,x}v)^{2\bigM-1}}s_i\\        
        &g_j\runsto{x^\bigM}h\runsto{x^\bigM}g_i
        \end{split}
    \]
    where $h$ is the grounding state of $(g_j,g_i)$. In particular, we have $g_j\runsto{x^{2\bigM}}g_i$, and therefore $t_j\runsto{x^{\bigM}}g_j\runsto{x^{2\bigM}}g_i$, so $t_j\runsto{x^{3\bigM}}g_i$. 
    Since $g_i\in \MinRefStates(B,x^\bigM)= \MinRefStates(B,x^{3\bigM})$ (by \cref{prop:minimal reflexive cycles stabilize at N}), it follows that $t_j\in \PlatPairs(B,x^{3\bigM})$ (\cref{def:plateau}). By the stabilization of Plateau  pairs (\cref{prop:plateau states stabilize at N}) we have that $t_j\runsto{x^{\bigM}}g_i$.
    But then we can compose the run 
    \[ s_j\runsto{u}t_j\runsto{x^\bigM}g_i\runsto{x^\bigM}r_i\runsto{v(u\alpha_{B,x}v)^{2\bigM-1}}s_i
    \]
    So $s_j\runsto{w^{2\bigM}}s_i$. 
    Again by the stabilization of plateau pairs (\cref{prop:plateau states stabilize at N}) we have that $s_i\in \PlatPairs(S',w^{2\bigM})$ and therefore $s_j\runsto{w^\bigM}s_i$. But $s_i\in  \MinRefStates(S',w^\bigM)$, and it can serve as a grounding state. We therefore have $s_j\runsto{w^\bigM}s_i\runsto{w^\bigM}s_i$, so $(s_j,s_i)\in \GroundPairs(S',w)$, and is therefore an edge in $\MinGraph(S',w)$.
    We can now prove the desired properties.

    \paragraph{All the $g_i$ are in different SCCs of $\MinGraph(B,x)$}
    Assume by way of contradiction that there are $i\neq j$ such that $g_i$ and $g_j$ are in the same SCC $D$ of $\MinGraph(B,x)$.
    By \cref{prop:mingraph is transitively closed} we have that $(g_j,g_i)$ and $(g_i,g_j)$ are edges in $\MinGraph(B,x)$, and by the above we get that $(s_j,s_i)$ and $(s_i,s_j)$ are edges in $\MinGraph(S',w)$, which contradicts the fact that $s_j,s_i$ are in difference SCCs.

    We conclude that each $g_i$ lies in a separate SCC, so the number of SCCs in $\MinGraph(B,x)$ is at least that of $\MinGraph(S',w)$.




    \paragraph{If $(S',w)$ is non-degenerate, there is some $g'\in \MinRefStates(B,x^\bigM)$ that is not in any of the SCCs of the $g_i$.}
    We now proceed to the case where $(S',w)$ is non-degenerate, and we exhibit at least one additional SCC in $\MinGraph(B,x)$. 

    Since $(S',w)$ is non-degenerate (\cref{def:degenerate stable cycle}), it has a non-degenerate state $s'\in S'$. That is, there is some (non-minimal) reflexive state $r\in \RefStates(S',w^{2\bigM})$ with $s'\runsto{w^{2\bigM k}}r$ for some $k\in \bbN$, such that $(s',r)\notin \GroundPairs(S',w)$. Similarly to the previous case, we expand the run above as
    \[
    s'\runsto{u}t'\runsto{\alpha_{B,x}}r'\runsto{vw^{2\bigM k-1}}r
    \]
    By \cref{def:stabilization} we have $(t',r')\in \GroundPairs(B,x)$, so there exists a state $g'\in \MinRefStates(B,x^\bigM)$ such that
    $t'\runsto{x^{\bigM}}g'\runsto{x^{\bigM}}r'$.
    We therefore have
    \[ s'\runsto{u}t'\runsto{x^{\bigM}}g'\runsto{x^{\bigM}}r'\runsto{vw^{2\bigM k-1}}r
    \]
    We claim that $g'$ is not in any SCC of $g_i$ for $1\le i\le m$. Assume otherwise by way of contradiction, then by \cref{prop:mingraph is transitively closed} there exists some $g_i$ such that $(g',g_i)$ and $(g_i,g')$ are edges in $\MinGraph(B,x)$. Thus, $(g_i,g'), (g',g_i)\in \GroundPairs(B,x)$, and in particular $g_i\runsto{x^{2\bigM}}g'$ and $g'\runsto{x^{2\bigM}}g_i$. We now have the following runs:
    \[
    \begin{split} &s'\runsto{u}t'\runsto{x^{\bigM}}g'\runsto{x^{\bigM}}r'\runsto{vw^{2\bigM k-1}}r\\ &s_i\runsto{u}t_i\runsto{x^{\bigM}}g_i\runsto{x^{\bigM}}r_i\runsto{vw^{2\bigM k-1}}s_i\\
    &g_i\runsto{x^{2\bigM}}g'\\
    &g'\runsto{x^{2\bigM}}g_i
    \end{split}
    \]
    We can therefore obtain the runs:
    \[
      \begin{split} &s'\runsto{u}t'\runsto{x^{\bigM}}g'\runsto{x^{2\bigM}}g_i\runsto{x^{\bigM}}r_i\runsto{vw^{2\bigM k-1}}s_i\\ &s_i\runsto{u}t_i\runsto{x^{\bigM}}g_i\runsto{x^{2\bigM}}g'\runsto{x^{\bigM}}r'\runsto{vw^{2\bigM k-1}}r\\
    \end{split}
    \]
    That is, $s'\runsto{w^{2\bigM}}s_i\runsto{w^{2\bigM}}r$. Since $s_i\in \MinRefStates(S',w^\bigM)$, then by \cref{prop:grounding states reachable with any bigM k} we have $(s',r)\in \GroundPairs(S',w)$, in contradiction to the non-degeneracy assumption.

    We conclude that $g'$ is not in any of the SCCs of the $g_i$, and therefore $\MinGraph(B,x)$ has strictly more SCCs than $\MinGraph(S',w)$.
\end{proof}

Since $\MinGraph(S',w)$ can have at most $|S|$ SCCs, an immediate corollary of \cref{lem:nondegenerate mingraph more SCC} is that a cactus chain of depth more than $|S|$ must have a degenerate cycle.
\begin{corollary}
    \label{cor:deep cactus chain has degenerate cycle}
    Consider a cactus chain $\alpha_{S'_1,w_1},\ldots,\alpha_{S'_n,w_n}$. If $n>|S|$ then there exists $1\le i\le n$ such that $\alpha_{S'_i,w_i}$ is a degenerate stable cycle.
\end{corollary}
Finally, by \cref{lem:degenerate cycles high cost}, if a cactus chain $\alpha_{S'_1,w_1},\ldots,\alpha_{S'_n,w_n}$ contains a degenerate stable cycle $\alpha_{S'_i,w_i}$, then we can replace this degenerate stable cycle by $w^{2\bigM |S| m}$ for some $m$ while maintaining equivalent transitions, but lowering the cost. Thus, minimal-cost cactus chains do not contain degenerate cycles. In particular, by \cref{cor:deep cactus chain has degenerate cycle}, their depth is bounded by $|S|$. We conclude this section with this important result.
\begin{corollary}[\keyicon Minimal-Cost Cactus Chains are Not Deep]
    \label{cor:minimal cost cactus chain has bounded depth}
    Consider a cactus chain $\alpha_{S'_1,w_1},\ldots,\alpha_{S'_n,w_n}$ of minimal cost, i.e., \[\cost(\alpha_{S'_1,w_1})=\min\{\cost(\gamma)\in \Gamma_\infty^0\mid \forall s,r\in S, \minweight(\alpha_{S'_1,w_1},s\to r)=\minweight(\gamma,s\to r)\}\]
    Then $n\le |S|$. In particular, $\depth(\alpha_{S'_1,w_1})\le |S|$.
\end{corollary}



\subsection{Baseline Shift}
\label{sec: baseline shift}
In \cref{sec:shift POV} we establish the correspondence between the runs of $\augA$ and of $\cA$. In particular, this shows that regardless of the choice of baseline run, the run structure of $\augA$ (i.e., the differences between runs) is fixed.

In this section, we show a similar result in the presence of cactus and rebase letters. Since these letters are not present in $\cA$, we show this directly on $\augA_\infty^\infty$. More precisely, we show that for every word $w\in \augTrans_\infty^\infty$ (without jump letters), and for every run $\rho_0$ on $w$, we can construct a new word $w'$ with the same ``inner letters'' as $w$, and establish a bijection between runs on $w$ and runs on $w'$, such that differences are maintained and such that the run corresponding to $\rho_0$ is the baseline run (and therefore has weight $0$ throughout).

The intuition behind the construction is simple: given the run $\rho_0$, we only need to change the letters of $w$ so that their  baseline component follows the state component dictated by $\rho_0$. Then, $\rho_0$ (or rather, the corresponding run that uses the same state components) becomes a baseline run, and all other runs shift their weights accordingly. In order to change the letters in this manner, cactus letters may become rebase letters (and some rebase letters become cactus letters).

The formal construction mainly tests the limits of the English and Greek alphabets, as well as the reader's patience, but is otherwise simple, as follows.

Consider a word $w=\tau_1\cdots\tau_k$ where for every $1\le i\le k$ we have that 
\[\tau_i\in \{(p_{i-1},\sigma_i,c_i,p_i),\alpha_{S'_i,w_i},\beta_{S'_i,w_i,s_i\to r_i}\}\]
i.e., each letter is either in $\augTrans$, a cactus, or a rebase.
Let $\rho_0=t_1,\ldots,t_k$ be a run of $\augA_{\infty}^\infty$ on $w$, and denote 
$t_i=((q_{i-1},p_{i-1},T_{i-1}),\tau_i,d_i,(q_i,p_i,T_i))$ (where the $d_i$ are the weights).

We define the word $w'=\gamma_1\cdots \gamma_k$, where we split the definition of $\gamma_i$ to cases according to whether $\tau_i$ is a standard letter or a cactus/rebase.
\begin{itemize}
    \item If $\tau_i=(p_{i-1},\sigma_i,c_i,p_i)$, then $d_i=c'_i-c_i$ where $c'_i$ is the weight of the transition $(q_{i-1},\sigma_i,c'_i,q_i)\in \augTrans$ (by \cref{sec:augmented construction}).
    In this case, we define $\gamma_i=(q_{i-1},\sigma_i,c'_i,q_i)$.
    \item If $\tau_i=\alpha_{S'_i,w_i}$ or $\tau_i=\beta_{S'_i,w_i,r_i\to s_i}$, denote $S'_i=\{(q,p,T)\mid q\in T\}$ for some $p,T$. We define $\gamma_i=\beta_{S'_i,w'_i,(q_{i-1},p,T)\to (q_i,p,T)}$. In case $q_{i-1}=q_i=p$, then we identify $\gamma_i=\alpha_{S'_i,w_i}$ as per \cref{rmk:cactus as rebase}.

    In order to show that $\gamma_i$ is a well-defined rebase letter, we need to show that $((q_{i-1},p,T),(q_i,p,T))\in \GroundPairs(S'_i,w'_i)$. 
    Again by \cref{rmk:cactus as rebase} we can uniformly consider $\tau_i$ as $\tau_i=\beta_{S'_i,w_i,r_i\to s_i}$ (identifying $\alpha_{S'_i,w_i}$ with a rebase letter on the baseline state). Denote $r_i=(q',p,T)$ and $s_i=(q'',p,T)$. 

    Since $t_i=((q_{i-1},p_{i-1},T_{i-1}),\tau_i,d_i,(q_i,p_i,T_i))$ then by \cref{def:rebase} we have $p_{i-1}=q'$ and $p_i=q''$, as well as $T_{i-1}=T_i=T$. So we can write 
    $t_i=((q_{i-1},q',T),\tau_i,d_i,(q_i,q'',T))$. Still by \cref{def:rebase} (and since $d_i<\infty$) we have $((q_{i-1},p,T),\alpha_{S'_i,w_i},e_i,(q_i,p,T))$ for some $e_i$, and in particular $((q_{i-1},p,T),(q_i,p,T))\in \GroundPairs(S'_i,w'_i)$, otherwise there would not be a transition as per \cref{def:stabilization}.
\end{itemize}
%
Having defined $w'$, it now remains to show a bijection between runs on $w$ and on $w'$.
\begin{proposition}
    \label{prop:baseline shift run bijection}
    In the notations above, for every sequence of states $f_1,\ldots,f_k\in Q$ (states of $\cA$), the following are equivalent.
    \begin{itemize}
        \item $\eta=x_1,\ldots,x_k$ with $x_i=((f_{i-1},p_{i-1},T_{i-1}),\tau_i,a_i,(f_i,p_i,T_i))$ is a run of $\augA_\infty^\infty$ on $w$.
        \item $\mu=y_1,\ldots,y_k$ with $y_i=((f_{i-1},q_{i-1},T_{i-1}),\gamma_i,a_i-d_i,(f_i,q_i,T_i))$ is a run of $\augA_\infty^\infty$ on $w'$ (recall that $d_i$ are the weights in $\rho_0$).
    \end{itemize}
\end{proposition}
\begin{proof}
    Consider a sequence of states $f_1,\ldots,f_k\in Q$, and $\eta$ and $\mu$ as in the statement. We show that the transitions $x_i$ have finite weight if and only if the transition $y_i$ have finite weight, thus concluding the claim.
    %We have that %$\eta=x_1,\ldots,x_k$ with $x_i=((f_{i-1},p_{i-1},T_{i-1}),\gamma_i,a_i,(f_i,p_i,T_i))$ if and only if 
    For every $1\le i\le k$ the following hold:
    \begin{itemize}
        \item If $\tau_i=(p_{i-1},\sigma_i,c_i,p_i)$, then the transition $x_i$ is in $\augTrans_\infty^\infty$ if and only if 
        $a_i=c''_i-c_i$ where $c''_i$ is the weight of the transition $(f_{i-1},\sigma_i,c''_i,f_i)\in \augTrans$.  Since $\gamma_i=(q_{i-1},\sigma_i,c'_i,q_i)$ (and in particular has the same letter $\sigma_i$), this happens if and only if  
        \[((f_{i-1},q_{i-1},T_{i-1}),\gamma_i,c''_i-c'_i,(f_i,q_i,T_i))\in \augTrans_{\infty}^\infty\] 
        Recall that by construction we have $d_i=c'_i-c_i$, and therefore 
        \[c''_i-c'_i=c''_i-c_i+c_i-c'_i=c''_i-c_i-(c'_i-c_i)=a_i-d_i\]
        and so the transition above is $y_i$.

        \item If $\tau_i=\beta_{S'_i,w_i,r_i\to s_i}$ (we again use \cref{rmk:cactus as rebase} to consider cactus and rebase jointly), denote $S'_i=\{(q,p,T)\mid q\in T\}$ and $r_i=(q',p,T)$ and $s_i=(q'',p,T)$. Since $(r_i,s_i)\in \GroundPairs(S'_i,w_i)$, we have $(r_i,\alpha_{S'_i,w_i},b'_i,s_i)\in \Delta_\infty^\infty$ for some $b'_i<\infty$. 
        As in the construction of $w'$, by \cref{def:rebase} 
        we have that $x_i\in \augTrans_\infty^\infty$ if and only if 
        $p_{i-1}=q'$, $p_i=q''$ and $T_{i-1}=T_i=T$, and $a_i=b_i-b'_i$ where $b_i$ is such that $((f_{i-1},p,T),\alpha_{S'_i,w_i},b_i,(f_i,p,T))\in \augTrans_\infty^\infty$ (and in particular these states are a grounded pair).

        As we show in the construction of $w'$, we have $((q_{i-1},p,T),\alpha_{S'_i,w_i},e_i,(q_i,p,T))$ for some $e_i$.
        By \cref{def:rebase}, the above holds if and only if 
        \[((f_{i-1},q_{i-1},T_{i-1}),\beta_{S'_i,w'_i,(q_{i-1},p,T)\to (q_i,p,T)},b_i-e_i,(f_i,q_i,T_i))\in \augTrans_\infty^\infty\]
        Note that $d_i=e_i-b'_i$, and therefore $a_i-d_i=b_i-b'_i-(e_i-b'_i)=b_i-e_i$.
        Therefore, this transition is exactly $y_i$.
    \end{itemize}
\end{proof}
We wrap up this section by introducing the baseline-shift operator, and providing a concise formalism for using it.
For a word $w$ and $\rho_0$ as above, we denote the constructed word $w'$ by 
$\baseshift{w}{\rho_0}$.
We overload this notation to runs: for a run $\eta=x_1,\ldots,x_k$ with $x_i=((f_{i-1},p_{i-1},T_{i-1}),\gamma_i,a_i,(f_i,p_i,T_i))$ we denote by $\baseshift{\eta}{\rho_0}$ the run $\mu=y_1,\ldots,y_k$ with $y_i=((f_{i-1},q_{i-1},T_{i-1}),\gamma_i,a_i-d_i,(f_i,q_i,T_i))$. Note that a run already encapsulates the information about the word, and therefore we do not need to specify $w$ in the latter notation.

\cref{prop:baseline shift run bijection} readily implies our two main results of this section, namely that the baseline shift of $\rho_0$ by itself is a seamless run, and that baseline shifts maintain the gaps between runs.
\begin{corollary}
    \label{cor:baseline shift to seamless run}
    Consider a word $w$ and a run $\rho_0$ on $w$, then $\baseshift{\rho_0}{\rho_0}$ is a seamless run (and in particular gains $0$ weight in every transition).
\end{corollary}
\begin{corollary}
    \label{cor:baseline shift maintains gaps}
    Consider a word $w$ and a run $\rho_0$ on $w$. Let $\rho_1,\rho_2$ be runs on $w$, and consider the shifted runs $\mu_1=\baseshift{\rho_1}{\rho_0}$ and $\mu_2=\baseshift{\rho_2}{\rho_0}$ then for every $0\le i\le |w|$ it holds that $\weight(\rho_1[1,i])-\weight(\rho_2[1,i])=\weight(\mu_1[1,i])-\weight(\mu_2[1,i])$.
\end{corollary}



\subsection{Cactus Flattening}
\label{sec: cactus unfolding}
Intuitively, cactus (and rebase) letters encapsulate many repetitions of the same word, where rebase also allows a change in the baseline. Naturally, we wish to consider the corresponding words that are obtained by repeatedly ``unfolding'' cactus and rebase letters, in a process we refer to as \emph{flattening}. 
We make extensive use of flattening throughout the paper.
%We describe here what we mean by flattening, and we use this notion in \cref{apx:aug inf inf is det iff aug A is det}\shtodo{add where (equiv of $\augA_\infty^\infty$) and other places.}

Recall that for a word $u$ the value $\maxeff{u}$ is an upper-bound on the absolute value of the change in weight that a run can incur upon reading $u$.

\begin{definition}[\keyicon Cactus-Unfolding]
    \label{def:unfolding function}
    Consider a cactus letter $\alpha_{S',w}$, a word $u=x \cdot \alpha_{S',w} \cdot y$ and $F\in \bbN$.

    By \cref{lem:pumping grounded pairs} there exists $M_0\in \bbN$ such that for every $k\ge M_0$ and every $s,r\in S'$ with $(s,r)\notin\GroundPairs(S',w)$ it holds that $\minweight(w^{k\cdot 2\bigM},s\to r)>F$.

    The \emph{Unfolding of $u$ with constant $F$} is then $\unfold(x,\alpha_{S',w},y \wr F)=xw^{2\bigM M_0}y$, and any word $xw^{2\bigM m}y$ with $m\ge M_0$ is \emph{an unfolding of $u$ with constant $F$.}
\end{definition}
%\shtodo{Fix un-parameterized places}
\begin{remark}[``The'' v.s. ``an'' unfolding]
\label{rmk:increasing repetitions in unfolding}
We remark that the distinction between ``the'' unfolding and ``an'' unfolding merely means that we can add repetitions of $w$ (in multiples of $2\bigM$), and still be referred to as an unfolding.

In the following, we mostly refer to $M_0$ as the number of repetitions, but we sometimes need to increase this number, in which case we remark that all the results still hold.
\end{remark}

% We illustrate the unfolding process of the cactus in \cref{fig:cactus} in \cref{fig:unfolding example}.
% \begin{figure}
%     \centering
%     \includegraphics[width=0.9\linewidth]{fig/flattening.pdf}
%     \caption{Illustration of flattening the cactus in \cref{fig:cactus}. The dotted line represents many more iterations.}
%     \label{fig:unfolding example}
% \end{figure}

Intuitively, while $\alpha_{S',w}$ makes transitions $s\runsto{\alpha_{S',w}}r$ attain value $\infty$ if $(s,r)\notin \GroundPairs(S',w)$, the unfolding repeats $w$ enough times such that these runs may exist, but attain a value as high as we like (namely $F$). 
We always choose $F$ large enough such that any continuation of such runs is irrelevant for the value of the word. Therefore, the values of runs after unfolding are the same as those before unfolding. We capture this as follows.

%\shtodo{GLOBAL: Notation for infixes of runs - make uniform across paper.}
\begin{proposition}
    \label{prop:unfolding cactus maintains seamlesss gaps}
    Consider a cactus letter $\alpha_{S',w}$, a word $x \cdot \alpha_{S',w} \cdot y$ and $F> 2\maxeff{x \cdot \alpha_{S',w} \cdot y}$.

    Let $\rho$ be a seamless run on $x \cdot \alpha_{S',w} \cdot y$, then there exists a \emph{seamless} run $\mu$ on $\unfold(x,\alpha_{S',w},y \wr F)=xw^{2\bigM M_0}y$ such that 
    $\mu[1,|x|]=\rho[1,|x|]$, and for every $i\ge 0$, if $z=x\cdot\alpha_{S',w}\cdot y[1,i]$ is a prefix of $x \cdot \alpha_{S',w} \cdot y$ and the corresponding prefix of $\unfold(x,\alpha_{S',w},y \wr F)$ is $z'=x\cdot w^{2\bigM M_0}\cdot  y[1,i]$, then it holds that 
    $\weight(\rho(z))=\weight(\mu(z'))$.
\end{proposition}
\begin{proof}
    Let $u=x \cdot \alpha_{S',w} \cdot y$ and $v=\unfold(x,\alpha_{S',w},y \wr F)=xw^{2\bigM M_0}y$, and let $\rho$ be a seamless run on $u$.
    Denote $\rho:s_0\runsto{x}s\runsto{\alpha_{S',w}}r\runsto{y}q$

    Since $s\runsto{\alpha_{S',w}}r$ then by the definition of transitions on cactus letters (\cref{def:stabilization}) we have that $(s,r)\in \GroundPairs(S',w)$. Let $g$ be the corresponding grounding state, i.e., $g\in \MinRefStates(S',w^\bigM)$
    and $s\runsto{w^\bigM}g\runsto{w^\bigM}r$. 
    In particular, $\minweight(g\runsto{w^\bigM}g)=0$. Take $\eta:s\runsto{w^\bigM}g$ and $\xi:g\runsto{w^\bigM}r$ to be runs of minimal weights (from/to their respective states), and $\zeta: g\runsto{w^\bigM}g$ with weight $0$.
    We construct $\mu$ as the following concatenation of runs:
    \[
    \mu:\rho(x)\eta\zeta^{(2M_0-2)}\xi\rho(y)
    \]
    and therefore
    \[
    \mu:s_0\runsto{x}s\runsto{w^\bigM}g\runsto{w^{(2M_0-2)\bigM}}g\runsto{w^\bigM}r\runsto{y}q
    \]
    First, note that $\mu$ and $\rho$ are identical on their $x$ prefix. That is,  
    $\mu[1,|x|]=\rho[1,|x|]$, as required.

    Next, let $i\ge 0$ and denote $z=x\cdot\alpha_{S',w}\cdot y[1,i]$ and $z'=x\cdot w^{2\bigM M_0}\cdot  y[1,i]$.
    Recall (from \cref{def:stabilization}) that $\weight(s\runsto{\alpha_{S',w}}r)=\minweight(s\runsto{w^\bigM}g\runsto{w^\bigM} r)$. Since $\zeta: g\runsto{w^\bigM}g$ has weight $0$, and $\xi$ and $\eta$ are of minimal weight, it follows that $\weight(s\runsto{\alpha_{S',w}}r)=\weight(\eta\zeta^{(2M_0-2)}\xi)$. Thus, upon reaching $r$, both $\rho$ and $\mu$ have the same weight.

    Since the suffix read from $r$ in both $z$ and $z'$ is $y[1,i]$ and the runs are identical at this suffix (namely $\rho(y)$), it follows that     
    $\weight(\rho(z))=\weight(\mu(z'))$.

    Finally, it is left to prove that $\mu$ is seamless (and recall that $\rho$ is seamless). 
    Assume by way of contradiction that $\mu$ is not seamless, and let $\mu'$ be a run on some prefix $u$ of $\unfold(x,\alpha_{S',w},y \wr F)$ such that both $\mu(u):s_0\runsto{u} s_1$ and $\mu'(u):s_0\runsto{u}s_1$ but 
    $\weight(\mu'(u))<\weight(\mu(u))$.
    That is, $\mu'$ arrives at $s_1$ with smaller weight than $\mu$, thus ``breaking'' $\mu$.
    We can assume without loss of generality that $\mu$ and $\mu'$ are identical from $s_1$ (i.e., after reading $u$). Indeed, by concatenating the suffix of $\mu$ to the prefix $\mu'(u)$, the obtained run remains strictly below $\mu$ from $s_1$ and on, and also ``breaks'' $\mu$ at $s_1$. %In particular, since we do not assume that $s_1$ is the first state where $\mu'$ breaks $\mu$, 
    We can further assume that $s_1$ is the last state in both runs, i.e., $q$. In particular $\weight(\mu')<\weight(\mu)$.

    Denote by $p_1,p_2$ the states visited by $\mu'$ after reading $x$  and $xw^{2M_0\bigM}$ respectively (we implicitly think of $p_1$ and $p_2$ as states at specific indices, to avoid cumbersome notations). See~\cref{fig:unfolding}.

