    %     &S_1=\ghostTrans(s_0,u)\quad S_2=\booltrans(s_0,u\alpha_{B,x})\quad S'_2=\booltrans(s_0,ux^{2\bigM M_0})
    % \end{split}
    % \]
    \[
\begin{array}{ l l l }
\vec{c_1} = \xconf(\vec{c_{s_0}}, u) & \vec{c_2} = \xconf(\vec{c_{s_0}}, u\alpha_{B,x}) & \vec{c'_2} = \xconf(\vec{c_{s_0}}, ux^{2\bigM M_0}) \\ 
S_1 = \ghostTrans(s_0, u) & S_2 = \booltrans(s_0, u\alpha_{B,x}) & S'_2 = \booltrans(s_0, ux^{2\bigM M_0}) \\ 
\end{array}
\]
    Note that $S_2=\supp(\vec{c_2})$ and $S'_2=\supp(\vec{c'_2})$. 
    By \cref{lem:unfolding configuration characterization} we have that 
    $S_2\subseteq S'_2$, for every $s\in S_2$ it holds that $\vec{c'_2}(s)=\vec{c_2}(s)$ and 
    for every $s'\notin S_2$ it holds that $\vec{c'_2}(s')> \vec{c_2}(s)$ (where $s'\notin S_2$ means either $s'\in  S'_2\setminus S_2$, or $s'\notin S'_2$).

    Consider a maximal-dominant state $q\in S$ in $\vec{c'_2}$. 
    By \cref{def:dominant state}, this means that there exists $z\in \Gamma^\infty_\infty$ such that 
    $\minweight(z,q\to S)<\infty$ 
    whereas for every $p\in S$ with $\vec{c'_2}(p)<\vec{c'_2}(q)$ we have 
    %$\minweight_{\vec{c'_2}}(z,p\to S)=\infty$. 
    $\minweight(z,p\to S)=\infty$. We now split to cases according to whether $q\in S'_2\setminus S_2$ (i.e., $q$ is ``very high'') or $q\in S_2$ (i.e., $q$ is ``low'').

    \paragraph*{Dominant State is Very High}
    If $q\in S'_2\setminus S_2$, we claim that $(u x^{2\bigM M_0},x^{2\bigM M_0},z)$ is a type-0 witness. 
    Indeed, following the requirements in \cref{def:witness}, we have:
    \begin{enumerate}
        \item $ux^{2\bigM M_0},x^{2\bigM M_0}\in \Gamma_\infty^0$ and $z\in \Gamma^\infty_\infty$.
        \item Since $\alpha_{B,x}$ is a cactus letter then by \cref{prop:cactus letters stabilizes at 2M} we have that $\alpha_{B,x^{2 \bigM M_0}}$ is a cactus letter with the same transitions. Also, $B=\ghostTrans(s_0,u)=\ghostTrans(s_0,ux)=\ghostTrans(s_0,ux^{2\bigM M_0})$, since $(B,x)$ is a stable cycle.
        \item By \cref{prop: transitions stabilize at M} we have that  $\booltrans(s_0,u x^{2\bigM M_0})=\booltrans(s_0,u x^{4\bigM M_0})=\booltrans(s_0,u x^{2\bigM M_0}x^{2\bigM M_0})$.
        \item Since $q\in S'_2=\booltrans(s_0,u x^{2\bigM M_0})$ then by Item 3 above we have $q\in \booltrans(s_0,u x^{2\bigM M_0}x^{2\bigM M_0})$. In particular, $\minweight(u x^{2\bigM M_0}x^{2\bigM M_0},s_0\to q)<\infty$. Since $z$ satisfies that $\minweight(z,q\to S)<\infty$, we conclude that:
        \[
        \minweight(u x^{2\bigM M_0}\cdot x^{2\bigM M_0}\cdot z,s_0\to S)\le\minweight(u x^{2\bigM M_0}x^{2\bigM M_0},s_0\to q)+\minweight(z,q\to S)<\infty
        \]

        It therefore remains to prove that $\minweight(u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}}\cdot z,s_0\to S)=\infty$. 
        To this end, we claim that for every state $p$, if $\minweight(u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}},s_0\to p)<\infty$, then $\vec{c'_2}(p)<\vec{c'_2}(q)$ (from which we can obtain the desired result).
        Indeed, if $\minweight(u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}},s_0\to p)<\infty$ then %there exists $p'\in \booltrans(s_0,u x^{2\bigM M_0})$ such that $\minweight(\alpha_{B,x^{2\bigM M_0}},p'\to p)<\infty$.
        there exists a run 
        \[
        \rho:s_0\runsto{u}s_1\runsto{x^{2\bigM M_0}}p'\runsto{\alpha_{B,x^{2\bigM M_0}}}p
        \]
        By \cref{def:stabilization}, this implies that $(p',p)\in \GroundPairs(\alpha_{B,x^{2\bigM M_0}})$. Then, however, it follows by \cref{prop:grounding states reachable with any bigM k} that $(s_1,p)\in \GroundPairs(B,x^{2\bigM M_0})$ (by using the same grounding state of $(p',p)$). 
        Recall that by \cref{prop:cactus letters stabilizes at 2M}, the letters $\alpha_{B,x^{2\bigM M_0}}$ and $\alpha_{B,x}$ have the exact same transitions. That is, $(s_1,p)\in \GroundPairs(B,x)$. 
        Thus, we have the run
        $s_0\runsto{u}s_1\runsto{\alpha_{B,x}}p$
        so $p\in S_2$. 
        As noted above, all the states in $S_2$ the configurations $\vec{c_2}$ and $\vec{c'_2}$ coincide, so $\vec{c_2}(p)=\vec{c'_2}(p)$. On the other hand, $q\in S'_2\setminus S_2$, and again as noted above this means that $\vec{c'_2}(q)>\vec{c_2}(p)=\vec{c'_2}(p)$.

        We are therefore in the following setting:
        \begin{itemize}
            \item If $\minweight(u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}},s_0\to p)<\infty$, then $\vec{c'_2}(p)<\vec{c'_2}(q)$, but then $\minweight(z,p\to S)=\infty$, so 
            \[\minweight(u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}}\cdot z,s_0\runsto{u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}}}p\runsto{z}S)=\infty\]
            \item If $\minweight(u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}},s_0\to p)=\infty$ then trivially 
            \[\minweight(u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}}\cdot z,s_0\runsto{u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}}}p\runsto{z}S)=\infty\]
        \end{itemize}
        We conclude that anyway we have
        $\minweight(u x^{2\bigM M_0}\cdot \alpha_{B,x^{2\bigM M_0}}\cdot z,s_0\to S)=\infty$
    \end{enumerate}
    This shows that all the requirements of \cref{def:witness} hold, so there is a type-0 witness.

    \paragraph*{Dominant State is Low}
    If $q\notin S'_2\setminus S_2$, then $q\in S_2$ (since $q\in \supp(\vec{c'_2})=S'_2$). Then, by the observations above, we have $\vec{c'_2}(q)=\vec{c_2}(q)$. We claim that for every prefix $v'$ of $v$ it holds that $\pot(ux^{2\bigM M_0}v')=\pot(u\alpha_{B,c}v')$. 
%
    Indeed, fix such a prefix $v'$ and denote
    \[
    \begin{split}
        &\vec{c_3}=\xconf(s_0,u\alpha_{B,x} v')=\xconf(c_2,v') \quad S_3=\supp(\vec{c_3})\\
        &\vec{c'_3}=\xconf(s_0,u x^{2\bigM M_0} v')=\xconf(c'_2,v') \quad S'_3=\supp(\vec{c_3})
    \end{split}
    \]
    Similarly to the above, we have $S_3\subseteq S'_3$, and due to the choice of $F$ as the unfolding constant (\cref{def:unfolding function,lem:unfolding configuration characterization}) for every $p\in S_3$ it holds that $\vec{c_3}(p)=\vec{c'_3}(p)$, and for every $p\in S'_3\setminus S_3$ we have $\vec{c'_3}(p)>\max\{\vec{c_3}(r)\mid r\in S_3\}+\maxeff{u\alpha_{B,c}v}$.

    Let $p,p'$ be maximal dominant states in $\vec{c_3}$ and $\vec{c'_3}$, respectively. We claim that $p,p'\in S_3$. Indeed, $p\in S_3$ by definition. If $p'\in S'_3\setminus S_3$, then there exists a suffix $z$ such that $\minweight(z,p'\to S)<\infty$ and for every $r'$ with $\vec{c'_3}(r')<\vec{c'_3}(p')$ it holds that $\minweight(z,r'\to S)=\infty$. In particular, for every $r'\in S_3$ this holds. 
    Since $p'\in S'_3\setminus S_3$, then $p'\in \booltrans(S'_2,v')\setminus \booltrans(S_2,v')$. But then $v'z$ is a suffix that exhibits a dominant state in $S'_2\setminus S_2$, and in particular the maximal dominant state of $\vec{c'_2}$ is in $S'_2\setminus S_2$, so we are back in the previous case of a very high dominant state (which we assume does not hold now).

    Thus, $p'\in S_3$. It now readily follows that $\pot(ux^{2\bigM M_0}v')=\pot(u\alpha_{B,c}v')$: restricted to $S_3$, the configurations $\vec{c_3}$ and $\vec{c'_3}$ are equivalent. Moreover, for every $r'\in S'_3\setminus S_3$ we have $\vec{c'_3}(r')>\vec{c'_3}(p')$, so does not come into consideration for the dominance of $p'$. 

    It thus follows that $\vec{c'_3}(p')=\vec{c_3}(p)$ (in fact, we can assume without loss of generality that $p=p'$, since we can choose any maximal-dominant state, if there are several), and since the baseline run is reachable and its state is also in $S_3$, we conclude that
    \[
    \pot(ux^{2\bigM M_0}v')=\vec{c'_3}(p')=\vec{c_3}(p)=\pot(u\alpha_{B,c}v').
    \]
\end{proof}


\begin{remark}[The Prefix ``Either $\augA_\infty^\infty$ has a type-0 witness, or...'']
\label{rmk:the either witness prefix}
    Most of our reasoning about potential in the coming sections is based on \cref{lem:unfolding maintains potential}. 
    Therefore, the prefix ``Either $\augA_\infty^\infty$ has a type-0 witness, or the following holds'' appears in many other arguments. Since having such a witness immediately implies nondeterminziability (by \cref{lem:witness implies nondet}), this condition can be read as ``either we are done, or the following holds''.
\end{remark}


\section{A Ramsey Theorem for Colored Infixes}
\label{sec:ramsey}
In this section we present a general Ramsey-type theorem, concerning finite coloring of an infinite set of words. Specifically, we assume that we have an infinite set of words such that all the infixes of each word are colored. 
We show that we can find arbitrarily-long words with arbitrarily-many indices such that all infixes between these indices are identically colored. 

These results are then used to reason about the types of runs between configurations in \cref{sec:existence of inc inf assuming covered}.

For $n\in \bbNinf$ denote $\interval_n=\{(i,j)\mid 1\le i\le j\le n\wedge  i,j\in \bbN\}$ denote the set of finite \emph{intervals} of $\{1,\ldots, n\}$ (think of $(i,j)$ as denoting the set $\{i,i+1,\ldots, j\}$). Note that for $n=\infty$, the set $\interval_\infty$ has all finite intervals. 
Fix a finite set $\colset$ of \emph{colors}. 
An \emph{interval coloring} is a function $\lambda:\interval_n\to \colset$ that assigns a color to each interval.

Fix a finite alphabet $\Sigma$. An \emph{infix-colored set} is an infinite set $C=\{(w_1,\lambda_1),(w_2,\lambda_2),\ldots\}$ where $w_i\in \Sigma^*$ and $\lambda_i:\interval_{|w_i|}\to \colset$ is an interval coloring for all $i\in \bbN$. 

Intuitively, the following lemma shows that given an infix-colored set $C$, there is a single infinite word $w$ and a corresponding interval coloring such that $w$ has infinitely many prefixes in $C$, and their infix coloring coincides with that of $w$. Technically, we state the lemma slightly differently. 
For $\lambda:\interval_{k}\to \colset$ and $k'<k$, we denote $\lambda|_{k'}$ as $\lambda$ restricted to the domain $\interval_{k'}$.
We denote by $\Sigma^\omega$ is the set of infinite words over $\Sigma$.

\begin{lemma}
    \label{lem:ramsey infinite word}
    Let $C$ be an infix-colored set, then there exists an infinite word $w\in \Sigma^\omega$ and an interval coloring $\lambda_\omega:\interval_\infty\to \colset$ such that for every finite prefix $v$ of $w$ there exists $(x,\lambda')\in C$ such that $v$ is a prefix of $x$ and $\lambda_\omega|_{|v|}\equiv \lambda'|_{|v|}$
    %for every $(i,j)\in \interval_{|v|}$ we have $\lambda_\omega(i,j)=\lambda_k((i,j))$.
\end{lemma}
\begin{proof}
    Consider a pair $(w,\lambda)\in C$, then for every prefix $v$ of $w$, we can consider the pair $(v,\lambda|_{|v|})$, which is a coloring of $v$ that coincides with $\lambda$ over the relevant indices.

    We now construct a finitely-branching forest\footnote{The graph is a forest since $\epsilon$ may appear with different colorings.} (i.e., a union of trees) $F=\tup{V,E}$ \`a la K\"onig, as follows. 
    The vertices of the tree are $F=\{(v,\lambda)\mid v\in \Sigma^*, \lambda:\interval_{|v|}\to \colset\}$, i.e., each vertex is an infix-colored word. The edges are
    \[
    E=\{((v,\lambda),(v\sigma,\lambda')\mid \lambda'|_{|v|}\equiv \lambda,\ \sigma\in \Sigma)\}
    \]
    That is, we connect a colored word $v$ to any word obtained by adding a single letter $\sigma$ to $v$, such that the coloring of $v\sigma$ coincides with that of $v$ on the relevant indices.

    Note that all the outgoing edges from vertices $(v,\lambda)$ with $|v|=n$ are to vertices $(v',\lambda')$ with $|v'|=n+1$. 
    Since there are only finitely many vertices $(v,\lambda)$ with $|v|=n$ (since $\colset$ is finite), then clearly the branching degree of the tree is also finite.

    We now restrict $F$ to the sub-forest $F'$ obtained by keeping only the vertices in $F$ from which there is a path to some $(x,\lambda')\in C$ (observe that the elements of $C$ are also vertices in $F$ by definition). 
    Since $C$ is infinite and $\Sigma$ is finite, it follows that $C$ contains arbitrarily long words. Since we keep all vertices along paths from $\epsilon$ (with some coloring) to words in $C$, it follows that $F'$ is a finitely-branching forest with arbitrarily long paths.

    By K\"onig's lemma, it follows that there is an infinite path in $F'$. We claim that such a path induces an infinite word as required. 
    Indeed, we can assume without loss of generality that the infinite path begins in $(\epsilon,\lambda_\epsilon)$ (otherwise we add prefixes to it until reaching $\epsilon$). We can therefore write the path as $(\epsilon,\lambda_\epsilon),(\sigma_1,\lambda_1),(\sigma_1\sigma_2,\lambda_2),\ldots$, i.e., the $n$-th vertex in the path is $(\sigma_1\cdots \sigma_n,\lambda_n)$. 

    We now define the infinite word $w$ and $\lambda_\omega$ as follows. $w=\sigma_1\sigma_2\cdots$ (i.e., $w[n,n]=\sigma_n$ for all $n\in \bbN$). For every $(i,j)\in \interval_\omega$ we define $\lambda_\omega(i,j)=\lambda_j(i,j)$.

    It remains to show that $(w,\lambda_\omega)$ satisfies the required conditions. Consider a finite prefix $v$ of $w$, then in particular $(v,\lambda_{|v|})\in F'$ (since $w$ is described by a path in $F'$), and $\lambda_{|v|}\equiv \lambda_\omega|_{|v|}$.
    Moreover, by the definition of $F'$, it follows that there is a path in $F$ from $(v,\lambda_{|v|})$ to some $(x,\lambda')\in C$. By the way we construct $F$, we have that $\lambda'|_{|v|}\equiv \lambda_{|v|}$. Putting these together, we have $\lambda_{\omega}|_{|v|}=\lambda'|_{|v|}$, as required.   
\end{proof}

We can now show that every infix-colored set $C$ has words that can be decomposed to arbitrarily many infixes such that all infixes have the same coloring, and moreover -- this coloring is idempotent with respect to concatenation. In addition, we are able to place some constraints on the cost of these infixes, where ``cost'' here is a general extension of the length of a word.
Naturally, our usage is with the cost functions of \cref{def:cost depth and sub cactus}.
%\shtodo{Add illustration}

Formally, a \emph{prefix-cost function} is a function $\precost:\Sigma^+\to \bbN\setminus \{0\}$ without any restrictions.
 A letter-cost function is $\lc:\Sigma^+\to \bbN\setminus \{0\}$ such that $\lc$ is ``strictly increasing on prefixes'', i.e., if $x$ is a strict prefix of $y$ then $\lc(x)<\lc(y)$ (c.f., \cref{rmk:cost is strictly increasing}).
%, and for a word $w=\sigma_1\cdots \sigma_n\in \Sigma^*$ we define $\lc(w)=\sum_{i=1}^n\lc(\sigma_i)$. 
We also denote $w[i,j]=\sigma_i\cdots \sigma_{j}$ for $1\le i\le j\le n$. Before we proceed, we recall a specific theorem by Ramsey that we use in the proof.
For a set $A$, write $(A)_n=\{A'\subseteq A: |A'|=n\}$
\begin{theorem}[Ramsey, 1930]
	\label{thm: ramsey original}
Let $f:(\bbN)_n\to \colset$, then there exists an infinite set $A\subseteq \bbN$ on which $f$ is homogeneous, i.e., $f$ is constant on $(A)_n$.
\end{theorem}
%
\begin{theorem}[\keyicon \lightbulbicon A Ramsey Theorem for Infix Coloring]
    \label{thm: our ramsey}
    Consider an infix-colored set $C$, a prefix-cost function $\precost$ and a letter-cost function $\lc$. 
    For every $L\in \bbN$ there exists a pair $(v,\lambda)$ and an index set $1\le i_0<i_1<\ldots <i_L\le |v|+1$ such that there are infinitely many pairs $(w_i,\lambda_i)\in C$ (for $i\in \bbN$) where $v$ is a prefix of $w_i$, and the following hold:
    \begin{enumerate}
        \item 
        %For every $(j,k)\in \interval_{|v|}$ we have $\lambda(j,k)=\lambda_i(j,k)$ for all $i\in \bbN$,i.e., the coloring of $v$ matches that of the $w_i$.
        $\lambda\equiv \lambda_i|_{|v|}$ for all $i\in \bbN$. I.e., the coloring of $v$ matches that of the $w_i$.
        \item For every $0\le j<k\le L$ we have $\lambda(i_0,i_1-1)=\lambda(i_j,i_{k-1})$, i.e., all the infixes between the indices in the set have the same color.
        \item $\precost(v[i_0,i_1-1])< \lc(v[i_1,i_{L}])$, i.e., the first infix is much ``cheaper'' than the remaining infix.
    \end{enumerate}
\end{theorem}
\begin{proof}
Let $w\in \Sigma^\omega$ and $\lambda_\omega$ be the infix-colored infinite word obtained as per \cref{lem:ramsey infinite word}. Note that $\lambda_\omega:(\bbN)_2\to \colset$, and we can therefore apply \cref{thm: ramsey original} to $\lambda_\omega$.
Thus, there exists an infinite subset $A\subseteq \bbN$ and a color $r\in \colset$ such that $\lambda_{\omega}(i,j)=r$ for all $i<j\in A$. Sort $A$ as $i_0<i_1<\ldots$. 

Recall that the cost function $\lc$ strictly increasing on prefixes, and in particular strictly increasing with \emph{length} along any infix of $w$.
Since $A$ is infinite, then there exists $L\in \bbN$ large enough such that $\precost(w[i_0,i_1-1])<\lc(w[i_1,i_L])$ (note that $\precost(w[i_0,i_1-1])$ is a constant).

Take $v=w[1,i_L]$. By the above, Requirement \textit{3} holds (since $v$ is identical to $w$ up to index $i_L$). 
Requirement \textit{2} holds by the application of \cref{thm: ramsey original}, since all the infixes with indices in $A$ are colored $r$.
The existence of infinitely many pairs in $C$ where $v$ is a prefix follows from \cref{lem:ramsey infinite word}. Indeed, for every prefix $x$ of $w$ such that $v$ is a prefix of $x$, there exists $(w_i,\lambda_i)\in C$ such that $x$ is a prefix of $w_i$ and $\lambda_\omega|_{|x|}\equiv \lambda_i|_{|x|}$. In particular, since there are arbitrarily long such prefixes $x$, it follows that there are infinitely many such pairs $(w_i,\lambda_i)$. This also shows that Requirement \textit{1} holds, concluding the proof.
\end{proof}





\section{Separated Increasing Infixes}
\label{sec:separated increasing infix}
In this section we define word infixes whose runs exhibit a very ``organized'' behavior, which are later used in our proof. We then show that such infixes exist.

\subsection{Separated Increasing Infixes -- Definition}
\label{sec:separated increasing infix definition}
We start with an intuitive overview of the properties we require, follows by the formal definition.
\begin{figure}[ht]
    \centering
    %\input{fig/inc_infix.pdf}
    \includegraphics[scale=0.5]{fig/inc_infix.pdf}
    \caption{A Separated Increasing Infix from State $p$. After reading $u$, the configuration is separated to sub-configurations corresponding to the $V_i$. Reading $x$ maintains this partition and the exact distances within each set. The same holds for $y$, but with different shifts. 
    In addition, $y$ is much longer than $x$ (or rather, has much higher cost). Moreover, the gaps between the sub-configurations are larger still -- much larger than the maximal effect of $x$ and $y$.
    }
    \label{fig:increasing infix}
\end{figure}

Consider the WFA $\augA_\infty^0=\tup{S,\Gamma^0_\infty,s_0,\augTrans^0_\infty}$. That is, we focus on the construction with cactus letters, but without rebase or jump.
%\shtodo{Do we want to focus on $\augA_\infty^0$? Yes. Changed.}
An separated increasing infix (from state $p$) consists of a concatenation $uxyv$ with the following structure (see \cref{fig:increasing infix}): 
\begin{itemize}
    \item Reading $u$ from $p$ reaches a configuration that is partitioned to ``sub-configurations'' that have a huge gap between them, we call the state sets in these sub configurations $V_1,\ldots, V_{\ell}$. 
    \item Next, reading $x$ maintains the structure of these $V_j$ sets, and increases all the states in each set $V_j$ by a constant $k_{j,x}\ge 0$. In particular, the entire configuration maintains its support after $x$.
    \item Reading $y$ has very similar behavior to $x$, in the sense that the $V_j$ are maintained, and each is increased by a constant $k_{j,y}$, with the property that $k_{j,y}=0$ if and only if $k_{j,x}=0$. 

    However, an additional property of $y$ is that it is \emph{very} long (or rather, very costly). Specifically, its cost (in the sense of \cref{def:cost depth and sub cactus}) is larger than the cost of a cactus letter on $x$. This means that replacing the infix $xy$ by the cactus $\alpha_{B,x}$ decreases the overall cost (which indeed we do in \cref{lem:increasing infix budding}).

    Despite the huge cost of $y$, the gaps between the $V_j$ are even higher, so much so that ``pumping'' $x$ should be safe. These notions are made concrete throughout the section.
    \item Finally, $v$ is just a harmless suffix.
\end{itemize}


We now turn to the formal definition, starting with some notations.
For a word $w$, recall that $\wmax{w}$ is the maximal absolute value of a weight over any transition on a letter of $w$.
%\gatodo{$w$ is only over $\augA_{\infty}$ (while we can define it with rebase letters there is no need)} 
%in transitions involving any letter\footnote{Observe that we cannot take the maximal weight in $\augA_\infty^\infty$, since the alphabet is infinite and the weights may be unbounded.} of $w$. 
Further recall that $\wmax{w}\cdot |w|$ upper-bounds the maximal finite change in weights that can be incurred upon reading $w$.
For a state $p\in S$, let $\vec{c_p}$ be the configuration that assigns $p$ weight $0$ and $\infty$ otherwise.
\begin{definition}[\keyicon Separated Increasing Infix from $p$]
    \label{def:separated increasing infix from state}
    Consider a state $p\in S$ and a word $w\in (\Gamma_\infty^0)^*$ decomposed as $w=u\cdot x\cdot y\cdot v$. 
    Denote $\vec{c_u}=\xconf(\vec{c_p},u)$ and similarly $\vec{c_{ux}}=\xconf(\vec{c_p},ux)$ and $\vec{c_{uxy}}=\xconf(\vec{c_p},uxy)$.
    We say that \emph{$w$ is a separated increasing infix from $p$} if the following conditions hold.
    \begin{enumerate}
        \item \label{itm:separated infix length diff} 
        %$\cost(x)\cdot 16\cdot\bigM < \cost(y)$ 
        $\cost(y)>2^{16(\bigM |S| \cost(x))^2}$
        (where $\cost$ is as per \cref{def:cost depth and sub cactus}).
        %\shtodo{This should be much higher -- enough to be above $\cost(\alpha_{S',x})$}
        \item \label{itm:separated infix reachable states} $\supp(\vec{c_u})=\supp(\vec{c_{ux}})=\supp(\vec{c_{uxy}})=B$ for some subset $B\subseteq S$. %$\booltrans(p,u)=\booltrans(p,ux)=\booltrans(p,uxy)$. 
        That is, the subsets of states reached after $u,ux,uxy$ are the same.
        \item \label{itm:separated infix partition}
        $B$ can be partitioned to $B=V_1\cup \ldots \cup V_\ell$ for some $\ell$ such that the following holds.
        \begin{enumerate}
            \item 
            \label{itm:separated infix gaps V}
            For every $1\le j<\ell$, every $s\in V_j,s'\in V_{j+1}$ and  every $\xi\in \{u,ux,uxy\}$ we have 
            $\vec{c_\xi}(s')-\vec{c_\xi}(s)> \incinfGapConst$. 
            \acctodo{If this constant changes, the accounting in the definition of $\sparse$ needs to be updated, along with every part influenced by it. These parts are next to comments labeled ACCOUNTING-1}

            That is, the values assigned to states in $V_{j+1}$ are significantly larger than those assigned to $V_{j}$ in the configurations $\vec{c_{u}}, \vec{c_{ux}}$ and $\vec{c_{uxy}}$.
            \item 
            \label{itm:separated infix linear k}
            For every $1\le j\le \ell$ there exist $k_{j,x},k_{j,y}\in \bbN$ such that for every $s\in V_j$ we have  $\vec{c_{ux}}(s)=\vec{c_u}(s)+k_{j,x}$ and $\vec{c_{uxy}}(s)=\vec{c_{ux}}(s)+k_{j,y}$.

            Moreover, $k_{j,x}=0$ if and only if $k_{j,y}=0$.
        \end{enumerate}
        \item \label{itm:separated infix seamless baseline}  If $p$ is a baseline state, then there is a seamless baseline run $\rho:p\runsto{uxyv}p$ from $\vec{c_p}$ (and so $\rho$ is constantly of weight $0$ in all prefixes).
    \end{enumerate}
\end{definition}
The partition and gaps described in \cref{itm:separated infix partition,itm:separated infix gaps V} give rise to a restriction on the runs on the infixes $x,y$. Specifically, there are only runs from $V_j$ to $V_{j'}$ for $j\ge j'$, and there is always a run from $V_{j'}$ to $V_{j'}$. In addition, the constants $k_{j,x}$ and $k_{j,y}$ are bounded.
\begin{proposition}
\label{prop:run characteristics of increasing infix from state}
    Consider a separated increasing infix $uxyv$ from state $p$, and let $B=V_1\cup\ldots \cup V_\ell$ and $k_{j,x},k_{j,y}$ as per \cref{def:separated increasing infix from state}. Then the following hold for every $1\le j\le \ell$,.
    \begin{itemize}
        \item $k_{j,x}\le \maxeff{x}$ and $k_{j,y}\le \maxeff{y}$.
        \item For every $z\in \{x,y\}$ and $s\in S$, if $s\in V_{j}$ then there exists $s'\in V_{j}$ such that $s'\runsto{z}s$.
        \item For every $z\in \{x,y\}$ and $s,s'\in S$ such that $s\runsto{z}s'$, if $s'\in V_{j'}$ then $s\in V_{j}$ for some $j\ge j'$.
    \end{itemize}
\end{proposition}
\begin{proof}
    We prove the claim for $z=x$, and the case of $y$ identical up to working with $\vec{c_{uxy}}$ instead of $\vec{c_{ux}}$.

