    \label{lem:unbounded long dip and G imply separated inc infix}
    Let $D,\ell,G\in \bbN$ such that there exists a function $\xwords$ that is $\ell$-sparse, $D$-dip and a $G$-cover. 

    Then there exists some $m\in \bbN$ with $\xwords(m)=w_1w_2w_3w_4$ and a decomposition $w_3=u'\cdot x\cdot y\cdot z'$ such that $u\cdot x\cdot y\cdot z$ is a separated increasing infix from 
    $\ghostTrans(s_0,w_1)$
    for $u=w_2\cdot u'$ and $z=z'\cdot w_4$.
\end{lemma}
