    &|\vec{c_{uv}}(\rho_j(uv))-\vec{c_{uv\sigma}}(\rho_j(uv\sigma))|+|\vec{c_{uv\sigma}}(\rho_j(uv\sigma))-\vec{c_{uv}}(\rho_i(uv))|\le \\
    & W_{\max}+ |\vec{c_{uv\sigma}}(\rho_j(uv\sigma))-\vec{c_{uv}}(\rho_i(uv))|=\\
    & W_{\max}+ |\vec{c_{uv\sigma}}(\rho_j(uv\sigma))-\vec{c_{uv\sigma}}(q)+\vec{c_{uv\sigma}}(q)-\vec{c_{uv}}(r)+\vec{c_{uv}}(r)-\vec{c_{uv}}(\rho_i(uv))|\le \\
