Since a single run is independent by definition, we therefore obtain a set of independent runs $I^m_p$ with $|I^m_p|=1$. Taking $\ell$ to be the maximal value such that $\ell=|\bigcup_{p}I^m_p|$ for infinitely many $m$, we can use \cref{prop:faithful restriction of words infinitely many ells} to obtain a faithful restriction of $\xwords$ that is $\ell$-sparse (for some $\ell\ge 1$). For brevity, we assume $\xwords$ itself is already $\ell$-sparse.

Crucially, note that taking a faithful restriction maintains the property of being a $D$-dip.


We can now apply \cref{lem:unbounded long dip imply separated inc infix}, to obtain a sparse $G$-cover $\xwords'$. Again, since $\xwords'$ is a faithful restriction of $\xwords$, then $\xwords'$ is also $D$-dip. Thus, we have the following.
\begin{corollary}
    \label{cor:there is a G cover}
    If there exists an elongated word sequence $\xwords$ that is a $D$-dip for some $D\in \bbN$, then there is a faithful restriction $\xwords'$ of $\xwords$ that is a $D$-dip $\ell$-sparse $G$-cover for some $\ell,G\in \bbN$. 
\end{corollary}
Then, by combining \cref{cor:there is a G cover} with \cref{lem:unbounded long dip and G imply separated inc infix} we have the following.
\begin{corollary}[\keyicon $D$-Dip to Increasing Infix]
    \label{cor:dip implies increasing infix}
    If there exists an elongated word sequence $\xwords$ that is $D$-dip for some $D\in \bbN$, then there exists $m\in \bbN$ with $\xwords(m)=w_1w_2w_3w_4$ and a decomposition $w_3=u'xyv'$ such that $uxyv$ is a separated increasing infix from $\ghostTrans(s_0,w_1)$ for $u=w_2u'$ and $v=v'w_4$.
\end{corollary}


\section{Cactus Budding}
\label{sec:cactus budding}
In this section we discuss how a cactus chain (\cref{def:cactus chain}) may grow a new cactus at its end (\emph{bud}, in cactus terms). The overall intuition is that a chain may bud a new inner cactus if doing so both decreases the cost of the chain (as per \cref{def:cost depth and sub cactus}), and does not decrease the potential. 
To this end, the main tool at our disposal is our study of Separated Increasing Infixes (\cref{def:separated increasing infix}).
As usual, there are several definitions and technical tools to develop before getting to the main result.
\begin{definition}[Superior Stable Cycle]
    \label{def:superior stable cycle}
    Consider two stable cycles $(S',u),(S',v)$ sharing the same first component $S'$. 
    We say that $(S',v)$ is \emph{superior} to $(S',u)$ if for every $q,p\in S'$ 
    %with $q\runsto{\alpha_{S',u}}p$ 
    we have $\minweight(\alpha_{S',u},q\to p)\le \minweight(\alpha_{S',v},q\to p)$.
\end{definition}
Our first (simple) observation is that a word that ``almost'' induces a stable cycle, and satisfies a superiority condition with respect to a stable cycle, actually induces a superior stable cycle.
\begin{proposition}
    \label{prop:superior word is a superior cycle}
    Consider a stable cycle $(S',u)$ and let $v\in (\Gamma_\infty^0)^*$ (i.e., without rebase and  jump letters) be a word such the following hold.
    \begin{enumerate}
        \item For every $q,p\in S'$ it holds that $\minweight(u,q\to p)\le \minweight(v,q\to p)$.
        \item For the baseline state $g \in S'$ it holds that $\minweight(v,g\to g)=0$.
    \end{enumerate}
    Then $(S',v)$ is a stable cycle, and it is superior to $(S',u)$.
\end{proposition}
\begin{proof}
    By the condition on the baseline state $g$
    and since $v$ does not have jump letters,
    the baseline run $\rho:g\runsto{v}g$ exists and $\weight(\rho)=0$. 
    Therefore in order to show that $(S',v)$ is a stable cycle, all that remains is to prove that there are no negative cycles on $v^k$ for any $k\in \bbN$, and that $\booltrans(S',v)\subseteq S'$.

    The latter is simple: if $q\in \booltrans(S',v)$ then $\minweight(v,S'\to q)<\infty$, but then $\minweight(u,S'\to q)<\infty$, so $q\in \booltrans(S',u)\subseteq S'$ (since $(S',u)$ is a stable cycle), so $\booltrans(S',v)\subseteq S'$.
    % \gatodo{isn't it obvious ? (as the base state goes back to itself, and so it the right component)}
    % \shtodo{I don't think so. The right component just tells us that we're repeating the ghost states. It doesn't mean that the boolean reachability is contained, it could just be a different set with the same right component.}
    Before addressing the main claim, we prove a slightly more general property: for every $k\in \bbN$ and $r_0,r_k\in S'$ it holds that $\minweight(u^k,r_0\to r_k)\le \minweight(v^k,r_0\to r_k)$. 
    Indeed, let $\rho:r_0\runsto{v^k}r_k$ such that $\weight(\rho)=\minweight(v^k,r_0\to r_k)$, and write $\rho:r_0\runsto{v}r_1\cdots r_{k-1}\runsto{v}r_k$. By the premise we have
    \[
    \begin{split}
    &\minweight(v^k,r_0\to r_k)=\weight(\rho)=\sum_{i=0}^{k-1}\minweight(v,r_{i}\to r_{i+1})\ge\\
    &\sum_{i=0}^{k-1}\minweight(u,r_{i}\to r_{i+1})\ge \minweight(u^k,r_0\to r_k).
    \end{split}
    \]

    Now, assume by way of contradiction that $\minweight(s \to s, v^k)<0$ for some $k\in \bbN$, then by the property above we have $\minweight(s \to s, u^k)<0$ in contradiction to the fact that $(S',u)$ is a stable cycle.

    We conclude that $(S',v)$ is a stable cycle. 
    Similarly, we can now prove that it is superior to $(S',u)$. Consider $p,q\in S'$. If $\minweight(\alpha_{S',v},p\to q)=\infty$, there is nothing to prove. Thus, assume $\minweight(\alpha_{S',v},p\to q)<\infty$. By \cref{def:stabilization}, we have that $(p,q)\in \GroundPairs(S',v)$ and there exists $g\in S'$ such that 
    $\minweight(\alpha_{S',v},p\to q)=\minweight(v^{2\bigM},p\runsto{v^\bigM}g\runsto{v^\bigM} q)$.
    By the property above, we now have
    \[
    \begin{split}
    &\minweight(\alpha_{S',v},p\to q)=\minweight(v^{2\bigM},p\runsto{v^\bigM}g\runsto{v^\bigM} q)=
    \minweight(v^{\bigM},p\to g)+\minweight(v^{\bigM},g\to q)\ge\\
    &    \minweight(u^{\bigM},p\to g)+\minweight(u^{\bigM},g\to q)=
    \minweight(u^{2\bigM},p\runsto{u^\bigM}g\runsto{u^\bigM} q)\ge
    \minweight(\alpha_{S',u},p\to q)
    \end{split}
    \]
    where the last inequality is by \cref{def:stabilization}, keeping in mind that the grounding state for $p,q$ with $u$ may differ from $g$, but that $g\in \MinRefStates(S',u^\bigM)$ (that is, it is a possible grounding state), so we indeed have the inequality.
    We thus have that $(S',v)$ is superior to $(S',u)$.
\end{proof}
Our next observation is that superiority ``propagates'' through to outer-cactus letters.

\begin{proposition}
\label{prop:superiority propagates to outer cactus}
    Consider a stable cycle $(S',w)$ such that $w=w_1  \alpha_{B,u} w_2$ with $B=\ghostTrans(s_0,w_1)$. Let $(B,v)$ be a superior stable cycle to $(B,u)$, then $(S',w_1\alpha_{B,v}  w_2)$ is a superior stable cycle to $(S',w)$.
\end{proposition}
\begin{proof}
Write $w'=w_1  \alpha_{B,v} w_2$, we prove that $w'$ satisfies the conditions of \cref{prop:superior word is a superior cycle} with respect to $(S',w)$.
Let $p,q\in S'$. If $\minweight(w_1\alpha_{B,v}w_2,p\to q)=\infty$, there is nothing to prove. Otherwise, let $r,t\in B$ such that 
\[\minweight(w_1\alpha_{B,v}w_2)=\minweight(w_1\alpha_{B,v}w_2,p\runsto{w_1}r\runsto{\alpha_{B,v}}t\runsto{w_2}q)\]
Since $(B,v)$ is superior to $(B,u)$, we now have
\[
\begin{split}
&\minweight(w_1\alpha_{B,v}w_2)=\minweight(w_1\alpha_{B,v}w_2,p\runsto{w_1}r\runsto{\alpha_{B,v}}t\runsto{w_2}q)\\
&=\minweight(w_1,p\to r)+\minweight(\alpha_{B,v},r\to t)+\minweight(w_2,t\to q)\\
&\ge \minweight(w_1,p\to r)+\minweight(\alpha_{B,u},r\to t)+\minweight(w_2,t\to q)\\
& = \minweight(w_1\alpha_{B,v}w_2,p\runsto{w_1}r\runsto{\alpha_{B,u}}t\runsto{w_2}q) \ge \minweight(w_1\alpha_{B,u}w_2)
\end{split}
\]
satisfying the first item in \cref{prop:superior word is a superior cycle}.

Finally, since $\alpha_{B,v}$ is a stable cycle, and since $w_1\alpha_{B,u}w_2$ has a seamless baseline run with weight $0$, then so does $w_1\alpha_{B,v}w_2$ (since $\alpha_{B,v}$ also has a $0$ baseline transition).
We conclude that $w'=w_1\alpha_{B,v}w_2$ satisfies the conditions in \cref{prop:superior word is a superior cycle}, and therefore $(S',w')$ is a superior stable cycle to $(S',w)$.
\end{proof}

Next, we show that the charge \emph{decreases} with superiority. Intuitively, this is because the charge measures how negative runs can be come, and superiority increases all the runs.

\begin{proposition}
    \label{prop:charge decreases superior}
    Consider stable cycles $(B,u),(B,v)$ such that $(B,v)$ is superior to $(B,u)$. Then for every $x,y$ we have that $\charge(x\alpha_{B,v}y)\le \charge(x\alpha_{B,u}y)$.
\end{proposition}
\begin{proof}
    Let $q\in S$ such that $\rho:s_0\runsto{x\alpha_{B,v}y}q$ satisfies $\weight(\rho)=-\charge(x\alpha_{B,v}y)$ and $\rho$ is seamless.
    Write $\rho:s_0\runsto{x}r\runsto{\alpha_{B,v}}t\runsto{y}q$, then by superiority and since $\rho$ is seamless, we have
    \[
    \begin{split}
        &-\charge(x\alpha_{B,v}y)=\weight(\rho)=
        \minweight(x,s_0\to r)+\minweight(\alpha_{B,v},r\to t)+\minweight(y,t\to q)\ge\\
        &\minweight(x,s_0\to r)+\minweight(\alpha_{B,u},r\to t)+\minweight(y,t\to q)\ge \minweight(x\alpha_{B,u}y,s_0\to q)\ge -\charge(x\alpha_{B,u}y)
    \end{split}
    \]
    So $\charge(x\alpha_{B,v}y)\le \charge(x\alpha_{B,u}y)$
    and we are done.
\end{proof}
Our next major goal is to show a dual result for the potential (namely that the potential increases with superiority), and moreover -- that this carries through cactus chains (\cref{def:cactus chain}).
Specifically, we do not prove this claim in full generality. Rather, we focus on cactus chains that end in an increasing infix (\cref{def:separated increasing infix}), and show how they induce superior cactus chains with increasing potential.


Recall that separated increasing infixes (\cref{def:separated increasing infix}) can be ``folded'' into stable cycles, as per \cref{lem:increasing infix budding}. 
We make use of this fact in order to ``bud'' a new cactus from an increasing infix, while maintaining nice properties, as follows (see depiction in \cref{fig:inc inf budding potential}).
\begin{figure}[ht]
    \centering
    \includegraphics[width=0.75\linewidth]{fig/inc_inf_budding.pdf}
    \caption{Budding a cactus from an increasing infix. Observe that $y$ is depicted as longer than $x$, to reflect its higher cost.}
    \label{fig:inc inf budding potential}
\end{figure}
\begin{lemma}[\lightbulbicon Increasing Infix Budding]
    \label{lem:increasing infix budding in chain base case}
    Either $\augA_{\infty}^\infty$ has a type-0 witness, or the following holds.
    Consider a cactus letter $\alpha_{S',w}\in (\Gamma_\infty^0)^*$ where $w=uxyz$ is a separated increasing infix from $S'$. Let $w'=u\alpha_{B,x}v$ where $B=\ghostTrans(S',u)$. Then $(S',w')$ is a stable cycle superior to $(S',w)$, and for every $w_1,w_2\in (\Gamma_\infty^0)^*$ we have $\pot(w_1\alpha_{S',w}w_2)\le \pot(w_1\alpha_{S',w'}w_2)$, if the potential is defined.
\end{lemma}
\begin{proof}
    The fact that $(S',w')$ is a superior stable cycle follows directly from \cref{lem:increasing infix budding}: we show there that either $\augA_{\infty}^\infty$ has a type-0 witness, or for every $r\in S'$ and $t\in S$ we have $\minweight(w,r\to t)\le \minweight(w',r\to t)$. Moreover, the baseline run exists in $(S',w')$, since $\alpha_{B,x}$ maintains the baseline run that is present in $xy$. 
    Therefore, we can use \cref{prop:superior word is a superior cycle} and we have that $(S',w')$ is a stable cycle superior to $(S',w)$.

    The interesting part of the lemma is obtaining the potential inequality. 
    Intuitively, we first unfold both $w_1\alpha_{S',w}w_2$ and $w_1\alpha_{S',w'}w_2$ with a high enough constant. This leaves us with many repetitions of $w$ and of $w'$, respectively. By \cref{lem:unfolding maintains potential}, we know that the potential is maintained by this unfolding. 
    We then use \cref{lem:increasing infix budding} again, this time deriving the potential inequality $\pot(w'_1ww'_2)\le \pot(w'_1w'w'_2)$ for every $w'_1,w'_2$.
    We then use this to replace each $w$ by $w'$ in the unfolding, while maintaining the potential inequality, which allows us to conclude the proof. We refer to the latter argument as \emph{synchronous unfolding}, and reuse it later.
    We turn to the precise details.

    Consider $w_1,w_2\in (\Gamma_\infty^0)^*$ such  that $\pot(w_1\alpha_{S',w}w_2)$ is defined. Note that this only means that the baseline run is seamless, and this is preserved in all the words we consider henceforth, so we do not mention this every time we discuss the potential.

    Let $F\ge \max\{2\maxeff{w_1\alpha_{S',w}w_2},2\maxeff{w_1\alpha_{S',w'}w_2}\}$, and consider $\unfold(w_1,\alpha_{S',w},w_2 \wr F)=w_1w^{2\bigM M_0}w_2$ and $\unfold(w_1,\alpha_{S',w'},w_2 \wr F)=w_1w'^{2\bigM M_0}w_2$. By \cref{rmk:increasing repetitions in unfolding} we can indeed assume that $M_0$ is the same for both unfoldings (by taking the maximum of the two unfolding constants).

    By \cref{lem:unfolding maintains potential}, either $\cA_\infty^\infty$ has a type-0 witness, in which case we are done, or we have 
    \[\pot(w_1\alpha_{S',w}w_2)=\pot(w_1w^{2\bigM M_0}w_2)\quad \text{ and }\quad \pot(w_1\alpha_{S',w'}w_2)=\pot(w_1w'^{2\bigM M_0}w_2)\]

    By \cref{lem:increasing infix budding}, for every $w'_1,w'_2\in (\Gamma_\infty^0)^*$ such that $\booltrans(s_0,w'_1)\subseteq S'$, it holds that $\pot(w'_1ww'_2)\le \pot(w'_1w'w'_2)$. 

    We claim that 
$\pot(w_1w^{2\bigM M_0}w_2)\le \pot(w_1w'^{2\bigM M_0}w_2)$. In order to show this, define for every $0\le j\le 2\bigM M_0$ the word $e_j=w_1 w^j w'^{2\bigM M_0-j}w_2$, then this is equivalent to showing that $\pot(e_{2\bigM M_0})\le \pot(e_0)$. We prove that for every $0< j\le 2\bigM M_0$ it holds that $\pot(e_{j})\le \pot(e_{j-1})$, which implies the claim.

Indeed, consider such $j$ and write $w'_1=w_1 w^{j-1}$ and $w'_2= w'^{2\bigM M_0-j}w_2$.  Note that $e_j=w'_1 w w'_2$ whereas $e_{j-1}=w'_1 w' w'_2$.
Since $(S',w)$ is a stable cycle and $\booltrans(s_0,w_1)\subseteq S'$, then in particular $\booltrans(s_0,w'_1)\subseteq S'$. Therefore, as we mention above, we have
$\pot(w'_1 w w'_2)\le \pot(w'_1w'w'_2)$, i.e., $\pot(e_{j})\le \pot(e_{j-1})$, concluding the claim.
We now conclude the proof with: 
\[\pot(w_1\alpha_{S',w}w_2)=\pot(w_1w^{2\bigM M_0}w_2)\le \pot(w_1w'^{2\bigM M_0}w_2)=\pot(w_1\alpha_{S',w'}w_2)\]
We remark that the latter argument is the \emph{synchronous unfolding} mentioned above.
\end{proof}

The results in this section so far pertain to stable cycles, and can be viewed as if they occur at the ``apex'' of a cactus \emph{chain} (recall \cref{def:cactus chain}).
We now turn to lift these results to the entire cactus chain.

\begin{definition}[Superior Cactus Chain]
    \label{def:superior cactus chain}
    Consider two cactus chains $\Theta_1=\alpha_{S'_1,w_1},...,\alpha_{S'_n,w_n}$ and  $\Theta_2=\beta_{S'_1,w'_1},...,\beta_{S'_n,w'_n}$. 
    We say that $\Theta_2$ is \emph{superior} to $\Theta_1$ if $\beta_{S'_i,w'_i}$ is superior to $\alpha_{S'_i,w_i}$
for every $1\le i\le n$.  
\end{definition}

In case a cactus chain ends with a separated increasing infix, we call it \emph{pre-bud}, with the intuition that we can now bud a new cactus letter at its end. The cactus chain obtained by budding this increasing infix is referred to as a \emph{post-bud} chain, as follows. 
\begin{definition}[Pre-bud and Post-bud Cactus Chain]
    \label{def: pre and post bud chain}
    A cactus chain $\alpha_{S'_1,w_1},...,\alpha_{S'_n,w_n}$ is \emph{pre-bud} if $w_n=uxyv$ is a separated increasing infix from $S'_n$. Denote $w_i=u_i\alpha_{S'_{i+1},w_{i+1}}v_{i}$ for every $1\le i<n$ as per \cref{def:cactus chain}.

    The corresponding \emph{post-bud} cactus chain $\alpha_{S'_1,w'_1},...,\alpha_{S'_n,w'_n}$ is defined as follows:
    \begin{itemize}
        \item $w'_n=u\alpha_{B,x}v$ with $B=\ghostTrans(S'_n,u)$.
        \item For every $1\le i<n$ we define $w'_i=u_i\alpha_{S'_{i+1},w'_{i+1}}v_i$.
    \end{itemize}
\end{definition}
It is easy to see (by induction) that the post-bud cactus chain is indeed a valid cactus chain, as per \cref{def:cactus chain}. The only non trivial part is the base case, which is also immediate by the definition of an increasing infix from $S'$ (\cref{def:separated increasing infix}).

Intuitively, the post-bud cactus chain can be elongated by placing $\alpha_{B,x}$ as a new element, but at this point we do not do that, in order to keep the number of elements in the pre-bud and post-bud the same, so that they can be compared by the superiority relation. 
Indeed, our main result of this section is that the post-bud chain is superior to the pre-bud chain, and also has increased potential.
\begin{lemma}[\keyicon The Post-Bud Chain is Superior]
    \label{lem:post bud chain is superior higher potential}
    Either $\augA_{\infty}^\infty$ has a type-0 witness, or the following holds.
    Let $\Theta_1=\alpha_{S'_1,w_1},...,\alpha_{S'_n,w_n}$ be a pre-bud cactus chain and $\Theta_2=\alpha_{S'_1,w'_1},...,\alpha_{S'_n,u\alpha_{B,x}v}$ its post-bud cactus chain, then $\Theta_2$ is superior to $\Theta_1$ and for every $z_1,z_2$ with $\booltrans(s_0,z_1)\subseteq S'_1$ it holds that 
    $\pot(z_1 \alpha_{S'_1,w_1}z_2)\le \pot(z_1 \alpha_{S'_1,w'_1}z_2)$, if the potential is defined.
\end{lemma}
\begin{proof}
    The proof is by induction over the length of the chain. In a nutshell, the base case is exactly \cref{lem:increasing infix budding in chain base case}, whereas the inductive step follows by a similar ``synchronized unfolding'' argument as in the proof of \cref{lem:increasing infix budding in chain base case}.

    Before starting the induction, we assume that $\augA_{\infty}^\infty$ does not have a type-0 witness. If it does, we are done. Accordingly, whenever we use results that are prefixed by this assumption, we ignore it (c.f., \cref{rmk:the either witness prefix}).

    \paragraph{Induction base: $n=1$} In this case $\Theta_1=\alpha_{S'_1,w_1}$ with $w_1=uxyv$ an increasing infix from $S'_1$. By \cref{lem:increasing infix budding in chain base case} for $w'_1=u\alpha_{B,x}$ we have that $(S'_1,w'_1)$ is a superior stable cycle to $(S'_1,w_1)$ and for every $z_1,z_2\in (\Gamma_\infty^0)^*$ with $\booltrans(s_0,z_1)\subseteq S'_1$ it holds that $\pot(z_1\alpha_{S'_1,w_1}z_2)\le \pot(z_1\alpha_{S'_1,w'_1}z_2)$, if the potential is defined. This concludes the base case.

    \paragraph{Inductive step:} Assume correctness for $n$, we prove for $n+1$.
    Consider the pre-bud chain $\Theta_1=\alpha_{S'_0,w_0},\alpha_{S'_1,w_1},...,\alpha_{S'_n,w_n}$ and its post-bud chain $\Theta_2=\alpha_{S'_0,w'_0}\alpha_{S'_1,w_1},...,\alpha_{S'_n,u\alpha_{B,x}v}$. 

    Observe that \cref{def: pre and post bud chain} is inductive from the end of the chain to its start. In particular, we have that $\Theta'_1=\alpha_{S'_1,w_1},...,\alpha_{S'_n,w_n}$ is a pre-bud chain and its corresponding post-bud chain is conveniently $\Theta'_2=\alpha_{S'_1,w_1},...,\alpha_{S'_n,u\alpha_{B,x}v}$. 
    By the induction hypothesis, it holds that $\Theta'_2$ is superior to $\Theta'_1$. In particular, $(S'_1,w'_1)$ is superior to $(S'_1,w_1)$. By the definition of the post-bud chain (\cref{def: pre and post bud chain}), we have that $w_0=u_0 \alpha_{S'_1,w_1} v_0$ and $w'_0=u_0 \alpha_{S'_1,w'_1} v_0$. 
    By the superiority-propagation of \cref{prop:superiority propagates to outer cactus} it follows that $(S'_0,w'_0)$ is superior to $(S'_0,w_0)$, as required.  

    It remains to show the potential inequality. Let $z_1,z_2\in (\Gamma_\infty^0)^*$ with $\booltrans(s_0,z_1)\subseteq S'_0$. We need to show that $\pot(z_1\alpha_{S'_0,w_0}z_2)\le \pot(z_1\alpha_{S'_0,w'_0}z_2)$.
    We proceed with the synchronous unfolding argument, similarly to \cref{lem:increasing infix budding in chain base case}, with the main difference being that the ``inner'' potential inequality is now obtained by the induction hypothesis.

    Let $F\ge \max\{ 2 \maxeff{z_1\alpha_{S'_0,w_0}z_2},2\maxeff{z_1\alpha_{S'_0,w'_0}z_2}\}$, 
    and consider $\unfold(z_1,\alpha_{S'_0,w_0},z_2 \wr F)=z_1w_0^{2\bigM M_0}z_2$ 
    and $\unfold(z_1,\alpha_{S'_0,w'_0},z_2 \wr F)=z_1 {w'_0}^{2\bigM {M_0}}z_2$. 
    By \cref{rmk:increasing repetitions in unfolding} we can indeed assume that $M_0$ is the same for both unfoldings (by taking the maximum of the two unfolding constants).

    By \cref{lem:unfolding maintains potential} we have 
    \[
    \pot(z_1\alpha_{S'_0,w_0}z_2)=\pot(z_1w_0^{2\bigM M_0}z_2)\quad \text{ and }\quad
    \pot(z_1\alpha_{S'_0,w'_0}z_2)=\pot(z_1{w'_0}^{2\bigM M_0}z_2)
    \]
    It is therefore enough to show that $\pot(z_1w_0^{2\bigM M_0}z_2)\le \pot(z_1{w'_0}^{2\bigM M_0}z_2)$.
    Recall that $w_0=u_0 \alpha_{S'_1,w_1} v_0$ and $w'_0=u_0 \alpha_{S'_1,w'_1} v_0$ (as per \cref{def: pre and post bud chain}). 
    For every $0\le j\le 2\bigM M_0$, define the word $e_j=z_1(u_0w_0v_0)^j(u_0w'_0v_0)^{2\bigM M_0-j}z_2$, then we want to prove $\pot(e_{2\bigM M_0})\le \pot(e_0)$. 
    We prove that for every $0<j\le 2\bigM M_0$ it holds that $\pot(e_j)\le \pot(e_{j-1})$, which implies the claim.

    Indeed, consider such $j$ and write $z'_1=z_1(u_0w_0v_0)^{j-1}$ and $z'_2=(u_0w'_0v_0)^{2\bigM M_0- j}z_2$. 
    Note that $e_j=z'_1w_0 z'_2$ and $e_{j-1}=z'_1w'_0 z'_2$.
    Further note that since $\booltrans(S'_0,u_0)\subseteq S'_1$, and $w_0$ and $w'_0$ are stable cycles on $S'_1$, and $\booltrans(S'_1,v_0)\subseteq S'_0$, and  $\booltrans(s_0,z_1)\subseteq S'_0$ by the assumption, it holds that $\booltrans(s_0,z'_1)\subseteq S'_1$. 
    Thus, by the induction hypothesis (applied with $z'_1$ and $z'_2$), we have that 
    $\pot(z'_1 w_0 z'_2)\le \pot(z'_1 w'_0 z'_2)$. That is, $\pot(e_j)\le \pot(e_{j-1})$, from which we conclude that $\pot(z_1w_0^{2\bigM M_0}z_2)\le \pot(z_1{w'_0}^{2\bigM M_0}z_2)$.
    Thus, we conclude the proof with:
    \[
    \pot(z_1\alpha_{S'_0,w_0}z_2)=\pot(z_1w_0^{2\bigM M_0}z_2)\le 
    \pot(z_1{w'_0}^{2\bigM M_0}z_2)=\pot(z_1\alpha_{S'_0,w'_0}z_2)
    \]    
\end{proof}



\section{On Charge and Unbounded Potential}
\label{sec:discharging and unbounded potential}
In this section we continue our examination of organized structures in runs on arbitrarily long words, akin to \cref{sec:existence of separated increasing infixes} (which we also rely on). 
Our focus now is on the behavior of the charge ($\charge$) and its implication on the potential ($\pot$) (see \cref{def:charge,def:potential}).

The structure of this section resembles that of \cref{sec:existence of separated increasing infixes}: we consider words of the form $w_1w_2w_3w_4$ (with an implicit decomposition as in \cref{rmk:w1w2w3w4 is a decomposition}) and define a new specialization of elongated words sequences, as well as concepts of independent runs, types and dips, and some new characteristics. 
We then prove certain properties of words that have these characteristics. 
The proofs of this section, however, are more involved than those of \cref{sec:existence of separated increasing infixes}, and make use of baseline shifts (\cref{sec: baseline shift}) and flattening (\cref{sec: cactus unfolding}).

In this section we fix a finite alphabet $\Gamma'\subseteq \Gamma^0_\infty$ -- that is, without rebase letters (and also without jump letters). In addition, we require that $\Gamma_0^0\subseteq \Gamma'$ (i.e., $\Gamma'$ contains the original letters of $\augA$).
We discuss these assumption when it becomes relevant.
Let $W_{\max}$ be the maximal weight appearing in a transition over $\Gamma'$.




\subsection{A Condition for Unbounded Potential}
\label{sec: closing runs condition implies unbounded potential}
Our starting point is now an elongated words sequence $\words$ (note that we drop the assumption that $|w_3|=m$ added in \cref{def:exact word sequence}). Unlike \cref{sec:existence of inc inf assuming covered}, in this section we do not focus on each state reachable after $w_1$, but rather on the configurations visited after $w_1w_2$. 


Our first definition is a variant of independent runs. 
%Unlike \cref{def:independent run} where we define independence with respect to a specific state reached after reading $w_1$, in this section we consider independence from a certain configuration (namely the configuration reached after reading $w_1w_2$).
\begin{definition}[Configuration-Independent Runs]
    \label{def:configuration independent runs}
    Consider a word $w_1w_2w_3w_4$ and two seamless runs $\rho_1,\rho_2$ over it. We say that $\rho_1$ and $\rho_2$ are \emph{configuration-independent on $w_3$} if there exists $G\in \bbN$ such that for every prefix $v$ of $w_3$ we have $\rho_2(w_1w_2v)-\rho_1(w_1w_2v)>G$. 
    In this case we say that $\rho_2$ is \emph{above $\rho_1$ with gap $G$}.

    We say that $\rho_2$ and $\rho_1$ are \emph{not within gap $G$} when the order is not important.

    A set $\{\rho_1,\ldots, \rho_k\}$ of runs is \emph{configuration-independent with gap $G$} if the runs are independent in pairs with gap $G$. A singleton is independent by definition.
\end{definition}
Note that since we now focus on all the runs starting from $\xconf(s_0,w_1w_2)$, it follows that the maximal number of independent runs is at most $|S|$.

We proceed with an analogue of sparse words. Since we now look at general $\words$, we define the gaps between runs as a function of $|w_3|$ instead of a function of $m$. 
In particular, when we apply the definition, we define the gap explicitly as an expression in $|w_3|$ (see e.g., \cref{lem: decomposed seq with cover sparse no ghosts implies unbounded potential} below).
\begin{definition}[$\ell$-Sparse $K$-Gap Words]
\label{def:discharging ell sparse K gap}
For $\ell\in \bbN$ and $K:\bbN\to \bbN$ we say that an elongated word sequence $\words$ is \emph{$\ell$-sparse} with $K$-gap if for every $m\in \bbN$ with $\words(m)=w_1w_2w_3w_4$ there is a set $I$ of independent runs with gap $K(|w_3|)$
%$W_{\max}(|S|+1)$ 
% \gatodo{why do we need a $K$ function and not just a gap larger then $|S|2M|w_3|^5$}
% \shtodo{Because the gap you just described depends on $|w_3|$. It's not a constant, but a function.\\ Unless you mean why not fix the gap in advanced? Because it's cleaner this way, and if something changes in the numbers we don't need to go around changing it in multiple places.\\
% Also, please stop using this 5 in the power. We never need it, and it's confusing if it's just overkill.}
such that $|I|=\ell$.
    %%%ACCOUNTING-3
\end{definition}


In the following, we consider \emph{decompositions} of $w_3$. Intuitively, a decomposition of $w_3$ is simply a concatenation $w_3=u_1u_2\cdots u_k$ for some $k\in \bbN$, such that the number of segments increases with $m$. We later impose further conditions on these decompositions, but for now they only serve as parts of definitions.
\begin{definition}[Decomposed Words Sequence]
    \label{def:decomposed words sequence}
    A sequence $\words$ is \emph{decomposed} if for every $m\in \bbN$ with $\words(m)=w_1w_2w_3w_4$ there is an associated decomposition $w_3=u_1u_2\cdots u_{d(m)}$ such that $\lim_{m\to \infty}d(m)=\infty$ and all the $u_i$ are nonempty.
\end{definition}
As usual, we assume that a decomposed word sequence has a fixed associated decomposition function, so we can refer to ``the decomposition of $\words(m)$'' for every $m\in \bbN$.


Our next definitions are variants of a $G$-cover (\cref{def:G cover inc infix}). 
\begin{definition}[Configuration $G$-Cover]
    \label{def: config G cover words}
    Consider an $\ell$-sparse decomposed sequence $\words$. 
    For every $m\in \bbN$ and $\words(m)=w_1w_2w_3w_4$ let $I=\{\rho_1,\ldots, \rho_\ell\}$ be the corresponding $\ell$-sparse independent runs. 

    For $G\in \bbN$, we say that $\words$ is a \emph{$G$-cover} if for every prefix $u$ of $w_3$ and configuration $\vec{c}=\xconf(s_0,w_1w_2u)$, for every state $q\in \booltrans(s_0,w_1w_2u)$ we have $\min\{|\vec{c}(q)-\weight(\rho_i(w_1w_2u))|: 1\le i\le \ell\}\le G$. 
\end{definition}
The next cover definition differs from \cref{def: config G cover words} in that we require the cover to hold only at end points of the decomposition segments.
%For this section, we consider independent runs along a fair decomposition, and we require the cover to hold only at the end points of each segment (i.e., that every reachable state is within gap $G$ from one of the independent runs)
\begin{definition}[Decomposition $G$-Cover]
    \label{def: G cover decomposed words}
    Consider an $\ell$-sparse decomposed sequence $\words$. 
    For every $m\in \bbN$ and $\words(m)=w_1w_2w_3w_4$ with decomposition $w_3=u_1\cdots u_{d(m)}$ let $I=\{\rho_1,\ldots, \rho_\ell\}$ be the corresponding $\ell$-sparse independent runs. 

    For $G\in \bbN$, we say that $\words$ is a \emph{decomposition $G$-cover} if for every $0\le j\le k$ and configuration $\vec{c_{j}}=\xconf(s_0,w_1w_2u_1\cdots u_j)$, for every state $q\in \booltrans(s_0,w_1w_2u_1\cdots u_j)$ we have $\min\{|\vec{c_j}(q)-\weight(\rho_i(w_1w_2u_1\cdots u_j))|: 1\le i\le \ell\}\le G$. 
\end{definition}

As mentioned above, our definitions here focus on reachable states. Nonetheless, the presence of ghost runs still introduces complications. The following definition (when applicable) enables us to mitigate the effect of these runs.
\begin{definition}[Ghost-Free Decomposition]
\label{def:ghost free decomposition}
 Consider a decomposed sequence $\words$.
 For every $m\in \bbN$ and $\words(m)=w_1w_2w_3w_4$ with decomposition $w_3=u_1\cdots u_{d(m)}$ we say that $\words$ is \emph{ghost-free} if there are no ghost runs from $w_1w_2u_1\cdots u_{i-1}$ to $w_1w_2u_1\cdots u_i$ for every $1\le i< d(m)$.
 (note that there is no requirement on the last segment, which can be thought of as a ``remainder'').
\end{definition}
Note the this requirement is not only that there are no ghost runs spanning the entire $w_3$, but that even when focusing on a single segment in the decomposition, there is no seamless ghost run on it. In particular, a ghost-free  decomposition has no ghost runs on any concatenation $u_i\cdots u_{j}$ for any $i\le j$ (this follows from the fact that an infix of a ghost run is also a ghost run, as noted after \cref{def:ghost run}).
Still, there could be ghost runs that start e.g., in the middle of segment $u_i$ and are cut in the middle of $u_{i+1}$.

Our next requirement of the decomposition is more involved, and assumes there exists a run whose gap from the minimal states gets smaller. 
\begin{definition}[\keyicon Decreasing-Gap Fair Decomposition]
    \label{def:decreasing gap fair decomposition}
    Consider a decomposed word sequence $\words$ and assume there exists a function $b:\bbN\to \bbN$ with $\lim_{n\to \infty}b(n)=\infty$ such that for every $m\in \bbN$ with $\words(m)=w_1w_2w_3w_4$, there is some seamless run $\rho$ on $w_1w_2w_3$ on such that   $\weight(\rho(w_1w_2))+\charge(w_1w_2)>\weight(\rho(w_1w_2w_3))+\charge(w_1w_2w_3)+b(m)$.

    We say that the decomposition is \emph{decreasing-gap fair} (with respect to $\rho$ and $b(n)$) if there is a function $\sqrtb:\bbN\to \bbN$ with $\lim_{n\to \infty}\sqrtb(n)=\infty$ such that the decomposition $w_3=u_1\cdots u_{d(m)}$ satisfies for every $1\le i<d(m)$ that
    \[ \weight(\rho(w_1w_2u_1\cdots u_{i-1}))+\charge(w_1w_2u_1\cdots u_{i-1})>\weight(\rho(w_1w_2u_1\cdots u_{i}))+\charge(w_1w_2u_1\cdots u_{i})+\sqrtb(m)
    \]
    (note that there is no requirement on the last segment, which can be thought of as a ``remainder'').
\end{definition}
Intuitively, a decreasing-gap fair decomposition guarantees that not only the number of segments increases, but also the gap between the minimal state and $\rho$ decreases significantly with every segment (except possibly the last segment). We remark that the expressions ``$+\charge$'' should be read as ``difference from the minimal weight'', since the charge is the inverse of the minimal weight. This idea is depicted in~\cref{fig:fair decomp}

\begin{figure}[ht]
    \centering
    \includegraphics[width=0.75\linewidth]{fig/fair_decomposition.pdf}
    \caption{For visual simplicity, we assume $\rho$ is constant $0$. The overall charge in every segment decreases (with respect to $\rho$), where the minimal charge for every segment is at its end. The segments are marked by the first time the charge crosses the threshold.}
    \label{fig:fair decomp}
\end{figure}

In this section we also make use of the $\difftype$, always starting from $s_0$. 
We remind that for a word $x$ we have $\difftype_{s_0,G}(x)=\tup{\supp(\vec{c_x}),\le_x,\near_{s_0,G}(x)}$ where $\le_x$ is the relative order of the states according to $\vec{c_x}$ and $\near_{s_0,G}$ specifies which states are assigned values within gap $G$ of each other by $\vec{c_x}$. Recall that the (finite) set of all $\difftype$ is denoted $\difftypeset$.


\paragraph{Main result of this section -- overview}
Consider a decomposed sequence $\words$ that satisfies enough of the ``nice'' properties above (i.e., it is sparse with a large gap, has a cover, is ghost-free, and has a decreasing-gap fair decomposition). 
Our main result in this section is that under this assumption, the potential ($\pot$, see \cref{def:potential}) over $\Gamma_0^0$ is unbounded. 

A high-level overview of this result is given in \cref{sec:abs:from decomposition to result horror}, and is depicted in \cref{fig:proofHorror}.
We now give a slightly more technical overview, followed by the complete proof. 

Recall that for a word $w$ with a seamless baseline run, the \emph{potential} $\pot(w)$ is the gap between the maximal dominant state and the baseline, which in turn means that there is some suffix $z$ (over $\Gamma_\infty^\infty$) such that reading $z$ from the dominant state yields finite weight, but all states lower than the dominant state (after reading $w$) do not yield finite-weight run on $z$.

Under the assumptions on $\words$, consider $\words(m)=w_1w_2w_3w_4$ for some very large $m$. In particular, we take $m$ large enough so that the decomposition has a repetition of $\difftype$ in some infix $x$ of $w_3$ (this is possible since the number of segments increases with $m$).

%By the charge constraints of $\diswords$ and its fair decomposition, the minimal run $\rho_{\min}$ on $w_3$, and in particular on $x$, starts far below the baseline run, and then greatly increases. 
By our assumption, the minimal run $\rho_{\min}$ gets close to some seamless run $\rho$. For intuition purposes, it's useful to think of the minimal run as increasing and on $\rho$ as decreasing (\cref{fig:abs:proofStep1}).
Thus, there are significantly-decreasing runs, and in particular we find such runs on $x$ (note that for this we need the properties of the fair decomposition).

We then \emph{shift} our perspective so that the most decreasing seamless run $\rhoss$ becomes baseline (see Step 2). We observe that $\rhoss$ is then far above the minimal run, which is now highly increasing. Moreover, there are now no decreasing runs (\cref{fig:abs:proofStep2}).

We then show (Step 3) that under sufficient assumptions, $x$ actually induces a stable cycle $\alpha_{S',x}$ (this is the more technical part of the proof). 
Now, since the minimal run increases so much, it follows that it has no grounded pairs, and therefore attains weight $\infty$ upon reading $\alpha_{S',x}$ (see Step 4\footnote{In \cref{fig:proofHorror} we combine Steps 3 and 4, so there is an offset in the numbering, i.e. Step 5 here is Step 4 in the figure.}, depicted in \cref{fig:abs:proofStep3}). 
Intuitively, we are already close to showing that the potential is unbounded, since we have a large gap between runs, and the lower runs jump to $\infty$. However, the precise definition of potential requires the gap to be from the baseline run, not the minimal run (indeed, if e.g., $\rhoss$ is the baseline and contains the dominant state, the potential would be $0$). 

We therefore want to make the minimal run the baseline. Thus, in Step 5 we \emph{shift} again, this time making the prefix of the minimal run up to $x$ the baseline (\cref{fig:abs:proofStep4}). Then, all that remains (almost) is to construct a suffix that would attain finite value from the shifted $\rhoss$, but not from minimal run. This is achieved by using a \emph{jump letter} and $\alpha_{S',x}$.

A caveat to the above is that it uses the general alphabet $\Gamma'$, whereas we want to show the unboundedness of the potential already over $\Gamma_0^0$. Therefore, already in Step 1 we \emph{flatten} the prefix before $x$. This guarantees that all the letters before $\alpha_{S',x}$ are from $\Gamma_0^0$, a property that is maintained by shifts.

\begin{lemma}[\keyicon \lightbulbicon Decomposed Words to Unbounded Potential]
    \label{lem: decomposed seq with cover sparse no ghosts implies unbounded potential}
    Assume there exists $G,\ell\in \bbN$ and a decomposed word sequence $\words$ that is $\ell$-sparse with gap 
    $4G + (|S|+1)4\bigM W_{\max} |w_3|$ and a ghost-free decomposition $G$-cover.
    \acctodo{ACCOUNTING}
    %%%ACCOUNTING-3
    In addition, assume the decomposition is decreasing-gap fair with respect to a seamless run $\rho$ and function $b:\bbN\to \bbN$.
    Then $\sup\{\pot(w)\mid w\in (\Gamma^0_0)^*\}=\infty$.
\end{lemma}
\begin{proof}
Let $P\in \bbN$, we construct a word over $\Gamma_0^0$ whose potential is at least $P$. Let $G,\ell\in \bbN$ and $\words$ be as in the premise of the lemma, and $b,\sqrtb:\bbN\to \bbN$ and $\rho$ as per \cref{def:decreasing gap fair decomposition}. 
Let $d:\bbN\to \bbN$ be the decomposition length function, i.e., for $m\in \bbN$ and $\words(m)=w_1w_2w_3w_4$ we have $w_3=u_1\cdots u_{d(m)}$.

Take $m\in \bbN$ large enough so that $m>P$,  $d(m)>|\difftypeset_{s_0,G}|+1$ and $\sqrtb(m)>4G$. Since both $d$ and $\sqrtb$ are increasing, this is possible.
%$\simsqrtm>|\difftypeset_{s_0,G}|$ and such that $m>P$.
Consider the word $w_1w_2w_3w_4=\words(m)$ and let 
%$w_3=u_1\cdots u_{\simsqrtm}$  be its fair decomposition. 
$w_3=u_1\cdots u_{d(m)}$ be its decreasing-gap fair decomposition.


By the pigeonhole principle, there exist $0\le i_1<i_2<d(m)$ such that 
\[\difftype_{s_0,G}(w_1w_2u_1\cdots u_{i_1})=\difftype_{s_0,G}(w_1w_2u_1\cdots u_{i_2})\]
(Observe that we take $d(m)$ large enough so that we can ignore the last segment, which is a remainder).

Denote 
%$x_0=w_1w_2u_1\cdots u_{i_1-1}$ and 
$\widehat{x_0}=w_1w_2u_1\cdots u_{i_1}$ (the reason for the hat is that we modify $\widehat{x_0}$ to obtain a ``simpler'' $x_0$ below), $x=u_{i_1+1}\cdots u_{i_2}$ and $x_1=u_{i_2+1}\cdots u_{d(m)}w_4$. 

\paragraph{Step 1: flatten the prefix before $x$.}
Recall that $\Gamma'\subseteq \Gamma_\infty^0$, i.e., has no rebase letters. It follows that the letters in $w_1w_2w_3w_4$ are either in $\Gamma_0^0$ or are nested cacti. 
Let $F>2\maxeff{\widehat{x_0}x}$, we now define $x_0=\flatten(\widehat{x_0} \wr F)$.
