    \item[]\label{prelim:ap}  \textbf{Atomic Proposition:} $\pi \in \Phi$, where $\Phi$ is the set of propositional variables in an LTL expression. During LTL verification, $\pi_i$ is assigned a value by matching with a condition $c \in S$.
    \item[]\label{prelim:lifting}  \textbf{Lifting:} $\lambda$: NL $\rightarrow \Phi$, extracting substrings corresponding to APs from natural language.
    \item[]\label{prelim:grounding}  \textbf{Grounding:} $g(\pi) = c$, replacing an abstract AP in an LTL expression with a condition $c \in S$.
    \item[]\label{prelim:translation}  \textbf{Translation:} $\tau$: NL $\rightarrow$ LTL, converting a natural language string into a formal LTL expression.
    \item[]\label{prelim:verification}  \textbf{Verification:} Given a trace $\sigma$ or Kripke structure $K$, check whether a grounded LTL expression $g(\varphi)$ holds. For trace-based verification, construct a minimally satisfactory $K$ from $\sigma$. 
\end{enumerate}


