			\left( \sum_{m \in \mathcal{M}} \frac{ \eta \left( |c_{\rm u} + c_{\rm t}|^2 - |c_{\rm u}|^2 - |c_{\rm t}|^2   \right)  }{\sqrt{ \left( \left(x_{\rm u} - x_{{\rm T}, m}\right)^2  + d_{{\rm u}, m}^2 \right) \left( \left(x_{\rm t} - x_{{\rm T}, m}\right)^2  + d_{{\rm t}, m}^2 \right)   }}    \right) \label{hat_f_t}
		\end{flalign}
		\hrule
	\end{figure*}

	Problem ${\bf P}_3$ is non-convex due to the objective function \eqref{p3a} and the constraints \eqref{p3b} and \eqref{p3c}. To handle the complicated coupling among $c_{\rm u}$, $c_{\rm t}$, and $\{x_{{\rm T}, m}\}$, auxiliary variables $\{a_{{\rm u}, m} \}$, $\{b_{{\rm u}, m}\}$, $\{a_{{\rm t}, m} \}$, and $\{b_{{\rm t}, m}\}$ are introduced, and they satisfy 
	\begin{flalign}
		&\left(x_{\rm u} - x_{{\rm T}, m} \right)^2 + d_{{\rm u}, m}^2 \geq e^{-2 a_{{\rm u},m}}, \label{aum} \\
		&\left(x_{\rm u} - x_{{\rm T}, m} \right)^2 + d_{{\rm u}, m}^2 \leq e^{-2 b_{{\rm u}, m}}, \label{bum} \\
		&\left(x_{\rm t} - x_{{\rm T}, m} \right)^2 + d_{{\rm t}, m}^2 \geq e^{-2 a_{{\rm t},m}}, \label{atm}  \\
		&\left(x_{\rm t} - x_{{\rm T}, m} \right)^2 + d_{{\rm t}, m}^2 \leq e^{-2 b_{{\rm t}, m}}. \label{btm}
	\end{flalign}
	Then, \eqref{p3a}, \eqref{p3b}, and \eqref{p3c} are respectively rewritten as
	\begin{flalign}
		& \log_2\left(1 + \frac{\eta^2 g_{\rm u}({\bf L}_1) }{\sigma_{\rm u}^2}\right),  \label{p3a1}  \\
		& g_{\rm p}({\bf L}_1) \leq \frac{P_{\max}}{\eta},  \label{p3b1}  \\
		& g_{\rm t} ({\bf L}_1) \geq \frac{\Gamma_{\rm Req} \sigma_{\rm s}^2}{\beta \eta^2},  \label{p3c1}
	\end{flalign}
	where ${\bf L}_1 \triangleq \{c_{\rm u}, c_{\rm t}, x_{{\rm T}, m}, a_{{\rm u}, m}, b_{{\rm u}, m}, a_{{\rm t}, m}, b_{{\rm t}, m}  \}$ and $g_{\rm u}({\bf L}_1)$, $g_{\rm p}({\bf L}_1)$, and $g_{\rm t}({\bf L}_1)$ are given by \eqref{gu}, \eqref{gp}, and \eqref{gt}, respectively.   
	\begin{figure*}
		\begin{flalign}
			&  g_{\rm u} \left( {\bf L}_1 \right) =  |c_{\rm u}|^2 \left( \sum_{m \in \mathcal{M}} e^{2 b_{{\rm u}, m}}\right)^2 + |c_{\rm t}|^2 \left( \sum_{m \in \mathcal{M}} e^{b_{{\rm u}, m} + b_{{\rm t}, m}}\right)^2 +  |c_{\rm u}+ c_{\rm t} |^2 \left( \sum_{m \in \mathcal{M}} e^{2 b_{{\rm u}, m}}  \right)\left( \sum_{m \in \mathcal{M}} e^{b_{{\rm u}, m}+b_{{\rm t}, m}} \right) \nonumber \\
			&~ - (|c_{\rm u}|^2 + |c_{\rm t}|^2) \left(\sum_{m \in \mathcal{M}} e^{2 a_{{\rm u}, m}}   \right)\left(\sum_{m \in \mathcal{M}} e^{a_{{\rm u}, m} + a_{{\rm t}, m}  }   \right) \label{gu}  \\
			& g_{\rm p} \left( {\bf L}_1 \right) = \sum_{m \in \mathcal{M}} \left( |c_{\rm u}|^2 e^{2 a_{{\rm u}, m}} + |c_{\rm t}|^2 e^{2 a_{{\rm t}, m}} + |c_{\rm u}+ c_{\rm t} |^2 e^{a_{{\rm u}, m} + a_{{\rm t}, m}} - (|c_{\rm u}|^2 + |c_{\rm t}|^2) e^{b_{{\rm u}, m}+ b_{{\rm t}, m}} \right) \label{gp} \\
			& g_{\rm t} \left({\bf L}_1 \right) = |c_{\rm u}|^2 \left(\sum_{m \in \mathcal{M}} e^{b_{{\rm u}, m} + b_{{\rm t}, m}}  \right)^2 + |c_{\rm t}|^2 \left(\sum_{m \in \mathcal{M}} e^{2 b_{{\rm t}, m} }  \right)^2 + |c_{\rm u} + c_{\rm t}|^2 \left( \sum_{m \in \mathcal{M}}  e^{2 b_{{\rm t},m}}  \right) \left( \sum_{m \in \mathcal{M}} e^{b_{{\rm u}, m} + b_{{\rm t}, m}} \right) \nonumber \\
			& - ( |c_{\rm u}|^2 + |c_{\rm t}|^2 )\left(\sum_{m \in \mathcal{M}} e^{2 a_{{\rm t}, m} } \right) \left( \sum_{m \in \mathcal{M}} e^{a_{{\rm u}, m} + a_{{\rm t}, m} }  \right) \label{gt}
		\end{flalign}
		\hrule
	\end{figure*}
	To address the coupling between $\{c_{\rm u}, c_{\rm t}\}$ and $\{a_{{\rm u}, m}, b_{{\rm u}, m}, a_{{\rm t}, m}, b_{{\rm t}, m} \}$, the auxiliary optimization variables $p_{\rm u}$, $q_{\rm u}$, $p_{\rm t}$, $q_{\rm t}$, $o$, and $v$ are introduced and satisfy
	\begin{flalign}
		& e^{p_{\rm u}} \leq |c_{\rm u}|^2 \leq e^{q_{\rm u}}, \label{pqu} \\
		& e^{p_{\rm t}} \leq |c_{\rm t}|^2 \leq e^{q_{\rm t}}, \label{pqt} \\
		& e^{o} \leq |c_{\rm u}+c_{\rm t}|^2 \leq e^{v}. \label{ov}  
	\end{flalign}
	With the introduced $\{ p_{\rm u}, q_{\rm u}, p_{\rm t}, q_{\rm t}, o, v \}$, \eqref{p3a1}, \eqref{p3b1}, and \eqref{p3c1} are respectively re-expressed as 
	\begin{flalign}
		& \log_2\left(1 + \frac{\eta^2 \widehat{g}_{\rm u}({\bf L}_2) }{\sigma_{\rm u}^2}\right),  \label{p3a2}  \\
		& \widehat{g}_{\rm p}({\bf L}_2) \leq \frac{P_{\max}}{\eta},  \label{p3b2}  \\
		& \widehat{g}_{\rm t} ({\bf L}_2) \geq \frac{\Gamma_{\rm Req} \sigma_{\rm s}^2}{\beta \eta^2},  \label{p3c2}
	\end{flalign}
	where ${\bf L}_2 \triangleq {\bf L}_1 \cup \{p_{\rm u}, q_{\rm u}, p_{\rm t}, q_{\rm t}, o, v\}$ and $\widehat{g}_{\rm u}({\bf L}_2)$, $\widehat{g}_{\rm p}({\bf L}_2)$, and $\widehat{g}_{\rm t}({\bf L}_2)$ are given by \eqref{hat_gu}, \eqref{hat_gp}, and \eqref{hat_gt}, respectively.
	\begin{figure*}
		\begin{flalign}
			&\widehat{g}_{\rm u} ({\bf L}_2) =  e^{p_{\rm u}} \left( \sum_{m \in \mathcal{M}} e^{2 b_{{\rm u}, m}}\right)^2 + e^{p_{\rm t}} \left( \sum_{m \in \mathcal{M}} e^{b_{{\rm u}, m} + b_{{\rm t}, m}}\right)^2 +  e^{o} \left( \sum_{m \in \mathcal{M}} e^{2 b_{{\rm u}, m}}  \right)\left( \sum_{m \in \mathcal{M}} e^{b_{{\rm u}, m}+b_{{\rm t}, m}} \right) \nonumber \\
			&~ - (e^{q_{\rm u}} + e^{q_{\rm t}}) \left(\sum_{m \in \mathcal{M}} e^{2 a_{{\rm u}, m}}   \right)\left(\sum_{m \in \mathcal{M}} e^{a_{{\rm u}, m} + a_{{\rm t}, m}  }   \right) \label{hat_gu}  \\
			& \widehat{g}_{\rm p} ({\bf L}_2) = \sum_{m \in \mathcal{M}} \left( e^{2 a_{{\rm u}, m} + q_{\rm u}} +  e^{2 a_{{\rm t}, m} + q_{\rm t}} +  e^{a_{{\rm u}, m} + a_{{\rm t}, m} + v} - (e^{p_{\rm u}} + e^{p_{\rm t}}) e^{b_{{\rm u}, m}+ b_{{\rm t}, m}} \right) \label{hat_gp} \\
			& \widehat{g}_{\rm t} ({\bf L}_2) = e^{p_{\rm u}} \left(\sum_{m \in \mathcal{M}} e^{b_{{\rm u}, m} + b_{{\rm t}, m}}  \right)^2 + e^{p_{\rm t}} \left(\sum_{m \in \mathcal{M}} e^{2 b_{{\rm t}, m} }  \right)^2 + e^o \left( \sum_{m \in \mathcal{M}}  e^{2 b_{{\rm t},m}}  \right) \left( \sum_{m \in \mathcal{M}} e^{b_{{\rm u}, m} + b_{{\rm t}, m}} \right) \nonumber \\
			& -  (e^{q_{\rm u}} + e^{q_{\rm t}})\left(\sum_{m \in \mathcal{M}} e^{2 a_{{\rm t}, m} } \right) \left( \sum_{m \in \mathcal{M}} e^{a_{{\rm u}, m} + a_{{\rm t}, m} }  \right) \label{hat_gt}
		\end{flalign}
		\hrule
	\end{figure*}

	After the aforementioned reformulations, Problem ${\bf P}_3$ is rewritten as
	\begin{subequations}
		\begin{flalign}
			{{\bf P}_4}: & \mathop{\max}  \limits_{ {\bf L}_2 }~  \widehat{g}_{\rm u} ({\bf L}_2) \label{p4a}  \\
			{\rm s.t.} ~
			&\eqref{p1d}, \eqref{aum}, \eqref{bum}, \eqref{atm}, \eqref{btm}, \eqref{pqu}, \eqref{pqt}, \eqref{ov}, \eqref{p3b2}, \eqref{p3c2}.  \nonumber
		\end{flalign}
	\end{subequations}
	Problem ${\bf P}_4$ is non-convex due to the objective function \eqref{p4a} and constraints \eqref{aum}, \eqref{bum}, \eqref{atm}, \eqref{btm}, \eqref{pqu}, \eqref{pqt}, \eqref{ov}, \eqref{p3b2}, and \eqref{p3c2}. Nevertheless, these constraints can be approximated by convex functions based on the first-order Taylor approximation, which are respectively given by
	\begin{flalign}
		& \widetilde{g}_{\rm u}({\bf L}_2, \widetilde{\bf L}_2  ),  \\
		& \left(x_{\rm u} - \widetilde{x}_{{\rm T}, m} \right)^2 + 2 \left(\widetilde{x}_{{\rm T}, m} - x_{\rm u}   \right) \left( x_{{\rm T}, m} - \widetilde{x}_{{\rm T}, m}  \right) + d_{{\rm u}, m}^2 \nonumber \\
		&~~~~ \geq e^{-2 a_{{\rm u},m}}, \label{tilde_aum} \\
		& \left(x_{\rm u} - x_{{\rm T}, m} \right)^2 + d_{{\rm u}, m}^2 \leq e^{-2 \widetilde{b}_{{\rm u}, m}} \left(1 - 2 \left(b_{{\rm u}, m} - \widetilde{b}_{{\rm u}, m} \right)\right) , \label{tilde_bum} \\
		&  \left(x_{\rm t} - \widetilde{x}_{{\rm T}, m} \right)^2 + 2 \left(\widetilde{x}_{{\rm T}, m} -x_{\rm t}   \right) \left(x_{{\rm T}, m} - \widetilde{x}_{{\rm T}, m}  \right) + d_{{\rm t}, m}^2 \nonumber \\
		&~~~~ \geq e^{-2 a_{{\rm t},m}}, \label{tilde_atm}  \\
		& \left(x_{\rm t} - x_{{\rm T}, m} \right)^2 + d_{{\rm t}, m}^2 \leq e^{-2 \widetilde{b}_{{\rm t}, m}}\left(1 - 2\left(b_{{\rm t}, m} - \widetilde{b}_{{\rm t}, m}\right)  \right), \label{tilde_btm} \\
		& e^{p_{\rm u}} \leq  2 {\rm Re}\left\{\widetilde{c}_{\rm u}^{*} c_{\rm u}  \right\} - |\widetilde{c}_{\rm u}|^2,~ |c_{\rm u}|^2 \leq e^{\widetilde{q}_{\rm u}}\left(1 + q_{\rm u} - \widetilde{q}_{\rm u}\right), \label{tilde_pqu} \\
		& e^{p_{\rm t}} \leq  2 {\rm Re}\left\{ \widetilde{c}_{\rm t}^{*}  c_{\rm t}  \right\} - |\widetilde{c}_{\rm t}|^2 , ~  |c_{\rm t}|^2 \leq e^{\widetilde{q}_{\rm t}} \left(1 + q_{\rm t} - \widetilde{q}_{\rm t}\right), \label{tilde_pqt} \\
		& e^{o} \leq  2 {\rm Re}\left\{ (\widetilde{c}_{\rm u}^{*}+\widetilde{c}_{\rm t}^{*} ) (c_{\rm u} + c_{\rm t})    \right\} - |\widetilde{c}_{\rm u}+\widetilde{c}_{\rm t}|^2 , \nonumber \\
		&|c_{\rm u}+c_{\rm t}|^2 \leq e^{\widetilde{v}}\left( 1 + v - \widetilde{v}  \right), \label{tilde_ov} \\
		& \widetilde{g}_{\rm p} \left({\bf L}_2, \widetilde{\bf L}_2  \right) \leq \frac{P_{\max}}{\eta},  \label{p3b_tilde}  \\
		& \widetilde{g}_{\rm t} \left( {\bf L}_2, \widetilde{\bf L}_2 \right)\geq \frac{\Gamma_{\rm Req} \sigma_{\rm s}^2}{\beta \eta^2},  \label{p3c_tilde}
	\end{flalign}
	where 
	$$\widetilde{\bf L}_2 \triangleq \{\widetilde{c}_{\rm u}, \widetilde{c}_{\rm t}, \widetilde{x}_{{\rm T}, m}, \widetilde{a}_{{\rm u}, m}, \widetilde{b}_{{\rm u}, m}, \widetilde{a}_{{\rm t}, m}, \widetilde{b}_{{\rm t}, m}, \widetilde{p}_{\rm u}, \widetilde{q}_{\rm u}, \widetilde{p}_{\rm t}, \widetilde{q}_{\rm t}, \widetilde{o}, \widetilde{v} \}$$
	is a feasible solution to Problem ${\bf P}_4$ and $\widetilde{g}_{\rm u} ({\bf L}_2, \widetilde{\bf L}_2  )$, $\widetilde{g}_{\rm p} ({\bf L}_2, \widetilde{\bf L}_2  )$, and $\widetilde{g}_{\rm t} ({\bf L}_2, \widetilde{\bf L}_2  )$ are given by \eqref{gu_tilde}, \eqref{gp_tilde}, and \eqref{gt_tilde}, respectively.
	\begin{figure*}
		\begin{flalign}
			\widetilde{g}_{\rm u} \left({\bf L}_2, \widetilde{\bf L}_2  \right) = &~  e^{\widetilde{p}_{\rm u}}\left(\sum_{m \in \mathcal{M}} e^{2 \widetilde{b}_{{\rm u}, m}} \right) \left(\sum_{m \in \mathcal{M}} e^{2 \widetilde{b}_{{\rm u}, m}}  \left(1+p_{\rm u} + 4 b_{{\rm u}, m}  - \widetilde{p}_{\rm u} -  4  \widetilde{b}_{{\rm u}, m}    \right) \right) + e^{\widetilde{p}_{\rm t}} \left(\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m} }  \right)  \times  \nonumber \\
			&  \Bigg(\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m} }\left( 1 + p_{\rm t} + 2 b_{{\rm u}, m} + 2 b_{{\rm t}, m}  - \widetilde{p}_{\rm t} -  2 \widetilde{b}_{{\rm u}, m} - 2 \widetilde{b}_{{\rm t}, m}  \right) \Bigg)  + e^{\widetilde{o}} \left( \sum_{m \in \mathcal{M}} e^{2\widetilde{b}_{{\rm u}, m}}  \right) \times  \nonumber \\
			& \Bigg(\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m}}   \left( 1 + o + b_{{\rm u}, m} + b_{{\rm t}, m} - \widetilde{o}- \widetilde{b}_{{\rm u}, m} - \widetilde{b}_{{\rm t}, m}  \right) \Bigg) + e^{\widetilde{o}} \left(\sum_{m \in \mathcal{M}} 2 e^{2 \widetilde{b}_{{\rm u}, m}}\left(b_{{\rm u}, m} - \widetilde{b}_{{\rm u}, m}  \right)   \right) \times \nonumber \\
			& \left(\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m}   }  \right) - \left(e^{q_{\rm u}} + e^{q_{\rm t}} \right) \left(\sum_{m \in \mathcal{M}} e^{2 a_{{\rm u}, m}}  \right) \left(\sum_{m \in \mathcal{M}} e^{a_{{\rm u}, m} + a_{{\rm t}, m}  }   \right) \label{gu_tilde}  \\
			\widetilde{g}_{\rm p} \left({\bf L}_2, \widetilde{\bf L}_2  \right) = & \sum_{m \in \mathcal{M}} \left( e^{2 a_{{\rm u}, m} + q_{\rm u}} +  e^{2 a_{{\rm t}, m} + q_{\rm t}} +  e^{a_{{\rm u}, m} + a_{{\rm t}, m} + v}  \right) -\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m}} \left( \left( e^{\widetilde{p}_{\rm u}} + e^{\widetilde{p}_{\rm t}} \right)  \left( 1 + b_{{\rm u}, m} + b_{{\rm t}, m} \right. \right.
			\nonumber \\
			&\left. \left.
			- \widetilde{b}_{{\rm u}, m} - \widetilde{b}_{{\rm t}, m}   \right)  \right)   -\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m}} \left(  e^{\widetilde{p}_{\rm u}}  \left( p_{\rm u}  - \widetilde{p}_{\rm u} \right) + e^{\widetilde{p}_{\rm t}}\left( p_{\rm t} - \widetilde{p}_{\rm t}  \right)  \right) \label{gp_tilde}  \\
			\widetilde{g}_{\rm t} \left( {\bf L}_2, \widetilde{\bf L}_2 \right) = &~ e^{\widetilde{p}_{\rm u}} \left(\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m} }  \right) \left(\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m} } \left( 1 + p_{\rm u} + 2 b_{{\rm u}, m} + 2 b_{{\rm t}, m} - \widetilde{p}_{\rm u} - 2 \widetilde{b}_{{\rm u}, m} - 2 \widetilde{b}_{{\rm t}, m}   \right)  \right)  +  e^{\widetilde{p}_{\rm t}}  \times \nonumber \\
			& \left(\sum_{m \in \mathcal{M}} e^{2 \widetilde{b}_{{\rm t}, m} } \right)  \left(\sum_{m \in \mathcal{M}} e^{2 \widetilde{b}_{{\rm t}, m} } \left(1 + p_{\rm t} +  4 b_{{\rm t}, m} - \widetilde{p}_{\rm t} - 4 \widetilde{b}_{{\rm t}, m} \right)  \right) +   e^{\widetilde{o}} \left( \sum_{m \in \mathcal{M}} e^{2 \widetilde{b}_{{\rm t}, m}}  \right) \Bigg(\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m}}  \nonumber \\
			&  \left(  1 + o + b_{{\rm u}, m} + b_{{\rm t}, m} - \widetilde{o} - \widetilde{b}_{{\rm u}, m} - \widetilde{b}_{{\rm t}, m} \right)  \Bigg) + e^{\widetilde{o}} \left(\sum_{m \in \mathcal{M}} 2 e^{2 \widetilde{b}_{{\rm t}, m} } \left( b_{{\rm t}, m} -  \widetilde{b}_{{\rm t}, m}  \right) \right) \left(\sum_{m \in \mathcal{M}} e^{\widetilde{b}_{{\rm u}, m} + \widetilde{b}_{{\rm t}, m}} \right) \nonumber\\
			& - \left(e^{q_{\rm u}} + e^{q_{\rm t}} \right) \left(\sum_{m \in \mathcal{M}} e^{2 a_{{\rm t}, m}}  \right) \left(\sum_{m \in \mathcal{M}} e^{a_{{\rm u}, m} + a_{{\rm t}, m}  }   \right) \label{gt_tilde} 
		\end{flalign}
		\hrule
	\end{figure*}
	With a given $\widetilde{\bf L}_2$, Problem ${\bf P}_4$ can be approximated by the following convex optimization problem:
	\begin{subequations}
		\begin{flalign}
			{{\bf P}_5}: & \mathop{\max}  \limits_{ {\bf L}_2 }~  \widetilde{g}_{\rm u} ({\bf L}_2, \widetilde{\bf L}_2) \label{p5a}  \\
			{\rm s.t.} ~
			&\eqref{p1d}, \eqref{tilde_aum}, \eqref{tilde_bum}, \eqref{tilde_atm}, \eqref{tilde_btm}, \eqref{tilde_pqu}, \eqref{tilde_pqt}, \eqref{tilde_ov}, \eqref{p3b_tilde}, \eqref{p3c_tilde}.  \nonumber
		\end{flalign}
	\end{subequations}

	Moreover, the SCA method is applied to enhance the approximation precision by iteratively solving Problem ${\bf P}_5$ and updating $\widetilde{\bf L}_2$. 

	\section{Simulation Results}
	This section provides simulation results to 
 evaluate the proposed pinching-antenna ISAC system, compared with the conventional ISAC system. Besides, the effectiveness of 
 the proposed algorithm is also demonstrated. In our simulations, unless otherwise specified, the default configuration is detailed as follows \cite{pinch, pa_isac1, pa_isac4}. The length and width of the serving area are set as $L = 40~{\rm m}$ and $W = 20~{\rm m}$, respectively; the height of the waveguide is set as $H = 3~{\rm m}$; the speed of light is $3 \times 10^8~{\rm m/s}$ and the wavelength of carrier frequency is set as $\lambda = 5~{\rm cm}$; the effective refractive index of each dielectric waveguide is set as $n_{\rm eff} = 1.4$; the number of TPAs and RPAs are set as $M = 4$ and $N = 4$, respectively, where the TPAs and RPAs are uniformly distributed within the serving area; the transmit power budget is set as $P_{\max} = 10~{\rm W}$; the radar SNR requirement is set as $\Gamma_{\rm Req} = 4$; the noise power at the user is set as $\sigma_{\rm u}^2 = -60~{\rm dBm}$, and that at the RPAs is set as $\sigma_{\rm s}^2 = -80~{\rm dBm}$.

	\subsection{Special Case Analysis}
	In this subsection, we quantitatively analyze the impact of  relative position between the user and the target on the communication performance in the pinching-antenna  ISAC system by considering $3$ special cases with $M=2$. Specifically, for each case, the $1$-st TPA is on the waveguide $y_{{\rm T}, 1} = W/3$ and the $2$-nd TPA is on the waveguide $y_{{\rm T}, 2} = 2W/3$, while the coordinates of user and target in Case1, Case2, and Case3 are set as ${\bm \psi}_{\rm u}^{\rm I} = [L/10, 2W/5, 0]^T$ and  ${\bm \psi}_{\rm t}^{\rm I} = [-L/10, 3W/5, 0]^T$,  ${\bm \psi}_{\rm u}^{\rm II} = [L/5, 2W/5, 0]^T$ and  ${\bm \psi}_{\rm t}^{\rm II} = [-L/5, 3W/5, 0]^T$, and ${\bm \psi}_{\rm u}^{\rm III} = [3L/10, 2W/5, 0]^T$ and  ${\bm \psi}_{\rm t}^{\rm III} = [-3L/10, 3W/5, 0]^T$, respectively. Meanwhile, to validate the effectiveness of the proposed algorithm, the exhaustive search-based algorithm is adopted as a baseline, which searches the location of each TPA in the area $[-L/2, L/2]$ with the step size of $0.5~{\rm m}$. 

	\begin{figure}[htbp]
		\centering
		\subfloat[Communication rate obtained by the proposed algorithm and the exhaustive search-based algorithm versus the radar SNR requirement.]{\includegraphics[width=0.95\columnwidth]{rate_cases-eps-converted-to.pdf}}
		\hfill
		\subfloat[Optimized horizontal coordinates obtained by the proposed algorithm of TPAs versus the radar SNR requirement under each case. ]{\includegraphics[width=0.95\columnwidth]{pos_cases-eps-converted-to.pdf}}
		\hfill
		\caption{Comparison between the proposed algorithm and the exhaustive search-based algorithm with $M =2$ under Case1, Case2, and Case3.  }
		\label{fig: special_case}
	\end{figure}

%since it can achieve nearly the same system performance as the exhaustive search-based algorithm with much higher computational efficiency.  Since the path loss follows an inverse-square law with respect to the transmission distance, significant additional path loss in the TPA-user link is induced when a TPA at close proximity to the user attempts to increase TPA-user distance. 

	Fig. \ref{fig: special_case}(a) compares the proposed algorithm (marked by Prop. Alg.) and the exhaustive search-based algorithm (marked by Ex. Search) in terms of the communication rate versus the radar SNR requirement under Case1, Case2, and Case3. For each case, one can observe that the results obtained by the proposed algorithm and the exhaustive search-based algorithm are very close, which validates the effectiveness of the proposed algorithm. Besides, the communication rate under Case1 tends to decrease gradually and smoothly with the increment of radar SNR requirement. But under Case2 and Case3,  two \emph{non-smoothing regions} (characterized by abrupt rate drops) are observed. The regions correspond to the critical communication-sensing trade-off in pinching-antenna ISAC systems. 

    Analyzing the underlying causes of \emph{non-smoothing regions} is  fundamental to unraveling the operational mechanisms of pinching antennas. To this end, Fig. \ref{fig: special_case}(b) illustrates the optimal horizontal coordinates of TPAs (i.e., $x_{{\rm T}, 1}^{\star}$ and $x_{{\rm T}, 2}^{\star}$) versus the radar SNR requirement under the three cases. For each case, the increment of radar SNR requirement requires the two TPAs to approach the target sequentially to reduce the path loss for sensing.  More specifically, for Case2 and Case3, it is observed that the $2$-nd TPA intends to depart from the user when the radar SNR requirement increases from $0$ to $0.5$, while the $1$-st TPA intends to depart from the user when the radar SNR requirement increases from $4.5$ to $5$. This behavior aligns with the two \emph{non-smoothing regions} in Fig. \ref{fig: special_case}(a). The departure of TPAs from the user greatly enlarges TPA-user path loss (inverse-square with respect to the transmission distance), and thus, induces a  significant degradation in the communication rate. Furthermore, comparing the three cases reveals that a larger user-target distance not only complicates the communication-sensing trade-off but also causes the emergence of the \emph{non-smoothing regions}. %while enhancing its distinctiveness

	\subsection{Evaluation of Pinching-Antenna ISAC Systems}

	In this subsection, we evaluate the performance of pinching-antenna  ISAC systems via the comparison with the following benchmarks:
	\begin{itemize}
		\item Conventional fixed-antenna system: This setting implements each TPA at the center of the serving area, i.e., $x_{{\rm T}, m} = 0$, $\forall m \in \mathcal{M}$.
		\item User-centric antenna system: This setting aims to enhance the communication performance by deploying the TPAs near the user, i.e., $x_{{\rm T}, m} = x_{\rm u}$, $\forall m \in \mathcal{M}$.
		\item Target-oriented antenna system: This setting aims to improve the probing range by deploying the TPAs near the target, i.e., $x_{{\rm T}, m} = x_{\rm t}$, $\forall m \in \mathcal{M}$.
		\item Midpoint antenna system: This setting aims to balance the communication-sensing trade-off  by deploying the TPAs at the midpoint between the user and the target, i.e., $x_{{\rm T}, m} = (x_{\rm u}+x_{\rm t})/2$, $\forall m \in \mathcal{M}$.
	\end{itemize}

	To mitigate the impact of randomness caused by the locations of user and target on the system performance, multiple Monte Carlo realizations have been conducted with results averaged over all realizations. It is noted that if Problem ${\bf P}_1$ is infeasible to one realization, the corresponding communication rate is marked as $0$.

	\begin{figure}
		\begin{center}
			\centerline{\includegraphics[ width=.49\textwidth]{rate_P_max-eps-converted-to.pdf}}
			\caption{Comparison among the proposed pinching, the target-oriented, the midpoint, the user-centric, and the conventional antenna systems.}
			\label{fig: p_max}
		\end{center}
		\vspace{-0.4cm}
	\end{figure}

	Fig. \ref{fig: p_max} compares the pinching antenna system with the benchmarks in terms of communication performance versus the transmit power budget. It is observed that the pinching antenna system achieves the highest communication rate among all systems, and the performance gain goes larger with the transmit power budget. The reason is that the pinching antenna system facilitates the flexible large-scale adjustment of TPAs according to the locations of  the user and the target, which not only reduces the propagation loss but also provides a new degree of freedom to mitigate the communication-sensing interference. Moreover, the joint optimization of deployment and beamforming design of pinching antennas inherently outperforms the benchmarks that only optimize beamforming.  %Consequently, the pinching antenna system can achieve a more significant joint gain compared with other systems when the transmit power budget increases.

    %the pinching antenna system can dynamically optimize the TPA location distribution according to the transmit power budget, enabling adaptive generation of dual-functional beamformer, while the other systems are limited to fixed TPA distributions for beamformer synthesis.

	\begin{figure}
		\begin{center}
			\centerline{\includegraphics[ width=.49\textwidth]{rate_snr-eps-converted-to.pdf}}
			\caption{Comparison among the proposed pinching, the target-oriented, the midpoint, the user-centric, and the conventional antenna systems.}
			\label{fig: snr}
		\end{center}
		\vspace{-0.4cm}
	\end{figure}

	Fig. \ref{fig: snr} compares the  pinching antenna system with the benchmarks in terms of communication-sense region characterized by communication rate and radar SNR. One can find that the  pinching antenna system obtains the largest region that encompasses the regions achieved by benchmarks, attributed to  the extra spatial degree of freedom brought by movable TPAs. Besides, as observed, the target-oriented design achieves similar performance to the pinching antenna design for high radar SNR requirement, since the TPAs should be deployed near the target to guarantee it within the probing range. The user-centric design is competitive to the pinching antenna design for low radar SNR requirement, since it minimizes the TPA-user distance. Moreover, there exists a significant gap between the midpoint  design and the pinching antenna design, which necessitates the optimization of TPA locations.

%This observation indicates that for some situations with extremely high or low radar SNR requirements, the TPA locations can be pre-determined to reduce the computational complexity.

	\begin{figure}
		\begin{center}
			\centerline{\includegraphics[ width=.49\textwidth]{rate_n-eps-converted-to.pdf}}
			\caption{Impact of the number of RPAs on the pinching-antenna ISAC systems.}
			\label{fig: n}
		\end{center}
		\vspace{-0.4cm}
	\end{figure}

	Fig. \ref{fig: n} shows the impact of the number of RPAs on the system performance. It is observed that the communication rate obtained by all the systems increases with the number of RPAs, as more RPAs can enhance the receiving antenna gain and reduce the average RPA-target path loss. Nevertheless, the system performance cannot be infinitely improved by increasing the number of RPAs, and there exists a upper bound  (about $14.57~{\rm bit/s/Hz}$ in this case), which corresponds to solving Problem ${\bf P}_1$ with $\Gamma_{\rm Req} = 0$. Besides, the pinching antenna system is superior to benchmarks.


	\begin{figure}
		\begin{center}
			\centerline{\includegraphics[ width=.49\textwidth]{rate_m-eps-converted-to.pdf}}
			\caption{Impact of the number of TPAs on pinching-antenna ISAC systems.}
			\label{fig: m}
		\end{center}
		\vspace{-0.4cm}
	\end{figure}

	Fig. \ref{fig: m} shows the impact of the number of TPAs on the system performance. One can find that the communication performance can be improved by increasing the number of TPAs, and the performance gain is slightly greater than that obtained by increasing the number of RPAs (cf. Fig. \ref{fig: n}). The reason is that more TPAs can not only enhance the transmit antenna gain and reduce the average propagation distance to both user and target, but also bring more spatial degrees of freedom for joint deployment and  beamforming design of TPAs, resulting in a better performance gain. Furthermore, the system performance exhibits diminishing marginal gains with the increasing number of TPAs or RPAs, suggesting that when partitioning a pinching antenna array, the numbers of TPAs and RPAs should be balanced.


	\section{Conclusion}
    This paper has investigated a multi-waveguide pinching-antenna ISAC system with the aim to simultaneously detect one potential target and  serve one downlink information user. We formulated a communication rate maximization problem under the constraints of radar SNR requirement, transmit power budget, and movable area of TPAs. A novel fine-tuning method was proposed to approximate the non-convex problem with negligible performance loss. Then, the approximated problem was solved by an SCA-based algorithm. Numerical results evaluated the proposed SCA-based algorithm in comparison with the exhaustive search-based algorithm. Besides, pinching-antenna ISAC systems were shown to be superior to conventional systems and three pinching-antenna benchmarks.     Our study on multi-waveguide pinching-antenna ISAC systems yielded  insightful observations, including {\emph{non-smoothing regions}} in communication rate as the radar SNR requirement increases, and diminishing marginal performance gains with the number of TPAs or RPAs. 

    %Motivated by these findings, our future work will pursue more practical designs for pinching-antenna ISAC systems, e.g., multi-user/multi-target scenarios, specific sensing tasks, and  theoretical analysis about the advantages of pinching antenna systems.

