    \subsection{Proof of Proposition 3}

    We first prove that the influence on distance caused by fine tuning is no more than $\lambda$.  

		It is observed that $x_{{\rm T}, m}^{\star}$ should be between $x_{\rm u}$ and ${x}_{\rm t}$. Otherwise, by moving $x_{{\rm T}, m}^{\star}$ to $x_{\rm u}$ (or ${x}_{\rm t}$), both communication and sensing performance can be enhanced.

		Denote $D_{{\rm t},m}^{\star} \triangleq || {\bm \psi}_{\rm t} -  {\bm \psi}_{{\rm T}, m}^{\star} ||$ and $D_{{\rm u},m}^{\star} \triangleq || {\bm \psi}_{\rm u} -  {\bm \psi}_{{\rm T}, m}^{\star} ||$ by the distance before fine tuning, $\widehat{D}_{{\rm t},m}^{\star} \triangleq || {\bm \psi}_{\rm t} -  \widehat{\bm \psi}_{{\rm T}, m}^{\star} ||$ and $\widehat{D}_{{\rm u},m}^{\star} \triangleq || {\bm \psi}_{\rm u} -  \widehat{{\bm \psi}}_{{\rm T}, m}^{\star} ||$ by the distance after fine tuning. Due to the continuity of $\theta_m ( x_{{\rm T}, m} ) $ with respect to $x_{{\rm T}, m}$, there exists $\widehat{x}_{{\rm T}, m}^{\star}$ such that $|\theta_m \left( \widehat{x}_{{\rm T}, m}^{\star} \right) - \theta_m \left( {x}_{{\rm T}, m}^{\star} \right) | \leq 1$
		and \eqref{re_theta} holds, which indicates that
		\begin{flalign}
			\lambda & \geq \left| \widehat{D}_{{\rm t},m}^{\star} - \widehat{D}_{{\rm u},m}^{\star} -\left( {D}_{{\rm t},m}^{\star} - {D}_{{\rm u},m}^{\star}     \right)           \right| \nonumber \\
			& \geq {\max} \left\{ \left|\widehat{D}_{{\rm t},m}^{\star} - {D}_{{\rm t},m}^{\star} \right|, \left|\widehat{D}_{{\rm u},m}^{\star} - {D}_{{\rm u},m}^{\star} \right|          \right\}. \label{appro_error}
		\end{flalign}
		Assume that $\|{\bf h}_{\rm t}^{\star}\|=\|\widehat{\bf h}_{\rm t}^{\star}\|$ and $\|{\bf h}_{\rm u}^{\star}\|=\|\widehat{\bf h}_{\rm t}^{\star}\|$, we prove that $\{\widehat{c}^{\star}_{\rm u}, \widehat{c}^{\star}_{\rm t}, \widehat{x}_{{\rm T}, m}^{\star}   \}$ satisfies the constraints \eqref{p1d}, \eqref{p2b}, and \eqref{p2c}. With $\{\widehat{c}^{\star}_{\rm u}, \widehat{c}^{\star}_{\rm t}, \widehat{x}_{{\rm T}, m}^{\star}   \}$, we can obtain an objective value which is not inferior to $\{{c}^{\star}_{\rm u}, {c}^{\star}_{\rm t}, {x}_{{\rm T}, m}^{\star}   \}$.

		As shown in \eqref{appro_error}, the movement of $\{ \widehat{x}_{{\rm T},m}^{\star} \}$ is at a scale of wavelength, which can be ignored when compared with $L$. Therefore, the constraint \eqref{p1d} holds.

		Next, we show the existence of $\zeta$ (i.e., the solution to \eqref{zeta}) by proving that
		\begin{flalign}
			& \left| \left({\bf h}_{\rm t}^{\star} \right)^H {\bf h}_{\rm u}^{\star} \right| = \left| \sum_{m \in \mathcal{M}} \frac{\eta e^{ 2 \pi j \theta_m \left( x_{{\rm T}, m}^{\star} \right)}}{ D_{{\rm u}, m}^{\star}  D_{{\rm t}, m}^{\star} }  \right| \leq \sum_{m \in \mathcal{M}}   \frac{\eta }{ D_{{\rm u}, m}^{\star}  D_{{\rm t}, m}^{\star} }  \nonumber \\
			& =  \left| \sum_{m \in \mathcal{M}} \frac{\eta e^{ 2 \pi j \theta_m \left( \widehat{x}_{{\rm T}, m}^{\star} \right)}}{ \widehat{D}_{{\rm u}, m}^{\star}  \widehat{D}_{{\rm t}, m}^{\star} }  \right| = \left| \left(\widehat{\bf h}_{\rm t}^{\star} \right)^H \widehat{\bf h}_{\rm u}^{\star} \right|. \label{tri}
		\end{flalign}
		Thus, we can find $\zeta$ such that
		\begin{flalign}
			{\rm Re} \left\{ c_{\rm u}^{\star}  \left(c_{\rm t}^{\star}\right)^{*}  \left({\bf h}_{\rm t}^{\star} \right)^{H} {\bf h}_{\rm u}^{\star}  \right\}  = {\rm Re} \left\{   \widehat{c}_{\rm u}^{\star}  \left( \widehat{c}_{\rm t}^{\star}  \right)^{*} \left(\widehat{\bf h}_{\rm t}^{\star} \right)^H \widehat{\bf h}_{\rm u}^{\star}  \right\}           \label{re_equal},
		\end{flalign}
        which is equivalent to equation \eqref{zeta}.


		Combining $|\widehat{c}_{\rm u}^{\star} | = |{c}_{\rm u}^{\star}  |$, $|\widehat{c}_{\rm t}^{\star} | = |{c}_{\rm t}^{\star}  |$, and \eqref{re_equal}, one can find 
		\begin{flalign}
			f_{\rm p}\left( \widehat{c}_{\rm u}^{\star}, \widehat{c}_{\rm t}^{\star}, \{ \widehat{x}_{{\rm T}, m}^{\star}\}   \right) = f_{\rm p}\left( c_{\rm u}^{\star}, c_{\rm t}^{\star}, \{x_{{\rm T}, m}^{\star}\}   \right) \leq P_{\max},
		\end{flalign}
		which indicates that \eqref{p2b} holds. 

		Besides, by substituting \eqref{tri} and \eqref{re_equal} into the functions	$f_{\rm t}\left( \widehat{c}_{\rm u}^{\star}, \widehat{c}_{\rm t}^{\star}, \{\widehat{x}_{{\rm T}, m}^{\star} \}  \right)$ and $f_{\rm u}\left( \widehat{c}_{\rm u}^{\star}, \widehat{c}_{\rm t}^{\star}, \{\widehat{x}_{{\rm T}, m}^{\star}\}   \right)$, we reach
		\begin{flalign}
			&f_{\rm t}\left( \widehat{c}_{\rm u}^{\star}, \widehat{c}_{\rm t}^{\star}, \{ \widehat{x}_{{\rm T}, m}^{\star} \}  \right) \geq f_{\rm t}\left( c_{\rm u}^{\star}, c_{\rm t}^{\star}, \{ x_{{\rm T}, m}^{\star}\}   \right) \geq \frac{\Gamma_{\rm Req} \sigma_{\rm s}^2}{\beta}, \\
			&f_{\rm u}\left( \widehat{c}_{\rm u}^{\star}, \widehat{c}_{\rm t}^{\star}, \{ \widehat{x}_{{\rm T}, m}^{\star} \}  \right) \geq f_{\rm u}\left( c_{\rm u}^{\star}, c_{\rm t}^{\star}, \{ x_{{\rm T}, m}^{\star} \}  \right) ,
		\end{flalign}
		which shows that $\{\widehat{c}^{\star}_{\rm u}, \widehat{c}^{\star}_{\rm t}, \widehat{x}_{{\rm T}, m}^{\star}   \}$ satisfies the constraint \eqref{p2c} and obtains a objective value which is not inferior to that obtained by $\{c_{\rm u}^{\star}, c_{\rm t}^{\star}, x_{{\rm T}, m}^{\star} \}$.



