\title{Bridging Theory and Perception in Fair Division: A Study on Comparative and Fair Share Notions}

\author[1]{Hadi Hosseini}
\author[2]{Joshua Kavner}
\author[1]{Samarth Khanna}
\author[3]{Sujoy Sikdar}
\author[4]{Lirong Xia}
