        \textbf{CC DLR} & $\text{LMP}_{i} = \lambda^\text{bal} - \sum_{e\in \mathcal{E}} S_{e,i}\lambda_{e}^f$ & $\text{LMP}_{i,t} = \lambda_t^\text{bal} - \sum_{e\in \mathcal{E}} S_{e,i}\lambda_{e,t}^f$ \\
        & $\text{LMRP}_i = \frac{1}{\Sigma_\Omega^{1/2} \delta} [ \lambda_i^\alpha - 2c_{i,2}\Sigma_\Omega \alpha_i - \sum_{e\in \mathcal{E}} (\lambda_e^{\overline{F}} - \lambda_e^{\underline{F}})Q^s_{e,t}\delta ]$ & $\text{LMRP}_{i,t} = \frac{1}{\Sigma_\Omega^{1/2} \delta} [\lambda^\alpha_t - 2 c_{i,2} \Sigma_\Omega \alpha_{i,t} - \sum_{e\in \mathcal{E}}\lambda_{e,t}^{\overline{\text{th}}}  Q^m_{e,t} \delta ]$ \\
        \hline
    \end{tabular}
    \label{tab:comparison}
\end{table*}
\vspace{-1ex}
\begin{gather}
    \hat{T}_{e,t+1} = \kappa^a_{e,t+1}+ \kappa_{e,t+1}^\top \mathbf{\hat{U}}_{e,t}(\boldsymbol{\omega}_t,\boldsymbol{\varsigma}_{e,t}),\label{hatT1}
\end{gather}
where $\mathbf{\hat{U}}_{e,t}=[\hat{T}_{e,t},\hat{f}_{e,t},\hat{\mu}_{e,t}^a,\hat{\mu}_{e,t}^b,\hat{\mu}_{e,t}^c,\hat{\mu}_{e,t}^d]^\top$.

According to \eqref{MU-OPF:f}, the stochastic variable $\hat{f}_{e,t}(\boldsymbol{\omega}_t)$ can be reformulated according to deterministic value $f_{e,t}$ as: 
\vspace{-1ex}
\begin{align}\label{hatf}
    \hat{f}_{e,t}(\boldsymbol{\omega}_t) =& f_{e,t} + \Sigma_{i \in \mathcal{V}} S_{e,i}(\alpha_{i,t}\Sigma_{j\in \mathcal{W}} \boldsymbol{\omega}_{j,t} - \boldsymbol{\omega}_{i,t}) \nonumber \\
    =& f_{e,t} + \acute{\kappa}_{e,t} \alpha_t \boldsymbol{\omega}_t,
\end{align}
where $\acute{\kappa}_{e,t}$ is a matrix to transform $\Sigma_{i \in \mathcal{V}} S_{e,i}(\alpha_{i,t}\Sigma_{j\in \mathcal{W}} \boldsymbol{\omega}_{j,t} - \boldsymbol{\omega}_{i,t})$ into $\acute{\kappa}_{e,t} \alpha_t \boldsymbol{\omega}_t$ for simplicity.

Denote $\boldsymbol{\mu}_{e,t}=[\mu_{e,t}^a,\mu_{e,t}^b,\mu_{e,t}^c,\mu_{e,t}^d]^\top$, $\kappa^\mu_{e,t+1} = \frac{\mathcal{J}_{\mathcal{T}}(\breve{\boldsymbol{\mu}}_{e,t})}{\mathcal{J}_{\mathcal{T}}(\breve{T}_{e,t+1})}$, $\kappa^b_{e,t+1} = \frac{\mathcal{J}_{\mathcal{T}}(\breve{T}_{e,t})}{\mathcal{J}_{\mathcal{T}}(\breve{T}_{e,t+1})}$, $\kappa^c_{e,t+1} = \frac{\mathcal{J}_{\mathcal{T}}(\breve{f}_{e,t})}{\mathcal{J}_{\mathcal{T}}(\breve{T}_{e,t+1})}$. Combine \eqref{omega_DLR} and \eqref{hatf} with \eqref{hatT1}, we can get:
\vspace{-1ex}
\begin{align}\label{thermal_relax}
    \hat{T}_{e,t+1} - T_{e,t+1}  =& \kappa^b_{e,t+1} (\hat{T}_{e,t} - T_{e,t})  + \kappa^c_{e,t+1} \acute{\kappa}_e \alpha_t \boldsymbol{\omega}_t \nonumber \\
    &+ \kappa_{e,t+1}^{\mu\top}\gamma_{e,t} \boldsymbol{\varsigma}_{e,t} \nonumber \\
    =& \kappa^b (\hat{T}_{e,t} -  T_{e,t}) + \acute{\kappa}^c \alpha_t \boldsymbol{\omega}_t + \acute{\kappa}^d \boldsymbol{\varsigma}_{e,t},
\end{align}
where $\gamma_{e,t} = \text{diag}\{ \gamma_{e,t}^a, \gamma_{e,t}^b,\gamma_{e,t}^c, \gamma_{e,t}^e \}$, $\acute{\kappa}^c = \kappa^c_{e,t+1} \acute{\kappa}_e$, $\acute{\kappa}^d=\kappa_{e,t+1}^{\mu\top}\gamma_{e,t}$. Since $\hat{T}_{e,t+1}$ depends on $\{ \boldsymbol{\omega}_1,...,\boldsymbol{\omega}_t,\boldsymbol{\varsigma}_1,...,\boldsymbol{\varsigma}_t \}$, we introduce the auxiliary thermal reserve $R^\text{th}_{e,t}$ to relax $\hat{T}_{e,t} - T_{e,t}$:
\vspace{-3ex}
\begin{align}
    R^\text{th}_{e,t+1} &= \max_{\boldsymbol{\omega},\boldsymbol{\varsigma}} \left\{\hat{T}_{e,t+1} - T_{e,t+1}\right\} \nonumber\\
    &=\max_{\boldsymbol{\omega},\boldsymbol{\varsigma}} \left\{\kappa^b (\hat{T}_{e,t} -  T_{e,t}) + \acute{\kappa}^c \alpha_t \boldsymbol{\omega}_t + \acute{\kappa}^d \boldsymbol{\varsigma}_{e,t}\right\} \nonumber\\
    &= \kappa^b R^\text{th}_{e,t} + \acute{\kappa}^c \alpha_t \boldsymbol{\omega}_t + \acute{\kappa}^d \boldsymbol{\varsigma}_{e,t}.
\end{align}
Note that this auxiliary thermal reserve $R^\text{th}_{e,t}$ represents the spare transmission capacity and is not related  to the primary/secondary/tertiary reserve products for frequency and contingencies. This thermal reserve is introduced to solve the combined uncertainty and non-convexity. 
Then \eqref{thermal_relax} can be relaxed as:
\vspace{-1ex}
\begin{subequations}
    \begin{gather}
        R^{\text{th}}_{e,t} \geq \hat{T}_{e,t} -  T_{e,t} \\
        \begin{cases}
            R^\text{th}_{e,1} = 0 \\
            R^\text{th}_{e,t+1} \geq \kappa^b R^\text{th}_{e,t} + \acute{\kappa}^c \alpha_t \boldsymbol{\omega}_t + \acute{\kappa}^d \boldsymbol{\varsigma}_{e,t}, \text{ for }  t\geq 1.
        \end{cases}
    \end{gather}
\end{subequations}
Then \eqref{MU-OPF:f} - \eqref{MU-OPF:Tmax} can be replaced by:
\vspace{-1ex}
\begin{subequations}
    \begin{align}
        (\lambda_{e,t}^f):& f_{e,t} =  \sum_{i\in\mathcal{V}} S_{e,i}(p_{i,t}+w_{i,t}-d_{i,t}) \label{MC-OPF:f} \\
        & \mathbb{P}_{\omega,\varsigma} [ R^\text{th}_{e,t+1} \geq \kappa^b R^\text{th}_{e,t} + \acute{\kappa}^c \alpha_t \boldsymbol{\omega}_t + \acute{\kappa}^d \boldsymbol{\varsigma}_{e,t}] \nonumber \\
        & \quad \quad \quad \quad \quad \quad \geq 1-\epsilon,\forall e \in \mathcal{E}, \forall t\\
        (\lambda_{e,t}^T):& T_{e,t+1} = \kappa^a + \kappa^b T_{e,t} + \kappa^c f_{e,t} + \kappa^d \mu_{e,t}^a \nonumber \\
        & \quad \quad \quad \quad + \kappa^e \mu_{e,t}^b + \kappa^f \mu_{e,t}^c + \kappa^g \mu_{e,t}^d  \label{MC-OPF:T_evo}\\
        & R^\text{th}_{e,1} = 0 \label{MC-OPF:R_th_1} \\
        (\lambda_{e,t}^{\overline{T}}):& T_{e,t} + R^\text{th}_{e,t} \leq T^\text{max}_e.  \label{MC-OPF:T_max}
    \end{align}
\end{subequations}

Assume $\boldsymbol{\varsigma} \sim \mathcal{N}(0, \Sigma_{\varsigma})$, the vector $b_{\omega e}$ contains covariances, where $b_{\omega e,k} = \text{Cov}(\boldsymbol{\omega}_k, \varsigma_e)$. Then all chance constraints can be transformed into SOC constraints:
\vspace{-1ex}
\begin{subequations}
    \begin{align}
        (\lambda_{e,t}^{\overline{\text{re}}}):&  \Sigma_\Omega^{1/2} \delta \alpha_i \leq R^\text{up}_{i,t}, \forall i \in \mathcal{G}, \forall t \label{MC-OPF:R_up}\\
        (\lambda_{e,t}^{\underline{\text{re}}}):&  \Sigma_\Omega^{1/2} \delta \alpha_i \leq R^\text{dn}_{i,t} , \forall i \in \mathcal{G}, \forall t \label{MC-OPF:R_dn}\\
        (\lambda_{e,t}^{\overline{\text{th}}}):& \delta \left\| \begin{bmatrix}
        \Sigma_{\omega}^{1/2} \acute{\kappa}^c \alpha_t + \Sigma_{\omega}^{-1/2} \acute{\kappa}^d b_{\omega e}^\top  \\
        \sqrt{\acute{\kappa}^{d\top} \Sigma_\varsigma \acute{\kappa}^d - b_{\omega e} \acute{\kappa}^{d\top} \Sigma_{\omega}^{-1} \acute{\kappa}^d b_{\omega e}^\top}
    \end{bmatrix} \right\|_2 \leq \nonumber \\
    &\quad R^\text{th}_{e,t+1} - \kappa^b R^\text{th}_{e,t}, \forall e \in \mathcal{E}, \forall t, \label{MC-OPF:R_th}
    \end{align}
\end{subequations}
where $\delta = \Phi^{-1}(1-\epsilon)$. In \eqref{MC-OPF:R_th} ,we impose the condition $b_{\omega e} \acute{\kappa}^{d\top} \Sigma_{\omega}^{-1} \acute{\kappa}^d b_{\omega e}^\top \leq \acute{\kappa}^{d\top} \Sigma_\varsigma \acute{\kappa}^d$ to ensure the non-negativity of the expression under the square root, which captures the variance of $\text{DLR}_e$, where $\sigma_{\varsigma}^2$ denotes its intrinsic variance, and $b_{\omega e} \acute{\kappa}^{d\top} \Sigma_{\omega}^{-1} \acute{\kappa}^d b_{\omega e}^\top$ quantifies the contribution from correlated wind uncertainty $\boldsymbol{\omega}$. This assumption reflects the physical observation that DLR is more sensitive to local weather conditions rather than to remote ones.

The initial multi-period CC DC-OPF problem in \eqref{MU-OPF} can be reformulated as:
\vspace{-1ex}
\begin{align}\label{MC-OPF}
    \min_\mathcal{P} &\quad \sum_{t}\sum_{i\in \mathcal{G}} c_{i,2}[p_{i,t}^2+\Sigma_{\Omega} \alpha_{i,t}^2] + c_{i,1}p_{i,t} \\
    &\quad \alpha_{i,t} \geq 0, (\text{\ref{MU-OPF:bal}}), (\text{\ref{MU-OPF:alpha}}), (\text{\ref{MU-OPF:gmax}}), (\text{\ref{MU-OPF:gmin}}), (\text{\ref{MU-OPF:UP}}), (\text{\ref{MU-OPF:DN}}), \nonumber\\
    & \quad(\text{\ref{MC-OPF:f}}), (\text{\ref{MC-OPF:T_evo}}), (\text{\ref{MC-OPF:R_th_1}}), (\text{\ref{MC-OPF:T_max}}), (\text{\ref{MC-OPF:R_up}}), (\text{\ref{MC-OPF:R_dn}}), (\text{\ref{MC-OPF:R_th}}) \nonumber,
\end{align}
where $\mathcal{P} = \{ p_{i,t},\alpha_{i,t},f_{e,t},T_{e,t},R^\text{up}_{i,t}, R^\text{dn}_{i,t}, R^\text{th}_{e,t}  \}$, and then the reformulated problem \eqref{MC-OPF} is convex.

Using \eqref{MC-OPF}, we obtain the LMP and LMRP at node $i$:
\vspace{-1ex}
\begin{subequations}\label{MC-OPF:LMP}
    \begin{equation}
        \text{LMP}_{i,t} = \frac{\partial\mathcal{L}}{\partial d_{i,t}}=\lambda_t^\text{bal} - \sum_{e\in \mathcal{E}} S_{e,i}\lambda_{e,t}^f \label{MC-OPF:LMPa}
    \end{equation}
    \vspace{-2ex}
    \begin{equation}
        \text{LMRP}_{i,t} = \frac{\partial \mathcal{L}}{\partial (R_{i,t}^\text{up} + R_{i,t}^\text{dn})} = {\lambda_{i,t}^{\overline{\text{re}}}} + \lambda_{i,t}^{\underline{\text{re}}}, \label{MC-OPF:LMPb}
    \end{equation}
\end{subequations}
which can be derived due to partial KKT conditions:
\vspace{-1ex}
\begin{subequations}\label{Multi_KKT}
\begin{align}
    (p_{i,t}):& 2c_{i,2} p_{i,t} + c_{i,1} - \lambda^\text{bal}_t + \lambda_{i,t}^{\overline{p}} - \lambda_{i,t}^{\underline{p}} - \lambda_{i,t}^{\overline{\text{rr}}} + \lambda_{i,t}^{\underline{\text{rr}}} \nonumber\\
    &+ \lambda_{i,t-1}^{\overline{\text{rr}}} - \lambda_{i,t-1}^{\underline{\text{rr}}} + \sum_{e\in \mathcal{E}}S_{e,i}\lambda_{e,t}^f = 0 \label{Multi-KKT:p}\\
    (\alpha_{i,t}):&  2 c_{i,2} \Sigma_\Omega \alpha_{i,t} -\lambda^\alpha_t + ({\lambda_{i,t}^{\overline{\text{re}}}} + \lambda_{i,t}^{\underline{\text{re}}})\Sigma_\Omega^{1/2} \delta \nonumber\\
    &+ \sum_{e\in \mathcal{E}}\lambda_{e,t}^{\overline{\text{th}}}  Q^m_{e,t} \delta = 0\label{Multi-KKT:a} \\
    (f_{e,t}):& \lambda_{e,t}^f - \kappa_{e,t}^c \lambda_{e,t}^T = 0\\
    (T_{e,t}):& \lambda_{e,t-1}^T - \kappa^b_{e,t}+\lambda_{e,t}^{\overline{T}}=0,
\end{align}
\end{subequations}
where $Q_{e,t}^m = \frac{\acute{\kappa}^{c\top} \Sigma_{\omega} \acute{\kappa}^c \alpha_t + \Sigma_{\omega}^{-1} \acute{\kappa}^d b_{\omega e}^\top}{\left\| \begin{bmatrix}
        \Sigma_{\omega}^{1/2} \acute{\kappa}^c \alpha_t + \Sigma_{\omega}^{-1/2} \acute{\kappa}^d b_{\omega e}^\top  \\
        \sqrt{\acute{\kappa}^{d\top} \Sigma_\varsigma \acute{\kappa}^d - b_{\omega e} \acute{\kappa}^{d\top} \Sigma_{\omega}^{-1} \acute{\kappa}^d b_{\omega e}^\top}
    \end{bmatrix} \right\|_2}$.
Then we can reformulate the LMPs and LMRPs as:
\vspace{-1ex}
\begin{subequations}
    \begin{align}
    \text{LMP}_{i,t} =& \lambda_t^\text{bal} -\frac{1}{2}\sum_{e\in\mathcal{E}}S_{e,i} \times \nonumber\\
    \vspace{-3pt}
    &\left[\kappa_{e,t+1}^b \lambda_{e,t+1}^T \!-\! \lambda_{e,t+1}^{\overline{T}} \!+\! \frac{\lambda_{e,t-1}^T \!+ \! \lambda_{e,t}^{\overline{T}}}{\kappa_{e,t}^b}\right]
    \end{align}
    \vspace{-4pt}
    \begin{equation}
    \text{LMRP}_{i,t} = \frac{1}{\Sigma_\Omega^{1/2} \delta} [\lambda^\alpha_t - 2 c_{i,2} \Sigma_\Omega \alpha_{i,t} - \sum_{e\in \mathcal{E}}\lambda_{e,t}^{\overline{\text{th}}}  Q_{e,t} \delta ], \label{MC-OPF:LMRP}
    \end{equation}
\end{subequations}
which shows that the LMPs at time $t$ are affected by the thermal state and power flow at both time $t-1$ and time $t+1$, indicating that LMPs are influenced by the time-varient interdependency introduced by DLRs. In LMPRs, $\lambda_i^\alpha$ is reserve balance price, $2c_{i,2} \Sigma_\Omega\alpha_i$ is local generator reserve cost, and $\sum_{e\in \mathcal{E}}\lambda_{e,t}^{\overline{\text{th}}}  Q_{e,t} \delta$ is reserve delivery cost.

We now show that the LMP and LMRP formulations in \eqref{MC-OPF:LMP} and \eqref{MC-OPF:LMRP} naturally induce a market equilibrium.

\begin{theorem}[Market equilibrium for single-period OPF]\label{theorem:market_multi}
Let $\{ p_{i,t}^*, \alpha_{i,t}^*, f_{e,t}^*, T_{e,t}^*, R_{i,t}^{\text{up}*}, R_{i,t}^{\text{dn}*},R_{i,t}^{\text{th}*}\}$ be the optimal solution of the problem in \eqref{MC-OPF} and let $\{\pi_i^*, \tau_i^*\}$ be the LMP and LMRP calculated by \eqref{MC-OPF:LMP} and \eqref{MC-OPF:LMRP} respectively. Then $\{ p_{i,t}^*, \alpha_{i,t}^*, f_{e,t}^*, T_{e,t}^*, R_{i,t}^{\text{up}*}, R_{i,t}^{\text{dn}*},R_{i,t}^{\text{th}*}, \pi_i^*, \tau_i^*\}$ constitutes a market equilibrium, i.e.:
\begin{itemize}
\item The market clears at $\sum_{i\in \mathcal{G}}p_{i,t}+\sum_{i\in \mathcal{W}}w_{i,t}-\sum_{i\in \mathcal{V}}d_{i,t}=0 $ and $\sum_{i\in \mathcal{G}}\alpha_{i,t} = 1$
\item Each producer maximizes its profit under the payment $\Gamma_{i} = \sum_{t} \pi^*_{i,t} p_{i,t}^* + \tau_{i,t}^* \alpha_{i,t}^*$
\hfill \qed

\end{itemize}
\end{theorem}

The proof is given in Appendix \ref{app:market_multi}. Theorem \ref{theorem:market_multi} implies that, given the LMPs and LMRPs computed from \eqref{MC-OPF:LMP} and \eqref{MC-OPF:LMRP}, each generator, acting as a price taker, maximize its individual profit while the overall social welfare is maximized as formulated in \eqref{MC-OPF}.

