\subsection{Detailed expression for $g(\cdot)$}\label{app:detailed DLR}

1) Solar heat gains are formulated as:
\vspace{-1ex}
\begin{equation}
    q_s = \alpha_s Q_{s} D,
\end{equation}
where $\alpha_s$ is solar absorptivity, $Q_{s}$ is total solar radiated heat intensity, $D$ is diameter of conductor.

2) Joule heat gains are given by electric power losses as:
\vspace{-1ex}
\begin{equation}
    q_J = R_c I_c^2 = R_a I_c^2 + \alpha_T  R_{ref} T_x I_c, \label{qj}
\end{equation}
where $R_c$ is conductor resistance at temperature $T_c$. $R_a$ is DC resistance at ambient temperature $T_a$. $\alpha_T$ is temperature coefficient of resistance and $R_{ref}$ is DC resistance at a reference temperature, $T_{ref}$. We denote the difference between current and ambient temperatures as $T_x = T_c - T_a$.

3) Radiated heat losses are computed as:
\vspace{-1ex}
\begin{subequations}
    \begin{equation}
    q_r = \pi D h_r T_x
\end{equation}
\begin{equation}
    h_r = \varepsilon \sigma_B (4T_A^3 + 6T_xT_A^2 + 4T_x^2 T_A + T_x^3),
\end{equation}
\end{subequations}
where $T_A = T_a + 273$. $h_r$ is radiative cooling coefficient. $\varepsilon$ is emissivity. $\sigma_B$ is the Stefan-Boltzmann constant.


4) Convective heat losses are given by:
\vspace{-1ex}
\begin{equation}
    q_c = \pi \lambda_f N_u (T_c - T_a) = \pi D h_c T_x, \label{qc}
\end{equation}
where $\lambda_f$ is thermal conductivity of air. $N_u$ is Nusselt number based on wind speed. $h_c$ is convective cooling coefficient.

5) Dynamic Line Rating: Given the gains and losses above, steady-state DLRs can be computed as:
\vspace{-2pt}
\begin{equation}
    f_c^\text{max} = g(T_c^\text{max}) = V_c \cdot \sqrt{\frac{q_c(T_c^\text{max})+q_r(T_c^\text{max})-q_s}{R_a + \alpha_T R_{ref} T_x }}.
\end{equation}

\subsection{Proof of Theorem \ref{theorem:DLR-tran}}\label{app:DLR-tran}
We first consider the steady-state condition in \eqref{bal} and consider the radiated cooling coefficient $h_r$. Since $T_A \gg T_x$, the last two terms of $h_r$ can be ignored, which is $4 T_x^2 T_A + T_x^3$. Then we can get our new radiative cooling coefficient:
\vspace{-1ex}
\begin{gather}
    h'_r = h_{r0} + k_1 T_x \\
    q_r = (\pi D h'_r + \Delta r)T_x, \label{qr}
\end{gather}
where $h_{r0} = 4 \sigma_B \varepsilon (T_a + 273)^3$, $k_1 = 6 \sigma_B \varepsilon(T_a + 273)^2$, which is independent of the conductor temperature, and $\Delta r = \pi D (4 T_x^2 T_A + T_x^3)$, is a relatively small positive quantity.

Furthermore, we set $T_c = T_c^{\text{max}}$ to get the worst-case steady-state heating balance:
\vspace{-1ex}
\begin{equation}\label{Rmax}
    R_\text{max} I_c^2 + q_s = \pi D[h_c + h_{r0} +k_1 (T_c^\text{max} - T_a)] T_x + \Delta r T_x,
\end{equation}
where $R_\text{max}$ is conductor temperature at thermal rating $T_\text{max}$. For simplification, we let $M_{cr} = \pi D[h_c + h_{r0} +k_1 (T_c^\text{max} - T_a)]$. When near thermal rating, Joule heating is considerably more than solar heating. So we let $\Delta s = \frac{q_s}{M_{cr} I_c^2}$. Then we can get:
\vspace{-1ex}
\begin{equation} \label{k2}
    T_x = (\frac{R_\text{max} + \Delta s}{M_{cr} + \Delta r}) I_c^2 \approx k_2 I_c^2,
\end{equation}
where $k_2 = \frac{R_\text{max}}{M_{cr}}$. Substituting \eqref{qj}, \eqref{qc}, \eqref{qr} into \eqref{bal}, we can get the exact formulation:
\vspace{-1ex}
\begin{equation}
    [\pi D (h_c + h'_r) + \Delta r] T_x = \alpha_s Q_s D + R_a I_c^2 + \alpha_T R_{ref}I_c^2 T_x
\end{equation}
\vspace{-5ex}
\begin{gather}
    [\pi D (h_c + h_{r0}) + \Delta r] T_x = \alpha_s Q_s D + R_a I_c^2 + \nonumber\\
    \alpha_T R_{ref} I_c^4(\frac{R_\text{max} + \Delta s}{M_{cr} + \Delta r}) -\pi D k_1 I_c^4 (\frac{R_\text{max} + \Delta s}{M_{cr} + \Delta r})^2. \label{Delta}
\end{gather}

We assume the influence of $\Delta r$ and $\Delta s$ in \eqref{Delta} is ignorable. Then we quantify and compare their influence respectively. Define function $F_1(\Delta r, \Delta s)$:
\vspace{-1ex}
\begin{align}
    F_1(\Delta r, \Delta s) =& \alpha_T R_{ref} I_c^4(\frac{R_\text{max} + \Delta s}{M_{cr} + \Delta r}) \nonumber\\
    & -\pi D k_1 I_c^4 (\frac{R_\text{max} + \Delta s}{M_{cr} + \Delta r})^2 - T_x \Delta r \label{F1_detail} \\
    =& \tilde{b}_1 (\frac{R_\text{max} + \Delta s}{M_{cr} + \Delta r}) - \tilde{b}_2 (\frac{R_\text{max} + \Delta s}{M_{cr} + \Delta r})^2 - T_x \Delta r . \nonumber 
\end{align}
Substituting \eqref{F1_detail} into \eqref{Delta}, we have:
\begin{equation}
    \pi D(h_c + h_{r0})T_x = \alpha_s Q_s D + R_a I_c^2 + F_1(\Delta r, \Delta s).
\end{equation}

Then we want to show $F_1(\Delta r, \Delta s) < F_1(0,0) = \alpha_T R_{ref} \frac{R_\text{max}}{M_{cr}} - \pi D k_1 (\frac{R_\text{max}}{M_{cr}})^2$. We conduct first order Taylor expansion at point $(0,0)$:
\vspace{-1ex}
\begin{equation}
    F_1(\Delta r, \Delta s) \!=\! F_1(0,0) \!+\! \Delta r \frac{\partial F_1(\Delta r, \Delta s)}{\partial \Delta r} \!+\! \Delta s \frac{\partial F_1(\Delta r, \Delta s)}{\partial \Delta s}.
\end{equation}

We calculate the derivative of $F_1(\Delta r, \Delta s)$ to $\Delta r$ and $\Delta x$:
\vspace{-1ex}
\begin{subequations}\label{Approxi:deltars}
\begin{equation}
    \frac{\partial F_1(\Delta r, \Delta s)}{\partial \Delta r} \!= \!-\! \tilde{b}_1 \frac{R_\text{max} \!+\! \Delta s}{(M_{cr} \!+\! \Delta r)^2} \!+\! 2\tilde{b}_2 \frac{(R_\text{max} \!+\! \Delta s)^2}{(M_{cr} \!+\! \Delta r)^3} \!-\! T_x
\end{equation}
\vspace{-3.5ex}
\begin{equation}
    \frac{\partial F_1(\Delta r, \Delta s)}{\partial \Delta s} = \frac{\tilde{b}_1}{M_{cr} + \Delta r} - 2 \tilde{b}_2 \frac{R_\text{max} + \Delta s}{(M_{cr} + \Delta r)^2}.
\end{equation}
\end{subequations}
So the sufficient condition is:
\vspace{-1ex}
\begin{equation}\label{proof:static}
    \Delta r \frac{\partial F_1(\Delta r, \Delta s)}{\partial \Delta r} + \Delta s \frac{\partial F_1(\Delta r, \Delta s)}{\partial \Delta s}< 0,
\end{equation}
which can be verified by numerical computation.

We then consider to impose transient process. For \eqref{Rmax}, we denote the difference between the transient $T_c$, given $I_c$ and maximum values as $\Delta T = T_c^\text{max} - T_c$, $\Delta I = I_c^\text{max} - I_c$. Then we can reformulate the heating balance as:
\vspace{-1ex}
\begin{gather}
    (I_c + \Delta I)^2 R_{\text{max}} + q_s = (M_{cr} + \Delta r)(T_c^\text{max} - T_a)\\
    T_x = (\frac{R_{\text{max}} + \Delta s}{M_{cr} + \Delta r})(I_c + \Delta I)^2 - \Delta T.
\end{gather}
Substituting this equality into \eqref{trans}, we can get:
\vspace{-1ex}
\begin{align}
    mc\frac{dT_c}{dt} = & \alpha_s Q_s D + R_a I_c^2 - \pi D (h_c + h_{r0}) T_x \nonumber \\
    & + \alpha_T R_{ref}I_c^2 T_x - \pi D k_1 T_x^2 - \Delta r T_x \\
    = & \alpha_s Q_s D + R_a I_c^2 - \pi D (h_c + h_{r0}) T_x - \Delta r T_x \nonumber \\
    & + \alpha_T R_{ref}I_c^2 \left[ (\frac{R_{\text{max}} + \Delta s}{M_{cr} + \Delta r})(I_c + \Delta I)^2 - \Delta T \right] \nonumber \\
    & - \pi D k_1 \left[ (\frac{R_{\text{max}} + \Delta s}{M_{cr} + \Delta r})(I_c + \Delta I)^2 - \Delta T \right]^2 .\nonumber
\end{align}

We disregard the small terms: $\Delta r$, $\Delta s$, $\Delta T$ and $\Delta I$. If \eqref{proof:static} is satisfied, $\Delta r$ and $\Delta s$ can be neglected. Then we consider $\Delta T$, $\Delta I$. Define $F_2(\Delta T,\Delta I)$:
\vspace{-1ex}
\begin{align}
    F_2(\Delta T,\Delta I) =& \alpha_T R_{ref}I_c^2 \left[ \frac{R_{\text{max}}}{M_{cr}}(I_c + \Delta I)^2 - \Delta T \right] \nonumber \\
    & - \pi D k_1 \left[ \frac{R_{\text{max}}}{M_{cr}}(I_c + \Delta I)^2 - \Delta T \right]^2
\end{align}
\begin{equation}
    = \hat{b}_1 \frac{R_\text{max}}{M_{cr}}(I_c + \Delta I)^2 - \hat{b}_1 \Delta T  
    - \hat{b}_2 \left[ \frac{R_{\text{max}}}{M_{cr}}(I_c + \Delta I)^2 - \Delta T \right]^2. \nonumber
\end{equation}

Then we have:
\vspace{-1ex}
\begin{equation}
    mc\frac{dT_c}{dt} \!<\! \alpha_s Q_s D \!+\! R_a I_c^2 \!-\! \pi D (h_c \!+\! h_{r0}) T_x \!+\! F_2(\Delta T, \Delta I).
\end{equation}
So if we show $F_2(\Delta T, \Delta I) < F_2(0,0) = \alpha_T R_{ref} \frac{R_\text{max}}{M_{cr}} - \pi D k_1 (\frac{R_\text{max}}{M_{cr}})^2$, then Theorem 1 stands. We conduct the first order Taylor expansion at point $(0,0)$:
\vspace{-2ex}
\begin{align}
    F_2(\Delta T, \Delta I) =& F_2(0,0) + \Delta T \frac{\partial F_2(\Delta T, \Delta I)}{\partial \Delta T} \nonumber\\
    &+ \Delta I \frac{\partial F_2(\Delta T, \Delta I)}{\partial \Delta I}.
\end{align}
We calculate the derivative of $F_2(\Delta T, \Delta I)$ to $\Delta T$ and $\Delta I$ and get the sufficient condition:
\vspace{-1ex}
\begin{equation}\label{proof:trans}
    \Delta T \frac{\partial F_2(\Delta T, \Delta I)}{\partial \Delta T} + \Delta I \frac{\partial F_2(\Delta T, \Delta I)}{\partial \Delta I} < 0.
\end{equation}

Furthermore, by discretizing the time intervals, we obtain the conservative temperature evolution:
\vspace{-1ex}
\begin{equation}
    T_{t+1} < h(T_t, f_t) = \hat{b}'_0 + \hat{b}'_1 T_t + \hat{b}'_2 f_t^2 + \hat{b}'_3 f_t^4,
\end{equation}
where $\mu^a = [\alpha_s Q_s D + \pi D (h_c + h_{r0}) T_a] \frac{\delta t}{mc}$, $\mu^b = 1 + \frac{\pi D (h_c + h_{r0})\delta t}{mc}$, $\mu^c = \frac{R_a\delta t}{mcV_c^2}$, $\mu^d = [\alpha_T R_{ref} \frac{R_\text{max}}{M_{cr}} - \pi D k_1 (\frac{R_\text{max}}{M_{cr}})^2]\frac{\delta t}{mcV_c^4}$. $\delta t$ is the time interval.

\subsection{Proof of Theorem \ref{theorem:market_single}}\label{app:market_single}

For the generator in node-$i$, its objective is to maximize the revenue under energy price $\pi$ and reserve price $\tau$:
\vspace{-1ex}
\begin{subequations}
\begin{align}
    \max_{\{p_i,R_i^\text{up}, R_i^\text{dn}\}} \quad& \pi p_i+\tau(R_i^\text{up} + R_i^\text{dn}) -c_{i,1}p_i-c_{n,2}p_i^2  \label{GEN:obj}\\
    \quad
    & p_i + R_i^\text{up} \leq p^\text{max}_i \quad:(\nu^+_i) \label{GEN:Pmax}\\
    & p_i - R_i^\text{dn}\geq p^\text{min}_i  \quad:(\nu^-_i), \label{GEN:Pmin}
\end{align}
\end{subequations}
which is to maximize a concave problem. The partial KKT conditions can be calculated as:
\vspace{-1ex}
\begin{subequations}
    \begin{align}
        (p_i):& -\pi + c_{i,1} + 2c_{i,2}p_i + \nu_i^+ - \nu_i^- =0\label{KKT-CC:gen:p}\\
        (R_i^\text{up}):& -\tau + \nu_i^+ = 0\label{KKT-CC:gen:a}\\
        (R_i^\text{dn}):& -\tau + \nu_i^- = 0.\label{KKT-CC:gen:a-}
    \end{align}
\end{subequations}

The equilibrium for $p_i$ and $\text{LMP}_i$ can be reached when $\pi = \text{LMP}_i$ based on \eqref{LMP:CC}, \eqref{KKT-CC:sys:a}, and \eqref{KKT-CC:gen:a}. The equilibrium for $R_i^\text{up}$, $R_i^\text{dn}$ and $\text{LMRP}_i$ can be reached according to \eqref{LMRP:CC}, \eqref{KKT-CC:sys:a}, \eqref{SOC:LMRP}, \eqref{KKT-CC:gen:a} and \eqref{KKT-CC:gen:a-}.

\subsection{Proof of Theorem \ref{theorem:market_multi}} \label{app:market_multi}

For the generator in node-$i$, its objective is to maximize the revenue under energy price $\pi$ and reserve price $\tau$:
\vspace{-1ex}
\begin{subequations}
\begin{align}
    \max_{\{p,R^\text{up}, R^\text{dn}\}} &\! \sum_t \pi p_{i,t} \!+\! \tau(R_{i,t}^\text{up} \!+\! R_{i,t}^\text{dn}) \!-\! c_{i,1}p_{i,t} \!-\! c_{i,2}p_{i,t}^2  \label{GEN-multi:obj}\\
    (\nu^+_t):& p_{i,t} + R_{i,t}^\text{up} \leq p^\text{max}_i \label{GEN-multi:Pmax}\\
    (\nu^-_t):& p_{i,t} - R_{i,t}^\text{dn}\geq p^\text{min}_i   \label{GEN-multi:Pmin} \\
    (\eta_t^+):& p_{i,t+1} - p_{i,t} + R^\text{up}_{i,t+1} + R^\text{dn}_{i,t} \leq U_i^\text{up} \label{GEN-multi:UP}\\
    (\eta_t^-):& p_{i,t+1} - p_{i,t} - R^\text{dn}_{i,t+1} - R^\text{up}_{i,t} \geq -U_i^\text{dn},\label{GEN-multi:DN}
\end{align}
\end{subequations}
which is to maximize a concave problem. The partial KKT conditions can be calculated as:

\vspace{-1ex}
\begin{subequations}
\vspace{-15pt}

    \begin{align}
        (p_{i,t}):& -\pi + c_{i,1} + 2c_{i,2}p_i + \nu_i^+ - \nu_i^- - \eta_t^+ \nonumber\\
        &\quad+ \eta_t^- + \eta_{t-1}^+ - \eta_{t-1}^-=0\label{KKT-CC:gen-multi:p}\\
        (R_{i,t}^\text{up}):& -\tau + \nu_i^+ + \eta_{t-1}^+ + \eta_t^- = 0\label{KKT-CC:gen-multi:a}\\
        (R_{i,t}^\text{dn}):& -\tau + \nu_i^- + \eta^+_t + \eta^-_{t-1}= 0.\label{KKT-CC:gen-multi:a-}
    \end{align}
\end{subequations}

The equilibrium for $p_{i,t}$ and $\text{LMP}_{i,t}$ can be reached when $\pi = \text{LMP}_{i,t}$ based on \eqref{MC-OPF:LMPa}, \eqref{Multi-KKT:p}, and \eqref{KKT-CC:gen-multi:p}. The equilibrium for $R_{i,t}^\text{up}$, $R_{i,t}^\text{dn}$ and $\text{LMRP}_{i,t}$ can be reached according to \eqref{MC-OPF:LMPb}, \eqref{Multi-KKT:a}, \eqref{MC-OPF:LMRP}, \eqref{KKT-CC:gen-multi:a} and \eqref{KKT-CC:gen-multi:a-}.

