\subsection{Other distributive fairness}
\label{subsec:lit3}

\begin{definition}[Fairness through unawareness \citep{dwork2012fairness,grgic2016case,kusner2017counterfactual,gajane2017formalizing}]
A predictor is said to achieve \emph{fairness through unawareness (FTU)} (or unconscious/unaware fairness) if all protected attributes $\mathcal{A}$ are excluded from the decision-making process. 

Despite its compelling simplicity, this approach has a clear shortcoming: the remaining attributes $\mathcal{X}$  may contain discriminatory information analogous to $\mathcal{A}$ that may not be obvious at first, acting as \emph{proxy} attributes. As a result, discrimination cannot be guaranteed to be eliminated. 

\end{definition}



\begin{definition}[False positive (FP) subgroup fairness, \ie{} $\gamma$-subgroup fairness \citep{kearns2018preventing,kearns2019empirical}]
\label{def:gamma_subgroup}
\begin{equation}
\topequation\small
    \alpha_\text{FP}(f) \cdot
    \beta_\text{FP}(f)
    \leqslant \gamma
    \,,\label{eq:sub,sf}
\end{equation}
where
\begin{subequations}
\topequation\small
\begin{align}
    \alpha_\text{FP}(f) &= \probP( a_1=0, y=0 ) \,,\\
    \beta_\text{FP}(f) &=|\hspace{1em} 
    \probP( f(\xneg,a_1)=1 \mid y=0 )
    \nonumber\\&\hspace{1.4em} 
    -\probP( f(\xneg,a_1)=1 \mid a_1=0,\, y=0 )
    | \,.
\end{align}%
\end{subequations}%
\end{definition}

\begin{definition}[Calibration \citep{pleiss2017fairness,kleinberg2016inherent}]
\label{def:calibration}
For two binary predictors $h_1,h_0: \mathbb{R}^{n_d+1}\mapsto[0,1]$, $h_1$ classifies samples with $a_1\!=\!1$ and $h_0$ does samples with $a_1\!=\!0$. Any $h_t \,(t\in\{1,0\})$ is perfectly calibrated if 
\begin{equation}
    \topequation\small
    \forall p\in[0,1],\, 
    \mathbb{P}_{(\xneg,a_i=t,y)}(
        y=1\mid h_t(\xneg,a_1)=p
    )=p \,.\nonumber
\end{equation}
It intuitively prevents the probability scores from carrying group-specific information. 
\end{definition}



\begin{definition}[Multicalibration \citep{hebert2018multicalibration,gohar2023survey}]
For any individual $i\!\in\! \mathcal{X}$, some unknown probability $p_i^*\!\in\![0,1]$ is assumed to exist, and there is no assumptions on the structure of $p^*\!: \mathcal{X}\!\mapsto\![0,1]$. Particularly, enough uncertainty is assumed to exist in the outcomes that it may be hard to learn $p^*$ directly. 
Let $\mathcal{D}$ denote the distribution over individuals, supported on $\mathcal{X}$; for $D_j\!\subseteq\! \mathcal{X}$, let $i\!\sim\! D_j$ denote a sample drawn from $\mathcal{D}$ conditioned on membership in $j$ where $j\!\in\!\mathcal{A}_1$ represent a subgroup \wrt{} $a_1$. 
Then for any $\alpha\!>\!0$ and $D_j\!\subseteq\! \mathcal{X}$, 
a predictor $h$ is $\alpha$-accurate-in-expectation (AE) \wrt{} $a_1$ if 
\begin{equation}
\topequation\small
| \mathbb{E}_{i\in D_j}[ h_i-p_i^* ] | \leqslant \alpha 
\,.\nonumber
\end{equation}

For any $v\!\in\![0,1]$, $D_j\!\subseteq\! \mathcal{X}$, and predictor $h$, let $S_v\!=\! \{i\!: f_i\!=\!v\}$. Then for $\alpha \!\in\! [0,1]$, $h$ is $\alpha$-calibrated with respect to $D_j$ if there exists some $S'\subseteq D_j$ with $\mathbb{P}_{i\sim\mathcal{D}} [i\in S'] \geqslant (1-\alpha) \cdot \mathbb{P}_{i\sim\mathcal{D}}[i\in D_j]$ such that for all $v\in[0,1]$,
\begin{equation}
\topequation\small
| \mathbb{E}_{i\sim S_v \cap S'} [h_i-p_i^*] | \leqslant\alpha
\,;\nonumber
\end{equation}
Note that $\alpha$-calibration \wrt{} $D_j$ implies $2\alpha$-AE \wrt{} $D_j$.

Let $\mathcal{C}\subseteq 2^\mathcal{X}$ be a collection of subsets of $\mathcal{X}$ and $\alpha\in[0,1]$. 
A predictor $h$ is $(\mathcal{C},\alpha)$-multicalibrated if for all $S\in\mathcal{C}$, $h$ is $\alpha$-calibrated with respect to $S$. 
\end{definition}




\begin{definition}[Bounded group loss \citep{agarwal2019fair}]
\label{def:bounded_grplos}
\begin{equation}
\topequation\small
    \mathbb{E}[ \ell(y,f(\xneg,a_1)) \mid a_1=j ]
    \leqslant\xi \,
    ,\;\forall j\in[n_{a_1}] \,,\nonumber
\end{equation}
at level $\xi$, where the loss $\ell\!:\mathcal{Y}\!\times\![0,1] \!\mapsto\![0,1]$, measuring the accuracy, is required to be $1$-Lipschitz under the $\ell_1$ norm.\footnote{
That is, $|\ell(y,u)-\ell(z,v)| \leqslant |y-z|+|u-v| \,,\; \forall y,z,u,v \,.$
} 
\end{definition}



\begin{definition}[Group benefit ratio and worst-case min-max ratio \citep{ghosh2021characterizing}]
Group benefit ratio for one subgroup is defined as
\begin{equation}
\topequation\small
\mathrm{GBR}_j =\frac{
    \probP( f(\xneg,a_1)=1 \mid a_1=j )
}{  \probP( y=1 \mid a_1=j ) } \,,\nonumber
\end{equation}
and using the worst case, min-max ratio definition, group benefit ratio ($\mathrm{GBR\_INT}$) is defined intersectionally as
\begin{equation}
\topequation\small
\mathrm{GBR\_INT} =\frac{
    \min\{ \mathrm{GBR}_j , j\in [n_{a_1}] \}
}{
    \max\{ \mathrm{GBR}_j , j\in [n_{a_1}] \}
} \,.
\end{equation}
\end{definition}


\begin{definition}[Strategic minimax fairness \citep{diana2024minimax}]
A classifier $h\in\mathcal{H}$ satisfies ``$\gamma$-minimax fairness'' with respect to the distribution $\mathsf{D}$ if it minimises the maximum group error rate up to an additive factor of $\gamma$. In other words,
\begin{equation}
\topequation\small
\max_{g\in\mathcal{A}_1} \ell_g(h) \leqslant
\min_{h'\in\mathcal{H}} \max_{g\in\mathcal{A}_1} \ell_g(h')+\gamma \,.
\end{equation}
Note that the distribution $\mathsf{D}$ exists over the data domain $\mathcal{X}\times\mathcal{A}_1\times\mathcal{Y}$, and $\mathsf{D}_g$ denotes the conditional distribution of $(\mathbf{x},y)$ conditioned on the group $g\in\mathcal{A}_1$. 
Also note that the overall error rate of $h$ and its corresponding group error rate for the group $g$ are defined as follows,
\begin{small}
\begin{subequations}
\topequation
\begin{align}
\ell(h) &\defineq \mathbb{P}_{(\mathbf{x},g,y)\sim \mathsf{D}} [h(\mathbf{x},g)\neq y] \,,\\
\ell_g(h) &\defineq \mathbb{P}_{(\mathbf{x},y)\sim \mathsf{D}_g}[ h(\mathbf{x},g)\neq y ] \,.
\end{align}%
\end{subequations}%
\end{small}%
\end{definition}


\begin{definition}[Discriminative risk \citep{bian2023increasing_alt}]
\label{def:my,dr}
\begin{equation}
    \topequation\small
    \mathrm{DR}(f)= \probE[
    \mathbb{I}( f(\xneg,\xpos)\neq f(\xneg,\xqtb) )
    ] \,,\label{eq:my,dr}
\end{equation}
where $\xqtb$ is the perturbed $\xpos$, and $n_a\geqslant 1, |\mathcal{A}_i|\geqslant 2 \,(i\in[n_a])$. 
\end{definition}

\begin{definition}[Harmonic fairness via manifold \citep{bian2024does,bian2024approximating}]
\label{def:my,hfm}
Given a dataset $D=(\mathsf{X,A,Y})$, it has three versions: (1) the \emph{previous} HFM for one bi-valued SA, and (2) the \emph{maximal (resp. average)} HFM for several multi-valued SAs. 

For one bi-valued SA $a_1\!\in\! \mathcal{A}_1 \!=\!\{0,1\}$, $D$ is divided into $D_1\!=\! \{ (\xneg_a,y)\defineq (\xneg,a_1,y)\in D\mid a_1=1\}$ and $\bar{D}_1\!=\! D\!\setminus\! D_1$, then given a specific distance metric $\dist(\cdot,\cdot)$ (\eg{} the standard Euclidean metric), the previous HFM is 
\begin{equation}
\topequation\small
    \mathrm{HFM}_\text{prev}(f) =
    \sfrac{ \disf_f(D_1,\bar{D}_1) }{ \disf(D_1,\bar{D}_1) }
    -1 \,,
\end{equation}
where 
\begin{equation}
\topequation%\small
\footnotesize
\begin{split}
    \disf_\cdot( D_1,\bar{D}_1;\newy )=\max\{
    & \max_{(\xneg_a\!,y)\in D_1} \min_{(\xneg_a'\!,y')\in \bar{D}_1} \dist((\xneg,\newy),(\xneg',\newy')) \\
    & \max_{(\xneg_a'\!,y')\in \bar{D}_1} \min_{(\xneg_a\!,y)\in D_1} \dist((\xneg,\newy),(\xneg',\newy'))
    \} ,\nonumber 
\end{split}
\end{equation}
and $\disf_f(D_1,\bar{D}_1)\!=\! \disf_\cdot( D_1,\bar{D}_1;f(\xneg,a_1) ) ,\, \disf(D_1,\bar{D}_1)\!=\! \disf_\cdot( D_1,\bar{D}_1;y )$ are two abbreviations for brevity. 


For one or more multi-valued SAs $\xpos\in\mathcal{A}$ where $n_a\!\geqslant\! 1$ and $|\mathcal{A}_i|\!\geqslant\! 2 \,(i\!\in\![n_a])$, 
the maximal (resp. average) HFM are 
\begin{subequations}
\topequation\small
\begin{align}
    \mathrm{HFM}(f) &= \log\left(
    \sfrac{ \disf_{f,\xpos}(D) }{ \disf_{\xpos}(D) }
    \right) \,,\\
    \mathrm{HFM}^\text{avg}(f) &= \log\left(
    \sfrac{ \disf_{f,\xpos}^\text{avg}(D) }{ \disf_{\xpos}^\text{avg}(D) }
    \right) \,,
\end{align}%
\end{subequations}%
where
\begin{subequations}
\topequation%\small
\footnotesize
\begin{align}
    \disf_{\cdot,\xpos}(D;\newy) &= %\textstyle
    \max_{1\leqslant i\leqslant n_a} 
    \disf_{\cdot,\xpos}(D,a_i;\newy) \,,\\
    \disf_{\cdot,\xpos}^\text{avg}(D;\newy) &=
    \textstyle
    \frac{1}{n_a}\sum_{i=1}^{n_a}
    \disf_{\cdot,\xpos}^\text{avg}(D,a_i;\newy) \,,%\\
\end{align}%
\end{subequations}%
\begin{subequations}
\topequation\footnotesize
\begin{align}
    \disf_{\cdot,\xpos}(D,a_i;\newy) &\!=\!
    \max_{i\in [n_{a_i}]}\{
        \! \max_{(\xneg_a\!,y)\in D_j}
        \! \min_{(\xneg_a'\!,y')\in \bar{D}_j} 
        \! \dist((\xneg,\newy),(\xneg',\newy'))
    \},\nonumber\\
    \disf_{\cdot,\xpos}^\text{avg}(D,a_i;\newy) &\!=\!
    \frac{1}{n} %\textstyle 
    \! \sum_{j\in[n_{a_i}]} 
    \! \sum_{(\xneg,y)\in D_j}
    \! \min_{(\xneg',y')\in \bar{D}_j}
    \! \dist((\xneg,\newy),(\xneg',\newy'))
    .\nonumber
\end{align}%
\end{subequations}%
Note that $D_j\!=\! \{(\xneg_a,y)\!\in\! D| a_i\!=\!j \} ,\, \bar{D}_j\!=\! D\!\setminus\! D_j,$ and special case $\disf_{\cdot,\xpos}(D,a_i;\newy) \!=\! \disf_\cdot(D_1,\bar{D}_1;\newy)$ when $\mathcal{A}_i \!=\! \{0,1\}$. 
\end{definition}












\subsection{Procedural fairness \citep{grgic2016case,grgic2018beyond}}
\label{subsec:lit4}
Here we use $D$ to denote the set of all instances/members (or queried users of society), and $S$ the set of all possible features that might be used in the decision-making process (in other words, $|S|\! \leqslant\! n_d+n_a$). 
Given a set of features $S'$, let $f_{S'}$ denote the classifier that uses those features $S'$. 

\begin{definition}[Feature-apriori fairness]
\label{def:procedural,1}
For a given feature $s\in S$, let $D_s\subseteq D$ denote the set of all members that consider the feature $s$ fair to use \emph{without a priori knowledge} of how its usage affects outcomes. 
Then
\begin{equation}
    \topequation\small
    \mathrm{PF}_\text{apr}(f_{S'}) \defineq
    \frac{| \bigcap_{s_i\in S'} D_{s_i} |}{|D|}
    \,.\label{eq:pcd,1}
\end{equation}
\end{definition}

\begin{definition}[Feature-accuracy fairness]
\label{def:procedural,2}
Let $D_s^\text{acc} \!\subseteq\! D$ denote the set of all members that consider the feature $s$ fair to be use \emph{if it increases the accuracy of the classifier}. 
Note that typically $D_s \!\subseteq\! D_s^\text{acc}$ is expected, though this need not always hold exactly (due to either noise in estimating member preferences, or some members attaching some sort of negative connotation to the notion of accuracy). 
Then
\begin{equation}
    \topequation\small%
    \mathrm{PF}_\text{acc}(f_{S'}) \defineq
    \frac{| \bigcap_{s_i\in S'} \mathrm{Cond}(D_{s_i}, D_{s_i}^{\text{acc}}) |}{|D|}
    \,,\label{eq:pcd,2}
\end{equation}
where
\begin{equation*}
    \topequation\footnotesize
    \mathrm{Cond}( D_{s_i}, D_{s_i}^{\text{acc}} )
    \!=\! \begin{cases}
        D_{s_i} ,\hspace{1.4em}\text{ if } \acc(f_{S'})\leqslant \acc(f_{S'\setminus\{s_i\}}) ;\\
        D_{s_i} \bigcup D_{s_i}^\text{acc} =D_{s_i}^\text{acc} ,\text{ otherwise} \,.\\
    \end{cases}
\end{equation*}
\end{definition}

\begin{definition}[Feature-disparity fairness]
\label{def:procedural,3}
Let $D_s^\text{disp} \subseteq D$ denote the set of all members that consider the feature $s$ fair to use \emph{even if it increases a measure of disparity} (\ie{} disparate impact or disparate mistreatment) of the classifier. 
Typically $D_s^\text{disp} \subseteq D_s$ is expected, though this need not always hold strictly due to estimation error or other reasons. 
Let $\mathrm{disp}(f_{S'})$ denote the disparity it induces, and then
\begin{equation}
    \topequation\small
    \mathrm{PF}_\text{disp}(f_{S'}) \defineq
    \frac{| \bigcap_{s_i\in S'} \mathrm{Cond}( D_{s_i},D_{s_i}^\text{disp} ) |}{|D|}
    \,,\label{eq:pcd,3}
\end{equation}
where
\begin{equation*}
    \topequation\footnotesize
    \mathrm{Cond}( D_{s_i},D_{s_i}^\text{disp} )
    \!=\! \begin{cases}
        D_{s_i}^\text{disp} ,\hspace{.9em}\text{ if } \mathrm{disp}(f_{S'})> \mathrm{disp}(f_{S'\setminus\{s_i\}}) ;\\
        D_{s_i} \bigcup D_{s_i}^\text{disp} =D_{s_i} ,\text{ otherwise} \,.
    \end{cases}
\end{equation*}
\end{definition}


These three measures accommodate scenarios with multiple SAs, each potentially having multiple values. Despite this advantage, they rely heavily on features and on a set of members/users who perceive these features as fair, which may still introduce hidden discrimination or human prejudice. Moreover, their computation is complex and time-consuming, as user judgments may evolve with learning, limiting their practical applicability. 
%
Additionally, \citet{wang2024procedural} proposed an FAE-based (feature attribution explanation) metric to assess group procedural fairness, which depends on the specific FAE techniques employed. 










\begin{definition}[FAE-based group procedural fairness \citep{wang2024procedural}]
\label{def:procedural,4}
A given dataset $D$ is divided into two subsets by the values of a single SA, that is, $D_1\!=\!\{ (\mathbf{x}_i,a_{1i},y_i)\!\in\! D| a_{1i}\!=\!1 \}$ and $D_2\!=\!\{ (\mathbf{x}_i,a_{1i},y_i)\!\in\! D| a_{1i}\!=\!0 \}$. 
A local FAE function $g(\cdot)$ takes a model $f(\cdot)$ and an explained data point $(\mathbf{x}_i,a_{1i})$ as inputs and returns explanations (\ie{} feature importance scores) $\mathbf{e}_i\!=\! g(f,\mathbf{x}_i,a_{1i}) \!\in\!\mathbb{R}^{n_d+1}$, where its $j$-th component $e_{ij}$ is the importance score of the feature $x_{ij}$ for the model's prediction $f(\mathbf{x}_i,a_{1i})$. 
For a distance measure $d_e(\cdot,\cdot)$ between two sets of FAE explanation results $E_1$ and $E_2$, then
\begin{equation}
\topequation\footnotesize
\begin{split}
\mathrm{GPF}_\text{FAE} &= d_e(E_1,E_2) \,;\\
E_1 &= \{ \mathbf{e}_i \mid%|
    \mathbf{e}_i= g(f,\mathbf{x}_i,a_{1i}), 
    (\mathbf{x}_i,a_{1i})\in D_1^\prime
\}\,,\\
E_2 &= \{ \mathbf{e}_j \mid%|
    \mathbf{e}_j= g(f,\mathbf{x}_j,a_{1j}), 
    (\mathbf{x}_j,a_{1j})\in D_2^\prime
\}\,,
\end{split}%
\end{equation}%
where $D_1^\prime$ and $D_2^\prime$ are sets of $n$ data points from $D_1$ and $D_2$, respectively, generated by \citep[Algorithm 1]{wang2024procedural}. 
\end{definition}















\subsection{Additional}

\begin{definition}[$\epsilon$-BER (balanced error rate) fairness \citep{feldman2015certifying}]
A dataset $D=(X,A_1,Y)$ is said to be $\epsilon$-fair if for any classification algorithm $f'\!: \mathcal{X\mapsto A}_1$,
\begin{equation}
\topequation\small
    \mathrm{BER}(f'(\xneg),a_1) 
    >\epsilon \,,\nonumber
\end{equation}
with (empirical) probabilities estimated from $D$, where
\begin{equation}
\topequation\footnotesize
\begin{split}
    \mathrm{BER}( f'(\xneg),a_1 )\defineq
    \tfrac{1}{2} [
        &\hspace{1.2em} \probP( f'(\xneg)=0 \mid a_1=1 )\\
        &+ \probP( f'(\xneg)=1 \mid a_1=0 )
    ]\nonumber
\end{split}
\end{equation} 
is the (unweighted) average class-conditioned error of $f'(\cdot)$. 

Note that it is not used to assess predictors, unlike others. 
\end{definition}

\begin{definition}[Intersectional fairness without demographics \cite{gohar2023survey}]
The fairness objective to minimise the worst-case loss can be formulated as
\begin{equation}
\topequation\small
\mathcal{L}_{\max}(f) =
\max_{a_i\in \mathcal{A}}
\probE[ \ell(f;X) ] \,,\nonumber
\end{equation}
where $\probE[\ell(f;X)]$ is the expected loss for a loss function \eg{} log loss. 
Note that it is not used to evaluate unfairness level of ML models, in other words, not a fairness measure. 
\end{definition}




\subsection{Brief summary}
\label{subsec:lit5}
We have summarised all existing fairness definitions or measures in Table~\ref{tab:fair,summary}, and will emphasise some notes here. 







\begin{remark}
Demographic parity (DP), disparate impact, disparate treatment, conditional statistical parity, and bounded group loss all meet the independence\footnote{%
%
Statistical non-discrimination criteria are properties of the joint distribution of a SA $\mathsf{A}$, target variable $y$, the classifier $f(\cdot)$ or score $\mathsf{R}$, sometimes including features $\mathsf{X}$. 
The three key criteria are: 
1) \emph{independence} (Random variables $(\mathsf{A,R})$ satisfy independence if $\mathsf{A\indep R}$); 
2) \emph{separation} (Random variables $(\mathsf{R,A,Y})$ satisfy separation if $\mathsf{R\indep A\mid Y}$); 
3) \emph{sufficiency} (Random variables $(\mathsf{R,A,Y})$ satisfy sufficiency if $\mathsf{Y\indep A\mid R}$). 
These criteria are rarely satisfied all at once, except in degenerate cases \citep{barocas2019fairness}.  
%
} criterion \citep{barocas2019fairness,barocas2023fairness}. 
Their original definitions only apply to a single bi-valued SA, yet there is potential for extension to a multi-valued SA. 
Taking DP as an example, the first two possible extensions focus on the difference or parity between unprivileged group(s) and one privileged group, that is, 
%
\begin{subequations}
\topequation\small
\begin{align}
\mathrm{DP}^{(1)}(f) &=|
    \hspace{1.3em} \probP( \poslbl\mid a_1\neq 1) \nonumber\\
    &\hspace{1.7em} -\probP( \poslbl\mid a_1=1)
| \,,\label{eq:grp,ext,a}\\
\mathrm{DP}^{(2)}(f) &=
\prival[|
    \hspace{1.2em} \probP( \poslbl\mid a_1=j ) \nonumber\\
    &\hspace{4.6em} -\probP( \poslbl\mid a_1=1 )
|] \nonumber\\
&= \mathbb{E}_{j\neq 1}[|
    \hspace{1.2em} \probP( \poslbl\mid a_1=j ) \nonumber\\
    &\hspace{4em} -\probP( \poslbl\mid a_1=1 )
|] \,,\label{eq:grp,ext,b}
\end{align}%
\label{eq:grp,extend}%
\end{subequations}%
where the privileged group is known.  
The third and fourth possible extensions also take the symmetrical property of a general metric into account, and are designed as 
\begin{subequations}
\topequation\small
\begin{align}
\mathrm{DP}^{(3)}(f) &=\textstyle
\tfrac{1}{n_{a_1}} \sum_{j=1}^{n_{a_1}} | 
    \hspace{3mm} \probP( \poslbl\mid a_1\!\neq \!j ) \nonumber\\
    &\hspace{19mm} -\probP( \poslbl\mid a_1\!=\!j )
| \,,\label{eq:grp,alt,a}\\
\mathrm{DP}^{(4)}(f) &= \textstyle
\!\binom{n_{a_1}}{2} \!\sum_{j_a=1}^{n_{a_1}\!-\!1} \!\sum_{j_b\!=\! j_a\!+\!1}^{n_{a_1}} |
    \probP( \poslbl| a_1\!=\!j_b ) \nonumber\\
    &\hspace{2.7cm} -\probP( \poslbl\mid a_1\!=\!j_a )
| \,.\label{eq:grp,alt,b}
\end{align}%
\label{eq:grp,extend,alter}%
\end{subequations}%
The extension of other group fairness measures can be made analogously. 
More detailed formulations for each fairness measure are provided in Appendix~\ref{appx:extension}. 
Note that these extensions still only apply for one single multi-valued SA.\footnote{%
For multiple (bi-valued or multi-valued) SAs (\ie{} $\mathcal{A}= \mathcal{A}_1\times\mathcal{A}_2\times...\times\mathcal{A}_{n_a}$ with $n_a\geqslant 2$ and $n_a, n_{a_i}\in\mathbb{Z}_+ \,(i\in[n_a])$), we continue using DP as an example, 
\begin{subequations}
\topequation\scriptsize
\begin{align}
\mathbf{DP}^{(5)}(f) &=
\max\{ \mathrm{DP}^{(k)}(f;a_i) \mid i\in[n_a] \}
\,,\\
\mathbf{DP}^{(6)}(f) &= \textstyle
\frac{1}{n_a} \sum_{i=1}^{n_a} 
\mathrm{DP}^{(k)}(f;a_i) \,,\\
\mathbf{DP}^{(7)}(f) &=\textstyle
\tbinom{\prod_i n_{a_i}}{2}^{-1} \sum_{\xpos_b\neq \xpos_a} 
|\probP(\poslbl\mid \xpos=\xpos_b) \nonumber\\
&\hspace{2.6cm} -\probP(\poslbl\mid \xpos=\xpos_a)|
\,,
\end{align}%
\label{eq:grp,multiple}%
\end{subequations}%
where $k$ could be one of $\{1,2,3,4\}$. 
} 







Independence is often the easiest one to apply mathematically and algorithmically, but it can also lead to undesirable outcomes (as seen in real-world phenomena termed the \emph{glass cliff}).%
\footnote{%
For instance, consider a company hiring from two groups at the same rate: group A (carefully selected applicants) and group B (carelessly selected applicants). Despite identical acceptance rates, group B is more likely to include less qualified hires, resulting in worse performance outcomes and a negative track record for that group. 
This disparity could occur without malice---perhaps the company has historically hired more from group A, providing better insights into that group. Moreover, having more training data for group A may reduce error rates in classifiers for that group. Finally, distinguishing between the groups assumes their heterogeneity, which may not hold. 
%
} Similar issues can arise with other statistical criteria. 
\end{remark}

\begin{remark}
Equalised odds (EOdd), equality of opportunity (EO), predictive equality, and $\gamma$-subgroup fairness are all considered to meet the separation criterion \citep{barocas2019fairness,barocas2023fairness}. 
They require that all groups experience the same false negative rate, which is associated with denied opportunities when acceptance is desired. 
There remains the possibility of extending these measures to scenarios for one multi-valued SA, analogous to \eqref{eq:grp,extend} and \eqref{eq:grp,extend,alter}. 
\end{remark}

\begin{remark}
Predictive parity (PP), on the other hand, satisfies the sufficiency criterion \citep{barocas2019fairness,barocas2023fairness}, which is closely related to the concept of calibration. 
\end{remark}


\begin{remark}
Both counterfactual fairness (CFF) and proxy discrimination (PD) heavily rely on causal graphs, meaning that the analysis cannot proceed if the algorithm under investigation is not a causal model. 
Furthermore, their definitions are not inherently quantitative, though they may potentially be extended to quantitative measures, such as
\begin{subequations}
\topequation\small
\begin{align}
    \mathbb{E}_{\xpos' \neq\xpos}[|
        &\hspace{1.3em} \probP( f_{\mathsf{A}\gets \xpos}(\cffU)=y \mid \mathsf{X}=\xneg, \mathsf{A}=\xpos )\nonumber\\
        &- \probP( f_{\mathsf{A}\gets \xpos'}(\cffU)=y \mid \mathsf{X}=\xneg, \mathsf{A}=\xpos)
    |] \,,\\
    \mathbb{E}_{\mathbf{p}' \neq\mathbf{p}}[|
        & \probP(f| \mathrm{do}( \mathsf{P}\!=\!\mathbf{p}), \mathsf{X}\!=\!\xneg)
        - \probP(f| \mathrm{do}( \mathsf{P}\!=\!\mathbf{p}'), \mathsf{X}\!=\!\xneg)
    |]\,.
\end{align}%
\end{subequations}%
However, these still apply only to a single SA; if multiple SAs are involved in CFF, they must be preprocessed into the form of one SA before assessment. 
\end{remark}

\begin{remark}
All three initial procedural fairness measures \citep{grgic2016case,grgic2018beyond} depend critically on member judgments regarding the use of individual features in decision-making. These member judgments may change over time, leading to unpredictable computational costs.
\end{remark}









\section{Alternative Views and Our Positions}
\label{sec:alter}
In this section, we will list some alternative views and give our arguments in turn. 



\subsection{Why do we need more designed fairness measures given many that we already have in the literature?}
\label{sec:multi}




Performance-based metrics (such as accuracy, recall, and precision) have traditionally dominated the assessment of ML models/algorithms in classification tasks, especially before the emergence of trustworthy AI. 
Even today, many people dismiss research focused on fairness or trustworthy AI as secondary or less valuable, asking, ``What is the point if the model's accuracy is not state-of-the-art?'' 
Our answer is that technology alone is not the key to societal progress. Advanced technologies without ethical considerations may lead to far more severe consequences than outdated technologies that are developed with ethical care. 
It is the responsibility of scientists to ensure that advanced technologies are developed with ethical care, ultimately benefiting society.\looseness=-1 







Developing fair ML models and addressing existing discrimination are crucial components of trustworthy ML research, and many scholars have dedicated their efforts to this area. 
One prevailing opinion is that instead of creating new computational methods for measuring fairness, it would be more valuable to develop tools that assist researchers in making decisions about their ML pipelines based on fairness measures. 
However, developing tools to assist researchers in mitigating bias has an implicit premise that one must understand clearly what fairness means so that they can develop tools to raise fairness. 
If the meaning of fairness is not clearly understood or a proper definition is not in place, a proper measurement of fairness will not follow. Besides, 
if fairness is raised in model training as one of the optimisation objectives, the purpose of raising fairness may not be fulfilled as well if the chosen measure is not very suitable for the scenario that learning tasks are facing. 


Unlike accuracy, which is universally understood, 
the concept of fairness is interdisciplinary, with broadly varying definitions across fields such as law, politics, social sciences, mathematics, computer science, statistics, economics, and philosophy. 
Even within machine learning and artificial intelligence, there are multiple fairness definitions/measures (discussed in Section~\ref{sec:relat}), and choosing one that suits every case is challenging. After all, meeting all three fairness criteria---independence, separation, and sufficiency---simultaneously is difficult \citep{barocas2023fairness,saravanakumar2020impossibility,kleinberg2016inherent}. 
Wouldn't it be counterproductive to guide the ML pipeline using fairness measures that are less suitable or improperly chosen, especially when fairness is an objective in the learning process? 
More importantly, a significant challenge lies in our limited understanding of the extent of discrimination within data or models. This makes it difficult to determine which fairness measure is the most appropriate. Even if we settle for using existing fairness measures, there is still significant room for improvement. 








