\begin{definition}[$\BSSK$ machines] \label{def:shorterBSSK}
    Let $K$ be a semiring.    
    A $\BSSK$ machine $M$
    computes a (possibly partial) \emph{input-output} function $f_M \colon K^*\to K^*$ represented by a directed graph of nodes labelled by $1, \ldots, N$. These nodes are of five different types.
    A configuration of the machine $M$ at any moment of computation consists of a node $m\in \{1, \ldots ,N\}$ and a current state $x \in K_*$, proceeding as follows.
    %The computation of the machine $M$ proceeds in the following manner.
    %\begin{itemize}

        %\item
        The node labelled by $1$ is the unique \emph{input node} and is associated with a next node $\beta(1)$.
        Here, the input $(x_1, \ldots ,x_n) \in K^*$ of the machine is initialized as
        \[
            (\ldots , 0, \underbrace{1, \dots, 1}_{n}, 0\textbf{.} x_1, \ldots ,x_n, 0,\ldots )\in K_*.
        \]
        %where the length $n$ is encoded in unary in the first negative coordinates.

        %\item
        Each \emph{computation node} $m$ is associated with a next node $\beta(m)$ and a mapping $g_m\colon K_* \to K_*$ such that $g_m(x)_l=x_l$, for $l \neq i$,
        %and on coordinate $i$ one of the following holds:
        %\[
        %    (g_m(x))_i =x_j+x_k,\quad
        %    (g_m(x))_i = x_j\cdot x_k,\quad
        %    (g_m(x))_i = c.
        %\]
        and $g_m(x)_i$ is one of $x_j+x_k$, $x_j\cdot x_k$, or $c$, for some $c \in K$ and $i,j,k\in \mathbb{Z}$.
        %\teemuS{Rephrase: the choice of operation does not depend on $x$, only the end result does.}

        %\item
        Every \emph{branch node} $m$ is associated with nodes $\beta^-(m)$ and $\beta^+(m)$.
        Given $x\in K_*$ the next node is $\beta^-(m)$ if $x_1 = x_2$ and $\beta^+(m)$, otherwise.
        If $K$ is ordered, instead the next node is $\beta^-(m)$ if $x_1 \leq x_2$ and $\beta^+(m)$, otherwise.

        %\item
        A \emph{shift node} $m$ is associated either with $\sigma_l$ or $\sigma_r$, and a next node $\beta(m)$.

        %\item
        The node labelled by $N$ is the unique \emph{output node}.
        Once this node is reached, the computation halts resulting in the string consisting of the first $l$ positive coordinates, where $l$ is the number of consecutive $1$s stored in the negative coordinates starting from the first negative coordinate.
        %For instance,
        %\[
        %    (\ldots ,2,1,1,1,0\textbf{.}x_1, x_2,x_3,x_4,\ldots ) \text{ results in } (x_1, x_2,x_3).
        %\]
    %\end{itemize}
    %The (sometimes partial) \emph{input-output} function $f_M \colon K^*\to K^*$ of the machine $M$ is now defined in the obvious manner.
    %
    %A function $f \colon K^*\to K^*$ is \emph{computable} if $f=f_M$ for some machine $M$. A language $L \subseteq K^*$ is \emph{decided} by a $\BSSK$ machine $M$ if its characteristic function $\chi_L \colon K^* \to K^*$ is $f_M$.
\end{definition}

