    %\]
     %where $x$ and $y$ are variables, $\bar{x}$ is a tuple of variables such that $\ar(R)=|\bar{x}|$. 
     \[
    \phi\ddfn x = y \mid  x \neq y \mid R(\bar{x})\mid \neg R(\bar{x}) \mid \phi \circ \phi \mid(\phi\wedge\phi) \mid (\phi\lor\phi) \mid \exists x\phi \mid \forall x\phi,
    \]
     where $x,y\in\Var$, $R\in\tau$, $\bar{x}$ is a tuple of variables so that $\ar(R)=|\bar{x}|$, and $\circ\in O$. 
\end{definition}
%\juha{We need to allow nesting of the formula equalities/inequalities, Minna: Fixed.}
If $O=\emptyset$, we write $\FO$ instead of $\FO(\emptyset)$. 
