    %a constant
    $c \in \N$ such that
    for each $x \in K^*$, the machine $M'$ runs on input $x$ in time $c(t(|x|) + |x|^2 + |f(x)|^2 + 1)$
    %and in space $cs(|x|) + c$.
    and in space $c(s(|x|) + 1)$.
    %where $y \in K^*$ is the output of $M$ on $x$.
\end{theorem}
