\subsection{OUR CONTRIBUTIONS} 
 In this work, we are interested in recovering the ``uncorrupted'' Gaussian distribution given samples from a ``corrupted'' distribution (according to our missingness model). We use a population maximum likelihood approach as the estimation algorithm, and apply projected stochastic gradient descent on the likelihood function. We give theoretical proof of fast convergence in the parameter space. 

A {\em missingness model} is defined by a function $\obs: \R^d \to 2^{[d]}$. For an underlying $d$-dimensional vector $\mb{y}$, $\obs(\mb{y})$ is interpreted as the set of coordinates of $\mb{y}$ that are not missing. An observation is a pair $(A, \mb{x})$, where $A = \obs(\mb{y})$ and $\mb{x} = \mb{y}_A$ for an underlying sample $\mb{y} \in \R^d$.


\subsubsection{DISTRIBUTION LEARNING UNDER THE SELF-CENSORING MECHANISM} \label{sec:self censoring}
\paragraph{Self-censoring Missingness Model.}
\textcolor{black}{The Self-censoring mechanism is commonly encountered in practice. In this model the missingness of an outcome is affected by its underlying value. For example, smokers are not willing to report their smoking behavior in insurance applications. Voters holding particular beliefs may not disclose their political preferences in election surveys.}
\textcolor{black}{The Self-censoring model is of significant interest because the model is: (i) conceptually well-motivated, and  (ii) can be considered as a baseline for other more complex missingness models.}
We say that $\obs$ is a {\em self-censoring missingness model} if there exist sets $S_1, \dots, S_d$ such that $\obs(\mb{y}) = \{i \in [d]: y_i \in S_i\}$.  

Our result in this setting rests on the following hypothesis:
\begin{restatable}{assumption}{censoringmissingness}
\label{censoring_assumpt}
For any pair of coordinates $i, j \in [d]:$
$
\Pr_{\mb{y} \sim \gauss(\bm{\mu}^*, \bm{\Sigma}^*)}[y_i \in S_i, y_j \in S_j] \geq \alpha.
$
\end{restatable}

\begin{restatable}{theorem}{censoringmain}
\label{th:censoring_main}
Suppose we can observe samples from $\gauss(\bm{\mu}^*, \mb{\Sigma}^*)$ censored through a self-censoring missingness model $\obs$.
\textcolor{black}{If \cref{censoring_assumpt} is satisfied for some constant value of the parameter $\alpha$,} there exists a polynomial-time algorithm that recovers estimated $\bm{\mu}^\ast, \mb{\Sigma}^\ast$ with arbitrary accuracy. Specifically, for all $\varepsilon > 0$, 
\textcolor{black}{and given that the eigenvalues of $\mb{\Sigma}^\ast$ lie in the interval $[\lambda_{min},\lambda_{max}]$,
the algorithm uses $\tilde{\mathcal{O}}\left(\frac{d^2(\lambda_{max}/\lambda_{min})^2}{\alpha\varepsilon^2 }\right)$ samples} and produces estimates that satisfy the following:
\begin{align*}
    & \left\|\mb{\Sigma}^{^\ast -1 / 2}(\bm{\mu}^\ast-\bm{\hat{{\mu}}}) \right\|_{2} \leq \mathcal{O}( \varepsilon) ; \\
    \quad \text { and } & \left\|\bm{I}-\mb{\Sigma}^{\ast -1 / 2} \mb{\hat{\Sigma}} \mb{\Sigma}^{\ast -1 / 2}\right\|_{F} \leq \mathcal{O}(  \varepsilon).
\end{align*}
\textcolor{black}{Note that the sample complexity is proportional to $1/\alpha$.}
Furthermore, under the above conditions, we have %the total variation distance 
$\tv(\gauss(\bm{\mu}^\ast, \mb{\Sigma}^\ast), \gauss(\bm{\hat{\mu}}, \mb{\hat{\Sigma}})) \leq \mathcal{O}(\varepsilon)$.
\end{restatable}

\subsubsection{MEAN ESTIMATION UNDER LINEAR THRESHOLDING MISSINGNESS} \label{sec:linear masking}

We say $\obs$ is a {\em linear thresholding missingness model} if there exist $\mb{v}_1, \dots, \mb{v}_d \in \R^d$ and $b_1, \dots, b_d \in \R$ such that $\obs(\mb{y}) = \{i \in [d]: \mb{v}_i^T \mb{y} \leq b_i\}$. For instance, if for a pair of coordinates $x_i, x_j$, we can only observe the 
maximum of the two, this can be modeled by a linear thresholding model where the $i$'th coordinate is observed if $x_j-x_i \leq 0$ and the $j$'th coordinate is observed if $x_i - x_j \leq 0$. 

