\paragraph{Basic Facts and Results} We begin by stating some standard facts below.
\paragraph{Vector and Matrix Norms}
We use $\| \mb{v} \|_2$ to denote the Euclidean norm of a vector $ \mb{v} $. Let $\mb{A}$ be an $d \times d$ matrix, $\|\mb{A}\|_2$ denote the operator norm of a matrix $\mb{A}$, and $ \Vert \mb{A} \Vert_2 = \max\{ |\lambda_i | \}$, where $ \lambda_i$'s are the eigenvalues of $\mb{A}$. Besides, we define $\mb{A}^{\flat}$ to be a vector in $\R^{n\cdot m}$ which is the flattening of $\mb{A}$.
$\|A\|_F = \| A^{\flat}\|_2$ denote the Frobenius norm of a matrix $\mb{A}$. We use the lexicographic order of the coordinates for the flattening of $\mb{A}$.

\paragraph{Convex Set and Projection}
Let $K \subseteq \R^d$ be a
convex set let $\mb{x} \in \R^d$, we define $\Pi_{K}(\mb{x})$ to be the projection of $\mb{x}$ to $K$. We use $\mathcal{B}(\mb{x}, r)$ to
denote the Euclidean ball with center $\mb{x}$ and radius $r$ and we use $\mathcal{B}(r)$ when 
$\mb{x} = \mb{0}$. Besides, we use $\mathcal{B}_{\Sigma}(\mb{x}, r) = \{\mb{y}: d(\mb{x}, \mb{y}) \leq r \}$ to
denote the Mahalanobis ball with center $\mb{x}$ and radius $r$.  

\begin{definition}[Mahalanobis distance] The Mahalanobis distance between two vectors $\mb{x}$ and $\mb{y}$, given a covariance matrix $\mb{\Sigma}$ is defined as $\Vert \mb{x} - \mb{y} \Vert_{\Sigma} = \sqrt{(\mb{x} - \mb{y})^{\top}\mb{\Sigma}^{-1}(\mb{x}- \mb{y})}$.

\end{definition}
\begin{definition}[Total variational (TV) distance]
Given two probability distributions $\cP$ and $\cQ$ over $\R^d$, the total variational distance between them is defined as
$
\tv(\cP, \cQ)
= \sup_{A \in \R^d} \Abs{\cP(A) - \cQ(A)}
= \frac{1}{2} \int_{\R^d} \Abs{\cP - \cQ} dx
$.
\end{definition}
