\begin{definition}[$\varepsilon$- approximation] 
A distribution $\hat{f}$ is an $\varepsilon$-approximation of $f$ if $\| f - \hat{f}\|_F \leq O(\varepsilon)$.  
\end{definition}

\begin{definition}[Strong convexity]
Let $f: \mathbb{R}^d \rightarrow \mathbb{R}$, and let $H_f$ be the Hessian of $f$. We say that $f$ is $\beta$-strongly convex if $H_f(\beta) \succeq \beta I$ for all $x \in \mathbb{R}^d$.
\end{definition}
