\textcolor{black}{$\mathrm{poly}(d, 1/\alpha, 1/\beta, 1/\gamma, 1/\lambda_{\min}(\bm{\Sigma}), \lambda_{\max}(\bm{\Sigma}), 1/\eps, \log(1/\delta))$ samples and running time}, and with probability at least $1-\delta$, produces an estimate $\widehat{\bm{\mu}}$ such that $\|\widehat{\bm{\mu}}-\bm{\mu}\|_\Sigma \leq \eps$. 
\end{theorem1f}
}
