\paragraph{General outline} In this section, we present and analyze our mean estimation algorithm of \texttt{MissingDescent} under anchor missingness models. As a high-level overview, our approach involves running a Projected Stochastic Gradient Descent (PSGD) algorithm on a negative log-likelihood function whose optimal value coincides with the true mean. The steps of proof are as follows:
\begin{itemize}%[leftmargin=*]
    \item We develop an appropriate objective function in \cref{subsec:log-likelihood} and design an efficient mean estimation algorithm \texttt{MissingDescent} in \cref{algo:psgd}, assuming that any small subset of coordinates is observed with sufficiently high probability (\cref{missingness_assumpt}), and the observed missingness pattern is not very rare conditioned on the values of the observed coordinates (\cref{dependence_assumpt}).
    \item We show that our objective function is strongly convex with respect to the correct parameterization and hence the optimum is unique. Furthermore, it is equal to the true mean.
    \item %Our \texttt{MissingDescent} algorithm is shown in \cref{subsec:algo}. 
    We analyze our \texttt{MissingDescent} algorithm in \cref{sec:gen_anal} by showing that \cref{algo:psgd} approximately optimizes $\ell$ with bounds on the runtime and sample complexity.
    \item Specifically, we show in \cref{algo:init} in \cref{subsec:algo} that we can use the \texttt{Initialize} algorithm to efficiently compute an initial feasible point to start the optimization.
    \item %Then we show in \texttt{SampleGradient} algorithm that we can find an approximately unbiased estimate of $\Delta \ell(\bm{\mu})$ when sampling from the conditional distribution, and apply \texttt{ProjectToDomain} algorithm to project a current guess back to the domain.
    In the \texttt{SampleGradient} algorithm in \cref{algo:sampgrad}, we demonstrate that it is possible to obtain an estimate of $\Delta \ell(\bm{\mu})$ that is approximately unbiased by sampling from the conditional distribution. Additionally, we use the \texttt{ProjectToDomain} algorithm in \cref{algo:projettodomain} to project a current guess back onto the domain.
\end{itemize}

\subsection{NEGATIVE LOG-LIKELIHOOD OBJECTIVE FUNCTION WITH ANCHOR MISSINGNESS}
\label{subsec:log-likelihood}
We will approach the mean estimation problem via optimization of the population log-likelihood with respect to a given parameter estimate $\mb{\mu}$ for the true mean $\mb{\mu}^*$. % given by $\mb{\mu}$.  
Define $g_{\bm{\mu}}$ to be the density function of $\gauss(\bm{\mu}, \bm{\Sigma})$:
\[
g_{\bm{\mu}}(\mb{y}) = (2\pi)^{\frac{-d}{2}} |\bm{\Sigma}|^{\frac{-1}{2}} \exp\left(-\frac{(\mb{y}-\bm{\mu})^T\bm{\Sigma}^{-1}(\mb{y}-\bm{\mu})}{2}\right).
\]
Recall the notation $g_{\bm{\mu}}^\obs$ defined in \cref{sec:notations} to be the density function of $\gauss(\bm{\mu},\bm{\Sigma})$ censored by $\obs$. We can then write down the population negative log-likelihood $\ell$ as:
\begin{align*}
\hspace{-0.3cm}
&\ell(\bm{\mu}) = \Exp_{(A,\mb{x}) \sim \gauss(\bm{\mu}^*, \bm{\Sigma})^\obs}[-\log g_{\bm{\mu}}^\obs(A, \mb{x})]\\
&=\Exp_{(A,\mb{x})}\left[- \log \int_{\mb{y}}\indic[\obs(\mb{y}) = A] \cdot \delta(\mb{y}_A-\mb{x}) \cdot  g_{\bm{\mu}}(\mb{y}) d\mb{y}\right].
%\label{eq:likelihood_general}
\end{align*} 
In the second equality, and everywhere later, $(A, \mb{x})$ is an observation sampled from the censored version of the true distribution: $\gauss(\bm{\mu}^*, \Sigma)^\obs$.
The integral above marginalizes over all $\mb{y}$ for which the missingness model would yield the observation $(A, \mb{x})$.

The gradient with respect to $\bm{\mu}$ of $\bm{\nabla}\ell(\bm{\mu})$ can be expressed as
\small
\begin{align}
& \Exp_{(A, \mb{x})}\left[ -\frac{\int_{\mb{y}}  \bm{\Sigma}^{-1} (\mb{y}-\bm{\mu})\cdot \indic[\obs(\mb{y}) = A] \cdot \delta(\mb{y}_A-\mb{x}) g_{\bm{\mu}}(\mb{y})  d\mb{y} }{\int_{\mb{y}}\indic[\obs(\mb{y}) = A] \cdot \delta(\mb{y}_A-\mb{x}) \cdot  g_{\bm{\mu}}(\mb{y}) d\mb{y}} \right] \label{eq:general_grad}\\
&=
-\Exp_{(A,\mb{x})}[\Exp_{\mb{y} \sim \gauss(\bm{\mu}, \Sigma)}[\bm{\Sigma}^{-1}(\mb{y}-\bm{\mu}) \mid \obs(\mb{y})=A, \mb{y}_A = \mb{x}]] \label{eq:general_grad_exp}
%&= \Exp_{\mb{x} \sim \gauss(\bm{\mu}^*, \bm{\Sigma})}\left[- \Exp_{ \mb{y} \sim \gauss(\bm{\mu}, \bm{\Sigma})}[ \bm{\Sigma}^{-1}\left(\mb{y}-\bm{\mu}\right) \mid \mb{y} \equiv \mb{x}]\right] 
\end{align}
\normalsize

\begin{restatable}{lemma}{globalmin}
\label{lem:globalmin}
For any $\bm{\mu} \in \R^d$, it holds that: $\ell(\bm{\mu}) \geq \ell(\bm{\mu}^*)$.
\end{restatable}


\begin{lemma}[Strong Convexity with Missing Entries]
\label{lm:strong convex general}
Given our missingness model and \cref{missingness_assumpt} \textcolor{black}{with $\beta=\frac{c}{d}$ for some integer $c\in\{1,\dots d\}$}, we have that the function with general covariance  $\ell(\bm{\mu})$ is $\lambda$-strongly convex for $\lambda=\alpha\beta/\lambda_{\max}(\bm{\Sigma})$.  
\end{lemma}
\begin{remark}
Convexity may not hold if the missignnness pattern is not linear thresholding. For example, even for $d=1$, if $\mu^*=0$ and $\obs(y) = \{1\}$ if $y \in [2,4]$ and $\emptyset$ otherwise, the function $\ell(\mu)$ is not convex.
\end{remark}
\subsection{ALGORITHM}
\label{subsec:algo}

\paragraph{Initialization}
\label{subsec:initialization}
Our first step for efficiently optimizing the negative log-likelihood function is finding a good initial point for the PSGT. Specifically, we take the empirical mean $\mb{\hat{\mu}}$.
This is a biased estimate, but we show below that this is good enough for initialization: the distance of the empirical estimates and true mean $\mb{\mu}^*$ is a constant that depends only on the constant $\beta$, mass $\alpha$ and $\lambda_{max}$ of the known $\mb{\Sigma}$. 
The pseudocode for \texttt{Initialize} appears in \cref{algo:init}. 

\begin{algorithm}[htbp]
\SetKwInOut{Input}{Input}
\Input{Access to data generator $\mathcal{O}$,  parameter \textcolor{black}{$\beta =\frac{c}{d}$ for some integer $c\in \{1, \dots, d\}$}, number of samples $M_{\text{init}}$}

$\mb{w} \gets $ empty array of length $d$\\
$\mb{X} \gets$ matrix with $M_{\text{init}}$ rows, each an independent sample from $\mathcal{O}$\\
\For{$i\gets0$ \KwTo $\lceil 1/\beta \rceil\textcolor{black}{-1}$}{
$s\gets i\beta d+1 $\\
$t\gets \textcolor{black}{\min\{ (i+1)\beta d,d\}}$\\
$\mb{Y}_i \gets $ submatrix of $\mb{X}$ consisting of columns $s, s+1, \dots, t$\\
Remove all rows of $\mb{Y}_i$ containing at least one $*$\\
$\bm{\hat{\mu}}_i \gets $ average of the rows of $\mb{Y}_{\textcolor{black}{i}}$\\
$\mb{w}[s, s+1, \dots, t] \gets \bm{\hat{\mu}}_i$
}
\Return $\mb{w}$

\caption{[\texttt{Initialize}] Initialization for the main algorithm.}
\label{algo:init}
\end{algorithm}

By \cref{missingness_assumpt}, we have that after line 7 in \texttt{Initialize}, each $\mb{Y}_i$ is the truncation of a $\beta d$-dimensional gaussian where the truncation set has mass at least $\alpha$. 
Using Lemma 6 of \cite{daskalakis2018efficient}, the mean of such a truncated gaussian is $O(\sqrt{\log(1/\alpha)})$ distance away from the untruncated mean. 
%Since the vectors $\Vert \Exp[\mb{w}]-\bm{\mu}^*\Vert$ are pairwise orthogonal
Hence, we have
$\|\Exp[\mb{w}]-\bm{\mu}^*\|_2^2 = \sum_i \|\Exp[\bm{\hat{\mu}}_i] - \bm{\mu}[i\beta d + 1, \dots, (i+1)\beta d]\|_2^2 
\leq \lambda_{\max}\sum_i \|\Exp[\bm{\hat{\mu}}_i] - \bm{\mu}[i\beta d + 1, \dots, (i+1)\beta d]\|_{\bm{\Sigma}}^2 
\leq \mathcal{O}(\frac{\lambda_{\max}}{\beta}{\log(1/\alpha)})$.\footnote{Define $\bm{x}= \Exp[\bm{\hat{\mu}}_i] - \bm{\mu}[i\beta d + 1, \dots, (i+1)\beta d]$, and the eigenvalue decomposition of $\mb{\Sigma}^{-1}$ as $\mb{\Sigma}^{-1}=Q^{\top}D^{-1}Q$. The first inequality holds because $\Vert \bm{x}\Vert_{\bm{\Sigma}}^2 = \Vert \bm{x}^{\top} Q^{\top} D^{-1} Q \bm{x} \Vert_2 =  \|D^{-1/2}Q\bm{x}\|_2^2 \geq \frac{1}{\lambda_{\max}} \Vert Q\bm{x} \Vert_2^2 = \frac{1}{\lambda_{\max}} \Vert \bm{x}\Vert_2^2$. Therefore, we have $\Vert \bm{x} \Vert_2^2 \leq \lambda_{\max} \Vert \bm{x} \Vert_{\bm{\Sigma}}^2$}
Therefore, $\|\Exp[\mb{w}]-\bm{\mu}^*\|_2 \leq \mathcal{O}({\sqrt{\frac{\lambda_{\max}}{\beta}\log(1/\alpha)}})$.
Later in \cref{sec:gen_anal}, we analyze the number of samples $M_{\text{init}}$ required for $\|\mb{w}-\bm{\mu}^*\|_2$ to satisfy this bound with high probability.





{
\begin{algorithm}[htbp]
\SetKwInOut{Input}{Input}
\SetKwFunction{Initialize}{Initialize}
\SetKwFunction{SampleGradient}{SampleGradient}
\SetKwFunction{ProjectToDomain}{ProjectToDomain}
\Input{Access to data generator $\mathcal{O}$, parameters $\beta, \lambda_{\text{sgd}}, \eta_{\text{lmc}}$, $R_{\text{lmc}}, r_{\text{proj}}$, $M_{\text{init}}$, $M_{\text{sgd}}$, $M_{\text{grad}}$}
$\bm{\mu}^{(0)} \gets \Initialize(\mathcal{O}, \beta, M_{\text{init}})$ \\
\For{$i\gets 1$ \KwTo $M_{\text{sgd}}$}{
Sample $(A^{(i)},\mb{x}^{(i)})$ from $\mathcal{O}$\\
$\eta_i \gets \frac{1}{\lambda_{\text{sgd}} \cdot i}$\\
$\mb{g}^{(i)} \gets \SampleGradient((A^{(i)},\mb{{x}}^{(i)}),\bm{\mu}^{(i-1)}, \eta_{\text{lmc}}, R_{\text{lmc}}, M_{\text{grad}})$\\
$\mb{v}^{(i)} \gets \bm{\mu}^{(i - 1)} - \eta_i \mb{g}^{(i)}$\\
$\bm{\mu}^{(i)} \gets \ProjectToDomain(\bm{\mu}^{(0)}, \mb{v}^{(i)}, r_{\text{proj}})$
}
$\bm{\bar{\mu}}\gets \frac{1}{M_{\text{sgd}}}\sum_{i=1}^{M_{\text{sgd}}} \bm{\mu}^{(i)}$\\
\Return $\bm{\bar{\mu}}$
\caption{[\texttt{MissingDescent}] Mean recovery algorithm given access to an oracle that generates samples with incomplete data.}
\label{algo:psgd}
\end{algorithm}
\DecMargin{1.2em}
}

Note that, in each iteration of SGD in \texttt{MissingDescent} (\cref{algo:psgd}), 
we choose a projection set, to make sure that PSGD converges. Specifically, we project a current guess back to a $\ball_{\bm{\Sigma}}$ ball scaled by $r_{proj}$ and centered at $\bm{\mu}^{(0)}$ as shown below:
\begin{algorithm}
\SetKwInOut{Input}{Input}
\Input{$\bm{\mu}^{(0)}, \mb{v}$, parameter $r_{\text{proj}}$}
\Return 
$\bm{\mu}^{(0)}+\min\{r_{proj},\Vert (\mb{v}-\bm{\mu}^{(0)})\Vert_{\Sigma} \}\cdot\frac{ (\mb{v}-\bm{\mu}^{(0)})}{(\Vert \mb{v}-\bm{\mu}^{(0))}\Vert_{\Sigma}}$

\caption{[\texttt{ProjectToDomain}] The function that projects a current guess back to the domain 
onto the $\ball_{\bm{\Sigma}}$ ball.}
%onto the $L_2$ unit ball.}
\label{algo:projettodomain}
\end{algorithm}

Our goal is to minimize the population negative log-likelihood $\ell$ via (projected) stochastic gradient descent while maintaining its strong-convexity. 
Specifically, \cref{algo:psgd} above describes this strategy. In order to apply  \cref{algo:psgd} to our log-likelihood objective function, we need to solve the following three algorithmic problems:
%(as we describe partially in the supplementary material due to space constraints):
\begin{itemize}[leftmargin=*]
    \item \textbf{Initialization}: efficiently compute an initial feasible point from which to start the optimization. The pseudocode for \texttt{Initialize} appears in \cref{algo:init};
    \item \textbf{Gradient estimation}: design a nearly unbiased sampler for $\bm{\nabla}\ell(\bm{\mu})$ using Langevin sampling. The \texttt{SampleGradient} pseudocode appears in \cref{algo:sampgrad}; 
    \item \textbf{Efficient projection}: perform an efficient projection into a set of feasible points to make sure that PSGD converges. The pseudocode presents in \cref{algo:projettodomain}. 
\end{itemize}

{
\IncMargin{1.2em}
\begin{algorithm}
\SetKwInOut{Input}{Input}
\Input{$(A, \mb{x})$, $\bm{\mu}$, parameters $\eta, R, M$}
$a \gets |A|$\\
Compute $\bm{\mu}_{\text{cond}}$ and $\bm{\Sigma}_{\text{cond}}$ as in (\ref{eq:newg}) and (\ref{eq:newc})\\
Let $W$ be such that $\bm{\Sigma}_{\text{cond}} = WW^\top$\\
Compute $\cL = (W^{-1} \cK)\cap \ball_{\textcolor{black}{\Sigma}}(W^{-1}\bm{\mu}_{\text{cond}},R)$ \\
$\mb{z}^{(0)} \gets $ a point in $\cL$\\
\For{$t = 0~\KwTo~ M-1$}{
Sample $\bm{\zeta}^{(t)}$ from $\gauss(0, I_{d-a})$\\
$\mb{z}^{(t+1)} \gets \Pi_\cL\left(\mb{z}^{(t)} - {\eta}(\mb{z}^{(t)} - W^{-1}\bm{\mu}_{\text{cond}}) + \sqrt{\eta} \cdot \bm{\zeta}^{(t)}\right)$
}
\Return $-\bm{\Sigma}^{-1}(\mb{x} \circ (W\mb{z}^{(M)})-\bm{\mu})$ 
\caption{[\texttt{SampleGradient}] Sampler for $\nabla \ell(\bm{\mu})$.}
\label{algo:sampgrad}
\end{algorithm}
\DecMargin{1.2em}
}

\subsection{ANALYSIS OF \texttt{MissingDescent}}\label{sec:gen_anal}

We show in this section that \cref{algo:psgd} approximately optimizes $\ell$ with bounds on the runtime and sample complexity. The following lemma describes the ingredients necessary to obtain  such bounds:

\begin{lemma}[Lemma 6 in \cite{cherapanamjeri2022makes}]
\label{lem:genmain}
Let $f: \R^k \to \R$ be a convex function, $K \subseteq \R^k$ a convex set, and fix an initial estimate $\mb{x}^{(0)} \in K$. Now, let $\mb{x}^{(1)}, \dots, \mb{x}^{(T)}$ be the iterates generated by running $T$ steps of projected SGD using gradient estimates $\mb{g}^{(1)}, \dots, \mb{g}^{(T)}$ satisfying $\Exp[\mb{g}^{(i)} \mid \mb{x}^{(i-1)}] = \nabla f(\mb{x}^{(i-1)}) + \mb{b}^{(i)}$. Let $\mb{x}_* = \arg \min_{\mb{x} \in K} f(\mb{x})$ be a minimizer of $f$. Then, if we assume:
\begin{enumerate}
\item[(i)] \textbf{Bounded step variance}: $\Exp[\|\mb{g}^{(i)}\|_2^2] \leq \rho^2$, 
\item[(ii)] \textbf{Strong convexity}: $f$ is $\lambda$-strongly convex, and 
\item[(iii)] \textbf{Bounded gradient bias}: $\|\mb{b}^{(i)}\|^2 \leq \frac{\rho^2}{2\lambda \cdot \text{diam}(K)\cdot i}$,
\end{enumerate}
then the average iterate $\widehat{\mb{x}} = \frac1T \sum_{t=1}^T \mb{x}^{(T)}$ satisfies $\Exp[f(\widehat{\mb{x}}) - f(\mb{x}_*)] \leq \frac{\rho^2}{\lambda T} (1 + \log(T))$.  
\end{lemma}

We study each of the three conditions in \cref{lem:genmain} above, before wrapping up with the overall analysis.


\subsubsection{STRONG CONVEXITY}
%Convexity of the negative log-likelihood function $\ell$ is not enough for our analysis. 
To show convergence of stochastic gradient descent on $\ell$, we require \emph{strong convexity} such that the optimum of $\ell$ is unique. 
Specifically, we need to show: $\bm{\nabla}^2\ell(\bm{\mu}) \succeq \beta I$ for some parameter $\beta > 0$ such that the probability mass is at least a constant. Once we proved the strong convexity, we can apply projected stochastic gradient descent (PSGD) to recover the parameter $\mu$.

\begin{restatable}[Strong Convexity with Missing Entries]{lemma}{StrongConvexityMissingEntries}
\label{lm:strong convex general}
Given our missingness model and \cref{missingness_assumpt} \textcolor{black}{with $\beta=\frac{c}{d}$ for some integer $c\in\{1,\dots d\}$}, we have that the function with general covariance $\ell(\bm{\mu})$ is $\lambda$-strongly convex for $\lambda=\alpha\beta/\lambda_{\max}(\bm{\Sigma})$.
\end{restatable}

