 \right] \\
 &= \Exp_{(A, \mb{x})}\left[\bm{\Sigma}^{-1} -\Cov_{\mb{y} \sim \gauss(\bm{\mu}, \bm{\Sigma})}\left[ \bm{\Sigma}^{-1} \left(\mb{y} - \bm{\mu}\right) \mid \obs(\mb{y})=A, \mb{y}_A = \mb{x}\right] \right].
