In the worst case, we can only observe $\alpha$-mass. For $d=1$, let $F$ represent the CDF of the standard normal distribution, given an vector $\mb{x} \in \R^d$, we have a subset with mass $\geq \alpha$ that would maximize $\Vert \mu_{0, A_i} \Vert_2^2$ as $\{\mb{x}^\top \mu_{0, A_i} \geq F^{-1}(1 - \alpha)\}$. Since $\alpha = 1 - F(t) \leq e^{- \frac{t^2}{2}}$, we have $t \leq \sqrt{2 \log{1/ \alpha}}$ and thus $ \Vert \mu_{0, A_i} -  \mu_{ A_i}^* \Vert_2^2 \leq \mathcal{O}(\log(\frac{1}{\alpha }))$.
For arbitrary $d$, Lemma 6 of \cite{daskalakis2018efficient} implies $ \Vert \mu_{0, A_i} -  \mu_{ A_i}^* \Vert_2 \leq \mathcal{O}(\sqrt{\log(\frac{1}{\alpha }}))$. 
Therefore $\Vert \Delta\mu \Vert_2 = \Vert \mu_0 - \mu^* \Vert_2 = \sqrt{ \lceil 1/\beta \rceil \Vert \mu_{0, A_i} -  \mu_{ A_i}^* \Vert_2^2} \leq \sqrt{\lceil \frac{1}{\beta} \rceil \log{\frac{1}{\alpha}}}$.

%Recall that with a identity covariance matrix, we have $\Vert \Delta\mu \Vert_2 = \Vert \mu_0 - \mu^* \Vert_2 = \sqrt{ \lceil 1/\beta \rceil \Vert \mu_{0, A_i} -  \mu_{ A_i}^* \Vert_2^2} \leq \sqrt{\lceil \frac{1}{\beta} \rceil \log{\frac{1}{\alpha}}}$. 
%Lemma 6 of \cite{daskalakis2018efficient} implies that $ \Vert \mu_{0, A_i} -  \mu_{ A_i}^* \Vert_{\bm{\Sigma}} \leq \mathcal{O}(\sqrt{\log(\frac{1}{\alpha }}))$. Thus, we can conclude that 
%$\Vert \Delta\mu \Vert_{\bm{\Sigma}} = \Vert \mu_0 - \mu^* \Vert_{\bm{\Sigma}} = \sqrt{ \lceil 1/\beta \rceil \Vert \mu_{0, A_i} -  \mu_{ A_i}^* \Vert_{\bm{\Sigma}}^2} \leq \sqrt{\lceil \frac{1}{\beta} \rceil \log{\frac{1}{\alpha}}}$.
}



\subsection{GRADIENT ESTIMATION}
Recall from the gradient expression in (\ref{eq:general_grad}) that the main %issue
obstacle in computing $\nabla \ell(\bm{\mu})$  is the term $\Exp_{(A,\mb{x})}\Exp_{\mb{y}}[\mb{y} \mid \obs(\mb{y})=A, \mb{y}_A=\mb{x}]$. Here, $(A,\mb{x})$ is an observation generated from $\gauss(\bm{\mu}^*, \bm{\Sigma})^\obs$, while $\mb{y}$ is sampled from $\gauss(\bm{\mu}, \bm{\Sigma})$ for some $\bm{\mu} \in \R^d$.  So, to implement \texttt{SampleGradient}, we need an approximately unbiased estimator.
%\themis{Is this a term that is used? Maybe "an estimator with small bias?"} for $\Exp_{(A,\mb{x})}\Exp_{\mb{y}}[\mb{y} \mid \obs(\mb{y})=A, \mb{y}_A=\mb{x}]$.


The most straightforward way is to apply rejection sampling: for an $(A, \mb{x})$ generated by $\mathcal{O}$, keep sampling $\mb{y}$ from the conditional\footnote{We need to sample from the conditional distribution because $\mb{y}\equiv \mb{x}$ occurs with probability $0$ in the $\gauss(\bm{\mu},\bm{\Sigma})$ measure.} distribution $\gauss(\bm{\mu},\bm{\Sigma}) \mid \mb{y}_A = \mb{x})$ until $\obs(\mb{y}) = A$. If $\bm{\mu}^* = \bm{\mu}$, then the expected cost of the rejection sampling is $O(1/\gamma)$ by \cref{dependence_assumpt}, as $\mb{y}_A = \mb{x}$ implies $\mb{y}_C = \mb{x}_C$. The issue that arises is that the probability of $\obs(\mb{y}) = A$ can decrease exponentially in the distance between $\bm{\mu}$ and $\bm{\mu}^*$, and so, rejection sampling becomes infeasible.
\ignore{To understand the issue more formally, we define $\gamma(\mb{x})$ to be the probability that a sample from the conditional distribution is not rejected when $\bm{\mu}=\bm{\mu}^*$:
\begin{equation}
\gamma(\mb{x}) \coloneqq \Pr_{\mb{y} \sim \gauss(\bm{\mu}^*, \bm{\Sigma})}\left[\cA(\mb{y}) = \cA(\mb{x}) \mid y_i = x_i \text{ for all } i \in \cA(\mb{x})\right]
\end{equation}}

To sample the gradient when $\bm{\mu}$ is far from $\bm{\mu}^*$, we use the projected Langevin Monte Carlo algorithm \cite{bubeck2018sampling}. For an observation $(A, \mb{x})$, suppose $\mb{y} \sim \gauss(\bm{\mu}, \bm{\Sigma})$, and let $\bm{\mu}_{\text{cond}}$ and ${\bm{\Sigma}}_{\text{cond}}$ be the mean and covariance of $\mb{y}_{\bar{A}}$ conditioned on $\mb{y}_A = \mb{x}$. It is well-known that the conditional distribution is Gaussian with:
\begin{align}\label{eq:newg}
\bm{\mu}_{\text{cond}}  &= \bm{\mu}_{\bar{A}} + \bm{\Sigma}_{\bar{A}, A} \bm{\Sigma}_{A, A}^{-1} (\mb{{x}} - \bm{\mu}_A)\\
\bm{\Sigma}_{\text{cond}} &= \bm{\Sigma}_{\bar{A}, \bar{A}} - \bm{\Sigma}_{\bar{A}, A} \bm{\Sigma}_{A,A}^{-1}\bm{\Sigma}_{A, \bar{A}}
\label{eq:newc}
\end{align}
    where ${\bar{A}}$ represents $[d] \setminus A$. Let\footnote{$\mb{x}_A \circ \mb{z}$, where $\mb{z} \in \R^{d-|A|}$, denotes the vector $\mb{y} \in \R^d$ where $\mb{y}_A = \mb{x}_A$ and $\mb{y}_{\bar{A}} = \mb{z}$.} $\cK = \{\mb{z} \in \R^{d-|A|} \mid \obs(\mb{x} \circ \mb{z}) = A\}$. 
%    and  set $\mb{z}^{(0)}$ to be the Chebyshev center of $K(\mb{x})$. 
%   Since $K(\mb{x})$ is defined as the intersection of linear inequalities, it is well-known that $\mb{z}^{(0)}$ can be computed by linear programming. 
The iteration of the projected Langevin Monte Carlo algorithm takes the following form:

\begin{equation}
\mb{z}^{(t+1)} = \Pi_{\cK \cap \ball_{\textcolor{black}{\Sigma}}(\bm{\mu},R)}\left(\mb{z}^{(t)} - \frac{\eta}{2}\bm{\Sigma}_{\text{cond}}^{-1}(\mb{z}^{(t)} - \bm{\mu}_{\text{cond}}) + \sqrt{\eta} \cdot \bm{\zeta}^{(t)}\right)
\end{equation}
where $\eta$ is a step-size parameter,
$R$ is an appropriate radius parameter, and $\bm{\zeta}^{(0)}, \bm{\zeta}^{(1)}, \dots$ are i.i.d.~samples from the standard normal distribution in $(d-|A|)$-dimensions. 
We implicitly make the reasonable assumption here that 
Mahalanobis projection 
%Euclidean projection
to the convex set 
$\Pi_{\cK \cap \ball_{\Sigma}(\bm{\mu},R)}(\cdot)$ can be performed efficiently. The pseudocode for \texttt{SampleGradient} appears in \cref{algo:sampgrad}.
\ignore{
{
\IncMargin{1.2em}
\begin{algorithm}
\SetKwInOut{Input}{Input}
\Input{$(A, \mb{x})$, $\bm{\mu}$, parameters $\eta, R, M$}
$a \gets |A|$\\
Compute $\bm{\mu}_{\text{cond}}$ and $\bm{\Sigma}_{\text{cond}}$ as in (\ref{eq:newg}) and (\ref{eq:newc})\\
Let $W$ be such that $\bm{\Sigma}_{\text{cond}} = WW^\top$\\
Compute $\cL = (W^{-1} \cK)\cap \ball_{\textcolor{black}{\Sigma}}(W^{-1}\bm{\mu}_{\text{cond}},R)$ \\
