$\mb{z}^{(t+1)} \gets \Pi_\cL\left(\mb{z}^{(t)} - {\eta}(\mb{z}^{(t)} - W^{-1}\bm{\mu}_{\text{cond}}) + \sqrt{\eta} \cdot \bm{\zeta}^{(t)}\right)$
}
\Return $-\bm{\Sigma}^{-1}(\mb{x} \circ (W\mb{z}^{(M)})-\bm{\mu})$ 
\caption{[\texttt{SampleGradient}] Sampler for $\nabla \ell(\bm{\mu})$.}
\label{algo:sampgrad}
