\title{CLEAN-MI: A Scalable and Efficient Pipeline for Constructing High-Quality Neurodata in Motor Imagery Paradigm}

\author{Dingkun~Liu, Zhu~Chen, and Dongrui~Wu,~\IEEEmembership{Fellow,~IEEE}
