	\Require \textit{A query point $\point$, a majorant density $\majrate$, a struct implementing the PBM density $\rate$, the PBM particle size $\size$.}
 	\Ensure \textit{Closest point $\closestpointmicro$.}
	\Function{SampleClosestPoint}{$\point,\ \majrate,\ \rate,\ \size$}
	 	\COMMENT[Initialize cubed radius]\ENDCOMMENT
		\State $\cubedradius \gets 0$
		\WHILEDO[\textsc{true}]
			\COMMENT[Sample exponential variate]\ENDCOMMENT
			\State $\xi \gets \Proc{SampleExponential}(\nicefrac{4}{3}\pi\majrate)$
