		{}
	\algtext*{ENDRETURN}
	\algblockdefx[Name]{COMMENT}{ENDCOMMENT}
		[1][Unknown]{\textcolor{commentcolor}{\(\triangleright\) \textit{#1}}}
		{}
	\algtext*{ENDCOMMENT}

	\Struct[$\Proc{Memory}$]
		\State \textbf{attribute} $\emptylist$	\Comment{List of center-radius pairs for empty balls}
		\State \textbf{attribute} $\particlelist$	\Comment{List of centers of sampled particles}

		\COMMENT[Initialize empty memory]\ENDCOMMENT
		\Function{Initialize}{\vphantom{0}}
			\State $\emptylist, \particlelist \gets \emptyset$
		\EndFunction

		\COMMENT[Add an empty ball of center $\point$ and radius $\distvar$]\ENDCOMMENT
		\Function{AddEmptySphere}{$\point, \distvar$}	
			\State $\emptylist \gets \emptylist \cup \{(\point, \distvar)\}$
		\EndFunction

		\COMMENT[Add a sampled particle of center $\centerpoint$]\ENDCOMMENT
		\Function{AddSampledParticle}{$\centerpoint$}
			\IFTHEN[$\centerpoint^\prime \textbf{ in } \particlelist$]{\textbf{return}}\Comment{Skip if $\centerpoint$ already in list}\ENDIFTHEN
			% \FORDO[$\centerpoint^\prime\ \textbf{in}\ \particlelist$]	
			% \ENDFORDO
			\State $\particlelist \gets \particlelist \cup \{(\centerpoint)\}$
		\EndFunction

		\COMMENT[Update memory given walk point $\point$ and its closest point $\cpvar$]\ENDCOMMENT\label{alg:memory:update}
		\Function{Update}{$\point, \cpvar$}
		\COMMENT[Add walk step to list of empty balls]\ENDCOMMENT
		\State $\Proc{AddEmptySphere}(\point, \norm{\point-\cpvar})$
		\COMMENT[Add sampled particle if $\cpvar$ is not on medium boundary]\ENDCOMMENT
		\IFTHEN[$\cpvar\notin \partial\medium$]{$\Proc{AddSampledParticle}(\cpvar + \size\ \dirop(\point,\cpvar))$}\ENDIFTHEN
		\EndFunction

		\COMMENT[Perform a containment query on dilated empty space]\ENDCOMMENT
		\Function{IsInsideDilatedEmptySpheres}{$\point, \size$}\label{alg:memory:containment}
			\FORDO[$(\point^\prime,\distvar)\ \textbf{in}\ \emptylist$]
				\IFTHEN[$\Vert\point - \point^\prime\Vert < \distvar + \size$]{\textbf{return} \textsc{true}}
				\ENDIFTHEN
			\ENDFORDO
			\RETURN[\textsc{false}]\ENDRETURN
		\EndFunction

		\COMMENT[Perform a closest point query on sampled particle boundary]\ENDCOMMENT
		\Function{GetClosestPoint}{$\point$}\label{alg:memory:cpq}
			\COMMENT[Query closest particle center]\ENDCOMMENT
			\State $\currentnn \gets \Proc{NearestNeighbor}(\point, \particlelist)$ 
			\COMMENT[Return corresponding closest point on particle boundary]\ENDCOMMENT
			\RETURN[$\currentnn - \size\ \dirop(\point,\currentnn)$]\ENDRETURN
		\EndFunction
	\EndStruct
	\end{algorithmic}
\end{algorithm}

