	\COMMENT[Implementation of conditional density in \cref{eqn:medium_k}]\ENDCOMMENT
	\Struct[$\Proc{ConditionalDensity}$]
		\State \textbf{attributes} $\rate,\size, \memory$ \Comment{PBM parameters and memory}
		\Function{Initialize}{$\rate^\prime, \size^\prime, \memory^\prime$}	\Comment{Initialize attributes}
			\State $\rate \gets \rate^\prime$, $\size \gets \size^\prime$, $\memory \gets \memory^\prime$
		\EndFunction
		\COMMENT[Evaluate conditional density at query point $\point$]\ENDCOMMENT
