	\COMMENT[Implementation of updated medium geometry in \cref{eqn:medium_k}]\ENDCOMMENT
	\Struct[$\Proc{UpdatedMediumGeometry}$]
		\State \textbf{attributes} $\partial\medium,\memory$ \Comment{Medium geometry and memory}
		\Function{Initialize}{$\partial\medium^\prime, \memory^\prime$}	\Comment{Initialize attributes}
			\State $\partial\medium \gets \partial\medium^\prime$, $\memory \gets \memory^\prime$
		\EndFunction
		\COMMENT[Perform a closest point query on updated medium boundary]\ENDCOMMENT
		\Function{GetClosestPoint}{$\point$}
			\COMMENT[Query closest points on medium and particle boundaries]\ENDCOMMENT
			\State $\cpvar \gets \partial\medium.\Proc{GetClosestPoint}(\point)$
			\State $\cpvar^\prime \gets \memory.\Proc{GetClosestPoint}(\point)$
			\RETURN[$\closest(\point, \{\cpvar, \cpvar^\prime\})$] \Comment{Return closest of two points}\ENDRETURN
