	\Function{SampleClosestPointWithMemory}{$\point,\majrate,\rate,\size,\memory$}
		\COMMENT[Create conditional density]\ENDCOMMENT
		\State $\condrate \gets \Proc{ConditionalDensity}.\Proc{Initialize}(\rate, \size, \memory)$
		\COMMENT[Create updated medium geometry]\ENDCOMMENT
		\State $\condmedium \gets \Proc{UpdatedMediumGeometry}.\Proc{Initialize}(\partial\medium, \memory)$
		\COMMENT[Sample a closest point conditioning on empty balls]\ENDCOMMENT
		\State $\cpvar^{\partial\scene} \gets \Proc{SampleClosestPoint}(\point, \majrate, \condrate, \size)$
		\COMMENT[Query closest point on updated deterministic boundary]\ENDCOMMENT
		$\closestpointvol \gets \condmedium.\Proc{GetClosestPoint}(\point)$
		\COMMENT[Return the closest of sampled and deterministic closest points]\ENDCOMMENT
		\State $\cpvar \gets \closest(\point, \{\closestpointmicro, \closestpointvol\})$
		\RETURN[$\cpvar$]\ENDRETURN
	\EndFunction
