We now present our method for constraining an LM to a regular language:

\begin{algorithm}[H]
\caption{Constrains LM $L$ with vocabulary $V$ to generate the language of regex $R$}
\label{alg:regex}
\begin{algorithmic}
\State \shortmath{\struct{T}_V \gets \textsc{BuildDetokenizingFST}(V)} \Comment{token-to-character FST, see \algoref{alg:detokenization}}
\State \shortmath{\struct{A}_R \gets \textsc{BuildRegexFSA}(R)} \Comment{character-accepting FSA \citep{thompson-regex}}
\State \shortmath{\struct{A}_{R\circ V} \gets \textsc{Determinize}(\struct{A}_R \circ \struct{T}_V)} \Comment{token-accepting FSA}

\State \shortmath{q \gets I_{R\circ V}} \Comment{start from initial FSA state}
\For{$t=1$ to $T$} \Comment{decoding steps}
  \State \shortmath{\ell \gets \textsc{ComputeLogits}(L)}
  \State \shortmath{A \gets \{\edgeinput{} : e \in E_{R\circ V} \land \edgesource{} = q\}} \Comment{allowed next tokens}
  \For{$i=1$ to \shortmath{|V|}} \Comment{penalize logits as in \citet{shyam}}
    \If{\shortmath{v_i \not \in A}} \shortmath{\ell_i \gets -\infty}
    \EndIf
  \EndFor
  \State \shortmath{\hat{v} \gets \textsc{SampleNextToken}(L, \ell)}
  \State \shortmath{\hat{e} \gets e \textrm{~~s.t.~~} e \in E_{R\circ V} \land \edgesource{}=q \land \edgeinput{}=\hat{v}} \Comment{find the matching edge}
  \State \shortmath{q \gets \edgetargetof{\hat{e}}} \Comment{traverse the edge}
\EndFor

\end{algorithmic}
\end{algorithm}
