This allows us to reuse \algoref{alg:regex} with minimal modification (see \appref{app:proof-grammar} for proof):

\vspace{-0.5em}
\begin{algorithm}[H]
\caption{Constrains LM $L$ with vocabulary $V$ to generate the language of grammar $G$}
\label{alg:grammar}
\begin{algorithmic}
\State \shortmath{\struct{T}_V \gets \textsc{BuildDetokenizingFST}(V)} \Comment{token-to-character FST, see \algoref{alg:detokenization}}
\State \shortmath{\struct{P}_G \gets \textsc{BuildGrammarPDA}(G)} \Comment{character-accepting PDA \citep{openfst-pdt}}
\State \shortmath{\struct{P}_{G\circ V} \gets \struct{P}_G \circ \struct{T}_V} \Comment{token-accepting PDA}

\State \shortmath{q \gets I_{G\circ V}},\,\, \shortmath{s \gets \epsilon} \Comment{start from initial PDA state and empty stack}
\For{$t=1$ to $T$} \Comment{decoding steps}
  \State \shortmath{\ell \gets \textsc{ComputeLogits}(L)}
  \State \shortmath{A \gets \{\edgeinput{} : e \in E_{G\circ V} \land \edgesource{} = q \land s \textrm{~ends with~} \edgepops{}\}} \Comment{allowed next tokens}
  \For{$i=1$ to \shortmath{|V|}} \Comment{penalize logits as in \citet{shyam}}
    \If{\shortmath{v_i \not \in A}} \shortmath{\ell_i \gets -\infty}
    \EndIf
  \EndFor
  \State \shortmath{\hat{v} \gets \textsc{SampleNextToken}(L, \ell)}
  \State \shortmath{\hat{e} \gets e \textrm{~~s.t.~~} e \in E_{G\circ V} \land \edgesource{}=q \land s \textrm{~ends with~} \edgepops{} \land \edgeinput{}=\hat{v}} \Comment{find the matching edge}
  \State \shortmath{q \gets \edgetargetof{\hat{e}}},\,\, \shortmath{\hat{m} \gets |s|-|\edgepopsof{\hat{e}}|},\,\, \shortmath{s \gets s_{1:\hat{m}}\edgepushesof{\hat{e}}} \Comment{traverse the edge}
\EndFor

\end{algorithmic}
\end{algorithm}

