\section{System Model and Main Results}
\label{sec:setup}


\begin{figure}[tbp]
  \begin{center}
    \input{systemmodel.tex}
    \caption{Covert communication over an AWGN channel.}
    \label{fig:AWGN_channel}
  \end{center}
\end{figure}

We consider the model illustrated in Fig.~\ref{fig:AWGN_channel}, in which a sender attempts to transmit a uniformly distributed message 
%$M\in\mathcal{M}=[1;\abs{\mathcal{M}}]$
$W\in\mathcal{M}$ to a legitimate receiver over an AWGN channel in the presence of an eavesdropper, by encoding the message as a length $n$ codeword $X^n$. We assume that the eavesdropper and the legitimate receiver observe the same outputs 
\begin{IEEEeqnarray}{rCl}
  \label{eq:channel_awgn}
  Y_i=X_i+Z_i, \quad i=1,2,\ldots,n.
\end{IEEEeqnarray}
where $Z_i\sim\mathcal{N}(0,\sigma)$. The transmission is assisted by a uniformly distributed key $K\in\mathcal{K}$,
%$k \in \mathcal{K}=[1;\abs{\mathcal{K}}]$,
shared between the transmitter and receiver but unknown to the eavesdropper. Formally, a code $\mathcal{C}=(f,g)$ of length $n$ for message set $\mathcal{M}$ and key set $\mathcal{K}$ consists of an encoder $f\colon\mathcal{M} \times \mathcal{K} \rightarrow \mathbb{R}^n , (w,k) \mapsto x^n$ and a decoder $g\colon \mathbb{R}^n \times \mathcal{K} \rightarrow \mathcal{M}, (y^n,k) \mapsto \hat{w}$.  
%and the codewords are the different possible input vectors $x^n_{\mathcal{C}}=(x_{1,\mathcal{C}},\ldots,x_{n,\mathcal{C}})$.
The code $\mathcal{C}$ is publicly known to all parties. We denote a uniformly distributed input over the codewords of $\mathcal{C}$ by $X_{\mathcal{C}}^n$.
% We consider the setup illustrated in Figure \ref{fig:AWGN_channel},
% where a transmitter and a receiver communicate over an AWGN channel in the presence of an eavesdropper. 
% The transmitter and the receiver are assumed to share a sufficiently long secret key $k \in \mathcal{K}$.  
% A code $\mathcal{C}=(f,g)$ of length $n$ for message set $\mathcal{M}$ and key set $\mathcal{K}$ consists of an encoder $f\colon\mathcal{M} \times \mathcal{K} \rightarrow \mathcal{X}^n , (m,k) \mapsto x^n$ and a decoder $g\colon \mathcal{Y}^n \times \mathcal{K} \rightarrow \mathcal{M}, (y^n,k) \mapsto \hat{m}$.
% We denote the input random vector by $X_{\mathcal{C}}^n$. 
% and the codewords are the different possible input vectors $x^n_{\mathcal{C}}=(x_{1,\mathcal{C}},\ldots,x_{n,\mathcal{C}})$.
% The key and the message are assumed to be uniformly distributed and independent of each other. 
% We will assume that the eavesdropper knows the encoding and decoding functions $f$ and $g$, but not the value of the secret key $k$.
% The sender communicates with the legitimate receiver through an AWGN channel: 
% and uses the channel $n$ times:
% We consider the additive channel with i.i.d. Gaussian noise:
% The input and output random variables $X^n$ and $Y^n$ take values in the alphabets $\mathcal{X}^n$
% and $\mathcal{Y}^n$ respectively.
% We assume that the input alphabet $\mathcal{X}$ includes an ``off'' symbol denoted by $0$, i.e. when the transmitter is not sending a message, it always transmits $0$. 
% $P_{Y^n|X^n}$ denotes the transition probability of the channel, modeling the noise added to a transmission.
The reliability of the communication is measured in terms of the average probability of decoding error
\begin{IEEEeqnarray}{rCl}
  \label{average_probability_decoding_error_section_finite_blocklength}
  P_e^{\textnormal{avg}}&=&\frac{1}{|\mathcal{K}|}\frac{1}{|\mathcal{M}|}\sum_{k=1}^{|\mathcal{K}|}\sum_{w=1}^{|\mathcal{M}|}\mathbb{P}\left[g(Y^n, k) \neq w ~|~ x^n = f(w,k) \right].\nonumber\\
\end{IEEEeqnarray}
% I changed the notation of to be in coherence with eq20
Covertness is measured in terms of the KL divergence ${D}\left(P_{Y^n_{\mathcal{C}}}\|P_{Z^n}\right)$ between the output distribution
\begin{IEEEeqnarray}{rCl}
  \label{output_sequence_averaged}
  P_{Y^n_\mathcal{C}}(\cdot)=\frac{1}{|\mathcal{K}||\mathcal{M}|}\sum_{k=1}^{|\mathcal{K}|}
  \sum_{w=1}^{|\mathcal{M}|}
  P_{Y^n|X^n} (\cdot|f(w,k))
\end{IEEEeqnarray}
induced by the coding scheme, and the output distribution $P_{Z^n}\sim\mathcal{N}(0,\sigma)$ induced in the absence of transmission. A code $\mathcal{C}$ of blocklength $n$, message size $M=\left|\mathcal{M}\right|$, that satisfies $P_e^{\textnormal{avg}}\leq \epsilon$ and 
\begin{IEEEeqnarray}{rCl}
\label{covertness_constraint}
{D}\left(P_{Y^n_{\mathcal{C}}}\|P_{Z^n}\right) \leq \delta
\end{IEEEeqnarray}
for some $\epsilon, \delta \in (0,1]$ is called an 
$(n, M, \epsilon, \delta)$-code.
We denote 
\begin{IEEEeqnarray}{rCl}
  M^*\left(n,\epsilon,\delta\right)&=&\max\bigg\{M~|~ \exists  (n,M,\epsilon,\delta)\textnormal{-code} \bigg\}.
\end{IEEEeqnarray}
% and
% \begin{IEEEeqnarray}{rCl}
%   M^*\left(n,\epsilon,\delta\right)_{\textnormal{D}}&=&\max\bigg\{M~|~ \exists  (n,M,\epsilon,\delta)_{\textnormal{D}}\textnormal{-code} \bigg\}.
% \end{IEEEeqnarray}.
The covert capacity is then defined as 
\begin{IEEEeqnarray}{rCl}
  L_{\epsilon,\delta}=\liminf\limits_{n\rightarrow +\infty} \frac{\ln\left(M^*(n,\epsilon,\delta)\right)}{\sqrt{n}}.
\end{IEEEeqnarray}
In what follows, we do not characterize the number of key nats required and merely assume it is large enough, in a way we make more precise later.

Our main results are summarized in the following propositions.
\begin{proposition}
  \label{prop:converse}
  For the AWGN channel defined by \eqref{eq:channel_awgn} % subject to the covertness constraint \eqref{covert_communication_hypothesis_AWGN_kl_d}, for average probability of error $\epsilon$,
  \begin{IEEEeqnarray}{rCl}
    \label{lower_bound_m_star_kl}
    L_{\epsilon,\delta}&\leq&\frac{\sqrt{\delta}}{1-\epsilon}. 
  \end{IEEEeqnarray}
\end{proposition}

\begin{proposition}
  \label{prop:achievability}
  % \label{second_order_asymptotic_awgn_channel_lower_bound_average_error_probability}
  % For $\epsilon\in(0,1)$ and $\delta>0$, there exists an $(n,M,\epsilon,\delta)$-code with
  % \begin{IEEEeqnarray}{rCl}
  %   \ln\left(M\right)&\geq&\sqrt{\frac{\delta}{1-\epsilon}}\sqrt{n} +O\left(n^\frac{1}{3}\right).
  % \end{IEEEeqnarray}
  For the AWGN channel defined by \eqref{eq:channel_awgn}
  \begin{IEEEeqnarray}{rCl}
    \label{upper_bound_m_star_kl}
    L_{\epsilon,\delta}&\geq&\frac{\sqrt{\delta}}{\sqrt{1-\epsilon}}.
  \end{IEEEeqnarray}
\end{proposition}

Although the bounds are not tight, in the regime $\epsilon,\delta \ll 1$, we obtain
\begin{equation}
  \sqrt{\delta}\left(1+\frac{\epsilon}{2}\right) \lesssim L_{\epsilon,\delta}\lesssim \sqrt{\delta}(1+\epsilon).
\end{equation}
Propositions~\ref{prop:converse} and~\ref{prop:achievability} are illustrated in Fig.~\ref{fig:comparison_lower_upper_bound_L_epsilon}, showing a relatively close characterization of $L_{\epsilon,\delta}$ over a wide range of average error probability $\epsilon$. % and $\delta$.

\begin{figure}[!htbp]
  \begin{center}
    \includegraphics[width=0.5\textwidth]{plot_functions_L_epsilon_kld_with_delta_in_numerator.eps}
    \caption{Upper and lower bounds on  $L_{\epsilon,\delta}$ for %covertness constraint \eqref{covert_communication_hypothesis_AWGN_kl_d} and 
      $\delta_1=0.1$ and $\delta_2=0.01$.}
    \label{fig:comparison_lower_upper_bound_L_epsilon}
  \end{center}
\end{figure}

Most importantly, our results clearly show that $L_{\epsilon,\delta}>\lim\limits_{\epsilon'\rightarrow 0} L_{\epsilon',\delta}$ for $\epsilon>0$.


