\mathbb{E}\left[P_e^{\text{avg}}(\mathsf{C})\right]&\leq&\mathbb{P}\left[\sum_{i=1}^n \left(U_i-\mathbb{E}\left[U_i\right]\right) \leq -n^\frac{1}{3} \right]+e^{-n\gamma}\nonumber\\
&\leq&\frac{1}{2}n^{-\frac{1}{6}}=\frac{\epsilon'_n}{2}
%}
\end{IEEEeqnarray}
which establishes \eqref{condition_mean_upper_bound_half_epsilon} as claimed. This concludes the proof of Lemma \ref{lemma_first_order}.  

\subsection{Moderate deviations bound}
\label{appendix_moderate_deviations}
We restate \cite[Theorem 3.7.1]{large_deviation}, which is used to prove \eqref{probability_error_small_exists_decomposition_bpsk}.
\begin{theorem}[Moderate Deviations]
\label{appendix_theorem_moderate_deviations}
Let $V_1,\ldots,V_n$ be a sequence of $\mathbb{R}$-valued i.i.d. random variables with variance $\sigma^2$ such that for any $i=1,\ldots,n$, $f(\lambda)=\ln(\mathbb{E}[e^{\lambda V_i}]) < \infty$ in some ball around the origin and $\mathbb{E}[V_i]=0$. Fix $a_n\rightarrow 0$ such that $n a_n \rightarrow+\infty$ as $n\rightarrow +\infty$, and let $A_n = \sqrt{\frac{a_n}{n}} \sum_{i=1}^n V_i$. Then, for every measurable set $\Gamma$,
\begin{IEEEeqnarray}{rCl}
    \limsup\limits_{n\rightarrow +\infty} a_n \ln\left(\mathbb{P}\left[A_n\in\Gamma\right]\right)&\leq&-\frac{1}{2}\inf_{x\in\bar{\Gamma}} \frac{x^2}{\sigma^2},
\end{IEEEeqnarray}
where $\bar{\Gamma}$ is the closure of the set $\Gamma$.
\end{theorem}
We now check that the hypotheses of the theorem are satisfied for $V_i=n^{\frac{1}{4}}(U_i -\mathbb{E}[U_i])$, so that \eqref{probability_error_small_exists_decomposition_bpsk} 
holds. 
% We check that the hypotheses of this theorem
% %\cite[Theorem 3.7.1]{large_deviation} 
% are verified. 
We compute
\begin{IEEEeqnarray}{rCl}
    %f(\lambda)
    \IEEEeqnarraymulticol{3}{l}{
    \ln\left(\mathbb{E}\left[e^{\lambda n^\frac{1}{4}\left(U_i -\mathbb{E}[U_i]\right)}\right]\right)
    } \nonumber \\*
    \label{f_lambda}
    &=&\ln\left(\mathbb{E}\left[e^{\lambda \left(\left(\frac{1}{\sigma^2}-\frac{P}{\sigma^4}\right)n^\frac{1}{4}\sqrt{P}Z_i-n^\frac{1}{4}\frac{P}{2\sigma^4}Z_i^2+n^\frac{1}{4}\frac{P}{2\sigma^2}\right)}\right]\right)\nonumber\\
    %&=&\ln\left(\mathbb{E}\left[e^{\lambda \left(-\frac{P}{2\sigma^4}\left(Z_i+\left(\frac{\sigma^2}{P}-1\right)\sqrt{P}\right)^2+\frac{P}{2\sigma^4}\left(\frac{\sigma^2}{P}-1\right)^2P+\frac{P}{2\sigma^2}\right)}\right]\right)\nonumber\\
    &=&\ln\left(\mathbb{E}\left[e^{\lambda \left(-\frac{n^\frac{1}{4}P}{2\sigma^4}\left(Z_i-\left(\frac{\sigma^2}{P}-1\right)\sqrt{P}\right)^2+\frac{n^\frac{1}{4}}{2}-\frac{n^\frac{1}{4}P}{2\sigma^2}+\frac{n^\frac{1}{4}P^2}{2\sigma^4}\right)}\right]\right)\nonumber\\    %\label{use_moment_generating_function}
    &\stackrel{(a)}{=}&
    %\textcolor{blue}{}
        \frac{\lambda n^\frac{1}{4}}{2}\left(1-\frac{P}{\sigma^2}+\frac{P^2}{\sigma^4}\right)-\frac{1}{2}\ln\left(1+\frac{n^\frac{1}{4}P\lambda}{\sigma^2}\right) \nonumber\\
    &&{}-\frac{\frac{n^\frac{1}{4}P^2\lambda}{2\sigma^4} \left(\frac{\sigma^2}{P}-1\right)^2}{1+\frac{n^\frac{1}{4}P\lambda}{\sigma^2}} \nonumber\\
    &=&\frac{n^\frac{1}{4}P\lambda}{2\sigma^2}+\frac{\frac{\sqrt{n}P\lambda^2}{2\sigma^2}-\frac{\sqrt{n}P^2\lambda^2}{\sigma^4}+\frac{\sqrt{n}P^3\lambda^2}{2\sigma^6}}{1+\frac{n^\frac{1}{4}P\lambda}{\sigma^2}}\nonumber\\
    &&{}-\frac{1}{2}\ln\left(1+\frac{n^\frac{1}{4}P\lambda}{\sigma^2}\right) 
    %= \frac{\sqrt{\delta'}}{\sigma^2}\lambda^2+o_n(1)%\\
    %&=& \frac{\lambda n^\frac{1}{4}P}{2\sigma^2}...
     %&=&\lambda\left(\frac{1}{2}-\frac{P}{2\sigma^2}+\frac{P^2}{2\sigma^4}\right)-\frac{1}{2}\ln\left(1+2\frac{P}{2\sigma^4}\lambda\right)-\frac{\lambda \left(\frac{1}{2\sigma^2}-\frac{P}{2\sigma^4}\right)\sqrt{P}}{1+2\frac{P}{2\sigma^4}\lambda},
 %   &=\lambda\left(\frac{1}{2}-\frac{P}{2\sigma^2}+\frac{P^2}{2\sigma^4}\right)\!-\frac{1}{2}\ln\left(1+\frac{P\lambda}{\sigma^4}\right)\! - \frac{\lambda \left(\frac{1}{2}\!-\!\frac{P}{\sigma^2}\!+\!\frac{P^2}{2\sigma^4}\right)}{1+\frac{P}{\sigma^4}\lambda} \nonumber
   % \label{check_f_lambda}
\end{IEEEeqnarray}
where $(a)$ %\eqref{use_moment_generating_function}
can be established using the moment generating function of a non-central chi-squared random variable \cite[eq. (29.6)']{johnson1995continuous}.
Recalling the definition of $P$ in \eqref{value_P_finite_blocklength_bpsk}, we deduce that \eqref{f_lambda} is $<\infty$ in a ball around the origin  for any $n$, so that Theorem
\ref{appendix_theorem_moderate_deviations} 
